  ON storage.objects 
  FOR SELECT 
  USING (bucket_id = 'negocio-arquivos');

CREATE POLICY "Permitir upload de arquivos" 
  ON storage.objects 
  FOR INSERT 
  WITH CHECK (bucket_id = 'negocio-arquivos');

CREATE POLICY "Permitir exclusão de arquivos" 
