-- 1. Alterar crm_empresas para UUID
ALTER TABLE crm_empresas DROP COLUMN id;
ALTER TABLE crm_empresas ADD COLUMN id UUID DEFAULT gen_random_uuid() PRIMARY KEY;

-- Inserir empresas com novos UUIDs
INSERT INTO crm_empresas (id, nome_fantasia, razao_social, cnpj, telefone, email, site, observacoes, status, tenant_id, created_at, updated_at)
SELECT em.new_id, b.nome_fantasia, b.razao_social, b.cnpj, b.telefone, b.email, b.site, b.observacoes, b.status, b.tenant_id, b.created_at, b.updated_at
FROM backup_empresas b
JOIN empresa_mapping em ON b.id = em.old_id
ORDER BY b.id;

-- 2. Alterar crm_pipelines para UUID
ALTER TABLE crm_pipelines DROP COLUMN id;
ALTER TABLE crm_pipelines ADD COLUMN id UUID DEFAULT gen_random_uuid() PRIMARY KEY;

-- Inserir pipelines com novos UUIDs
INSERT INTO crm_pipelines (id, nome, descricao, ativo, tenant_id, created_at, updated_at)
SELECT pm.new_id, b.nome, b.descricao, b.ativo, b.tenant_id, b.created_at, b.updated_at
FROM backup_pipelines b
JOIN pipeline_mapping pm ON b.id = pm.old_id
ORDER BY b.id;

-- 3. Alterar crm_stages para UUID
ALTER TABLE crm_stages DROP COLUMN id;
ALTER TABLE crm_stages ADD COLUMN id UUID DEFAULT gen_random_uuid() PRIMARY KEY;
ALTER TABLE crm_stages DROP COLUMN pipeline_id;
ALTER TABLE crm_stages ADD COLUMN pipeline_id UUID NOT NULL;

-- Inserir stages com novos UUIDs e pipeline_id mapeado
INSERT INTO crm_stages (id, nome, cor, ordem, ativo, pipeline_id, tenant_id, created_at, updated_at)
SELECT sm.new_id, b.nome, b.cor, b.ordem, b.ativo,
       (SELECT pm2.new_id FROM pipeline_mapping pm2 WHERE pm2.old_id = b.pipeline_id),
       b.tenant_id, b.created_at, b.updated_at
FROM backup_stages b
JOIN stage_mapping sm ON b.id = sm.old_id
ORDER BY b.id;

-- 4. Alterar crm_pessoas para UUID
ALTER TABLE crm_pessoas DROP COLUMN id;
ALTER TABLE crm_pessoas ADD COLUMN id UUID DEFAULT gen_random_uuid() PRIMARY KEY;
ALTER TABLE crm_pessoas DROP COLUMN empresa_id;
ALTER TABLE crm_pessoas ADD COLUMN empresa_id UUID;

-- Inserir pessoas com novos UUIDs e empresa_id mapeado
INSERT INTO crm_pessoas (id, nome, email, telefone, whatsapp, documento, empresa_id, origem, status, observacoes, tenant_id, created_at, updated_at)
SELECT pm.new_id, b.nome, b.email, b.telefone, b.whatsapp, b.documento,
       CASE WHEN b.empresa_id IS NOT NULL THEN 
         (SELECT em2.new_id FROM empresa_mapping em2 WHERE em2.old_id = b.empresa_id)
       ELSE NULL END,
       b.origem, b.status, b.observacoes, b.tenant_id, b.created_at, b.updated_at
FROM backup_pessoas b
JOIN pessoa_mapping pm ON b.id = pm.old_id
ORDER BY b.id;

-- 5. Alterar crm_leads para UUID
ALTER TABLE crm_leads DROP COLUMN id;
ALTER TABLE crm_leads ADD COLUMN id UUID DEFAULT gen_random_uuid() PRIMARY KEY;
