INSERT INTO crm_messages (from_message, message, tipo_mensagem, audio_url, transcricao, duracao_audio, lead_id, pessoa_id, usuario_id, tenant_id, created_at, updated_at)
SELECT b.from_message, b.message, b.tipo_mensagem, b.audio_url, b.transcricao, b.duracao_audio,
       (SELECT lm2.new_id FROM lead_mapping lm2 WHERE lm2.old_id = b.lead_id),
       CASE WHEN b.pessoa_id IS NOT NULL THEN 
         (SELECT pm2.new_id FROM pessoa_mapping pm2 WHERE pm2.old_id = b.pessoa_id)
       ELSE NULL END,
       b.usuario_id, b.tenant_id, b.created_at, b.updated_at
FROM backup_messages b
WHERE EXISTS (SELECT 1 FROM lead_mapping lm2 WHERE lm2.old_id = b.lead_id)
