ON crm_agendamentos 
FOR INSERT 
WITH CHECK (
  EXISTS (
    SELECT 1 FROM crm_usuarios 
    WHERE auth_user_id = auth.uid() 
    AND tenant_id = crm_agendamentos.tenant_id
    AND (
      -- Super admin pode criar para qualquer usuário
      super_adm = true
      OR
      -- Gestor pode criar para qualquer usuário do tenant
