  au.email,
  true,
  true,
  true,
  (SELECT id FROM crm_tenants WHERE value = 'iatize' LIMIT 1)
FROM auth.users au
WHERE au.email = 'rafaela@iatize.com'
  AND NOT EXISTS (
    SELECT 1 FROM crm_usuarios cu 
    WHERE cu.auth_user_id = au.id
  );

