-- CORREÇÃO DO PERFIL DA RAFAELA E MELHORIA NA FUNÇÃO get_user_available_tenants
-- ========================================================================

-- 1. CORRIGIR PERFIL DA RAFAELA
UPDATE crm_usuarios 
SET 
  gestor = true,
