-- STEP 3: Verificar se a função is_user_super_admin existe e está correta
CREATE OR REPLACE FUNCTION public.is_user_super_admin(user_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 
    FROM crm_usuarios 
    WHERE auth_user_id = user_id 
    AND super_adm = true 
    AND ativo = true
  );
END;
$$;

