CREATE POLICY "agencias_insert_policy" ON public.crm_agencias
  FOR INSERT WITH CHECK (public.is_super_admin());

CREATE POLICY "agencias_update_policy" ON public.crm_agencias
  FOR UPDATE USING (public.is_super_admin());

