  ON public.lp_templates FOR INSERT
  TO authenticated
  WITH CHECK (public.is_admin_or_gestor());

CREATE POLICY "lp_templates_update"
  ON public.lp_templates FOR UPDATE
  TO authenticated
  USING (public.is_admin_or_gestor());

