-- ---------------------------------------------------------------------------
-- Migration: 20260218200000_fix_bi_ad_campaigns_schema-ok.sql
-- ---------------------------------------------------------------------------

-- BI PRO™ — Fix bi_ad_campaigns remote schema mismatch
-- The remote table was created via Supabase dashboard with a different schema
-- than what the edge functions (bi-sync-meta-ads, bi-sync-google-ads) and
-- the frontend hooks expect. This migration aligns the remote schema.
-- Created: 2026-02-18

-- 1. Add ad_account_id column (edge functions write with this name, remote had 'account_id')
ALTER TABLE public.bi_ad_campaigns
  ADD COLUMN IF NOT EXISTS ad_account_id uuid REFERENCES public.bi_ad_accounts(id) ON DELETE CASCADE;

-- 2. Populate ad_account_id from existing account_id column (for any existing rows)
UPDATE public.bi_ad_campaigns
  SET ad_account_id = account_id
  WHERE ad_account_id IS NULL AND account_id IS NOT NULL;

-- 3. Add platform column (critical: used in edge function upsert + channel attribution)
ALTER TABLE public.bi_ad_campaigns
  ADD COLUMN IF NOT EXISTS platform text;

-- 4. Populate platform from bi_ad_accounts for any existing rows
UPDATE public.bi_ad_campaigns c
  SET platform = a.platform
  FROM public.bi_ad_accounts a
  WHERE (c.ad_account_id = a.id OR c.account_id = a.id)
    AND c.platform IS NULL;

-- 5. Default remaining NULLs to 'meta' (existing campaigns are most likely Meta)
UPDATE public.bi_ad_campaigns
  SET platform = 'meta'
  WHERE platform IS NULL;

-- 6. Add utm_campaign column (for matching campaigns to leads.utm_campaign)
ALTER TABLE public.bi_ad_campaigns
  ADD COLUMN IF NOT EXISTS utm_campaign text;

-- 7. Add unique constraint on (platform, campaign_id) — required for ON CONFLICT upserts
--    First remove any duplicates that would block it
DELETE FROM public.bi_ad_campaigns c1
  USING public.bi_ad_campaigns c2
  WHERE c1.ctid > c2.ctid
    AND c1.campaign_id = c2.campaign_id
    AND c1.platform = c2.platform;

DROP INDEX IF EXISTS bi_ad_campaigns_platform_campaign_id_unique;
ALTER TABLE public.bi_ad_campaigns
  DROP CONSTRAINT IF EXISTS bi_ad_campaigns_platform_campaign_id_key;
ALTER TABLE public.bi_ad_campaigns
  ADD CONSTRAINT bi_ad_campaigns_platform_campaign_id_key UNIQUE (platform, campaign_id);

-- 8. Add indexes for fast lookups
CREATE INDEX IF NOT EXISTS idx_bi_ad_campaigns_platform
  ON public.bi_ad_campaigns (platform);

CREATE INDEX IF NOT EXISTS idx_bi_ad_campaigns_utm_campaign
  ON public.bi_ad_campaigns (utm_campaign)
  WHERE utm_campaign IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_bi_ad_campaigns_ad_account
  ON public.bi_ad_campaigns (ad_account_id)
  WHERE ad_account_id IS NOT NULL;

-- 9. Remove orphaned bi_ad_spend rows with campaign_id=NULL
--    These were inserted when campaign upserts were failing silently.
--    After re-syncing, correct rows (with valid campaign_id) will be inserted.
DELETE FROM public.bi_ad_spend WHERE campaign_id IS NULL;


-- ---------------------------------------------------------------------------
-- Migration: 20260219000000_fix_bi_ad_spend_campaign_fk-ok.sql
-- ---------------------------------------------------------------------------

-- BI PRO™ — Fix bi_ad_spend FK and bi_ad_campaigns duplicate constraint
-- Root cause 1: PostgREST requires a declared FK to resolve joins via
--   .select('bi_ad_campaigns(campaign_name, utm_campaign)')
-- Root cause 2: bi_ad_campaigns had two overlapping unique constraints causing upsert failures
-- Root cause 3: bi_ad_campaigns.account_id was NOT NULL but edge function wasn't sending it
--
-- Applied to remote: 2026-02-19 via Management API (direct SQL execution)

-- 1. Clean up stale spend rows (from failed syncs)
DELETE FROM public.bi_ad_spend WHERE campaign_id IS NULL;
DELETE FROM public.bi_ad_spend
  WHERE campaign_id IS NOT NULL
    AND campaign_id NOT IN (SELECT id FROM public.bi_ad_campaigns);

-- 2. Drop redundant old unique constraint (conflicts with onConflict: 'platform,campaign_id')
--    The (platform, campaign_id) constraint is sufficient since Meta campaign IDs are globally unique
ALTER TABLE public.bi_ad_campaigns
  DROP CONSTRAINT IF EXISTS bi_ad_campaigns_account_id_campaign_id_key;

-- 3. Add FK so PostgREST can resolve the join in:
--    bi_ad_spend.select('spend, platform, ..., bi_ad_campaigns(campaign_name, utm_campaign)')
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.table_constraints
    WHERE table_name = 'bi_ad_spend'
      AND constraint_name = 'bi_ad_spend_campaign_id_fkey'
  ) THEN
    ALTER TABLE public.bi_ad_spend
      ADD CONSTRAINT bi_ad_spend_campaign_id_fkey
      FOREIGN KEY (campaign_id) REFERENCES public.bi_ad_campaigns(id) ON DELETE SET NULL;
  END IF;
END $$;


-- ---------------------------------------------------------------------------
-- Migration: 20260219100000_lead_custom_fields-ok.sql
-- ---------------------------------------------------------------------------

-- Lead Custom Fields — Dynamic field definitions and per-lead values
-- Feature: CRM Pro™ Dynamic Lead Fields
-- Created: 2026-02-19

-- =============================================================================
-- TABLE: lead_field_definitions
-- Admin-configurable field schema (global or per-pipeline)
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.lead_field_definitions (
  id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name          text NOT NULL,
  key           text NOT NULL,                 -- snake_case identifier
  type          text NOT NULL CHECK (type IN ('text', 'number', 'single_select', 'boolean', 'date')),
  category      text NOT NULL CHECK (category IN ('qualificacao', 'outros')),
  pipeline_id   uuid REFERENCES public.leads_pipelines(id) ON DELETE CASCADE,  -- NULL = global
  options       jsonb NOT NULL DEFAULT '[]',   -- [{label, value}] for single_select
  required      boolean NOT NULL DEFAULT false,
  active        boolean NOT NULL DEFAULT true,
  ordem         integer NOT NULL DEFAULT 0,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now()
);

-- Unique field key per pipeline scope (NULLs treated as equal → global fields can't duplicate)
CREATE UNIQUE INDEX IF NOT EXISTS idx_lead_field_definitions_key_pipeline
  ON public.lead_field_definitions(key, pipeline_id) NULLS NOT DISTINCT;

CREATE INDEX IF NOT EXISTS idx_lead_field_definitions_active
  ON public.lead_field_definitions(active, category, ordem);

CREATE INDEX IF NOT EXISTS idx_lead_field_definitions_pipeline
  ON public.lead_field_definitions(pipeline_id)
  WHERE pipeline_id IS NOT NULL;

-- RLS
ALTER TABLE public.lead_field_definitions ENABLE ROW LEVEL SECURITY;

-- Drop existing policies before recreating (idempotent)
DROP POLICY IF EXISTS "lead_field_definitions_select" ON public.lead_field_definitions;
DROP POLICY IF EXISTS "lead_field_definitions_insert" ON public.lead_field_definitions;
DROP POLICY IF EXISTS "lead_field_definitions_update" ON public.lead_field_definitions;
DROP POLICY IF EXISTS "lead_field_definitions_delete" ON public.lead_field_definitions;

-- Any authenticated user can read definitions
CREATE POLICY "lead_field_definitions_select"
  ON public.lead_field_definitions FOR SELECT
  TO authenticated
  USING (true);

-- Only admin/gestor can create, update, or delete definitions
CREATE POLICY "lead_field_definitions_insert"
  ON public.lead_field_definitions FOR INSERT
  TO authenticated
  WITH CHECK (is_admin_or_gestor());

CREATE POLICY "lead_field_definitions_update"
  ON public.lead_field_definitions FOR UPDATE
  TO authenticated
  USING (is_admin_or_gestor())
  WITH CHECK (is_admin_or_gestor());

CREATE POLICY "lead_field_definitions_delete"
  ON public.lead_field_definitions FOR DELETE
  TO authenticated
  USING (is_admin_or_gestor());

-- =============================================================================
-- TABLE: lead_field_values
-- Per-lead values for custom fields
-- =============================================================================
CREATE TABLE IF NOT EXISTS public.lead_field_values (
  id                    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  lead_id               uuid NOT NULL REFERENCES public.leads(id) ON DELETE CASCADE,
  field_definition_id   uuid NOT NULL REFERENCES public.lead_field_definitions(id) ON DELETE CASCADE,
  value_text            text,
  value_number          numeric,
  value_boolean         boolean,
  value_date            date,
