CREATE TABLE IF NOT EXISTS public.meeting_followup_queue (
  id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  rule_id          uuid        NOT NULL REFERENCES public.meetings_followups(id) ON DELETE CASCADE,
