                                 CHECK (status IN ('pending', 'sent', 'failed', 'cancelled')),
  channel          text        NOT NULL,
  webhook_url      text        NOT NULL,
  message_snapshot text,
  fired_at         timestamptz,
  response_status  int,
  response_body    text,
