-- ---------------------------------------------------------------------------
-- Migration: 20260228050000_p12_whatsapp_templates_status_normalize-ok.sql
-- ---------------------------------------------------------------------------

-- P12: whatsapp_templates.status value standardization (Portuguese → English)
--
-- Current values: 'ativo', 'inativo' (internal) + Gupshup API values (often uppercase)
-- The UI uses status.toLowerCase() — confirming uppercase values exist in DB.
-- Canonical values after P12: lowercase only, with internal PT values → English.
--
-- No CHECK constraint existed on this column — just a DEFAULT 'ativo'.

BEGIN;

-- === STEP 1: Lowercase all values first (normalize API-returned uppercase) ===

UPDATE public.whatsapp_templates SET status = LOWER(status)
  WHERE status != LOWER(status);

-- === STEP 2: Normalize internal Portuguese values ===

UPDATE public.whatsapp_templates SET status = 'active'
  WHERE status = 'ativo';

UPDATE public.whatsapp_templates SET status = 'inactive'
  WHERE status = 'inativo';

-- === STEP 2: Update default value on column ===

ALTER TABLE public.whatsapp_templates ALTER COLUMN status SET DEFAULT 'active';

-- === STEP 3: Add CHECK constraint covering all valid values ===
-- Includes Gupshup API values (lowercase) that may be synced directly to this column.

ALTER TABLE public.whatsapp_templates DROP CONSTRAINT IF EXISTS whatsapp_templates_status_check;

ALTER TABLE public.whatsapp_templates ADD CONSTRAINT whatsapp_templates_status_check
  CHECK (status = ANY (ARRAY[
    'active'::text,
    'inactive'::text,
    'approved'::text,
    'rejected'::text,
    'pending'::text,
    'submitted'::text,
    'paused'::text,
    'disabled'::text,
    'deleted'::text,
    'in_appeal'::text,
    'flagged'::text
  ]));

-- === STEP 4: Verify ===

DO $$
DECLARE
  bad_count INTEGER;
BEGIN
  SELECT COUNT(*) INTO bad_count
  FROM public.whatsapp_templates
  WHERE status NOT IN ('active', 'inactive', 'approved', 'rejected', 'pending',
                       'submitted', 'paused', 'disabled', 'deleted', 'in_appeal', 'flagged');

  IF bad_count > 0 THEN
    RAISE EXCEPTION 'P12 verification failed: % templates have non-canonical status', bad_count;
  ELSE
    RAISE NOTICE 'P12 verified OK — all whatsapp_templates.status values are canonical';
  END IF;
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260228060000_fix_book_meeting_status-ok.sql
-- ---------------------------------------------------------------------------

-- Fix: book_meeting (public booking overload) was inserting status='agendada'
-- P7 tightened meetings_status_check to canonical values only ('agendado', not 'agendada').
-- This caused "violates check constraint" on every public booking confirmation.

CREATE OR REPLACE FUNCTION public.book_meeting(
  p_lead_id     uuid,
  p_start_time  timestamptz,
  p_end_time    timestamptz,
  p_rule_set_id uuid    DEFAULT NULL,
  p_duration    integer DEFAULT 30,
  p_notes       text    DEFAULT NULL
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id       uuid;
  v_user_name     text;
  v_meeting_id    uuid;
  v_title         text;
  v_eligible_ids  uuid[];
BEGIN
  v_eligible_ids := public.get_booking_eligible_user_ids(p_rule_set_id);

  IF v_eligible_ids IS NULL OR array_length(v_eligible_ids, 1) IS NULL THEN
    RETURN json_build_object('error', 'Nenhum consultor disponível');
  END IF;

  IF p_rule_set_id IS NOT NULL THEN
    SELECT su.id, su.name
    INTO v_user_id, v_user_name
    FROM public.booking_rules br
    INNER JOIN public.settings_users su
      ON su.id = (br.config->>'user_id')::uuid
      AND su.active = true
      AND su.id = ANY(v_eligible_ids)
    WHERE br.rule_set_id = p_rule_set_id
      AND br.rule_type   = 'specific_user'
      AND br.is_active   = true
      AND NOT EXISTS (
        SELECT 1 FROM public.meetings m
        WHERE m.user_id    = su.id
          AND m.start_time < p_end_time
          AND m.end_time   > p_start_time
          AND m.status NOT IN ('cancelado')
      )
    ORDER BY br.order_index ASC
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    SELECT su.id, su.name
    INTO v_user_id, v_user_name
    FROM public.settings_users su
    WHERE su.id = ANY(v_eligible_ids)
      AND su.active = true
      AND NOT EXISTS (
        SELECT 1 FROM public.meetings m
        WHERE m.user_id    = su.id
          AND m.start_time < p_end_time
          AND m.end_time   > p_start_time
          AND m.status NOT IN ('cancelado')
      )
    ORDER BY
      (SELECT COUNT(*) FROM public.meetings m2
       WHERE m2.user_id    = su.id
         AND m2.start_time >= NOW()
         AND m2.status NOT IN ('cancelado')
      ) ASC,
      COALESCE((
        SELECT MAX(m3.created_at) FROM public.meetings m3
        WHERE m3.user_id = su.id
      ), '1970-01-01'::timestamptz) ASC
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN json_build_object('error', 'Horário não disponível — escolha outro horário');
  END IF;

  v_title := 'Reunião agendada — ' ||
    TO_CHAR(p_start_time AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI');

  INSERT INTO public.meetings (
    lead_id, user_id, title, start_time, end_time, status, notes, source
  )
  VALUES (
    p_lead_id, v_user_id, v_title,
    p_start_time, p_end_time,
    'agendado', p_notes, 'public_booking'
  )
  RETURNING id INTO v_meeting_id;

  RETURN json_build_object(
    'meeting_id', v_meeting_id::text,
    'consultor', json_build_object(
      'id',   v_user_id::text,
      'name', v_user_name
    )
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.book_meeting(uuid, timestamptz, timestamptz, uuid, integer, text)
  TO anon, authenticated;


