-- =============================================================================
-- N8N-WAA-1: Extend ai_agents — LLM + WhatsApp + buffer config
-- Epic: Native AI Agent Runtime (N8N-WAA)
-- Agent: @data-engineer
-- =============================================================================

-- LLM runtime configuration
ALTER TABLE ai_agents
  ADD COLUMN IF NOT EXISTS llm_provider       text    NOT NULL DEFAULT 'openai',
  ADD COLUMN IF NOT EXISTS llm_model          text    NOT NULL DEFAULT 'gpt-4o-mini',
  ADD COLUMN IF NOT EXISTS llm_temperature    float   NOT NULL DEFAULT 0.7,
  ADD COLUMN IF NOT EXISTS llm_max_tokens     int     NOT NULL DEFAULT 1024,
  ADD COLUMN IF NOT EXISTS llm_provider_id    uuid,   -- FK added after settings_ai_providers migration
  -- Conversation memory
  ADD COLUMN IF NOT EXISTS memory_window      int     NOT NULL DEFAULT 20,
  -- WhatsApp routing
  ADD COLUMN IF NOT EXISTS wa_phone_number_id text,
  -- Message debounce
  ADD COLUMN IF NOT EXISTS buffer_ms          int     NOT NULL DEFAULT 3000;

-- CHECK constraints
ALTER TABLE ai_agents
  ADD CONSTRAINT ai_agents_llm_provider_check
    CHECK (llm_provider IN ('openai', 'anthropic', 'groq', 'gemini')),
  ADD CONSTRAINT ai_agents_llm_temperature_check
    CHECK (llm_temperature >= 0.0 AND llm_temperature <= 2.0),
  ADD CONSTRAINT ai_agents_llm_max_tokens_check
    CHECK (llm_max_tokens > 0 AND llm_max_tokens <= 32768),
  ADD CONSTRAINT ai_agents_memory_window_check
    CHECK (memory_window > 0 AND memory_window <= 200),
  ADD CONSTRAINT ai_agents_buffer_ms_check
    CHECK (buffer_ms >= 0 AND buffer_ms <= 30000);

-- Column documentation
COMMENT ON COLUMN ai_agents.llm_provider     IS 'LLM provider: openai | anthropic | groq | gemini';
COMMENT ON COLUMN ai_agents.llm_model        IS 'Model ID (e.g. gpt-4o-mini, claude-3-5-haiku-20241022)';
COMMENT ON COLUMN ai_agents.llm_temperature  IS 'Sampling temperature 0.0–2.0 (default 0.7)';
COMMENT ON COLUMN ai_agents.llm_max_tokens   IS 'Max output tokens per LLM call (default 1024)';
COMMENT ON COLUMN ai_agents.llm_provider_id  IS 'FK to settings_ai_providers — global API key store';
COMMENT ON COLUMN ai_agents.memory_window    IS 'Number of past messages loaded as conversation context';
COMMENT ON COLUMN ai_agents.wa_phone_number_id IS 'Meta WhatsApp Business phone_number_id for this agent';
COMMENT ON COLUMN ai_agents.buffer_ms        IS 'Inbound message debounce window in ms (0 = process immediately)';


-- ---------------------------------------------------------------------------
-- Migration: 20260302110000_n8n-waa-2-settings-ai-providers-ok.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- N8N-WAA-2: settings_ai_providers — global LLM API key store
-- Epic: Native AI Agent Runtime (N8N-WAA)
-- Agent: @data-engineer
--
-- SECURITY NOTE: api_key is stored as plaintext here.
-- For production, encrypt via pgsodium:
--   UPDATE settings_ai_providers SET api_key = pgsodium.crypto_aead_det_encrypt(
--     api_key::bytea, additional::bytea, key_id
--   )
-- Edge functions use service_role to read and decrypt at runtime.
-- The api_key column is NEVER returned to the frontend (RLS SELECT excludes it).
-- =============================================================================

CREATE TABLE IF NOT EXISTS settings_ai_providers (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  provider    text        NOT NULL,
  label       text        NOT NULL,
  api_key     text        NOT NULL,
  is_default  boolean     NOT NULL DEFAULT false,
  active      boolean     NOT NULL DEFAULT true,
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT settings_ai_providers_provider_check
    CHECK (provider IN ('openai', 'anthropic', 'groq', 'gemini'))
);

-- Only one default per provider
CREATE UNIQUE INDEX IF NOT EXISTS settings_ai_providers_one_default_per_provider
  ON settings_ai_providers (provider)
  WHERE is_default = true AND active = true;

-- Documentation
COMMENT ON TABLE settings_ai_providers IS 'Global LLM API keys. api_key never exposed to frontend — service_role only.';
COMMENT ON COLUMN settings_ai_providers.provider   IS 'Provider: openai | anthropic | groq | gemini';
COMMENT ON COLUMN settings_ai_providers.label      IS 'Human-readable label (e.g. "OpenAI Produção")';
COMMENT ON COLUMN settings_ai_providers.api_key    IS 'Raw API key — service_role read only, never SELECT via RLS';
COMMENT ON COLUMN settings_ai_providers.is_default IS 'Fallback provider when ai_agents.llm_provider_id is null';

-- updated_at trigger
CREATE OR REPLACE FUNCTION settings_ai_providers_set_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER settings_ai_providers_updated_at
  BEFORE UPDATE ON settings_ai_providers
  FOR EACH ROW EXECUTE FUNCTION settings_ai_providers_set_updated_at();

-- RLS: frontend sees label/provider/is_default/active but NOT api_key
ALTER TABLE settings_ai_providers ENABLE ROW LEVEL SECURITY;

-- Gestor/admin: full metadata view (api_key excluded via application layer)
CREATE POLICY "ai_providers_select_admin"
  ON settings_ai_providers FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  );

CREATE POLICY "ai_providers_insert_admin"
  ON settings_ai_providers FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  );

CREATE POLICY "ai_providers_update_admin"
  ON settings_ai_providers FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  );

CREATE POLICY "ai_providers_delete_admin"
  ON settings_ai_providers FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  );

-- FK from ai_agents (migration 1 created the column, now add constraint)
ALTER TABLE ai_agents
  ADD CONSTRAINT ai_agents_llm_provider_id_fkey
    FOREIGN KEY (llm_provider_id)
    REFERENCES settings_ai_providers(id)
    ON DELETE SET NULL;


-- ---------------------------------------------------------------------------
-- Migration: 20260302120000_n8n-waa-3-message-buffer-ok.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- N8N-WAA-3: message_buffer + AI fields on clients_people + messages tracking
-- Epic: Native AI Agent Runtime (N8N-WAA)
-- Agent: @data-engineer
--
-- Replaces Redis for inbound message debouncing.
-- messages.from_contact normalized: 'cliente' | 'ia' | 'humano' | 'sistema'
-- =============================================================================

-- ── 1. MESSAGE BUFFER (replaces Redis list) ──────────────────────────────────

CREATE TABLE IF NOT EXISTS message_buffer (
  id          uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  people_id   uuid        NOT NULL REFERENCES clients_people(id) ON DELETE CASCADE,
  -- Array of {content, message_type, media_url, wa_message_id} objects
  messages    jsonb[]     NOT NULL DEFAULT '{}',
  created_at  timestamptz NOT NULL DEFAULT now(),
  -- expires_at = created_at + ai_agents.buffer_ms (set by edge function)
  expires_at  timestamptz NOT NULL,
  processed   boolean     NOT NULL DEFAULT false,
  processed_at timestamptz
);

COMMENT ON TABLE  message_buffer                 IS 'Inbound message debounce buffer. Replaces Redis list. Processed by pg_cron every 5s.';
COMMENT ON COLUMN message_buffer.messages        IS 'Array of {content, message_type, media_url, wa_message_id}';
COMMENT ON COLUMN message_buffer.expires_at      IS 'When this buffer window closes (= created_at + buffer_ms)';
COMMENT ON COLUMN message_buffer.processed       IS 'True once ai-agent-execute has consumed this buffer entry';

-- Index for pg_cron polling (unprocessed entries past expiry)
CREATE INDEX IF NOT EXISTS message_buffer_ready_to_process
  ON message_buffer (people_id, expires_at)
  WHERE processed = false;

-- RLS: only service_role (edge functions) — never called from frontend
ALTER TABLE message_buffer ENABLE ROW LEVEL SECURITY;

CREATE POLICY "message_buffer_service_role_only"
  ON message_buffer FOR ALL
  USING (auth.role() = 'service_role');


-- ── 2. AI PROCESSING FIELDS ON clients_people ────────────────────────────────

ALTER TABLE clients_people
  ADD COLUMN IF NOT EXISTS ai_last_message_at  timestamptz,
  ADD COLUMN IF NOT EXISTS ai_processing_lock  boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN clients_people.ai_last_message_at IS 'Timestamp of last inbound message (used by pg_cron debounce check)';
COMMENT ON COLUMN clients_people.ai_processing_lock IS 'Lock flag: prevents concurrent ai-agent-execute runs for same person';


-- ── 3. MESSAGE TRACKING FIELDS ───────────────────────────────────────────────

ALTER TABLE messages
  ADD COLUMN IF NOT EXISTS wa_message_id  text,
  ADD COLUMN IF NOT EXISTS execution_id   uuid
    REFERENCES ai_agents_execution_log(id) ON DELETE SET NULL;

-- Deduplication: prevent storing duplicate inbound WA messages
CREATE UNIQUE INDEX IF NOT EXISTS messages_wa_message_id_unique
  ON messages (wa_message_id)
  WHERE wa_message_id IS NOT NULL;

