-- Migration: 20260317000000_fix_claim_pending_messages_types.sql
-- ---------------------------------------------------------------------------

-- Fix claim_pending_messages RPC: module_ref_id type mismatch (text → uuid)
-- The messages.module_ref_id column is uuid, not text.
-- Migration: 20260317000000

DROP FUNCTION IF EXISTS claim_pending_messages(int, int, uuid, text);

CREATE OR REPLACE FUNCTION claim_pending_messages(
  p_batch_size    int  DEFAULT 20,
  p_max_age_hours int  DEFAULT 24,
  p_people_id     uuid DEFAULT NULL,
  p_channel       text DEFAULT NULL
)
RETURNS TABLE (
  id                   bigint,
  channel              text,
  content              text,
  message_type         text,
  media_url            text,
  media_metadata       jsonb,
  people_id            uuid,
  lead_id              uuid,
  user_id              uuid,
  source_type          text,
  module_ref_id        uuid,
  whatsapp_template_id text,
  wa_phone_number_id   text,
  execution_id         uuid,
  metadata             jsonb,
  sent_at              timestamptz
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  WITH claimed AS (
    UPDATE messages m_upd
    SET status = 'sending'
    WHERE m_upd.id IN (
      SELECT m.id
      FROM messages m
      WHERE m.status = 'pending'
        AND m.from_contact != 'cliente'
        AND m.created_at > now() - (p_max_age_hours || ' hours')::interval
        AND (p_people_id IS NULL OR m.people_id = p_people_id)
        AND (p_channel IS NULL OR m.channel = p_channel)
        AND (
          (m.metadata->>'delay_minutes') IS NULL
          OR (m.metadata->>'delay_minutes')::int = 0
          OR (
            COALESCE(m.sent_at, m.created_at)
            + ((m.metadata->>'delay_minutes')::int * interval '1 minute')
            <= now()
          )
        )
      ORDER BY m.id ASC
      LIMIT p_batch_size
      FOR UPDATE SKIP LOCKED
    )
    RETURNING
      m_upd.id,
      m_upd.channel,
      m_upd.content,
      m_upd.message_type,
      m_upd.media_url,
      m_upd.media_metadata,
      m_upd.people_id,
      m_upd.lead_id,
      m_upd.user_id,
      m_upd.source_type,
      m_upd.module_ref_id,
      m_upd.whatsapp_template_id,
      m_upd.wa_phone_number_id,
      m_upd.execution_id,
      m_upd.metadata,
      m_upd.sent_at
  )
  SELECT * FROM claimed ORDER BY claimed.id ASC;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260317100000_fix_claim_reset_and_security.sql
-- ---------------------------------------------------------------------------

-- ╔════════════════════════════════════════════════════════════════════════════╗
-- ║  QA Fix: BUG-1 + SEC-1 from Omni Pro QA gate review                    ║
-- ║                                                                          ║
-- ║  BUG-1 (HIGH): reset_stale_sending_messages used created_at instead of  ║
-- ║  updated_at — messages created >5min ago were reset immediately after   ║
-- ║  being claimed, causing infinite claim→reset loop and potential dupes.  ║
-- ║                                                                          ║
-- ║  SEC-1 (MEDIUM): claim_pending_messages and reset_stale_sending_messages║
-- ║  were callable by anon/authenticated via PostgREST. Now restricted to   ║
-- ║  service_role only.                                                      ║
-- ╚════════════════════════════════════════════════════════════════════════════╝

-- ── 1. FIX BUG-1: Use updated_at instead of created_at ─────────────────────
-- The messages table has a BEFORE UPDATE trigger that sets updated_at = now()
-- automatically. When claim_pending_messages sets status='sending', updated_at
-- is refreshed. So we filter on updated_at to detect truly stale claims.

CREATE OR REPLACE FUNCTION reset_stale_sending_messages()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE messages
  SET status = 'pending'
  WHERE status = 'sending'
    AND updated_at < now() - interval '5 minutes';
END;
$$;

-- ── 2. FIX SEC-1: Restrict RPC access to service_role only ──────────────────
-- These functions should only be called by edge functions (service_role key)
-- and pg_cron (runs as superuser). Never by anon or authenticated clients.

REVOKE ALL ON FUNCTION claim_pending_messages(int, int, uuid, text) FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION claim_pending_messages(int, int, uuid, text) TO service_role;

REVOKE ALL ON FUNCTION reset_stale_sending_messages() FROM public, anon, authenticated;
GRANT EXECUTE ON FUNCTION reset_stale_sending_messages() TO service_role;


-- ---------------------------------------------------------------------------
-- Migration: 20260317110000_restrict_merge_persons_rpc.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- SEC-2: Restrict merge_persons & find_duplicate_person to service_role
-- ============================================================
-- These RPCs modify the person graph (re-parent messages, mark
-- records as merged). They must NOT be callable by end-users
-- via PostgREST — only edge functions using service_role key.
-- ============================================================

-- Revoke from public roles
REVOKE EXECUTE ON FUNCTION public.merge_persons(uuid, uuid)
  FROM public, anon, authenticated;

REVOKE EXECUTE ON FUNCTION public.find_duplicate_person(uuid, text, text, text, text, text)
  FROM public, anon, authenticated;

-- Grant only to service_role (edge functions + pg_cron)
GRANT EXECUTE ON FUNCTION public.merge_persons(uuid, uuid)
  TO service_role;

GRANT EXECUTE ON FUNCTION public.find_duplicate_person(uuid, text, text, text, text, text)
  TO service_role;


