BEGIN
  SELECT id INTO v_agent_id
  FROM public.ai_agents
  WHERE is_template = true AND template_type = 'triagem'
  LIMIT 1;

  IF v_agent_id IS NULL THEN
    RAISE NOTICE '[Phase1-Sec1] Template triagem não encontrado — pulando.';
  ELSE
