-- ---------------------------------------------------------------------------
-- Migration: 20260318100001_instagram_token_refresh_cron.sql
-- ---------------------------------------------------------------------------

-- Instagram Token Auto-Refresh — pg_cron Schedule
-- Epic: EPIC-OMNI-PRO-V2 | Story: OP-03
-- Runs daily at 03:00 UTC to check/refresh Instagram OAuth token
-- Pattern: same as omni-delivery-engine (SECURITY DEFINER + _app_config)

-- ── 1. PL/pgSQL function ─────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION trigger_instagram_token_refresh()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  supabase_url  text;
  svc_key       text;
BEGIN
  SELECT value INTO supabase_url FROM _app_config WHERE key = 'supabase_url';
  SELECT value INTO svc_key      FROM _app_config WHERE key = 'service_role_key';

  IF supabase_url IS NULL OR svc_key IS NULL THEN
    RAISE WARNING 'trigger_instagram_token_refresh: _app_config missing supabase_url or service_role_key';
    RETURN;
  END IF;

  -- Only trigger if instagram channel is active
  IF NOT EXISTS (
    SELECT 1 FROM omni_channel_configs
    WHERE channel = 'instagram' AND is_active = true
    LIMIT 1
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := supabase_url || '/functions/v1/instagram-token-refresh',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || svc_key
    ),
    body    := '{"trigger":"cron"}'::jsonb
  );
END;
$$;

COMMENT ON FUNCTION trigger_instagram_token_refresh() IS
  'Disparada pelo pg_cron diariamente às 03:00 UTC. '
  'Só chama a edge function se canal Instagram estiver ativo. '
  'Lê credenciais de _app_config (SECURITY DEFINER).';

-- ── 2. Remover job anterior se existir ──────────────────────────────────────
SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'instagram-token-refresh';

-- ── 3. Agendar daily às 03:00 UTC ──────────────────────────────────────────
SELECT cron.schedule(
  'instagram-token-refresh',
  '0 3 * * *',
  $$ SELECT trigger_instagram_token_refresh(); $$
);


-- ---------------------------------------------------------------------------
-- Migration: 20260318100002_omni_dead_letter_queue.sql
-- ---------------------------------------------------------------------------

-- OMNI PRO™ Dead-Letter Queue — Retry failed deliveries
-- Epic: EPIC-OMNI-PRO-V2 | Story: OP-04
-- Captures messages that fail delivery and retries with exponential backoff

-- ── 1. Criar tabela omni_delivery_dead_letter ────────────────────────────────
CREATE TABLE IF NOT EXISTS omni_delivery_dead_letter (
  id              uuid DEFAULT gen_random_uuid() PRIMARY KEY,
  message_id      integer NOT NULL REFERENCES messages(id),
  channel         text NOT NULL,
  error_code      text,
  error_message   text,
  attempts        integer DEFAULT 0,
  max_attempts    integer DEFAULT 5,
  next_retry_at   timestamptz,
  status          text NOT NULL DEFAULT 'pending'
                    CHECK (status IN ('pending', 'retrying', 'exhausted', 'resolved')),
  created_at      timestamptz DEFAULT now(),
  updated_at      timestamptz DEFAULT now()
);

COMMENT ON TABLE omni_delivery_dead_letter IS
  'OMNI PRO™ dead-letter queue para mensagens que falharam no delivery engine. '
  'Retry exponencial: 1min, 5min, 30min, 2h, 12h (max 5 tentativas).';

-- ── 2. Indexes ──────────────────────────────────────────────────────────────
CREATE INDEX idx_dead_letter_retry
  ON omni_delivery_dead_letter (status, next_retry_at)
  WHERE status = 'pending';

CREATE INDEX idx_dead_letter_message
  ON omni_delivery_dead_letter (message_id);

-- ── 3. RLS ──────────────────────────────────────────────────────────────────
ALTER TABLE omni_delivery_dead_letter ENABLE ROW LEVEL SECURITY;

-- Leitura: qualquer usuário autenticado ativo
DROP POLICY IF EXISTS "omni_dead_letter_read" ON omni_delivery_dead_letter;
CREATE POLICY "omni_dead_letter_read"
  ON omni_delivery_dead_letter FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND active = true
        AND deleted_at IS NULL
    )
  );

-- Update: gestor ou super_admin (para "Retry Now" manual)
DROP POLICY IF EXISTS "omni_dead_letter_update" ON omni_delivery_dead_letter;
CREATE POLICY "omni_dead_letter_update"
  ON omni_delivery_dead_letter FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  );

-- ── 4. Trigger updated_at ──────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION set_dead_letter_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER trg_dead_letter_updated_at
  BEFORE UPDATE ON omni_delivery_dead_letter
  FOR EACH ROW EXECUTE FUNCTION set_dead_letter_updated_at();


-- ---------------------------------------------------------------------------
-- Migration: 20260318100003_omni_retry_dead_letter_cron.sql
-- ---------------------------------------------------------------------------

-- OMNI PRO™ Dead-Letter Retry — pg_cron Schedule
-- Epic: EPIC-OMNI-PRO-V2 | Story: OP-04
-- Runs every 5 minutes to retry failed deliveries

-- ── 1. PL/pgSQL function ─────────────────────────────────────────────────────
CREATE OR REPLACE FUNCTION trigger_omni_retry_dead_letter()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  supabase_url  text;
  svc_key       text;
BEGIN
  SELECT value INTO supabase_url FROM _app_config WHERE key = 'supabase_url';
  SELECT value INTO svc_key      FROM _app_config WHERE key = 'service_role_key';

  IF supabase_url IS NULL OR svc_key IS NULL THEN
    RAISE WARNING 'trigger_omni_retry_dead_letter: _app_config missing';
    RETURN;
  END IF;

  -- Only trigger if there are entries ready for retry
  IF NOT EXISTS (
    SELECT 1 FROM omni_delivery_dead_letter
    WHERE status = 'pending'
      AND next_retry_at <= now()
    LIMIT 1
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := supabase_url || '/functions/v1/omni-retry-dead-letter',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || svc_key
    ),
    body    := '{"trigger":"cron"}'::jsonb
  );
END;
$$;

COMMENT ON FUNCTION trigger_omni_retry_dead_letter() IS
  'Disparada pelo pg_cron a cada 5 minutos. '
  'Só chama a edge function se houver dead-letter entries prontas para retry.';

-- ── 2. Remover job anterior se existir ──────────────────────────────────────
SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'omni-retry-dead-letter';

-- ── 3. Agendar a cada 5 minutos ────────────────────────────────────────────
SELECT cron.schedule(
  'omni-retry-dead-letter',
  '*/5 * * * *',
  $$ SELECT trigger_omni_retry_dead_letter(); $$
);


