-- ============================================================
-- Task 5: Trigger function + trigger on leads stage change
-- ============================================================
CREATE OR REPLACE FUNCTION public.fn_queue_conversion_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_person record;
  v_email_hash text;
  v_phone_hash text;
  v_lead_user_id uuid;
BEGIN
  -- Resolve the owner (user_id) of this lead via settings_users
  SELECT su.auth_user_id INTO v_lead_user_id
  FROM public.settings_users su
  WHERE su.id = NEW.user_id;

  -- If no user found, try the lead's team or skip
  IF v_lead_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Fetch person data for hashing
  IF NEW.people_id IS NOT NULL THEN
    SELECT email, whatsapp INTO v_person
    FROM public.clients_people
    WHERE id = NEW.people_id;

    -- SHA-256 hashes for Meta CAPI + Google Enhanced Conversions
    IF v_person.email IS NOT NULL AND v_person.email <> '' THEN
      v_email_hash := encode(
        digest(lower(trim(v_person.email)), 'sha256'), 'hex'
      );
    END IF;

    IF v_person.whatsapp IS NOT NULL AND v_person.whatsapp <> '' THEN
      v_phone_hash := encode(
        digest(regexp_replace(v_person.whatsapp, '[^0-9+]', '', 'g'), 'sha256'), 'hex'
      );
    END IF;
  END IF;

  INSERT INTO public.conversion_events_queue (
    user_id,
    lead_id,
    stage_id,
    lead_source,
    event_data
  ) VALUES (
    v_lead_user_id,
    NEW.id,
    NEW.leads_stages_id,
    COALESCE(NEW.lead_source, 'unknown'),
    jsonb_build_object(
      'gclid',        NEW.gclid,
      'fbclid',       NEW.fbclid,
      'fbc',          NEW.fbc,
      'fbp',          NEW.fbp,
      'fb_lead_id',   NEW.fb_lead_id,
      'email_hash',   v_email_hash,
      'phone_hash',   v_phone_hash,
      'value',        NEW.value,
      'old_stage_id', OLD.leads_stages_id::text,
      'new_stage_id', NEW.leads_stages_id::text,
      'timestamp',    extract(epoch from now())::bigint
    )
  );

  -- Fire-and-forget: invoke conversion-send edge function via pg_net
  PERFORM net.http_post(
    url := current_setting('app.settings.supabase_url', true) || '/functions/v1/conversion-send',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
    ),
    body := '{}'::jsonb
  );

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    -- pg_net failure should never block the lead stage update
    RETURN NEW;
END;
$$;

-- Drop existing trigger if any, then create
DROP TRIGGER IF EXISTS trg_conversion_on_stage_change ON public.leads;

CREATE TRIGGER trg_conversion_on_stage_change
  AFTER UPDATE ON public.leads
  FOR EACH ROW
  WHEN (OLD.leads_stages_id IS DISTINCT FROM NEW.leads_stages_id)
  EXECUTE FUNCTION public.fn_queue_conversion_event();

-- ============================================================
-- Task 14: Cron job for retry processing (every 5 minutes)
-- Catches events where pg_net failed or API returned error
-- ============================================================
SELECT cron.schedule(
  'conversion-send-retry',
  '*/5 * * * *',
  $$
  SELECT net.http_post(
    url := current_setting('app.settings.supabase_url', true) || '/functions/v1/conversion-send',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
    ),
    body := '{}'::jsonb
  );
  $$
);


-- ---------------------------------------------------------------------------
-- Migration: 20260318900000_fix_followup_trigger_lead_id.sql
-- ---------------------------------------------------------------------------

-- ══════════════════════════════════════════════════════════════════════════════
-- Fix: handle_meeting_followup_queue() references 'leads_id' but column was
-- renamed to 'lead_id' in P6 FK consistency migration (20260227140000).
-- Error: column "leads_id" of relation "meeting_followup_queue" does not exist
-- ══════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.handle_meeting_followup_queue()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status    text;
  rule_rec    record;
  delay_secs  bigint;
  v_scheduled timestamptz;
BEGIN
  -- Skip if status didn't change on UPDATE
  IF (TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  -- Normalize meetings.status → meetings_followups.meeting_status
  v_status := CASE NEW.status
    WHEN 'agendada'       THEN 'agendado'
    WHEN 'compareceu'     THEN 'compareceu'
    WHEN 'nao_compareceu' THEN 'nao_compareceu'
    WHEN 'cancelado'      THEN 'cancelado'
    WHEN 'realizado'      THEN 'realizado'
    ELSE NEW.status
  END;

  -- Cancel existing pending queue entries for this meeting (status changed)
  IF TG_OP = 'UPDATE' THEN
    UPDATE public.meeting_followup_queue
       SET status = 'cancelled'
     WHERE meeting_id = NEW.id
       AND status = 'pending';
  END IF;

  -- Create queue entry for each active rule matching the new status
  -- Now accepts rules with webhook_url OR whatsapp_template_id
  FOR rule_rec IN
    SELECT id, channel, webhook_url, message, days, hours, minutes, whatsapp_template_id
      FROM public.meetings_followups
     WHERE active = true
       AND meeting_status = v_status
       AND (
         (webhook_url IS NOT NULL AND webhook_url <> '')
         OR whatsapp_template_id IS NOT NULL
       )
  LOOP
    delay_secs := (
      COALESCE(rule_rec.days, 0)    * 86400 +
      COALESCE(rule_rec.hours, 0)   * 3600  +
      COALESCE(rule_rec.minutes, 0) * 60
    )::bigint;

    -- For 'agendado' status: schedule BEFORE the meeting (start_time - delay)
    -- For all other statuses: schedule AFTER now (now + delay)
    IF v_status = 'agendado' AND NEW.start_time IS NOT NULL THEN
      v_scheduled := NEW.start_time - (delay_secs * interval '1 second');
      -- If the calculated time is in the past, schedule immediately
      IF v_scheduled < now() THEN
        v_scheduled := now();
      END IF;
    ELSE
      v_scheduled := now() + (delay_secs * interval '1 second');
    END IF;

    INSERT INTO public.meeting_followup_queue (
      rule_id, meeting_id, people_id, lead_id,
      scheduled_for, channel, webhook_url, message_snapshot, template_id
    ) VALUES (
      rule_rec.id,
      NEW.id,
      NEW.people_id,
      NEW.lead_id,
      v_scheduled,
      rule_rec.channel,
      rule_rec.webhook_url,
      rule_rec.message,
      rule_rec.whatsapp_template_id
    );
  END LOOP;

  RETURN NEW;
END;
$$;


