BEGIN
  SELECT id INTO v_agent_id
  FROM public.ai_agents
  WHERE is_template = true AND template_type = 'qualificacao'
  LIMIT 1;

  IF v_agent_id IS NULL THEN
    RAISE NOTICE '[Prompt-v2] Template qualificação não encontrado — pulando.';
  ELSE
    RAISE NOTICE '[Prompt-v2] Atualizando template qualificação para v2: %', v_agent_id;

    UPDATE public.ai_agents
    SET
      identity        = v_identity,
      general_rules   = v_general_rules,
      input_data      = v_input_data,
      current_version = current_version + 1,
      updated_at      = NOW()
    WHERE id = v_agent_id;

    -- Replace step with v2
    DELETE FROM public.ai_agents_steps WHERE ai_agent_id = v_agent_id;

    INSERT INTO public.ai_agents_steps (
      id, ai_agent_id, name, prompt, control, order_index, active, created_at, updated_at
    ) VALUES (
      gen_random_uuid(), v_agent_id, 'Qualificação v2', v_step_prompt, '1', 1, true, NOW(), NOW()
    );

    -- Version history
    INSERT INTO public.ai_agents_history (
      id, ai_agent_id, version, data, changelog, created_at
    ) VALUES (
      gen_random_uuid(),
      v_agent_id,
      (SELECT current_version FROM public.ai_agents WHERE id = v_agent_id),
      jsonb_build_object(
        'identity', v_identity,
        'general_rules', v_general_rules,
        'input_data', v_input_data
      ),
      jsonb_build_object(
        'resumo', 'Prompt v2: proteção dados sensíveis, abertura contextual obrigatória, remoção redundâncias, progressão adaptativa',
        'areas_alteradas', jsonb_build_array('identidade', 'regras_gerais', 'dados_entrada', 'etapa_prompt'),
        'detalhes', jsonb_build_object(
          'dados_confidenciais', 'Bloco NUNCA CITAR — score, faturamento, valor, DISC protegidos',
          'abertura', 'Abertura genérica PROIBIDA quando objetivo/momento/empresa preenchidos. 5 regras com prioridade. Exemplo real incluído.',
          'runtime_fix', 'lp-submit agora salva goal/moment. ai-agent-execute agora resolve score category names e empresa via junction.',
          'redundancias', 'Regras duplicadas removidas (~200 tokens economizados)',
          'progressao', 'Avanço adaptativo: q1 + 1 campo suficiente',
          'anti_patterns', 'Proibido: "Sou o clone IA do João", "O que te trouxe aqui?" com contexto, eco analítico'
        ),
        'timestamp', NOW()
      ),
      NOW()
    );

    RAISE NOTICE '[Prompt-v2] Template qualificação atualizado com sucesso.';
  END IF;
END;
$migration$;


