BEGIN
  -- Find the PRODUCTION agent (NOT template)
  SELECT id INTO v_agent_id
  FROM public.ai_agents
  WHERE is_template = false AND name ILIKE '%iagnos%'
  LIMIT 1;

  IF v_agent_id IS NULL THEN
    RAISE NOTICE '[Prompt-v2-prod] Production Diagnóstico agent not found — pulando.';
  ELSE
    RAISE NOTICE '[Prompt-v2-prod] Updating PRODUCTION Diagnóstico agent: %', v_agent_id;

    UPDATE public.ai_agents
    SET
      identity        = v_identity,
      general_rules   = v_general_rules,
      input_data      = v_input_data,
      current_version = current_version + 1,
      updated_at      = NOW()
    WHERE id = v_agent_id;

    -- Replace steps with v2
    DELETE FROM public.ai_agents_steps WHERE ai_agent_id = v_agent_id;

    INSERT INTO public.ai_agents_steps (
      id, ai_agent_id, name, prompt, control, order_index, active, created_at, updated_at
    ) VALUES (
      gen_random_uuid(), v_agent_id, 'Qualificação v2', v_step_prompt, '1', 1, true, NOW(), NOW()
    );

    -- Version history
    INSERT INTO public.ai_agents_history (
      id, ai_agent_id, version, data, changelog, created_at
    ) VALUES (
      gen_random_uuid(),
      v_agent_id,
      (SELECT current_version FROM public.ai_agents WHERE id = v_agent_id),
      jsonb_build_object(
        'identity', v_identity,
        'general_rules', v_general_rules,
        'input_data', v_input_data
      ),
      jsonb_build_object(
        'resumo', 'Propagate v2 prompt to PRODUCTION agent (was only on template)',
        'fix', 'Previous migration 20260319300000 only updated is_template=true, production agent was still on v1',
        'timestamp', NOW()
      ),
      NOW()
    );

    RAISE NOTICE '[Prompt-v2-prod] Production Diagnóstico agent updated successfully.';
  END IF;
END;
