-- ---------------------------------------------------------------------------
-- Migration: 20260319500000_fix_track_leads_changes_schema_mismatch.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- FIX: P6 column rename aftermath — 3 broken trigger functions
-- =============================================================================
-- Migration 20260227140000 (P6) renamed columns:
--   leads.users_id → user_id
--   leads_updates.leads_id → lead_id
--   leads_updates.users_id → user_id
--   meetings.leads_id → lead_id
--
-- 3 trigger functions were NOT updated:
--   1. track_leads_changes() — inserts with old column names into leads_updates
--   2. fn_queue_conversion_event() — references NEW.users_id on leads table
--   3. fn_queue_conversion_booking() — references NEW.leads_id on meetings table
--
-- Impact: ALL updates to leads table fail (stage, value, status, etc.)
-- =============================================================================


-- ============================================================
-- FIX 1: track_leads_changes() — PRIMARY BLOCKER
-- Old function referenced: leads_id, changed_by, changed_at,
-- field_name, old_value, new_value, change_type
-- Current leads_updates schema: lead_id, user_id, from_stage_id,
-- to_stage_id, notes, created_at
-- ============================================================

CREATE OR REPLACE FUNCTION public.track_leads_changes()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Track stage changes with from/to stage IDs
    IF OLD.leads_stages_id IS DISTINCT FROM NEW.leads_stages_id THEN
      INSERT INTO leads_updates (
        lead_id,
        user_id,
        from_stage_id,
        to_stage_id,
        notes,
        created_at
      ) VALUES (
        NEW.id,
        (SELECT id FROM settings_users WHERE auth_user_id = auth.uid() LIMIT 1),
        OLD.leads_stages_id,
        NEW.leads_stages_id,
        'stage_change',
        NOW()
      );
    END IF;

    -- Track status changes
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      INSERT INTO leads_updates (
        lead_id,
        user_id,
        notes,
        created_at
      ) VALUES (
        NEW.id,
        (SELECT id FROM settings_users WHERE auth_user_id = auth.uid() LIMIT 1),
        'status_change: ' || COALESCE(OLD.status, 'null') || ' → ' || COALESCE(NEW.status, 'null'),
        NOW()
      );
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- NEVER block lead updates due to audit trail failures
  RAISE WARNING 'track_leads_changes failed: %', SQLERRM;
  RETURN NEW;
END;
$function$;


-- ============================================================
-- FIX 2: fn_queue_conversion_event() — NEW.users_id → NEW.user_id
-- Also add outer EXCEPTION to never block lead updates
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_queue_conversion_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_person record;
  v_email_hash text;
  v_phone_hash text;
  v_lead_user_id uuid;
  v_rule record;
  v_event_type text;
BEGIN
  -- Resolve the owner (user_id) of this lead via settings_users
  -- FIX: was NEW.users_id, column renamed to user_id by P6
  SELECT su.auth_user_id INTO v_lead_user_id
  FROM public.settings_users su
  WHERE su.id = NEW.user_id;

  IF v_lead_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Determine event type
  IF TG_ARGV[0] = 'stage_change' THEN
    v_event_type := 'stage_enter';
  ELSIF TG_ARGV[0] = 'lead_won' THEN
    v_event_type := 'lead_won';
  ELSIF TG_ARGV[0] = 'lead_lost' THEN
    v_event_type := 'lead_lost';
  ELSE
    v_event_type := 'stage_enter';
  END IF;

  -- Fetch person data for hashing
  IF NEW.people_id IS NOT NULL THEN
    SELECT email, whatsapp INTO v_person
    FROM public.clients_people
    WHERE id = NEW.people_id;

    IF v_person.email IS NOT NULL AND v_person.email <> '' THEN
      v_email_hash := encode(digest(lower(trim(v_person.email)), 'sha256'), 'hex');
    END IF;
    IF v_person.whatsapp IS NOT NULL AND v_person.whatsapp <> '' THEN
      v_phone_hash := encode(digest(regexp_replace(v_person.whatsapp, '[^0-9+]', '', 'g'), 'sha256'), 'hex');
    END IF;
  END IF;

  -- Find matching rules
  FOR v_rule IN
    SELECT id, name, trigger_type, trigger_config, meta_enabled, meta_event_name, meta_send_value,
           google_enabled, google_conversion_action_id, google_send_value, google_currency,
           meta_pixel_id, google_account_id
    FROM public.conversion_event_rules
    WHERE user_id = v_lead_user_id
      AND active = true
      AND (meta_enabled = true OR google_enabled = true)
      AND trigger_type = v_event_type
  LOOP
    -- Check trigger_config match
    IF v_event_type = 'stage_enter' AND (v_rule.trigger_config->>'stage_id') IS NOT NULL THEN
      IF (v_rule.trigger_config->>'stage_id') <> NEW.leads_stages_id::text THEN
        CONTINUE;
      END IF;
    END IF;

    -- Insert queue entry for this matched rule
    INSERT INTO public.conversion_events_queue (
      user_id, lead_id, stage_id, lead_source, event_data,
      meta_status, google_status
    ) VALUES (
      v_lead_user_id,
      NEW.id,
      NEW.leads_stages_id,
      COALESCE(NEW.lead_source, 'unknown'),
      jsonb_build_object(
        'rule_id',      v_rule.id::text,
        'rule_name',    v_rule.name,
        'trigger_type', v_rule.trigger_type,
        'gclid',        NEW.gclid,
        'fbclid',       NEW.fbclid,
        'fbc',          NEW.fbc,
        'fbp',          NEW.fbp,
        'fb_lead_id',   NEW.fb_lead_id,
        'email_hash',   v_email_hash,
        'phone_hash',   v_phone_hash,
        'value',        NEW.value,
        'timestamp',    extract(epoch from now())::bigint,
        -- Meta-specific
        'meta_pixel_id',     v_rule.meta_pixel_id,
        'meta_event_name',   v_rule.meta_event_name,
        'meta_send_value',   v_rule.meta_send_value,
        -- Google-specific
        'google_account_id',           v_rule.google_account_id,
        'google_conversion_action_id', v_rule.google_conversion_action_id,
        'google_send_value',           v_rule.google_send_value,
        'google_currency',             v_rule.google_currency
      ),
      CASE WHEN v_rule.meta_enabled THEN 'pending' ELSE 'skipped' END,
      CASE WHEN v_rule.google_enabled THEN 'pending' ELSE 'skipped' END
    );
  END LOOP;

  -- Fire-and-forget: invoke conversion-send edge function
  BEGIN
    PERFORM net.http_post(
      url := current_setting('app.settings.supabase_url', true) || '/functions/v1/conversion-send',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
      ),
      body := '{}'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- Never block lead updates
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Outer safety net: NEVER block lead updates due to conversion tracking
  RAISE WARNING 'fn_queue_conversion_event failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


-- ============================================================
-- FIX 3: fn_queue_conversion_booking() — NEW.leads_id → NEW.lead_id
-- meetings.leads_id was renamed to lead_id by P6
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_queue_conversion_booking()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_lead record;
  v_person record;
  v_email_hash text;
  v_phone_hash text;
  v_lead_user_id uuid;
  v_rule record;
  v_normalized_status text;
BEGIN
  -- Normalize status
  v_normalized_status := CASE NEW.status
    WHEN 'agendada'   THEN 'agendado'
    WHEN 'cancelada'  THEN 'cancelado'
    WHEN 'realizada'  THEN 'compareceu'
    ELSE NEW.status
  END;

  -- Get the lead associated with this meeting
  -- FIX: was NEW.leads_id, column renamed to lead_id by P6
  SELECT l.*, su.auth_user_id AS owner_user_id INTO v_lead
  FROM public.leads l
  LEFT JOIN public.settings_users su ON su.id = l.user_id
  WHERE l.id = NEW.lead_id;

  IF v_lead IS NULL OR v_lead.owner_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_lead_user_id := v_lead.owner_user_id;

  -- Hash person data
  IF v_lead.people_id IS NOT NULL THEN
    SELECT email, whatsapp INTO v_person
    FROM public.clients_people WHERE id = v_lead.people_id;

    IF v_person.email IS NOT NULL AND v_person.email <> '' THEN
      v_email_hash := encode(digest(lower(trim(v_person.email)), 'sha256'), 'hex');
    END IF;
    IF v_person.whatsapp IS NOT NULL AND v_person.whatsapp <> '' THEN
      v_phone_hash := encode(digest(regexp_replace(v_person.whatsapp, '[^0-9+]', '', 'g'), 'sha256'), 'hex');
    END IF;
  END IF;

  -- Find matching booking_status rules
  FOR v_rule IN
    SELECT *
    FROM public.conversion_event_rules
    WHERE user_id = v_lead_user_id
      AND active = true
      AND trigger_type = 'booking_status'
      AND (meta_enabled = true OR google_enabled = true)
      AND (trigger_config->>'status') = v_normalized_status
  LOOP
    INSERT INTO public.conversion_events_queue (
      user_id, lead_id, stage_id, lead_source, event_data,
      meta_status, google_status
    ) VALUES (
      v_lead_user_id,
      v_lead.id,
      v_lead.leads_stages_id,
      COALESCE(v_lead.lead_source, 'unknown'),
      jsonb_build_object(
        'rule_id',        v_rule.id::text,
        'rule_name',      v_rule.name,
        'trigger_type',   'booking_status',
        'booking_status', v_normalized_status,
        'meeting_id',     NEW.id::text,
        'gclid',          v_lead.gclid,
        'fbclid',         v_lead.fbclid,
        'fbc',            v_lead.fbc,
        'fbp',            v_lead.fbp,
        'fb_lead_id',     v_lead.fb_lead_id,
        'email_hash',     v_email_hash,
        'phone_hash',     v_phone_hash,
        'value',          v_lead.value,
        'timestamp',      extract(epoch from now())::bigint,
        'meta_pixel_id',               v_rule.meta_pixel_id,
        'meta_event_name',             v_rule.meta_event_name,
        'meta_send_value',             v_rule.meta_send_value,
        'google_account_id',           v_rule.google_account_id,
        'google_conversion_action_id', v_rule.google_conversion_action_id,
        'google_send_value',           v_rule.google_send_value,
        'google_currency',             v_rule.google_currency
      ),
      CASE WHEN v_rule.meta_enabled THEN 'pending' ELSE 'skipped' END,
      CASE WHEN v_rule.google_enabled THEN 'pending' ELSE 'skipped' END
    );
  END LOOP;

  -- Fire conversion-send
  BEGIN
    PERFORM net.http_post(
      url := current_setting('app.settings.supabase_url', true) || '/functions/v1/conversion-send',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
      ),
      body := '{}'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Outer safety net: NEVER block meeting updates due to conversion tracking
  RAISE WARNING 'fn_queue_conversion_booking failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260319500000-fix_track_leads_changes_schema_mismatch-ok.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- FIX: P6 column rename aftermath — 3 broken trigger functions
-- =============================================================================
-- Migration 20260227140000 (P6) renamed columns:
--   leads.users_id → user_id
--   leads_updates.leads_id → lead_id
--   leads_updates.users_id → user_id
--   meetings.leads_id → lead_id
--
-- 3 trigger functions were NOT updated:
--   1. track_leads_changes() — inserts with old column names into leads_updates
--   2. fn_queue_conversion_event() — references NEW.users_id on leads table
--   3. fn_queue_conversion_booking() — references NEW.leads_id on meetings table
--
-- Impact: ALL updates to leads table fail (stage, value, status, etc.)
-- =============================================================================


-- ============================================================
-- FIX 1: track_leads_changes() — PRIMARY BLOCKER
-- Old function referenced: leads_id, changed_by, changed_at,
-- field_name, old_value, new_value, change_type
-- Current leads_updates schema: lead_id, user_id, from_stage_id,
-- to_stage_id, notes, created_at
-- ============================================================

CREATE OR REPLACE FUNCTION public.track_leads_changes()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Track stage changes with from/to stage IDs
    IF OLD.leads_stages_id IS DISTINCT FROM NEW.leads_stages_id THEN
      INSERT INTO leads_updates (
        lead_id,
        user_id,
        from_stage_id,
        to_stage_id,
        notes,
        created_at
      ) VALUES (
        NEW.id,
        (SELECT id FROM settings_users WHERE auth_user_id = auth.uid() LIMIT 1),
        OLD.leads_stages_id,
        NEW.leads_stages_id,
        'stage_change',
        NOW()
      );
    END IF;

    -- Track status changes
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      INSERT INTO leads_updates (
        lead_id,
        user_id,
        notes,
        created_at
      ) VALUES (
        NEW.id,
        (SELECT id FROM settings_users WHERE auth_user_id = auth.uid() LIMIT 1),
        'status_change: ' || COALESCE(OLD.status, 'null') || ' → ' || COALESCE(NEW.status, 'null'),
        NOW()
      );
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- NEVER block lead updates due to audit trail failures
  RAISE WARNING 'track_leads_changes failed: %', SQLERRM;
  RETURN NEW;
END;
$function$;


-- ============================================================
-- FIX 2: fn_queue_conversion_event() — NEW.users_id → NEW.user_id
-- Also add outer EXCEPTION to never block lead updates
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_queue_conversion_event()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_person record;
  v_email_hash text;
  v_phone_hash text;
  v_lead_user_id uuid;
  v_rule record;
  v_event_type text;
BEGIN
  -- Resolve the owner (user_id) of this lead via settings_users
  -- FIX: was NEW.users_id, column renamed to user_id by P6
  SELECT su.auth_user_id INTO v_lead_user_id
  FROM public.settings_users su
  WHERE su.id = NEW.user_id;

  IF v_lead_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Determine event type
  IF TG_ARGV[0] = 'stage_change' THEN
    v_event_type := 'stage_enter';
  ELSIF TG_ARGV[0] = 'lead_won' THEN
    v_event_type := 'lead_won';
  ELSIF TG_ARGV[0] = 'lead_lost' THEN
    v_event_type := 'lead_lost';
  ELSE
    v_event_type := 'stage_enter';
  END IF;

  -- Fetch person data for hashing
  IF NEW.people_id IS NOT NULL THEN
    SELECT email, whatsapp INTO v_person
    FROM public.clients_people
    WHERE id = NEW.people_id;

    IF v_person.email IS NOT NULL AND v_person.email <> '' THEN
      v_email_hash := encode(digest(lower(trim(v_person.email)), 'sha256'), 'hex');
    END IF;
    IF v_person.whatsapp IS NOT NULL AND v_person.whatsapp <> '' THEN
      v_phone_hash := encode(digest(regexp_replace(v_person.whatsapp, '[^0-9+]', '', 'g'), 'sha256'), 'hex');
    END IF;
  END IF;

  -- Find matching rules
  FOR v_rule IN
    SELECT id, name, trigger_type, trigger_config, meta_enabled, meta_event_name, meta_send_value,
           google_enabled, google_conversion_action_id, google_send_value, google_currency,
           meta_pixel_id, google_account_id
    FROM public.conversion_event_rules
    WHERE user_id = v_lead_user_id
      AND active = true
      AND (meta_enabled = true OR google_enabled = true)
      AND trigger_type = v_event_type
  LOOP
    -- Check trigger_config match
    IF v_event_type = 'stage_enter' AND (v_rule.trigger_config->>'stage_id') IS NOT NULL THEN
      IF (v_rule.trigger_config->>'stage_id') <> NEW.leads_stages_id::text THEN
        CONTINUE;
      END IF;
    END IF;

    -- Insert queue entry for this matched rule
    INSERT INTO public.conversion_events_queue (
      user_id, lead_id, stage_id, lead_source, event_data,
      meta_status, google_status
    ) VALUES (
      v_lead_user_id,
      NEW.id,
      NEW.leads_stages_id,
      COALESCE(NEW.lead_source, 'unknown'),
      jsonb_build_object(
        'rule_id',      v_rule.id::text,
        'rule_name',    v_rule.name,
        'trigger_type', v_rule.trigger_type,
        'gclid',        NEW.gclid,
        'fbclid',       NEW.fbclid,
        'fbc',          NEW.fbc,
        'fbp',          NEW.fbp,
        'fb_lead_id',   NEW.fb_lead_id,
        'email_hash',   v_email_hash,
        'phone_hash',   v_phone_hash,
        'value',        NEW.value,
        'timestamp',    extract(epoch from now())::bigint,
        -- Meta-specific
        'meta_pixel_id',     v_rule.meta_pixel_id,
        'meta_event_name',   v_rule.meta_event_name,
        'meta_send_value',   v_rule.meta_send_value,
        -- Google-specific
        'google_account_id',           v_rule.google_account_id,
        'google_conversion_action_id', v_rule.google_conversion_action_id,
        'google_send_value',           v_rule.google_send_value,
        'google_currency',             v_rule.google_currency
      ),
      CASE WHEN v_rule.meta_enabled THEN 'pending' ELSE 'skipped' END,
      CASE WHEN v_rule.google_enabled THEN 'pending' ELSE 'skipped' END
    );
  END LOOP;

  -- Fire-and-forget: invoke conversion-send edge function
  BEGIN
    PERFORM net.http_post(
      url := current_setting('app.settings.supabase_url', true) || '/functions/v1/conversion-send',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
      ),
      body := '{}'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN
    NULL; -- Never block lead updates
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Outer safety net: NEVER block lead updates due to conversion tracking
  RAISE WARNING 'fn_queue_conversion_event failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


-- ============================================================
-- FIX 3: fn_queue_conversion_booking() — NEW.leads_id → NEW.lead_id
-- meetings.leads_id was renamed to lead_id by P6
-- ============================================================

CREATE OR REPLACE FUNCTION public.fn_queue_conversion_booking()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_lead record;
  v_person record;
  v_email_hash text;
  v_phone_hash text;
  v_lead_user_id uuid;
  v_rule record;
  v_normalized_status text;
BEGIN
  -- Normalize status
  v_normalized_status := CASE NEW.status
    WHEN 'agendada'   THEN 'agendado'
    WHEN 'cancelada'  THEN 'cancelado'
    WHEN 'realizada'  THEN 'compareceu'
    ELSE NEW.status
  END;

  -- Get the lead associated with this meeting
  -- FIX: was NEW.leads_id, column renamed to lead_id by P6
  SELECT l.*, su.auth_user_id AS owner_user_id INTO v_lead
  FROM public.leads l
  LEFT JOIN public.settings_users su ON su.id = l.user_id
  WHERE l.id = NEW.lead_id;

  IF v_lead IS NULL OR v_lead.owner_user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_lead_user_id := v_lead.owner_user_id;

  -- Hash person data
  IF v_lead.people_id IS NOT NULL THEN
    SELECT email, whatsapp INTO v_person
    FROM public.clients_people WHERE id = v_lead.people_id;

    IF v_person.email IS NOT NULL AND v_person.email <> '' THEN
      v_email_hash := encode(digest(lower(trim(v_person.email)), 'sha256'), 'hex');
    END IF;
    IF v_person.whatsapp IS NOT NULL AND v_person.whatsapp <> '' THEN
      v_phone_hash := encode(digest(regexp_replace(v_person.whatsapp, '[^0-9+]', '', 'g'), 'sha256'), 'hex');
    END IF;
  END IF;

  -- Find matching booking_status rules
  FOR v_rule IN
    SELECT *
    FROM public.conversion_event_rules
    WHERE user_id = v_lead_user_id
      AND active = true
      AND trigger_type = 'booking_status'
      AND (meta_enabled = true OR google_enabled = true)
      AND (trigger_config->>'status') = v_normalized_status
  LOOP
    INSERT INTO public.conversion_events_queue (
      user_id, lead_id, stage_id, lead_source, event_data,
      meta_status, google_status
    ) VALUES (
      v_lead_user_id,
      v_lead.id,
      v_lead.leads_stages_id,
      COALESCE(v_lead.lead_source, 'unknown'),
      jsonb_build_object(
        'rule_id',        v_rule.id::text,
        'rule_name',      v_rule.name,
        'trigger_type',   'booking_status',
        'booking_status', v_normalized_status,
        'meeting_id',     NEW.id::text,
        'gclid',          v_lead.gclid,
        'fbclid',         v_lead.fbclid,
        'fbc',            v_lead.fbc,
        'fbp',            v_lead.fbp,
        'fb_lead_id',     v_lead.fb_lead_id,
        'email_hash',     v_email_hash,
        'phone_hash',     v_phone_hash,
        'value',          v_lead.value,
        'timestamp',      extract(epoch from now())::bigint,
        'meta_pixel_id',               v_rule.meta_pixel_id,
        'meta_event_name',             v_rule.meta_event_name,
        'meta_send_value',             v_rule.meta_send_value,
        'google_account_id',           v_rule.google_account_id,
        'google_conversion_action_id', v_rule.google_conversion_action_id,
        'google_send_value',           v_rule.google_send_value,
        'google_currency',             v_rule.google_currency
      ),
      CASE WHEN v_rule.meta_enabled THEN 'pending' ELSE 'skipped' END,
      CASE WHEN v_rule.google_enabled THEN 'pending' ELSE 'skipped' END
    );
  END LOOP;

  -- Fire conversion-send
  BEGIN
    PERFORM net.http_post(
      url := current_setting('app.settings.supabase_url', true) || '/functions/v1/conversion-send',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || current_setting('app.settings.service_role_key', true)
      ),
      body := '{}'::jsonb
    );
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Outer safety net: NEVER block meeting updates due to conversion tracking
  RAISE WARNING 'fn_queue_conversion_booking failed: %', SQLERRM;
  RETURN NEW;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260319600000_voice_agents_mvp_agent_type.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- Voice Agents MVP — Story VA-01: agent_type + voice config fields
-- Epic: VOICE-AGENTS-MVP
-- PRD: docs/prd/VOICE-AGENTS-MVP.md (Section 5)
--
-- Adds agent_type ('text'|'voice') pivot column to ai_agents,
-- plus voice configuration fields for ElevenLabs Conversational AI sync.
--
-- Zero breaking changes: default 'text' preserves all existing agents.
-- Builds on top of EL-01 (20260319100000_elevenlabs_infrastructure.sql)
-- which already added: voice_enabled, voice_id, elevenlabs_agent_id
-- =============================================================================

-- ─── 1. Pivot column: agent_type ────────────────────────────────────────────

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS agent_type text DEFAULT 'text';

-- Add CHECK constraint separately (IF NOT EXISTS not supported for constraints)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'ai_agents_agent_type_check'
      AND conrelid = 'public.ai_agents'::regclass
  ) THEN
    ALTER TABLE public.ai_agents
      ADD CONSTRAINT ai_agents_agent_type_check
      CHECK (agent_type IN ('text', 'voice'));
  END IF;
END $$;

COMMENT ON COLUMN public.ai_agents.agent_type IS 'Agent type: text (default, current behavior) or voice (ElevenLabs Conversational AI)';

-- ─── 2. Voice configuration fields ─────────────────────────────────────────

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS voice_first_message text;

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS voice_language text DEFAULT 'pt';

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS voice_model_id text;

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS voice_stability real DEFAULT 0.5;

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS voice_similarity real DEFAULT 0.75;

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS voice_speed real DEFAULT 1.0;

COMMENT ON COLUMN public.ai_agents.voice_first_message IS 'Initial greeting for voice agent (what it says when answering)';
COMMENT ON COLUMN public.ai_agents.voice_language IS 'Language code for voice conversations (pt, en, es, etc.)';
COMMENT ON COLUMN public.ai_agents.voice_model_id IS 'ElevenLabs TTS model override (null = use default from settings_elevenlabs)';
COMMENT ON COLUMN public.ai_agents.voice_stability IS 'Voice stability 0.0-1.0 (higher = more consistent)';
COMMENT ON COLUMN public.ai_agents.voice_similarity IS 'Voice similarity boost 0.0-1.0 (higher = more faithful to original)';
COMMENT ON COLUMN public.ai_agents.voice_speed IS 'Voice speed 0.5-2.0 (1.0 = normal)';

-- ─── 3. ElevenLabs sync tracking ───────────────────────────────────────────

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS el_sync_status text DEFAULT 'not_applicable';

-- Add CHECK constraint separately
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'ai_agents_el_sync_status_check'
      AND conrelid = 'public.ai_agents'::regclass
  ) THEN
    ALTER TABLE public.ai_agents
      ADD CONSTRAINT ai_agents_el_sync_status_check
      CHECK (el_sync_status IN ('pending', 'synced', 'error', 'not_applicable'));
  END IF;
END $$;

ALTER TABLE public.ai_agents
  ADD COLUMN IF NOT EXISTS el_last_synced_at timestamptz;

COMMENT ON COLUMN public.ai_agents.el_sync_status IS 'ElevenLabs sync status: not_applicable (text agents), pending, synced, error';
COMMENT ON COLUMN public.ai_agents.el_last_synced_at IS 'Timestamp of last successful sync with ElevenLabs API';


-- ---------------------------------------------------------------------------
-- Migration: 20260319700000_backfill_meta_leadgen_attribution.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Backfill: Meta Lead Ad attribution for pre-existing submissions
--
-- Problem: Leads imported via Meta Lead Ads BEFORE the conversion_tracking_schema
-- migration (20260318800000) have meta_leadgen_id = NULL in form_pro_submissions
-- and fb_lead_id = NULL in leads. The BI PRO attribution hook relies on these
-- columns to detect Meta Lead Ad leads and assign them to campaigns.
--
-- Signal: The webhook (meta-inbound) ALWAYS stored _source and _leadgen_id
-- inside the jsonb `data` column, even before dedicated columns existed.
--
-- This migration:
--   1. Fixes source='site' → 'meta' for Meta Lead Ad submissions
--   2. Populates meta_leadgen_id from data->>'_leadgen_id'
--   3. Propagates fb_lead_id to the associated leads record
-- ============================================================

-- Step 1: Fix source column for Meta submissions that defaulted to 'site'
UPDATE form_pro_submissions
SET source = 'meta'
WHERE source = 'site'
  AND data->>'_source' = 'meta';

-- Step 2: Backfill meta_leadgen_id from jsonb data
UPDATE form_pro_submissions
SET meta_leadgen_id = data->>'_leadgen_id'
WHERE meta_leadgen_id IS NULL
  AND data->>'_leadgen_id' IS NOT NULL
  AND data->>'_leadgen_id' != '';

-- Step 3: Propagate fb_lead_id to leads that don't have it yet
-- Uses the submission's meta_leadgen_id as the fb_lead_id value
UPDATE leads l
SET fb_lead_id = fps.meta_leadgen_id,
    lead_source = 'meta_lead_ad'
FROM form_pro_submissions fps
WHERE fps.lead_id = l.id
  AND fps.meta_leadgen_id IS NOT NULL
  AND l.fb_lead_id IS NULL;


-- ---------------------------------------------------------------------------
-- Migration: 20260319800000_fix6_insights_context_meta_forms_join.sql
-- ---------------------------------------------------------------------------

-- Fix get_insights_context: meta_forms_stats CTE used l.metadata->>'meta_form_id'
-- but leads table has NO metadata column. Correct path:
-- meta_lead_forms → form_pro_submissions (via meta_form_id) → leads (via lead_id)

CREATE OR REPLACE FUNCTION public.get_insights_context(
  p_date_from timestamptz DEFAULT NULL,
  p_date_to   timestamptz DEFAULT NULL,
  p_pipeline_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result jsonb := '{}'::jsonb;
  v_funnel jsonb;
  v_people jsonb;
  v_messages jsonb;
  v_meetings jsonb;
  v_calls jsonb;
  v_marketing jsonb;
  v_prospect jsonb;
BEGIN

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 1: FUNNEL (leads by stage, conversion, loss reasons, velocity)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH lead_base AS (
    SELECT l.id, l.status, l.value, l.leads_stages_id, l.leads_pipelines_id,
           l.leads_loss_reasons_id, l.created_at, l.won_at
    FROM leads l
    WHERE (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
  ),
  stages_agg AS (
    SELECT
      ls.name AS stage_name,
      ls.order_index,
      COUNT(lb.id) AS lead_count,
      COALESCE(SUM(lb.value), 0) AS total_value,
      ROUND(AVG(EXTRACT(EPOCH FROM (now() - lb.created_at)) / 86400)::numeric, 1) AS avg_days
    FROM lead_base lb
    JOIN leads_stages ls ON ls.id = lb.leads_stages_id
    WHERE lb.status = 'em-andamento'
    GROUP BY ls.name, ls.order_index
    ORDER BY ls.order_index
  ),
  loss_reasons AS (
    SELECT
      COALESCE(lr.name, 'Sem motivo') AS reason,
      COUNT(*) AS cnt
    FROM lead_base lb
    LEFT JOIN leads_loss_reasons lr ON lr.id = lb.leads_loss_reasons_id
    WHERE lb.status = 'perdido'
    GROUP BY lr.name
    ORDER BY cnt DESC
    LIMIT 5
  ),
  funnel_totals AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ganho') AS won,
      COUNT(*) FILTER (WHERE status = 'perdido') AS lost,
      COUNT(*) FILTER (WHERE status = 'em-andamento') AS active,
      COALESCE(SUM(value) FILTER (WHERE status = 'ganho'), 0) AS revenue,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - created_at)) / 86400) FILTER (WHERE status = 'ganho' AND won_at IS NOT NULL))::numeric, 1) AS avg_cycle_days
    FROM lead_base
  )
  SELECT jsonb_build_object(
    'total', ft.total,
    'won', ft.won,
    'lost', ft.lost,
    'active', ft.active,
    'revenue', ft.revenue,
    'avg_deal', CASE WHEN ft.won > 0 THEN ROUND((ft.revenue / ft.won)::numeric, 2) ELSE 0 END,
    'conversion_pct', CASE WHEN ft.total > 0 THEN ROUND((ft.won::numeric / ft.total * 100), 1) ELSE 0 END,
    'avg_cycle_days', COALESCE(ft.avg_cycle_days, 0),
    'stages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', s.stage_name, 'leads', s.lead_count, 'value', s.total_value, 'avg_days', s.avg_days
    ) ORDER BY s.order_index) FROM stages_agg s), '[]'::jsonb),
    'loss_reasons', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'reason', r.reason, 'count', r.cnt
    )) FROM loss_reasons r), '[]'::jsonb)
  ) INTO v_funnel
  FROM funnel_totals ft;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 2: PEOPLE & COMPANIES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH people_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ativo') AS active,
      COUNT(*) FILTER (WHERE status != 'ativo') AS inactive,
      COUNT(*) FILTER (WHERE score BETWEEN 0 AND 25) AS score_0_25,
      COUNT(*) FILTER (WHERE score BETWEEN 26 AND 50) AS score_26_50,
      COUNT(*) FILTER (WHERE score BETWEEN 51 AND 75) AS score_51_75,
      COUNT(*) FILTER (WHERE score BETWEEN 76 AND 100) AS score_76_100
    FROM clients_people
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  top_sources AS (
    SELECT source, COUNT(*) AS cnt
    FROM clients_people
    WHERE source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY source
    ORDER BY cnt DESC
    LIMIT 5
  ),
  company_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) AS active
    FROM clients_companies
  )
  SELECT jsonb_build_object(
    'people_total', ps.total,
    'people_active', ps.active,
    'people_inactive', ps.inactive,
    'score_distribution', jsonb_build_object(
      '0_25', ps.score_0_25, '26_50', ps.score_26_50,
      '51_75', ps.score_51_75, '76_100', ps.score_76_100
    ),
    'top_sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('source', ts.source, 'count', ts.cnt)) FROM top_sources ts), '[]'::jsonb),
    'companies_total', cs.total,
    'companies_active', cs.active
  ) INTO v_people
  FROM people_stats ps, company_stats cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 3: MESSAGES (volume by channel, IA vs human, trend, abandoned)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH msg_base AS (
    SELECT id, channel, from_contact, created_at, lead_id
    FROM messages
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  by_channel AS (
    SELECT channel, COUNT(*) AS cnt
    FROM msg_base GROUP BY channel ORDER BY cnt DESC
  ),
  by_sender AS (
    SELECT from_contact, COUNT(*) AS cnt
    FROM msg_base GROUP BY from_contact
  ),
  daily_trend AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM msg_base
    WHERE created_at >= (COALESCE(p_date_to, now()) - interval '7 days')
    GROUP BY day ORDER BY day
  ),
  abandoned AS (
    SELECT COUNT(DISTINCT lead_id) AS cnt
    FROM (
      SELECT lead_id,
             from_contact,
             created_at,
             LEAD(from_contact) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_sender,
             LEAD(created_at) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_at
      FROM msg_base
    ) sub
    WHERE from_contact = 'cliente'
      AND (next_sender IS NULL OR (next_sender != 'cliente' AND next_at - created_at > interval '24 hours'))
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM msg_base),
    'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'count', c.cnt)) FROM by_channel c), '[]'::jsonb),
    'by_sender', COALESCE((SELECT jsonb_agg(jsonb_build_object('sender', s.from_contact, 'count', s.cnt)) FROM by_sender s), '[]'::jsonb),
    'daily_trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'count', d.cnt)) FROM daily_trend d), '[]'::jsonb),
    'abandoned_conversations', ab.cnt
  ) INTO v_messages
  FROM abandoned ab;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 4: MEETINGS (status, show rate by closer, time metrics)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH mtg_base AS (
    SELECT m.id, m.status, m.start_time, m.user_id, l.created_at AS lead_created, l.won_at
    FROM meetings m
    LEFT JOIN leads l ON l.id = m.lead_id
    WHERE (p_date_from IS NULL OR m.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR m.created_at <= p_date_to)
  ),
  by_status AS (
    SELECT status, COUNT(*) AS cnt FROM mtg_base GROUP BY status
  ),
  show_rate_by_user AS (
    SELECT
      COALESCE(su.name, 'Sem responsável') AS closer_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mb.status = 'realizada') AS attended,
      CASE WHEN COUNT(*) > 0
        THEN ROUND((COUNT(*) FILTER (WHERE mb.status = 'realizada'))::numeric / COUNT(*) * 100, 1)
        ELSE 0 END AS show_rate
    FROM mtg_base mb
    LEFT JOIN settings_users su ON su.id = mb.user_id
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 5
  ),
  time_metrics AS (
    SELECT
      ROUND(AVG(EXTRACT(EPOCH FROM (start_time - lead_created)) / 86400)::numeric, 1) AS avg_lead_to_meeting,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - start_time)) / 86400) FILTER (WHERE won_at IS NOT NULL))::numeric, 1) AS avg_meeting_to_close
    FROM mtg_base
    WHERE lead_created IS NOT NULL
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM mtg_base),
    'by_status', COALESCE((SELECT jsonb_agg(jsonb_build_object('status', bs.status, 'count', bs.cnt)) FROM by_status bs), '[]'::jsonb),
    'show_rate_by_closer', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', sr.closer_name, 'total', sr.total, 'attended', sr.attended, 'show_rate', sr.show_rate
    )) FROM show_rate_by_user sr), '[]'::jsonb),
    'avg_lead_to_meeting_days', COALESCE(tm.avg_lead_to_meeting, 0),
    'avg_meeting_to_close_days', COALESCE(tm.avg_meeting_to_close, 0)
  ) INTO v_meetings
  FROM time_metrics tm;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 5: CALLS (inbound/outbound, answer rate, duration, operators)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH call_base AS (
    SELECT id, direction, status, duration, user_id, outcome, tags
    FROM call_pro_calls
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  call_summary AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE direction = 'inbound') AS inbound,
      COUNT(*) FILTER (WHERE direction = 'outbound') AS outbound,
      COUNT(*) FILTER (WHERE status IN ('answered', 'handled')) AS answered,
      ROUND((AVG(duration) FILTER (WHERE duration > 0))::numeric, 0) AS avg_duration_sec
    FROM call_base
  ),
  top_operators AS (
    SELECT
      COALESCE(su.name, 'Desconhecido') AS operator_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE cb.status IN ('answered', 'handled')) AS answered
    FROM call_base cb
    LEFT JOIN settings_users su ON su.id = cb.user_id
    WHERE cb.user_id IS NOT NULL
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 3
  ),
  top_outcomes AS (
    SELECT outcome, COUNT(*) AS cnt
    FROM call_base
    WHERE outcome IS NOT NULL AND outcome != ''
    GROUP BY outcome
    ORDER BY cnt DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total', cs.total,
    'inbound', cs.inbound,
    'outbound', cs.outbound,
    'answered', cs.answered,
    'answer_rate', CASE WHEN cs.total > 0 THEN ROUND((cs.answered::numeric / cs.total * 100), 1) ELSE 0 END,
    'avg_duration_sec', COALESCE(cs.avg_duration_sec, 0),
    'top_operators', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', op.operator_name, 'total', op.total, 'answered', op.answered
    )) FROM top_operators op), '[]'::jsonb),
    'top_outcomes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'outcome', o.outcome, 'count', o.cnt
    )) FROM top_outcomes o), '[]'::jsonb)
  ) INTO v_calls
  FROM call_summary cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 6: MARKETING (sends, LPs, UTM, Meta forms)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH sends_summary AS (
    SELECT
      COUNT(*) AS total_sends,
      SUM(total_contacts) AS total_contacts,
      SUM(sent_count) AS total_sent,
      SUM(delivered_count) AS total_delivered,
      SUM(read_count) AS total_read
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  sends_by_channel AS (
    SELECT channel, COUNT(*) AS cnt, SUM(sent_count) AS sent, SUM(delivered_count) AS delivered, SUM(read_count) AS read_cnt
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY channel
  ),
  lp_stats AS (
    SELECT
      f.name AS page_name,
      COUNT(s.id) AS submissions
    FROM form_pro_forms f
    LEFT JOIN form_pro_submissions s ON s.form_id = f.id
      AND (p_date_from IS NULL OR s.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR s.submitted_at <= p_date_to)
    GROUP BY f.name
    ORDER BY submissions DESC
    LIMIT 5
  ),
  utm_stats AS (
    SELECT
      COALESCE(utm_source, 'direto') AS source,
      COALESCE(utm_medium, 'none') AS medium,
      COUNT(*) AS leads,
      COUNT(*) FILTER (WHERE status = 'ganho') AS won
    FROM leads
    WHERE utm_source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR leads_pipelines_id = p_pipeline_id)
    GROUP BY utm_source, utm_medium
    ORDER BY leads DESC
    LIMIT 5
  ),
  meta_forms_stats AS (
    SELECT
      mf.name AS form_name,
      COUNT(DISTINCT l.id) AS leads_count
    FROM meta_lead_forms mf
    LEFT JOIN form_pro_submissions fps ON fps.meta_form_id = mf.id
      AND (p_date_from IS NULL OR fps.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR fps.submitted_at <= p_date_to)
    LEFT JOIN leads l ON l.id = fps.lead_id
    WHERE mf.status = 'active'
    GROUP BY mf.name
    ORDER BY leads_count DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'sends', jsonb_build_object(
      'total_campaigns', ss.total_sends,
      'total_sent', COALESCE(ss.total_sent, 0),
      'total_delivered', COALESCE(ss.total_delivered, 0),
      'total_read', COALESCE(ss.total_read, 0),
      'delivery_rate', CASE WHEN COALESCE(ss.total_sent, 0) > 0
        THEN ROUND((COALESCE(ss.total_delivered, 0)::numeric / ss.total_sent * 100), 1) ELSE 0 END,
      'read_rate', CASE WHEN COALESCE(ss.total_delivered, 0) > 0
        THEN ROUND((COALESCE(ss.total_read, 0)::numeric / ss.total_delivered * 100), 1) ELSE 0 END,
      'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'channel', sc.channel, 'campaigns', sc.cnt, 'sent', sc.sent, 'delivered', sc.delivered, 'read', sc.read_cnt
      )) FROM sends_by_channel sc), '[]'::jsonb)
    ),
    'landing_pages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', lps.page_name, 'submissions', lps.submissions
    )) FROM lp_stats lps WHERE lps.submissions > 0), '[]'::jsonb),
    'utm_attribution', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'source', u.source, 'medium', u.medium, 'leads', u.leads, 'won', u.won
    )) FROM utm_stats u), '[]'::jsonb),
    'meta_forms', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', mfs.form_name, 'leads', mfs.leads_count
    )) FROM meta_forms_stats mfs), '[]'::jsonb)
  ) INTO v_marketing
  FROM sends_summary ss;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 7: PROSPECT PRO (campaigns, contacts breakdown, AI score)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH prospect_campaigns_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'running') AS running,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed
    FROM prospect_campaigns
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  prospect_contacts_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE pc.status = 'raw') AS raw_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'filtered') AS filtered_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'enriched') AS enriched_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'approved') AS approved_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'rejected') AS rejected_cnt,
      ROUND((AVG(ai_score) FILTER (WHERE ai_score IS NOT NULL))::numeric, 0) AS avg_ai_score
    FROM prospect_contacts pc
    JOIN prospect_campaigns camp ON camp.id = pc.campaign_id
    WHERE (p_date_from IS NULL OR pc.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR pc.created_at <= p_date_to)
  )
  SELECT jsonb_build_object(
    'campaigns_total', pca.total,
    'campaigns_running', pca.running,
    'campaigns_completed', pca.completed,
    'contacts_total', pcta.total,
    'contacts_by_status', jsonb_build_object(
      'raw', pcta.raw_cnt, 'filtered', pcta.filtered_cnt,
      'enriched', pcta.enriched_cnt, 'approved', pcta.approved_cnt, 'rejected', pcta.rejected_cnt
    ),
    'avg_ai_score', COALESCE(pcta.avg_ai_score, 0),
    'approval_rate', CASE WHEN pcta.total > 0
      THEN ROUND((pcta.approved_cnt::numeric / pcta.total * 100), 1) ELSE 0 END
  ) INTO v_prospect
  FROM prospect_campaigns_agg pca, prospect_contacts_agg pcta;

  -- ═══════════════════════════════════════════════════════════════════════
  -- ASSEMBLE FINAL RESULT
  -- ═══════════════════════════════════════════════════════════════════════
  result := jsonb_build_object(
    'funnel', COALESCE(v_funnel, '{}'::jsonb),
    'people', COALESCE(v_people, '{}'::jsonb),
    'messages', COALESCE(v_messages, '{}'::jsonb),
    'meetings', COALESCE(v_meetings, '{}'::jsonb),
    'calls', COALESCE(v_calls, '{}'::jsonb),
    'marketing', COALESCE(v_marketing, '{}'::jsonb),
    'prospect', COALESCE(v_prospect, '{}'::jsonb)
  );

  RETURN result;
END;
$$;

-- Grant access to authenticated users and service_role
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO service_role;


-- ---------------------------------------------------------------------------
-- Migration: 20260323900000_fix7_insights_meetings_filter_campaign_cross.sql
-- ---------------------------------------------------------------------------

-- Fix get_insights_context:
-- 1. Filter meetings to only include system-booked ones (exclude source='google')
--    following the same rule as the Reuniões list page
-- 2. Add campaign→lead→meeting cross-analysis (meetings_by_campaign)

CREATE OR REPLACE FUNCTION public.get_insights_context(
  p_date_from timestamptz DEFAULT NULL,
  p_date_to   timestamptz DEFAULT NULL,
  p_pipeline_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result jsonb := '{}'::jsonb;
  v_funnel jsonb;
  v_people jsonb;
  v_messages jsonb;
  v_meetings jsonb;
  v_calls jsonb;
  v_marketing jsonb;
  v_prospect jsonb;
BEGIN

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 1: FUNNEL (leads by stage, conversion, loss reasons, velocity)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH lead_base AS (
    SELECT l.id, l.status, l.value, l.leads_stages_id, l.leads_pipelines_id,
           l.leads_loss_reasons_id, l.created_at, l.won_at
    FROM leads l
    WHERE (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
  ),
  stages_agg AS (
    SELECT
      ls.name AS stage_name,
      ls.order_index,
      COUNT(lb.id) AS lead_count,
      COALESCE(SUM(lb.value), 0) AS total_value,
      ROUND(AVG(EXTRACT(EPOCH FROM (now() - lb.created_at)) / 86400)::numeric, 1) AS avg_days
    FROM lead_base lb
    JOIN leads_stages ls ON ls.id = lb.leads_stages_id
    WHERE lb.status = 'em-andamento'
    GROUP BY ls.name, ls.order_index
    ORDER BY ls.order_index
  ),
  loss_reasons AS (
    SELECT
      COALESCE(lr.name, 'Sem motivo') AS reason,
      COUNT(*) AS cnt
    FROM lead_base lb
    LEFT JOIN leads_loss_reasons lr ON lr.id = lb.leads_loss_reasons_id
    WHERE lb.status = 'perdido'
    GROUP BY lr.name
    ORDER BY cnt DESC
    LIMIT 5
  ),
  funnel_totals AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ganho') AS won,
      COUNT(*) FILTER (WHERE status = 'perdido') AS lost,
      COUNT(*) FILTER (WHERE status = 'em-andamento') AS active,
      COALESCE(SUM(value) FILTER (WHERE status = 'ganho'), 0) AS revenue,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - created_at)) / 86400) FILTER (WHERE status = 'ganho' AND won_at IS NOT NULL))::numeric, 1) AS avg_cycle_days
    FROM lead_base
  )
  SELECT jsonb_build_object(
    'total', ft.total,
    'won', ft.won,
    'lost', ft.lost,
    'active', ft.active,
    'revenue', ft.revenue,
    'avg_deal', CASE WHEN ft.won > 0 THEN ROUND((ft.revenue / ft.won)::numeric, 2) ELSE 0 END,
    'conversion_pct', CASE WHEN ft.total > 0 THEN ROUND((ft.won::numeric / ft.total * 100), 1) ELSE 0 END,
    'avg_cycle_days', COALESCE(ft.avg_cycle_days, 0),
    'stages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', s.stage_name, 'leads', s.lead_count, 'value', s.total_value, 'avg_days', s.avg_days
    ) ORDER BY s.order_index) FROM stages_agg s), '[]'::jsonb),
    'loss_reasons', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'reason', r.reason, 'count', r.cnt
    )) FROM loss_reasons r), '[]'::jsonb)
  ) INTO v_funnel
  FROM funnel_totals ft;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 2: PEOPLE & COMPANIES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH people_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ativo') AS active,
      COUNT(*) FILTER (WHERE status != 'ativo') AS inactive,
      COUNT(*) FILTER (WHERE score BETWEEN 0 AND 25) AS score_0_25,
      COUNT(*) FILTER (WHERE score BETWEEN 26 AND 50) AS score_26_50,
      COUNT(*) FILTER (WHERE score BETWEEN 51 AND 75) AS score_51_75,
      COUNT(*) FILTER (WHERE score BETWEEN 76 AND 100) AS score_76_100
    FROM clients_people
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  top_sources AS (
    SELECT source, COUNT(*) AS cnt
    FROM clients_people
    WHERE source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY source
    ORDER BY cnt DESC
    LIMIT 5
  ),
  company_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) AS active
    FROM clients_companies
  )
  SELECT jsonb_build_object(
    'people_total', ps.total,
    'people_active', ps.active,
    'people_inactive', ps.inactive,
    'score_distribution', jsonb_build_object(
      '0_25', ps.score_0_25, '26_50', ps.score_26_50,
      '51_75', ps.score_51_75, '76_100', ps.score_76_100
    ),
    'top_sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('source', ts.source, 'count', ts.cnt)) FROM top_sources ts), '[]'::jsonb),
    'companies_total', cs.total,
    'companies_active', cs.active
  ) INTO v_people
  FROM people_stats ps, company_stats cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 3: MESSAGES (volume by channel, IA vs human, trend, abandoned)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH msg_base AS (
    SELECT id, channel, from_contact, created_at, lead_id
    FROM messages
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  by_channel AS (
    SELECT channel, COUNT(*) AS cnt
    FROM msg_base GROUP BY channel ORDER BY cnt DESC
  ),
  by_sender AS (
    SELECT from_contact, COUNT(*) AS cnt
    FROM msg_base GROUP BY from_contact
  ),
  daily_trend AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM msg_base
    WHERE created_at >= (COALESCE(p_date_to, now()) - interval '7 days')
    GROUP BY day ORDER BY day
  ),
  abandoned AS (
    SELECT COUNT(DISTINCT lead_id) AS cnt
    FROM (
      SELECT lead_id,
             from_contact,
             created_at,
             LEAD(from_contact) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_sender,
             LEAD(created_at) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_at
      FROM msg_base
    ) sub
    WHERE from_contact = 'cliente'
      AND (next_sender IS NULL OR (next_sender != 'cliente' AND next_at - created_at > interval '24 hours'))
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM msg_base),
    'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'count', c.cnt)) FROM by_channel c), '[]'::jsonb),
    'by_sender', COALESCE((SELECT jsonb_agg(jsonb_build_object('sender', s.from_contact, 'count', s.cnt)) FROM by_sender s), '[]'::jsonb),
    'daily_trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'count', d.cnt)) FROM daily_trend d), '[]'::jsonb),
    'abandoned_conversations', ab.cnt
  ) INTO v_messages
  FROM abandoned ab;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 4: MEETINGS (status, show rate by closer, time metrics)
  -- FILTER: Only system-booked meetings (exclude Google Calendar imports)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH mtg_base AS (
    SELECT m.id, m.status, m.start_time, m.user_id, m.lead_id,
           l.created_at AS lead_created, l.won_at,
           l.utm_campaign, l.utm_source
    FROM meetings m
    LEFT JOIN leads l ON l.id = m.lead_id
    WHERE (p_date_from IS NULL OR m.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR m.created_at <= p_date_to)
      AND (m.source IS NULL OR m.source != 'google')
  ),
  by_status AS (
    SELECT status, COUNT(*) AS cnt FROM mtg_base GROUP BY status
  ),
  show_rate_by_user AS (
    SELECT
      COALESCE(su.name, 'Sem responsável') AS closer_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mb.status = 'realizada') AS attended,
      CASE WHEN COUNT(*) > 0
        THEN ROUND((COUNT(*) FILTER (WHERE mb.status = 'realizada'))::numeric / COUNT(*) * 100, 1)
        ELSE 0 END AS show_rate
    FROM mtg_base mb
    LEFT JOIN settings_users su ON su.id = mb.user_id
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 5
  ),
  time_metrics AS (
    SELECT
      ROUND(AVG(EXTRACT(EPOCH FROM (start_time - lead_created)) / 86400)::numeric, 1) AS avg_lead_to_meeting,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - start_time)) / 86400) FILTER (WHERE won_at IS NOT NULL))::numeric, 1) AS avg_meeting_to_close
    FROM mtg_base
    WHERE lead_created IS NOT NULL
  ),
  meetings_by_campaign AS (
    -- Reverse lookup: start from leads with UTM → check if they have meetings
    SELECT
      COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha') AS campaign,
      COUNT(DISTINCT l.id) AS leads,
      COUNT(DISTINCT m2.id) AS meetings,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('realizada', 'compareceu')) AS attended,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('não compareceu', 'cancelado')) AS no_show,
      COUNT(DISTINCT l.id) FILTER (WHERE l.status = 'ganho') AS won
    FROM leads l
    LEFT JOIN meetings m2 ON m2.lead_id = l.id AND (m2.source IS NULL OR m2.source != 'google')
    WHERE (l.utm_source IS NOT NULL OR l.utm_campaign IS NOT NULL)
      AND (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
    GROUP BY COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha')
    ORDER BY leads DESC
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM mtg_base),
    'by_status', COALESCE((SELECT jsonb_agg(jsonb_build_object('status', bs.status, 'count', bs.cnt)) FROM by_status bs), '[]'::jsonb),
    'show_rate_by_closer', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', sr.closer_name, 'total', sr.total, 'attended', sr.attended, 'show_rate', sr.show_rate
    )) FROM show_rate_by_user sr), '[]'::jsonb),
    'avg_lead_to_meeting_days', COALESCE(tm.avg_lead_to_meeting, 0),
    'avg_meeting_to_close_days', COALESCE(tm.avg_meeting_to_close, 0),
    'by_campaign', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'campaign', mc.campaign, 'leads', mc.leads, 'meetings', mc.meetings,
      'attended', mc.attended, 'no_show', mc.no_show, 'won', mc.won
    )) FROM meetings_by_campaign mc), '[]'::jsonb)
  ) INTO v_meetings
  FROM time_metrics tm;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 5: CALLS (inbound/outbound, answer rate, duration, operators)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH call_base AS (
    SELECT id, direction, status, duration, user_id, outcome, tags
    FROM call_pro_calls
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  call_summary AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE direction = 'inbound') AS inbound,
      COUNT(*) FILTER (WHERE direction = 'outbound') AS outbound,
      COUNT(*) FILTER (WHERE status IN ('answered', 'handled')) AS answered,
      ROUND((AVG(duration) FILTER (WHERE duration > 0))::numeric, 0) AS avg_duration_sec
    FROM call_base
  ),
  top_operators AS (
    SELECT
      COALESCE(su.name, 'Desconhecido') AS operator_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE cb.status IN ('answered', 'handled')) AS answered
    FROM call_base cb
    LEFT JOIN settings_users su ON su.id = cb.user_id
    WHERE cb.user_id IS NOT NULL
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 3
  ),
  top_outcomes AS (
    SELECT outcome, COUNT(*) AS cnt
    FROM call_base
    WHERE outcome IS NOT NULL AND outcome != ''
    GROUP BY outcome
    ORDER BY cnt DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total', cs.total,
    'inbound', cs.inbound,
    'outbound', cs.outbound,
    'answered', cs.answered,
    'answer_rate', CASE WHEN cs.total > 0 THEN ROUND((cs.answered::numeric / cs.total * 100), 1) ELSE 0 END,
    'avg_duration_sec', COALESCE(cs.avg_duration_sec, 0),
    'top_operators', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', op.operator_name, 'total', op.total, 'answered', op.answered
    )) FROM top_operators op), '[]'::jsonb),
    'top_outcomes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'outcome', o.outcome, 'count', o.cnt
    )) FROM top_outcomes o), '[]'::jsonb)
  ) INTO v_calls
  FROM call_summary cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 6: MARKETING (sends, LPs, UTM, Meta forms)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH sends_summary AS (
    SELECT
      COUNT(*) AS total_sends,
      SUM(total_contacts) AS total_contacts,
      SUM(sent_count) AS total_sent,
      SUM(delivered_count) AS total_delivered,
      SUM(read_count) AS total_read
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  sends_by_channel AS (
    SELECT channel, COUNT(*) AS cnt, SUM(sent_count) AS sent, SUM(delivered_count) AS delivered, SUM(read_count) AS read_cnt
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY channel
  ),
  lp_stats AS (
    SELECT
      f.name AS page_name,
      COUNT(s.id) AS submissions
    FROM form_pro_forms f
    LEFT JOIN form_pro_submissions s ON s.form_id = f.id
      AND (p_date_from IS NULL OR s.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR s.submitted_at <= p_date_to)
    GROUP BY f.name
    ORDER BY submissions DESC
    LIMIT 5
  ),
  utm_stats AS (
    SELECT
      COALESCE(utm_source, 'direto') AS source,
      COALESCE(utm_medium, 'none') AS medium,
      COUNT(*) AS leads,
      COUNT(*) FILTER (WHERE status = 'ganho') AS won
    FROM leads
    WHERE utm_source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR leads_pipelines_id = p_pipeline_id)
    GROUP BY utm_source, utm_medium
    ORDER BY leads DESC
    LIMIT 5
  ),
  meta_forms_stats AS (
    SELECT
      mf.name AS form_name,
      COUNT(DISTINCT l.id) AS leads_count
    FROM meta_lead_forms mf
    LEFT JOIN form_pro_submissions fps ON fps.meta_form_id = mf.id
      AND (p_date_from IS NULL OR fps.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR fps.submitted_at <= p_date_to)
    LEFT JOIN leads l ON l.id = fps.lead_id
    WHERE mf.status = 'active'
    GROUP BY mf.name
    ORDER BY leads_count DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'sends', jsonb_build_object(
      'total_campaigns', ss.total_sends,
      'total_sent', COALESCE(ss.total_sent, 0),
      'total_delivered', COALESCE(ss.total_delivered, 0),
      'total_read', COALESCE(ss.total_read, 0),
      'delivery_rate', CASE WHEN COALESCE(ss.total_sent, 0) > 0
        THEN ROUND((COALESCE(ss.total_delivered, 0)::numeric / ss.total_sent * 100), 1) ELSE 0 END,
      'read_rate', CASE WHEN COALESCE(ss.total_delivered, 0) > 0
        THEN ROUND((COALESCE(ss.total_read, 0)::numeric / ss.total_delivered * 100), 1) ELSE 0 END,
      'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'channel', sc.channel, 'campaigns', sc.cnt, 'sent', sc.sent, 'delivered', sc.delivered, 'read', sc.read_cnt
      )) FROM sends_by_channel sc), '[]'::jsonb)
    ),
    'landing_pages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', lps.page_name, 'submissions', lps.submissions
    )) FROM lp_stats lps WHERE lps.submissions > 0), '[]'::jsonb),
    'utm_attribution', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'source', u.source, 'medium', u.medium, 'leads', u.leads, 'won', u.won
    )) FROM utm_stats u), '[]'::jsonb),
    'meta_forms', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', mfs.form_name, 'leads', mfs.leads_count
    )) FROM meta_forms_stats mfs), '[]'::jsonb)
  ) INTO v_marketing
  FROM sends_summary ss;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 7: PROSPECT PRO (campaigns, contacts breakdown, AI score)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH prospect_campaigns_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'running') AS running,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed
    FROM prospect_campaigns
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  prospect_contacts_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE pc.status = 'raw') AS raw_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'filtered') AS filtered_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'enriched') AS enriched_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'approved') AS approved_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'rejected') AS rejected_cnt,
      ROUND((AVG(ai_score) FILTER (WHERE ai_score IS NOT NULL))::numeric, 0) AS avg_ai_score
    FROM prospect_contacts pc
    JOIN prospect_campaigns camp ON camp.id = pc.campaign_id
    WHERE (p_date_from IS NULL OR pc.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR pc.created_at <= p_date_to)
  )
  SELECT jsonb_build_object(
    'campaigns_total', pca.total,
    'campaigns_running', pca.running,
    'campaigns_completed', pca.completed,
    'contacts_total', pcta.total,
    'contacts_by_status', jsonb_build_object(
      'raw', pcta.raw_cnt, 'filtered', pcta.filtered_cnt,
      'enriched', pcta.enriched_cnt, 'approved', pcta.approved_cnt, 'rejected', pcta.rejected_cnt
    ),
    'avg_ai_score', COALESCE(pcta.avg_ai_score, 0),
    'approval_rate', CASE WHEN pcta.total > 0
      THEN ROUND((pcta.approved_cnt::numeric / pcta.total * 100), 1) ELSE 0 END
  ) INTO v_prospect
  FROM prospect_campaigns_agg pca, prospect_contacts_agg pcta;

  -- ═══════════════════════════════════════════════════════════════════════
  -- ASSEMBLE FINAL RESULT
  -- ═══════════════════════════════════════════════════════════════════════
  result := jsonb_build_object(
    'funnel', COALESCE(v_funnel, '{}'::jsonb),
    'people', COALESCE(v_people, '{}'::jsonb),
    'messages', COALESCE(v_messages, '{}'::jsonb),
    'meetings', COALESCE(v_meetings, '{}'::jsonb),
    'calls', COALESCE(v_calls, '{}'::jsonb),
    'marketing', COALESCE(v_marketing, '{}'::jsonb),
    'prospect', COALESCE(v_prospect, '{}'::jsonb)
  );

  RETURN result;
END;
$$;

-- Grant access to authenticated users and service_role
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO service_role;


-- ---------------------------------------------------------------------------
-- Migration: 20260323900001_fix8_insights_campaign_funnel_reverse.sql
-- ---------------------------------------------------------------------------

-- Fix get_insights_context:
-- 1. Filter meetings to only include system-booked ones (exclude source='google')
--    following the same rule as the Reuniões list page
-- 2. Add campaign→lead→meeting cross-analysis (meetings_by_campaign)

CREATE OR REPLACE FUNCTION public.get_insights_context(
  p_date_from timestamptz DEFAULT NULL,
  p_date_to   timestamptz DEFAULT NULL,
  p_pipeline_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result jsonb := '{}'::jsonb;
  v_funnel jsonb;
  v_people jsonb;
  v_messages jsonb;
  v_meetings jsonb;
  v_calls jsonb;
  v_marketing jsonb;
  v_prospect jsonb;
BEGIN

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 1: FUNNEL (leads by stage, conversion, loss reasons, velocity)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH lead_base AS (
    SELECT l.id, l.status, l.value, l.leads_stages_id, l.leads_pipelines_id,
           l.leads_loss_reasons_id, l.created_at, l.won_at
    FROM leads l
    WHERE (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
  ),
  stages_agg AS (
    SELECT
      ls.name AS stage_name,
      ls.order_index,
      COUNT(lb.id) AS lead_count,
      COALESCE(SUM(lb.value), 0) AS total_value,
      ROUND(AVG(EXTRACT(EPOCH FROM (now() - lb.created_at)) / 86400)::numeric, 1) AS avg_days
    FROM lead_base lb
    JOIN leads_stages ls ON ls.id = lb.leads_stages_id
    WHERE lb.status = 'em-andamento'
    GROUP BY ls.name, ls.order_index
    ORDER BY ls.order_index
  ),
  loss_reasons AS (
    SELECT
      COALESCE(lr.name, 'Sem motivo') AS reason,
      COUNT(*) AS cnt
    FROM lead_base lb
    LEFT JOIN leads_loss_reasons lr ON lr.id = lb.leads_loss_reasons_id
    WHERE lb.status = 'perdido'
    GROUP BY lr.name
    ORDER BY cnt DESC
    LIMIT 5
  ),
  funnel_totals AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ganho') AS won,
      COUNT(*) FILTER (WHERE status = 'perdido') AS lost,
      COUNT(*) FILTER (WHERE status = 'em-andamento') AS active,
      COALESCE(SUM(value) FILTER (WHERE status = 'ganho'), 0) AS revenue,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - created_at)) / 86400) FILTER (WHERE status = 'ganho' AND won_at IS NOT NULL))::numeric, 1) AS avg_cycle_days
    FROM lead_base
  )
  SELECT jsonb_build_object(
    'total', ft.total,
    'won', ft.won,
    'lost', ft.lost,
    'active', ft.active,
    'revenue', ft.revenue,
    'avg_deal', CASE WHEN ft.won > 0 THEN ROUND((ft.revenue / ft.won)::numeric, 2) ELSE 0 END,
    'conversion_pct', CASE WHEN ft.total > 0 THEN ROUND((ft.won::numeric / ft.total * 100), 1) ELSE 0 END,
    'avg_cycle_days', COALESCE(ft.avg_cycle_days, 0),
    'stages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', s.stage_name, 'leads', s.lead_count, 'value', s.total_value, 'avg_days', s.avg_days
    ) ORDER BY s.order_index) FROM stages_agg s), '[]'::jsonb),
    'loss_reasons', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'reason', r.reason, 'count', r.cnt
    )) FROM loss_reasons r), '[]'::jsonb)
  ) INTO v_funnel
  FROM funnel_totals ft;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 2: PEOPLE & COMPANIES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH people_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ativo') AS active,
      COUNT(*) FILTER (WHERE status != 'ativo') AS inactive,
      COUNT(*) FILTER (WHERE score BETWEEN 0 AND 25) AS score_0_25,
      COUNT(*) FILTER (WHERE score BETWEEN 26 AND 50) AS score_26_50,
      COUNT(*) FILTER (WHERE score BETWEEN 51 AND 75) AS score_51_75,
      COUNT(*) FILTER (WHERE score BETWEEN 76 AND 100) AS score_76_100
    FROM clients_people
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  top_sources AS (
    SELECT source, COUNT(*) AS cnt
    FROM clients_people
    WHERE source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY source
    ORDER BY cnt DESC
    LIMIT 5
  ),
  company_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) AS active
    FROM clients_companies
  )
  SELECT jsonb_build_object(
    'people_total', ps.total,
    'people_active', ps.active,
    'people_inactive', ps.inactive,
    'score_distribution', jsonb_build_object(
      '0_25', ps.score_0_25, '26_50', ps.score_26_50,
      '51_75', ps.score_51_75, '76_100', ps.score_76_100
    ),
    'top_sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('source', ts.source, 'count', ts.cnt)) FROM top_sources ts), '[]'::jsonb),
    'companies_total', cs.total,
    'companies_active', cs.active
  ) INTO v_people
  FROM people_stats ps, company_stats cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 3: MESSAGES (volume by channel, IA vs human, trend, abandoned)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH msg_base AS (
    SELECT id, channel, from_contact, created_at, lead_id
    FROM messages
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  by_channel AS (
    SELECT channel, COUNT(*) AS cnt
    FROM msg_base GROUP BY channel ORDER BY cnt DESC
  ),
  by_sender AS (
    SELECT from_contact, COUNT(*) AS cnt
    FROM msg_base GROUP BY from_contact
  ),
  daily_trend AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM msg_base
    WHERE created_at >= (COALESCE(p_date_to, now()) - interval '7 days')
    GROUP BY day ORDER BY day
  ),
  abandoned AS (
    SELECT COUNT(DISTINCT lead_id) AS cnt
    FROM (
      SELECT lead_id,
             from_contact,
             created_at,
             LEAD(from_contact) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_sender,
             LEAD(created_at) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_at
      FROM msg_base
    ) sub
    WHERE from_contact = 'cliente'
      AND (next_sender IS NULL OR (next_sender != 'cliente' AND next_at - created_at > interval '24 hours'))
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM msg_base),
    'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'count', c.cnt)) FROM by_channel c), '[]'::jsonb),
    'by_sender', COALESCE((SELECT jsonb_agg(jsonb_build_object('sender', s.from_contact, 'count', s.cnt)) FROM by_sender s), '[]'::jsonb),
    'daily_trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'count', d.cnt)) FROM daily_trend d), '[]'::jsonb),
    'abandoned_conversations', ab.cnt
  ) INTO v_messages
  FROM abandoned ab;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 4: MEETINGS (status, show rate by closer, time metrics)
  -- FILTER: Only system-booked meetings (exclude Google Calendar imports)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH mtg_base AS (
    SELECT m.id, m.status, m.start_time, m.user_id, m.lead_id,
           l.created_at AS lead_created, l.won_at,
           l.utm_campaign, l.utm_source
    FROM meetings m
    LEFT JOIN leads l ON l.id = m.lead_id
    WHERE (p_date_from IS NULL OR m.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR m.created_at <= p_date_to)
      AND (m.source IS NULL OR m.source != 'google')
  ),
  by_status AS (
    SELECT status, COUNT(*) AS cnt FROM mtg_base GROUP BY status
  ),
  show_rate_by_user AS (
    SELECT
      COALESCE(su.name, 'Sem responsável') AS closer_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mb.status = 'realizada') AS attended,
      CASE WHEN COUNT(*) > 0
        THEN ROUND((COUNT(*) FILTER (WHERE mb.status = 'realizada'))::numeric / COUNT(*) * 100, 1)
        ELSE 0 END AS show_rate
    FROM mtg_base mb
    LEFT JOIN settings_users su ON su.id = mb.user_id
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 5
  ),
  time_metrics AS (
    SELECT
      ROUND(AVG(EXTRACT(EPOCH FROM (start_time - lead_created)) / 86400)::numeric, 1) AS avg_lead_to_meeting,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - start_time)) / 86400) FILTER (WHERE won_at IS NOT NULL))::numeric, 1) AS avg_meeting_to_close
    FROM mtg_base
    WHERE lead_created IS NOT NULL
  ),
  meetings_by_campaign AS (
    -- Reverse lookup: start from leads with UTM → check if they have meetings
    SELECT
      COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha') AS campaign,
      COUNT(DISTINCT l.id) AS leads,
      COUNT(DISTINCT m2.id) AS meetings,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('realizada', 'compareceu')) AS attended,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('não compareceu', 'cancelado')) AS no_show,
      COUNT(DISTINCT l.id) FILTER (WHERE l.status = 'ganho') AS won
    FROM leads l
    LEFT JOIN meetings m2 ON m2.lead_id = l.id AND (m2.source IS NULL OR m2.source != 'google')
    WHERE (l.utm_source IS NOT NULL OR l.utm_campaign IS NOT NULL)
      AND (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
    GROUP BY COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha')
    ORDER BY leads DESC
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM mtg_base),
    'by_status', COALESCE((SELECT jsonb_agg(jsonb_build_object('status', bs.status, 'count', bs.cnt)) FROM by_status bs), '[]'::jsonb),
    'show_rate_by_closer', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', sr.closer_name, 'total', sr.total, 'attended', sr.attended, 'show_rate', sr.show_rate
    )) FROM show_rate_by_user sr), '[]'::jsonb),
    'avg_lead_to_meeting_days', COALESCE(tm.avg_lead_to_meeting, 0),
    'avg_meeting_to_close_days', COALESCE(tm.avg_meeting_to_close, 0),
    'by_campaign', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'campaign', mc.campaign, 'leads', mc.leads, 'meetings', mc.meetings,
      'attended', mc.attended, 'no_show', mc.no_show, 'won', mc.won
    )) FROM meetings_by_campaign mc), '[]'::jsonb)
  ) INTO v_meetings
  FROM time_metrics tm;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 5: CALLS (inbound/outbound, answer rate, duration, operators)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH call_base AS (
    SELECT id, direction, status, duration, user_id, outcome, tags
    FROM call_pro_calls
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  call_summary AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE direction = 'inbound') AS inbound,
      COUNT(*) FILTER (WHERE direction = 'outbound') AS outbound,
      COUNT(*) FILTER (WHERE status IN ('answered', 'handled')) AS answered,
      ROUND((AVG(duration) FILTER (WHERE duration > 0))::numeric, 0) AS avg_duration_sec
    FROM call_base
  ),
  top_operators AS (
    SELECT
      COALESCE(su.name, 'Desconhecido') AS operator_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE cb.status IN ('answered', 'handled')) AS answered
    FROM call_base cb
    LEFT JOIN settings_users su ON su.id = cb.user_id
    WHERE cb.user_id IS NOT NULL
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 3
  ),
  top_outcomes AS (
    SELECT outcome, COUNT(*) AS cnt
    FROM call_base
    WHERE outcome IS NOT NULL AND outcome != ''
    GROUP BY outcome
    ORDER BY cnt DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total', cs.total,
    'inbound', cs.inbound,
    'outbound', cs.outbound,
    'answered', cs.answered,
    'answer_rate', CASE WHEN cs.total > 0 THEN ROUND((cs.answered::numeric / cs.total * 100), 1) ELSE 0 END,
    'avg_duration_sec', COALESCE(cs.avg_duration_sec, 0),
    'top_operators', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', op.operator_name, 'total', op.total, 'answered', op.answered
    )) FROM top_operators op), '[]'::jsonb),
    'top_outcomes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'outcome', o.outcome, 'count', o.cnt
    )) FROM top_outcomes o), '[]'::jsonb)
  ) INTO v_calls
  FROM call_summary cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 6: MARKETING (sends, LPs, UTM, Meta forms)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH sends_summary AS (
    SELECT
      COUNT(*) AS total_sends,
      SUM(total_contacts) AS total_contacts,
      SUM(sent_count) AS total_sent,
      SUM(delivered_count) AS total_delivered,
      SUM(read_count) AS total_read
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  sends_by_channel AS (
    SELECT channel, COUNT(*) AS cnt, SUM(sent_count) AS sent, SUM(delivered_count) AS delivered, SUM(read_count) AS read_cnt
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY channel
  ),
  lp_stats AS (
    SELECT
      f.name AS page_name,
      COUNT(s.id) AS submissions
    FROM form_pro_forms f
    LEFT JOIN form_pro_submissions s ON s.form_id = f.id
      AND (p_date_from IS NULL OR s.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR s.submitted_at <= p_date_to)
    GROUP BY f.name
    ORDER BY submissions DESC
    LIMIT 5
  ),
  utm_stats AS (
    SELECT
      COALESCE(utm_source, 'direto') AS source,
      COALESCE(utm_medium, 'none') AS medium,
      COUNT(*) AS leads,
      COUNT(*) FILTER (WHERE status = 'ganho') AS won
    FROM leads
    WHERE utm_source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR leads_pipelines_id = p_pipeline_id)
    GROUP BY utm_source, utm_medium
    ORDER BY leads DESC
    LIMIT 5
  ),
  meta_forms_stats AS (
    SELECT
      mf.name AS form_name,
      COUNT(DISTINCT l.id) AS leads_count
    FROM meta_lead_forms mf
    LEFT JOIN form_pro_submissions fps ON fps.meta_form_id = mf.id
      AND (p_date_from IS NULL OR fps.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR fps.submitted_at <= p_date_to)
    LEFT JOIN leads l ON l.id = fps.lead_id
    WHERE mf.status = 'active'
    GROUP BY mf.name
    ORDER BY leads_count DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'sends', jsonb_build_object(
      'total_campaigns', ss.total_sends,
      'total_sent', COALESCE(ss.total_sent, 0),
      'total_delivered', COALESCE(ss.total_delivered, 0),
      'total_read', COALESCE(ss.total_read, 0),
      'delivery_rate', CASE WHEN COALESCE(ss.total_sent, 0) > 0
        THEN ROUND((COALESCE(ss.total_delivered, 0)::numeric / ss.total_sent * 100), 1) ELSE 0 END,
      'read_rate', CASE WHEN COALESCE(ss.total_delivered, 0) > 0
        THEN ROUND((COALESCE(ss.total_read, 0)::numeric / ss.total_delivered * 100), 1) ELSE 0 END,
      'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'channel', sc.channel, 'campaigns', sc.cnt, 'sent', sc.sent, 'delivered', sc.delivered, 'read', sc.read_cnt
      )) FROM sends_by_channel sc), '[]'::jsonb)
    ),
    'landing_pages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', lps.page_name, 'submissions', lps.submissions
    )) FROM lp_stats lps WHERE lps.submissions > 0), '[]'::jsonb),
    'utm_attribution', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'source', u.source, 'medium', u.medium, 'leads', u.leads, 'won', u.won
    )) FROM utm_stats u), '[]'::jsonb),
    'meta_forms', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', mfs.form_name, 'leads', mfs.leads_count
    )) FROM meta_forms_stats mfs), '[]'::jsonb)
  ) INTO v_marketing
  FROM sends_summary ss;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 7: PROSPECT PRO (campaigns, contacts breakdown, AI score)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH prospect_campaigns_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'running') AS running,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed
    FROM prospect_campaigns
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  prospect_contacts_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE pc.status = 'raw') AS raw_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'filtered') AS filtered_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'enriched') AS enriched_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'approved') AS approved_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'rejected') AS rejected_cnt,
      ROUND((AVG(ai_score) FILTER (WHERE ai_score IS NOT NULL))::numeric, 0) AS avg_ai_score
    FROM prospect_contacts pc
    JOIN prospect_campaigns camp ON camp.id = pc.campaign_id
    WHERE (p_date_from IS NULL OR pc.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR pc.created_at <= p_date_to)
  )
  SELECT jsonb_build_object(
    'campaigns_total', pca.total,
    'campaigns_running', pca.running,
    'campaigns_completed', pca.completed,
    'contacts_total', pcta.total,
    'contacts_by_status', jsonb_build_object(
      'raw', pcta.raw_cnt, 'filtered', pcta.filtered_cnt,
      'enriched', pcta.enriched_cnt, 'approved', pcta.approved_cnt, 'rejected', pcta.rejected_cnt
    ),
    'avg_ai_score', COALESCE(pcta.avg_ai_score, 0),
    'approval_rate', CASE WHEN pcta.total > 0
      THEN ROUND((pcta.approved_cnt::numeric / pcta.total * 100), 1) ELSE 0 END
  ) INTO v_prospect
  FROM prospect_campaigns_agg pca, prospect_contacts_agg pcta;

  -- ═══════════════════════════════════════════════════════════════════════
  -- ASSEMBLE FINAL RESULT
  -- ═══════════════════════════════════════════════════════════════════════
  result := jsonb_build_object(
    'funnel', COALESCE(v_funnel, '{}'::jsonb),
    'people', COALESCE(v_people, '{}'::jsonb),
    'messages', COALESCE(v_messages, '{}'::jsonb),
    'meetings', COALESCE(v_meetings, '{}'::jsonb),
    'calls', COALESCE(v_calls, '{}'::jsonb),
    'marketing', COALESCE(v_marketing, '{}'::jsonb),
    'prospect', COALESCE(v_prospect, '{}'::jsonb)
  );

  RETURN result;
END;
$$;

