-- ---------------------------------------------------------------------------
-- Migration: 20260327180001_schedule_automation_trigger.sql
-- ---------------------------------------------------------------------------

-- Schedule Automation Trigger
-- When meetings.status changes, look up schedule_automations rules and move the lead accordingly.
--
-- Mapping: meetings.status (DB) → schedule_automations.trigger_status (config)
--   'agendado'         → 'criado'       (new meeting created/set to agendado)
--   'compareceu'       → 'realizado'    (attended)
--   'cancelado'        → 'cancelado'    (cancelled)
--   'não compareceu'   → 'no_show'      (no-show)
--   'bloqueio manual'  → (no mapping — internal status, not a user action)
--
-- Note: 'confirmado' and 'reagendado' are not canonical meetings.status values yet.
-- When those are added to the meetings CHECK constraint, this trigger will handle them automatically.

CREATE OR REPLACE FUNCTION public.fn_schedule_automation_on_status_change()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  v_trigger_status TEXT;
  v_lead_id        UUID;
  v_lead           RECORD;
  v_rule           RECORD;
BEGIN
  -- Only fire on status change (UPDATE) or new meeting (INSERT)
  IF TG_OP = 'UPDATE' AND OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;

  -- Skip bloqueio manual — internal status
  IF NEW.status = 'bloqueio manual' THEN
    RETURN NEW;
  END IF;

  -- Map meetings.status → schedule_automations.trigger_status
  v_trigger_status := CASE NEW.status
    WHEN 'agendado'         THEN 'criado'
    WHEN 'compareceu'       THEN 'realizado'
    WHEN 'cancelado'        THEN 'cancelado'
    WHEN 'não compareceu'   THEN 'no_show'
    WHEN 'confirmado'       THEN 'confirmado'
    WHEN 'reagendado'       THEN 'reagendado'
    ELSE NULL
  END;

  IF v_trigger_status IS NULL THEN
    RETURN NEW;
  END IF;

  -- Find the lead:
  -- 1. Direct FK: meetings.leads_id
  -- 2. Fallback: find lead by meetings.people_id
  v_lead_id := NEW.leads_id;

  IF v_lead_id IS NULL AND NEW.people_id IS NOT NULL THEN
    -- Find the most recent active lead for this person
    SELECT id, leads_pipelines_id, leads_stages_id
      INTO v_lead
      FROM public.leads
     WHERE people_id = NEW.people_id
       AND status = 'em-andamento'
       AND archived = false
     ORDER BY updated_at DESC
     LIMIT 1;

    v_lead_id := v_lead.id;
  ELSE
    SELECT id, leads_pipelines_id, leads_stages_id
      INTO v_lead
      FROM public.leads
     WHERE id = v_lead_id;
  END IF;

  -- No lead found → nothing to do
  IF v_lead_id IS NULL OR v_lead.id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Look up matching automation rule
  SELECT sa.target_pipeline_id, sa.target_stage_id
    INTO v_rule
    FROM public.schedule_automations sa
   WHERE sa.pipeline_id = v_lead.leads_pipelines_id
     AND sa.trigger_status = v_trigger_status
     AND sa.is_active = true
   LIMIT 1;

  -- No matching rule → nothing to do
  IF v_rule IS NULL THEN
    RETURN NEW;
  END IF;

  -- Move the lead: update pipeline + stage
  UPDATE public.leads
     SET leads_pipelines_id = v_rule.target_pipeline_id,
         leads_stages_id    = v_rule.target_stage_id,
         updated_at         = NOW()
   WHERE id = v_lead_id;

  -- Log the move in leads_updates for audit trail
  INSERT INTO public.leads_updates (leads_id, from_stage_id, to_stage_id, notes)
  VALUES (
    v_lead_id,
    v_lead.leads_stages_id,
    v_rule.target_stage_id,
    'Automação Schedule: meeting status → ' || NEW.status
  );

  RETURN NEW;
END;
$$;

-- Trigger on INSERT (new meeting) and UPDATE (status change)
DROP TRIGGER IF EXISTS trg_schedule_automation ON public.meetings;
CREATE TRIGGER trg_schedule_automation
  AFTER INSERT OR UPDATE OF status ON public.meetings
  FOR EACH ROW
  EXECUTE FUNCTION public.fn_schedule_automation_on_status_change();


-- ---------------------------------------------------------------------------
-- Migration: 20260327190000_fix_followup_resolve_attendee_emails.sql
-- ---------------------------------------------------------------------------

-- ══════════════════════════════════════════════════════════════════════════════
-- FIX: Meeting followup trigger — resolve people_id from attendee_emails
--
-- Root cause: GCal-synced meetings have people_id=NULL and lead_id=NULL.
-- The trigger created queue entries with no contact, causing 100% failure.
--
-- This migration adds a third resolution path: match attendee_emails against
-- clients_people.email to find the contact.
-- ══════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.handle_meeting_followup_queue()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status     text;
  v_people_id  uuid;
  rule_rec     record;
  delay_secs   bigint;
  v_scheduled  timestamptz;
BEGIN
  -- Skip if status didn't change on UPDATE
  IF (TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  -- Normalize meetings.status → meetings_followups.meeting_status
  v_status := CASE NEW.status
    WHEN 'agendada'       THEN 'agendado'
    WHEN 'agendado'       THEN 'agendado'
    WHEN 'compareceu'     THEN 'compareceu'
    WHEN 'nao_compareceu' THEN 'nao_compareceu'
    WHEN 'cancelado'      THEN 'cancelado'
    WHEN 'cancelada'      THEN 'cancelado'
    WHEN 'realizado'      THEN 'realizado'
    ELSE NEW.status
  END;

  -- Cancel existing pending queue entries for this meeting (status changed)
  IF TG_OP = 'UPDATE' THEN
    UPDATE public.meeting_followup_queue
       SET status = 'cancelled'
     WHERE meeting_id = NEW.id
       AND status = 'pending';
  END IF;

  -- Resolve people_id: direct → from lead → from attendee_emails
  v_people_id := NEW.people_id;

  IF v_people_id IS NULL AND NEW.lead_id IS NOT NULL THEN
    SELECT people_id INTO v_people_id
      FROM public.leads
     WHERE id = NEW.lead_id;
  END IF;

  -- Fallback: match attendee_emails against clients_people.email
  IF v_people_id IS NULL
     AND NEW.attendee_emails IS NOT NULL
     AND array_length(NEW.attendee_emails, 1) > 0
  THEN
    SELECT cp.id INTO v_people_id
      FROM public.clients_people cp
     WHERE cp.email = ANY(NEW.attendee_emails)
     LIMIT 1;

    -- Backfill meeting.people_id for future lookups (best-effort)
    IF v_people_id IS NOT NULL THEN
      UPDATE public.meetings SET people_id = v_people_id WHERE id = NEW.id;
    END IF;
  END IF;

  -- Create queue entry for each active rule matching the new status
  FOR rule_rec IN
    SELECT id, channel, webhook_url, message, days, hours, minutes,
           whatsapp_template_id, as_queue_id
      FROM public.meetings_followups
     WHERE active = true
       AND meeting_status = v_status
       AND (
         (webhook_url IS NOT NULL AND webhook_url <> '')
         OR whatsapp_template_id IS NOT NULL
         OR as_queue_id IS NOT NULL
       )
  LOOP
    delay_secs := (
      COALESCE(rule_rec.days, 0)    * 86400 +
      COALESCE(rule_rec.hours, 0)   * 3600  +
      COALESCE(rule_rec.minutes, 0) * 60
    )::bigint;

    -- For 'agendado' status: schedule BEFORE the meeting (start_time - delay)
    IF v_status = 'agendado' AND NEW.start_time IS NOT NULL THEN
      v_scheduled := NEW.start_time - (delay_secs * interval '1 second');
      IF v_scheduled < now() THEN
        v_scheduled := now();
      END IF;
    ELSE
      v_scheduled := now() + (delay_secs * interval '1 second');
    END IF;

    INSERT INTO public.meeting_followup_queue (
      rule_id, meeting_id, people_id, lead_id,
      scheduled_for, channel, webhook_url, message_snapshot,
      template_id, as_queue_id
    ) VALUES (
      rule_rec.id,
      NEW.id,
      v_people_id,
      NEW.lead_id,
      v_scheduled,
      rule_rec.channel,
      rule_rec.webhook_url,
      rule_rec.message,
      rule_rec.whatsapp_template_id,
      rule_rec.as_queue_id
    );
  END LOOP;

  RETURN NEW;
END;
$$;

-- Ensure trigger is attached
DROP TRIGGER IF EXISTS trg_meeting_followup_queue ON public.meetings;
CREATE TRIGGER trg_meeting_followup_queue
  AFTER INSERT OR UPDATE ON public.meetings
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_meeting_followup_queue();


-- ---------------------------------------------------------------------------
-- Migration: 20260327191000_hotfix_meetings_status_constraint.sql
-- ---------------------------------------------------------------------------

-- ══════════════════════════════════════════════════════════════════════════════
-- HOTFIX: meetings_status_check constraint blocking public bookings
--
-- Root cause: Migration 20260326130000 recreated book_meeting with 'agendada'
-- but P7 constraint (20260228000000) only allows 'agendado'.
-- Also missing: 'nao_compareceu' (used by followup trigger) and 'realizado'.
--
-- Fix: 1) Expand constraint to include ALL status values used across the system
--       2) Fix both book_meeting overloads to use canonical 'agendado'
-- ══════════════════════════════════════════════════════════════════════════════

-- ─── 1. Expand CHECK constraint ────────────────────────────────────────────────

ALTER TABLE public.meetings DROP CONSTRAINT IF EXISTS meetings_status_check;

ALTER TABLE public.meetings ADD CONSTRAINT meetings_status_check
  CHECK (status = ANY (ARRAY[
    'agendado'::text,
    'agendada'::text,
    'compareceu'::text,
    'nao_compareceu'::text,
    'não compareceu'::text,
    'cancelado'::text,
    'cancelada'::text,
    'realizado'::text,
    'bloqueio manual'::text
  ]));

-- ─── 2. Fix book_meeting (public booking overload) — 'agendada' → 'agendado'

CREATE OR REPLACE FUNCTION public.book_meeting(
  p_lead_id     uuid,
  p_start_time  timestamptz,
  p_end_time    timestamptz,
  p_rule_set_id uuid    DEFAULT NULL,
  p_duration    integer DEFAULT 30,
  p_notes       text    DEFAULT NULL
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user_id       uuid;
  v_user_name     text;
  v_meeting_id    uuid;
  v_title         text;
  v_people_id     uuid;
  v_eligible_ids  uuid[];
BEGIN
  v_eligible_ids := public.get_booking_eligible_user_ids(p_rule_set_id);

  IF v_eligible_ids IS NULL OR array_length(v_eligible_ids, 1) IS NULL THEN
    RETURN json_build_object('error', 'Nenhum consultor disponível');
  END IF;

  -- Resolve people_id from lead
  SELECT people_id INTO v_people_id FROM public.leads WHERE id = p_lead_id;

  IF p_rule_set_id IS NOT NULL THEN
    SELECT su.id, su.name
    INTO v_user_id, v_user_name
    FROM public.booking_rules br
    INNER JOIN public.settings_users su
      ON su.id = (br.config->>'user_id')::uuid
      AND su.active = true
      AND su.id = ANY(v_eligible_ids)
    WHERE br.rule_set_id = p_rule_set_id
      AND br.rule_type   = 'specific_user'
      AND br.is_active   = true
      AND NOT EXISTS (
        SELECT 1 FROM public.meetings m
        WHERE m.user_id    = su.id
          AND m.start_time < p_end_time
          AND m.end_time   > p_start_time
          AND m.status NOT IN ('cancelado', 'cancelada')
      )
    ORDER BY br.order_index ASC
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    SELECT su.id, su.name
    INTO v_user_id, v_user_name
    FROM public.settings_users su
    WHERE su.id = ANY(v_eligible_ids)
      AND su.active = true
      AND NOT EXISTS (
        SELECT 1 FROM public.meetings m
        WHERE m.user_id    = su.id
          AND m.start_time < p_end_time
          AND m.end_time   > p_start_time
          AND m.status NOT IN ('cancelado', 'cancelada')
      )
    ORDER BY
      (SELECT COUNT(*) FROM public.meetings m2
       WHERE m2.user_id    = su.id
         AND m2.start_time >= NOW()
         AND m2.status NOT IN ('cancelado', 'cancelada')
      ) ASC,
      COALESCE((
        SELECT MAX(m3.created_at) FROM public.meetings m3
        WHERE m3.user_id = su.id
      ), '1970-01-01'::timestamptz) ASC
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN json_build_object('error', 'Horário não disponível — escolha outro horário');
  END IF;

  v_title := 'Reunião agendada — ' ||
    TO_CHAR(p_start_time AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI');

  INSERT INTO public.meetings (
    lead_id, people_id, user_id, title, start_time, end_time, status, notes, source
  )
  VALUES (
    p_lead_id, v_people_id, v_user_id, v_title,
    p_start_time, p_end_time,
    'agendado', p_notes, 'public_booking'
  )
  RETURNING id INTO v_meeting_id;

  RETURN json_build_object(
    'meeting_id', v_meeting_id::text,
    'consultor', json_build_object(
      'id',   v_user_id::text,
      'name', v_user_name
    )
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.book_meeting(uuid, timestamptz, timestamptz, uuid, integer, text)
  TO anon, authenticated;

-- ─── 3. Fix book_meeting (N8N/AI agent overload) — already uses 'agendado' ──

CREATE OR REPLACE FUNCTION public.book_meeting(
  p_lead_id          UUID,
  p_user_id          UUID,
  p_title            TEXT,
  p_start_ts         TIMESTAMPTZ,
  p_duration_minutes INT  DEFAULT 30,
  p_notes            TEXT DEFAULT NULL
)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_meeting_id UUID;
  v_people_id  UUID;
  v_end_ts     TIMESTAMPTZ;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.leads WHERE id = p_lead_id) THEN
    RAISE EXCEPTION 'book_meeting: lead % not found', p_lead_id;
  END IF;

  SELECT people_id INTO v_people_id FROM public.leads WHERE id = p_lead_id;
  v_end_ts := p_start_ts + (p_duration_minutes || ' minutes')::INTERVAL;

  INSERT INTO public.meetings (
    lead_id, people_id, user_id, title, start_time, end_time, notes, status, source
  )
  VALUES (
    p_lead_id, v_people_id, p_user_id, p_title,
    p_start_ts, v_end_ts,
    p_notes,
    'agendado',
    'ai_agent'
  )
  RETURNING id INTO v_meeting_id;

  RETURN v_meeting_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.book_meeting(UUID, UUID, TEXT, TIMESTAMPTZ, INT, TEXT)
  TO authenticated, service_role;


