-- ---------------------------------------------------------------------------
-- Migration: 20260405200000_create_user_rpc.sql
-- ---------------------------------------------------------------------------

-- RPC to create a user in auth.users + settings_users
-- Uses service_role_key from _app_config to call Auth Admin API via pg_net/http
-- This avoids the need for an edge function on the tenant project.

CREATE OR REPLACE FUNCTION public.create_tenant_user(
  p_email text,
  p_password text,
  p_name text,
  p_phone text DEFAULT NULL,
  p_user_type text DEFAULT 'atendente',
  p_super_admin boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_service_role_key text;
  v_supabase_url text;
  v_auth_response jsonb;
  v_auth_user_id uuid;
  v_user_record jsonb;
  v_request_id bigint;
  v_response_status int;
  v_response_body text;
BEGIN
  -- 1. Get service_role_key and supabase_url from _app_config
  SELECT value INTO v_service_role_key FROM _app_config WHERE key = 'service_role_key';
  SELECT value INTO v_supabase_url FROM _app_config WHERE key = 'supabase_url';

  IF v_service_role_key IS NULL OR v_supabase_url IS NULL THEN
    RETURN jsonb_build_object('error', 'Configuração do tenant incompleta. Contacte o administrador.');
  END IF;

  -- 2. Call Supabase Auth Admin API to create user
  SELECT net.http_post(
    url := v_supabase_url || '/auth/v1/admin/users',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_service_role_key,
      'Authorization', 'Bearer ' || v_service_role_key
    ),
    body := jsonb_build_object(
      'email', p_email,
      'password', p_password,
      'email_confirm', true,
      'user_metadata', jsonb_build_object('full_name', p_name)
    )
  ) INTO v_request_id;

  -- 3. Wait briefly and get response
  -- pg_net is async, but we can poll for the response
  PERFORM pg_sleep(2);

  SELECT status_code, (response).body::text
  INTO v_response_status, v_response_body
  FROM net._http_response
  WHERE id = v_request_id;

  IF v_response_status IS NULL THEN
    -- Retry wait
    PERFORM pg_sleep(3);
    SELECT status_code, (response).body::text
    INTO v_response_status, v_response_body
    FROM net._http_response
    WHERE id = v_request_id;
  END IF;

  IF v_response_status IS NULL OR v_response_status >= 400 THEN
    RETURN jsonb_build_object('error', COALESCE(v_response_body, 'Timeout ao criar usuário no Auth. Tente novamente.'));
  END IF;

  v_auth_response := v_response_body::jsonb;
  v_auth_user_id := (v_auth_response ->> 'id')::uuid;

  IF v_auth_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Auth retornou sem ID de usuário');
  END IF;

  -- 4. Insert into settings_users
  INSERT INTO settings_users (auth_user_id, name, email, phone, user_type, super_admin, active)
  VALUES (v_auth_user_id, p_name, p_email, p_phone, p_user_type, p_super_admin, true);

  -- 5. Return success
  SELECT jsonb_build_object(
    'success', true,
    'user_id', su.id,
    'auth_user_id', v_auth_user_id,
    'email', p_email,
    'name', p_name
  ) INTO v_user_record
  FROM settings_users su
  WHERE su.auth_user_id = v_auth_user_id;

  RETURN v_user_record;

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;

-- Grant execute to authenticated users (gestors will use this)
GRANT EXECUTE ON FUNCTION public.create_tenant_user TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260405210000_adm_clients_secrets_status.sql
-- ---------------------------------------------------------------------------

-- ADM: Secrets status RPC
-- Returns boolean existence indicators for service_role_key, db_password, management_token
-- Uses SECURITY DEFINER to bypass any column-level privilege gaps that may cause the
-- encrypted blob columns to return NULL even for super_admin users.

CREATE OR REPLACE FUNCTION public.adm_clients_secrets_status()
RETURNS TABLE(
  id UUID,
  has_service_role_key BOOLEAN,
  has_db_password BOOLEAN,
  has_management_token BOOLEAN
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT
    id,
    (service_role_key IS NOT NULL AND service_role_key <> '') AS has_service_role_key,
    (db_password IS NOT NULL AND db_password <> '')           AS has_db_password,
    (management_token IS NOT NULL AND management_token <> '')  AS has_management_token
  FROM adm_clients;
$$;

COMMENT ON FUNCTION public.adm_clients_secrets_status IS
  'Returns boolean presence of encrypted secrets for all adm_clients. SECURITY DEFINER bypasses column-level privilege gaps.';

-- Ensure authenticated role can call the function and access adm_clients
GRANT EXECUTE ON FUNCTION public.adm_clients_secrets_status TO authenticated;
GRANT ALL ON public.adm_clients TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260405220000_fix_create_user_rpc.sql
-- ---------------------------------------------------------------------------

-- Fix create_tenant_user: pg_net on tenants uses flat columns (body, status_code)
-- not a composite (response).body. Rewrite to avoid net._http_response polling
-- and use net.http_collect_response instead (available in pg_net >= 0.6).
-- Falls back to polling with correct flat column names if needed.

CREATE OR REPLACE FUNCTION public.create_tenant_user(
  p_email text,
  p_password text,
  p_name text,
  p_phone text DEFAULT NULL,
  p_user_type text DEFAULT 'atendente',
  p_super_admin boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_service_role_key text;
  v_supabase_url text;
  v_auth_user_id uuid;
  v_user_record jsonb;
  v_request_id bigint;
  v_response net.http_response_result;
  v_status int;
  v_body text;
BEGIN
  -- 1. Get service_role_key and supabase_url from _app_config
  SELECT value INTO v_service_role_key FROM _app_config WHERE key = 'service_role_key';
  SELECT value INTO v_supabase_url FROM _app_config WHERE key = 'supabase_url';

  IF v_service_role_key IS NULL OR v_supabase_url IS NULL THEN
    RETURN jsonb_build_object('error', 'Configuração do tenant incompleta. Contacte o administrador.');
  END IF;

  -- 2. Fire async HTTP request to Supabase Auth Admin API
  SELECT net.http_post(
    url := v_supabase_url || '/auth/v1/admin/users',
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'apikey', v_service_role_key,
      'Authorization', 'Bearer ' || v_service_role_key
    ),
    body := jsonb_build_object(
      'email', p_email,
      'password', p_password,
      'email_confirm', true,
      'user_metadata', jsonb_build_object('full_name', p_name)
    )
  ) INTO v_request_id;

  -- 3. Collect response (blocking, waits up to 5s)
  BEGIN
    SELECT * INTO v_response FROM net.http_collect_response(v_request_id, async := false);
    v_status := v_response.status_code;
    v_body   := v_response.content;
  EXCEPTION WHEN OTHERS THEN
    -- net.http_collect_response not available — fall back to polling
    PERFORM pg_sleep(3);
    BEGIN
      -- pg_net flat columns: status_code, content (or body depending on version)
      SELECT status_code,
             COALESCE(content, body)
        INTO v_status, v_body
        FROM net._http_response
       WHERE id = v_request_id;
    EXCEPTION WHEN OTHERS THEN
      -- Try alternate column name used in older pg_net versions
      SELECT status_code, response_body::text
        INTO v_status, v_body
        FROM net._http_response
       WHERE id = v_request_id;
    END;
  END;

  IF v_status IS NULL OR v_status >= 400 THEN
    RETURN jsonb_build_object('error', COALESCE(v_body, 'Timeout ou erro ao criar usuário no Auth.'));
  END IF;

  v_auth_user_id := (v_body::jsonb ->> 'id')::uuid;

  IF v_auth_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Auth retornou sem ID de usuário');
  END IF;

  -- 4. Insert into settings_users
  INSERT INTO settings_users (auth_user_id, name, email, phone, user_type, super_admin, active)
  VALUES (v_auth_user_id, p_name, p_email, p_phone, p_user_type, p_super_admin, true)
  ON CONFLICT (auth_user_id) DO NOTHING;

  -- 5. Return success
  SELECT jsonb_build_object(
    'success', true,
    'user_id', su.id,
    'auth_user_id', v_auth_user_id,
    'email', p_email,
    'name', p_name
  ) INTO v_user_record
  FROM settings_users su
  WHERE su.auth_user_id = v_auth_user_id;

  RETURN COALESCE(v_user_record, jsonb_build_object('error', 'Usuário criado no Auth mas não encontrado em settings_users'));

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_tenant_user TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260405230000_fix_create_user_timeout.sql
-- ---------------------------------------------------------------------------

-- Fix create_tenant_user: statement timeout and pg_net column compatibility
-- The previous version used net.http_collect_response which blocks and hits
-- Supabase's default 8s statement timeout. Use SET LOCAL to disable it within
-- this function, and poll net._http_response with the correct flat columns.

CREATE OR REPLACE FUNCTION public.create_tenant_user(
  p_email text,
  p_password text,
  p_name text,
  p_phone text DEFAULT NULL,
  p_user_type text DEFAULT 'atendente',
  p_super_admin boolean DEFAULT false
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_service_role_key text;
  v_supabase_url text;
  v_auth_user_id uuid;
  v_user_record jsonb;
  v_request_id bigint;
  v_status int;
  v_body text;
  v_attempts int := 0;
BEGIN
  -- Disable statement timeout for this call — HTTP + polling can exceed 8s default
  SET LOCAL statement_timeout = '30s';

  -- 1. Get credentials from _app_config
  SELECT value INTO v_service_role_key FROM _app_config WHERE key = 'service_role_key';
  SELECT value INTO v_supabase_url FROM _app_config WHERE key = 'supabase_url';

  IF v_service_role_key IS NULL OR v_supabase_url IS NULL THEN
    RETURN jsonb_build_object('error', 'Configuração do tenant incompleta. Contacte o administrador.');
  END IF;

  IF NOT v_service_role_key LIKE 'eyJ%' THEN
    RETURN jsonb_build_object('error', 'Service Role Key inválida (não parece um JWT). Re-salve no ADM.');
  END IF;

  -- 2. Fire async HTTP request to Auth Admin API
  SELECT net.http_post(
    url     := v_supabase_url || '/auth/v1/admin/users',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'apikey',        v_service_role_key,
      'Authorization', 'Bearer ' || v_service_role_key
    ),
    body := jsonb_build_object(
      'email',        p_email,
      'password',     p_password,
      'email_confirm', true,
      'user_metadata', jsonb_build_object('full_name', p_name)
    )
  ) INTO v_request_id;

  -- 3. Poll for response (flat columns: status_code + body)
  LOOP
    PERFORM pg_sleep(0.5);
    v_attempts := v_attempts + 1;

    BEGIN
      SELECT status_code, body
        INTO v_status, v_body
        FROM net._http_response
       WHERE id = v_request_id;
    EXCEPTION WHEN undefined_column THEN
      -- Older pg_net uses 'content' instead of 'body'
      SELECT status_code, content
        INTO v_status, v_body
        FROM net._http_response
       WHERE id = v_request_id;
    END;

    EXIT WHEN v_status IS NOT NULL;
    EXIT WHEN v_attempts >= 20; -- max 10s
  END LOOP;

  IF v_status IS NULL THEN
    RETURN jsonb_build_object('error', 'Timeout aguardando resposta do Auth. Tente novamente.');
  END IF;

  IF v_status >= 400 THEN
    RETURN jsonb_build_object('error', COALESCE(
      (v_body::jsonb ->> 'msg'),
      (v_body::jsonb ->> 'message'),
      v_body,
      'Erro ao criar usuário no Auth'
    ));
  END IF;

  v_auth_user_id := (v_body::jsonb ->> 'id')::uuid;

  IF v_auth_user_id IS NULL THEN
    RETURN jsonb_build_object('error', 'Auth retornou sem ID de usuário');
  END IF;

  -- 4. Insert into settings_users
  INSERT INTO settings_users (auth_user_id, name, email, phone, user_type, super_admin, active)
  VALUES (v_auth_user_id, p_name, p_email, p_phone, p_user_type, p_super_admin, true)
  ON CONFLICT (auth_user_id) DO NOTHING;

  -- 5. Return result
  SELECT jsonb_build_object(
    'success',      true,
    'user_id',      su.id,
    'auth_user_id', v_auth_user_id,
    'email',        p_email,
    'name',         p_name
  ) INTO v_user_record
  FROM settings_users su
  WHERE su.auth_user_id = v_auth_user_id;

  RETURN COALESCE(v_user_record,
    jsonb_build_object('error', 'Usuário criado no Auth mas não encontrado em settings_users'));

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('error', SQLERRM);
END;
$$;

GRANT EXECUTE ON FUNCTION public.create_tenant_user TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260408000000_fix_meeting_followup_trigger_lead_id.sql
-- ---------------------------------------------------------------------------

-- ══════════════════════════════════════════════════════════════════════════════
-- Fix: handle_meeting_followup_queue trigger referenced leads_id instead of lead_id
-- Bug: 'new has no field leads_id' when scheduling meetings
-- ══════════════════════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.handle_meeting_followup_queue()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status    text;
  rule_rec    record;
  delay_secs  bigint;
BEGIN
  -- Skip if status didn't change on UPDATE
  IF (TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  -- Normalize meetings.status → meetings_followups.meeting_status
  v_status := CASE NEW.status
    WHEN 'agendada'       THEN 'agendado'
    WHEN 'compareceu'     THEN 'compareceu'
    WHEN 'nao_compareceu' THEN 'nao_compareceu'
    WHEN 'cancelado'      THEN 'cancelado'
    WHEN 'realizado'      THEN 'realizado'
    ELSE NEW.status
  END;

  -- Cancel existing pending queue entries for this meeting (status changed)
  IF TG_OP = 'UPDATE' THEN
    UPDATE public.meeting_followup_queue
       SET status = 'cancelled'
     WHERE meeting_id = NEW.id
       AND status = 'pending';
  END IF;

  -- Create queue entry for each active rule matching the new status
  FOR rule_rec IN
    SELECT id, channel, webhook_url, message, days, hours, minutes
      FROM public.meetings_followups
     WHERE active = true
       AND meeting_status = v_status
       AND webhook_url IS NOT NULL
       AND webhook_url <> ''
  LOOP
    delay_secs := (
      COALESCE(rule_rec.days, 0)    * 86400 +
      COALESCE(rule_rec.hours, 0)   * 3600  +
      COALESCE(rule_rec.minutes, 0) * 60
    )::bigint;

    INSERT INTO public.meeting_followup_queue (
      rule_id, meeting_id, people_id, lead_id,
      scheduled_for, channel, webhook_url, message_snapshot
    ) VALUES (
      rule_rec.id,
      NEW.id,
      NEW.people_id,
      NEW.lead_id,
      now() + (delay_secs * interval '1 second'),
      rule_rec.channel,
      rule_rec.webhook_url,
      rule_rec.message
    );
  END LOOP;

  RETURN NEW;
END;
$$;


