-- ---------------------------------------------------------------------------
-- Migration: 20260415120000_remove_ora_viva_america.sql
-- ---------------------------------------------------------------------------

-- ================================================================
-- MIGRATION: 20260415120000_remove_ora_viva_america.sql
-- JOB-034 — Remove clientes Ora e Viva América do control plane
--
-- Clientes removidos:
--   • Ora          — slug='ora',          supabase_ref='gkvnotsebzjbwiskwnjr'
--   • Viva América — slug='vivaamerica',  supabase_ref='tipahegkywzgrzheckou'
--
-- Ordem de deleção (respeito a FKs):
--   1. adm_migration_runs  — client_id sem FK formal; deleção manual obrigatória
--   2. adm_sync_logs       — FK → adm_sync_jobs (CASCADE), explicitado para auditoria
--   3. adm_sync_jobs       — FK → adm_clients (CASCADE), explicitado para auditoria
--   4. adm_clients         — registro principal
--
-- Banco alvo: control plane ohzwetkaazgxafubzvop
-- Autor: R2-D2 (data-engineer) — JOB-034 — 2026-04-15
-- ================================================================

BEGIN;

DO $$
DECLARE
  v_ids          UUID[];
  v_ora_id       UUID;
  v_viva_id      UUID;
  v_count        INT;
BEGIN

  -- ──────────────────────────────────────────────────────────────
  -- 0. Resolve IDs — dupla verificação: slug + supabase_url
  --    Garante que nunca deletamos o cliente errado
  -- ──────────────────────────────────────────────────────────────
  SELECT id INTO v_ora_id
    FROM public.adm_clients
   WHERE slug = 'ora'
     AND supabase_url LIKE '%gkvnotsebzjbwiskwnjr%';

  SELECT id INTO v_viva_id
    FROM public.adm_clients
   WHERE slug = 'vivaamerica'
     AND supabase_url LIKE '%tipahegkywzgrzheckou%';

  IF v_ora_id IS NULL THEN
    RAISE NOTICE '[JOB-034] Cliente "ora" (gkvnotsebzjbwiskwnjr) não encontrado — sem ação.';
  ELSE
    RAISE NOTICE '[JOB-034] Ora localizado: id=%', v_ora_id;
  END IF;

  IF v_viva_id IS NULL THEN
    RAISE NOTICE '[JOB-034] Cliente "vivaamerica" (tipahegkywzgrzheckou) não encontrado — sem ação.';
  ELSE
    RAISE NOTICE '[JOB-034] Viva América localizado: id=%', v_viva_id;
  END IF;

  -- Monta array compacto com apenas os IDs encontrados
  v_ids := ARRAY_REMOVE(ARRAY[v_ora_id, v_viva_id], NULL);

  IF array_length(v_ids, 1) IS NULL THEN
    RAISE NOTICE '[JOB-034] Nenhum cliente encontrado. Migration encerrada sem alterações.';
    RETURN;
  END IF;

  -- ──────────────────────────────────────────────────────────────
  -- 1. adm_migration_runs
  --    Sem FK formal para adm_clients — deleção manual obrigatória
  -- ──────────────────────────────────────────────────────────────
  DELETE FROM public.adm_migration_runs
   WHERE client_id = ANY(v_ids);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RAISE NOTICE '[JOB-034] adm_migration_runs: % linha(s) removida(s).', v_count;

  -- ──────────────────────────────────────────────────────────────
  -- 2. adm_sync_logs
  --    FK: adm_sync_logs.job_id → adm_sync_jobs.id ON DELETE CASCADE
  --    Explicitado aqui para rastreabilidade de auditoria
  -- ──────────────────────────────────────────────────────────────
  DELETE FROM public.adm_sync_logs
   WHERE job_id IN (
     SELECT id FROM public.adm_sync_jobs
      WHERE client_id = ANY(v_ids)
   );

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RAISE NOTICE '[JOB-034] adm_sync_logs: % linha(s) removida(s).', v_count;

  -- ──────────────────────────────────────────────────────────────
  -- 3. adm_sync_jobs
  --    FK: adm_sync_jobs.client_id → adm_clients.id ON DELETE CASCADE
  --    Explicitado aqui para rastreabilidade de auditoria
  -- ──────────────────────────────────────────────────────────────
  DELETE FROM public.adm_sync_jobs
   WHERE client_id = ANY(v_ids);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RAISE NOTICE '[JOB-034] adm_sync_jobs: % linha(s) removida(s).', v_count;

  -- ──────────────────────────────────────────────────────────────
  -- 4. adm_clients — registro principal
  --    Usa os IDs resolvidos na etapa 0 para máxima segurança
  -- ──────────────────────────────────────────────────────────────
  DELETE FROM public.adm_clients
   WHERE id = ANY(v_ids);

  GET DIAGNOSTICS v_count = ROW_COUNT;
  RAISE NOTICE '[JOB-034] adm_clients: % linha(s) removida(s).', v_count;

  RAISE NOTICE '[JOB-034] Migration concluída com sucesso.';

END;
$$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260417200205_save_agent_complete_rpc.sql
-- ---------------------------------------------------------------------------

-- AIA-07: Atomic save for ai_agents + ai_agents_steps + ai_agents_history
-- Replaces the 5-roundtrip sequential save in useSalvarAgente with a single transaction.
--
-- Contract:
--   p_agent_id    uuid   — agent to update
--   p_agent_data  jsonb  — fields to update on ai_agents (only provided keys are applied)
--   p_steps_data  jsonb  — full replacement array for ai_agents_steps
--                          each element: {id?, name, prompt, control?, order_index, active?,
--                                         pipeline_id?, stage_id?}
--   p_changelog   jsonb  — changelog object already built by the frontend
--   p_created_by  uuid   — optional: settings_users.id of the saving user
--
-- Returns: jsonb {version: int, ok: bool}
--
-- Notes:
--   - Steps are fully replaced (DELETE + INSERT) to avoid partial-update drift.
--   - If p_steps_data is NULL the steps are left untouched (agent-only save).
--   - History snapshot is taken BEFORE the update (state the user is replacing).
--   - SECURITY DEFINER so it runs with owner privileges (bypasses RLS for internal ops).
--     The caller must be authenticated — enforced by the Supabase anon/service-role key.

CREATE OR REPLACE FUNCTION public.save_agent_complete(
  p_agent_id   uuid,
  p_agent_data jsonb,
  p_steps_data jsonb DEFAULT NULL,
  p_changelog  jsonb DEFAULT NULL,
  p_created_by uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_current_version int;
  v_new_version     int;
  v_snapshot        jsonb;
  v_step            jsonb;
  v_step_id         uuid;
BEGIN
  -- 1. Lock the agent row and read current state
  SELECT current_version,
         to_jsonb(a) AS snapshot
  INTO   v_current_version, v_snapshot
  FROM   public.ai_agents a
  WHERE  id = p_agent_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent not found: %', p_agent_id;
  END IF;

  -- Attach current steps to the snapshot (same shape as the frontend historyData)
  v_snapshot := jsonb_set(
    v_snapshot,
    '{steps}',
    COALESCE(
      (SELECT jsonb_agg(to_jsonb(s) ORDER BY s.order_index)
       FROM public.ai_agents_steps s
       WHERE s.ai_agent_id = p_agent_id),
      '[]'::jsonb
    )
  );

  -- 2. Write history entry (state BEFORE the update)
  INSERT INTO public.ai_agents_history
    (ai_agent_id, version, data, changelog, created_by)
  VALUES
    (p_agent_id, v_current_version, v_snapshot, p_changelog, p_created_by);

  -- 3. Update ai_agents
  v_new_version := v_current_version + 1;

  UPDATE public.ai_agents
  SET
    name                = COALESCE((p_agent_data->>'name'),                name),
    description         = COALESCE((p_agent_data->>'description'),         description),
    identity            = COALESCE((p_agent_data->>'identity'),            identity),
    general_rules       = COALESCE((p_agent_data->>'general_rules'),       general_rules),
    input_data          = COALESCE((p_agent_data->>'input_data'),          input_data),
    use_stages          = COALESCE((p_agent_data->>'use_stages')::boolean, use_stages),
    active              = COALESCE((p_agent_data->>'active')::boolean,     active),
    pipeline_id         = CASE WHEN p_agent_data ? 'pipeline_id'
                               THEN (p_agent_data->>'pipeline_id')::uuid
                               ELSE pipeline_id END,
    pipeline_ids        = CASE WHEN p_agent_data ? 'pipeline_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'pipeline_ids'))::uuid[]
                               ELSE pipeline_ids END,
    leads_stages_id     = CASE WHEN p_agent_data ? 'leads_stages_id'
                               THEN (p_agent_data->>'leads_stages_id')::uuid
                               ELSE leads_stages_id END,
    score_matrix_ids    = CASE WHEN p_agent_data ? 'score_matrix_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'score_matrix_ids'))::uuid[]
                               ELSE score_matrix_ids END,
    score_allow_empty   = COALESCE((p_agent_data->>'score_allow_empty')::boolean, score_allow_empty),
    score_value         = COALESCE((p_agent_data->>'score_value')::integer,       score_value),
    channel_types       = CASE WHEN p_agent_data ? 'channel_types'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'channel_types'))
                               ELSE channel_types END,
    stage_ids           = CASE WHEN p_agent_data ? 'stage_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'stage_ids'))::uuid[]
                               ELSE stage_ids END,
    llm_provider        = COALESCE((p_agent_data->>'llm_provider'),        llm_provider),
    llm_model           = COALESCE((p_agent_data->>'llm_model'),           llm_model),
    llm_temperature     = COALESCE((p_agent_data->>'llm_temperature')::numeric,  llm_temperature),
    llm_max_tokens      = COALESCE((p_agent_data->>'llm_max_tokens')::integer,   llm_max_tokens),
    llm_provider_id     = CASE WHEN p_agent_data ? 'llm_provider_id'
                               THEN (p_agent_data->>'llm_provider_id')::uuid
                               ELSE llm_provider_id END,
    memory_window       = COALESCE((p_agent_data->>'memory_window')::integer,    memory_window),
    wa_phone_number_id  = COALESCE((p_agent_data->>'wa_phone_number_id'),  wa_phone_number_id),
    wa_channel_id       = CASE WHEN p_agent_data ? 'wa_channel_id'
                               THEN (p_agent_data->>'wa_channel_id')::uuid
                               ELSE wa_channel_id END,
    buffer_ms           = COALESCE((p_agent_data->>'buffer_ms')::integer,  buffer_ms),
    humanizacao         = COALESCE((p_agent_data->>'humanizacao')::boolean, humanizacao),
    agent_type          = COALESCE((p_agent_data->>'agent_type'),          agent_type),
    voice_enabled       = COALESCE((p_agent_data->>'voice_enabled')::boolean,    voice_enabled),
    voice_response_mode = COALESCE((p_agent_data->>'voice_response_mode'), voice_response_mode),
    voice_id            = COALESCE((p_agent_data->>'voice_id'),            voice_id),
    voice_first_message = COALESCE((p_agent_data->>'voice_first_message'), voice_first_message),
    voice_language      = COALESCE((p_agent_data->>'voice_language'),      voice_language),
    voice_model_id      = COALESCE((p_agent_data->>'voice_model_id'),      voice_model_id),
    voice_stability     = COALESCE((p_agent_data->>'voice_stability')::numeric,  voice_stability),
    voice_similarity    = COALESCE((p_agent_data->>'voice_similarity')::numeric, voice_similarity),
    voice_speed         = COALESCE((p_agent_data->>'voice_speed')::numeric,      voice_speed),
    el_sync_status      = COALESCE((p_agent_data->>'el_sync_status'),      el_sync_status),
    current_version     = v_new_version,
    updated_at          = now()
  WHERE id = p_agent_id;

  -- 4. Replace steps (only when caller provides the array)
  IF p_steps_data IS NOT NULL THEN
    DELETE FROM public.ai_agents_steps
    WHERE ai_agent_id = p_agent_id;

    FOR v_step IN SELECT * FROM jsonb_array_elements(p_steps_data)
    LOOP
      -- Honour the id supplied by the frontend so React Query cache stays valid;
      -- fall back to a fresh uuid when not provided.
      v_step_id := CASE
        WHEN v_step ? 'id'
          AND (v_step->>'id') IS NOT NULL
          AND (v_step->>'id') <> ''
        THEN (v_step->>'id')::uuid
        ELSE gen_random_uuid()
      END;

      INSERT INTO public.ai_agents_steps
        (id, ai_agent_id, name, prompt, control, order_index,
         pipeline_id, stage_id, active, created_at, updated_at)
      VALUES (
        v_step_id,
        p_agent_id,
        v_step->>'name',
        COALESCE(v_step->>'prompt', ''),
        NULLIF(v_step->>'control', ''),
        (v_step->>'order_index')::integer,
        CASE WHEN (v_step->>'pipeline_id') IS NOT NULL AND (v_step->>'pipeline_id') <> ''
             THEN (v_step->>'pipeline_id')::uuid ELSE NULL END,
        CASE WHEN (v_step->>'stage_id') IS NOT NULL AND (v_step->>'stage_id') <> ''
             THEN (v_step->>'stage_id')::uuid ELSE NULL END,
        COALESCE((v_step->>'active')::boolean, true),
        now(),
        now()
      );
    END LOOP;
  END IF;

  -- 5. Return new version
  RETURN jsonb_build_object('version', v_new_version, 'ok', true);
END;
$$;

-- Grant execute to authenticated users (Supabase RLS-compatible pattern)
GRANT EXECUTE ON FUNCTION public.save_agent_complete(uuid, jsonb, jsonb, jsonb, uuid)
  TO authenticated;

-- Revoke from anon (this RPC must never run unauthenticated)
REVOKE EXECUTE ON FUNCTION public.save_agent_complete(uuid, jsonb, jsonb, jsonb, uuid)
  FROM anon;


-- ---------------------------------------------------------------------------
-- Migration: 20260420000000_fix_insights_context_status_strings.sql
-- ---------------------------------------------------------------------------

-- Fix get_insights_context: normalize status strings to English (P8 migration)
-- Root cause: 20260228010000 normalized lead/meeting statuses to English but function
-- still used Portuguese values, causing won=0, revenue=0, conversion=0% everywhere.

CREATE OR REPLACE FUNCTION public.get_insights_context(
  p_date_from timestamptz DEFAULT NULL,
  p_date_to   timestamptz DEFAULT NULL,
  p_pipeline_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result jsonb := '{}'::jsonb;
  v_funnel jsonb;
  v_people jsonb;
  v_messages jsonb;
  v_meetings jsonb;
  v_calls jsonb;
  v_marketing jsonb;
  v_prospect jsonb;
  v_pipelines jsonb;
BEGIN

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 0: AVAILABLE PIPELINES (for LLM context)
  -- ═══════════════════════════════════════════════════════════════════════
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name)), '[]'::jsonb)
  INTO v_pipelines
  FROM leads_pipelines
  WHERE active = true;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 1: FUNNEL (leads by stage, conversion, loss reasons, velocity)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH lead_base AS (
    SELECT l.id, l.status, l.value, l.leads_stages_id, l.leads_pipelines_id,
           l.leads_loss_reasons_id, l.created_at, l.won_at
    FROM leads l
    WHERE (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
  ),
  stages_agg AS (
    SELECT
      ls.name AS stage_name,
      ls.order_index,
      COUNT(lb.id) AS lead_count,
      COALESCE(SUM(lb.value), 0) AS total_value,
      ROUND(AVG(EXTRACT(EPOCH FROM (now() - lb.created_at)) / 86400)::numeric, 1) AS avg_days
    FROM lead_base lb
    JOIN leads_stages ls ON ls.id = lb.leads_stages_id
    WHERE lb.status = 'in_progress'
    GROUP BY ls.name, ls.order_index
    ORDER BY ls.order_index
  ),
  loss_reasons AS (
    SELECT
      COALESCE(lr.name, 'Sem motivo') AS reason,
      COUNT(*) AS cnt
    FROM lead_base lb
    LEFT JOIN leads_loss_reasons lr ON lr.id = lb.leads_loss_reasons_id
    WHERE lb.status = 'lost'
    GROUP BY lr.name
    ORDER BY cnt DESC
    LIMIT 5
  ),
  funnel_totals AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'won') AS won,
      COUNT(*) FILTER (WHERE status = 'lost') AS lost,
      COUNT(*) FILTER (WHERE status = 'in_progress') AS active,
      COALESCE(SUM(value) FILTER (WHERE status = 'won'), 0) AS revenue,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - created_at)) / 86400) FILTER (WHERE status = 'won' AND won_at IS NOT NULL))::numeric, 1) AS avg_cycle_days
    FROM lead_base
  )
  SELECT jsonb_build_object(
    'total', ft.total,
    'won', ft.won,
    'lost', ft.lost,
    'active', ft.active,
    'revenue', ft.revenue,
    'avg_deal', CASE WHEN ft.won > 0 THEN ROUND((ft.revenue / ft.won)::numeric, 2) ELSE 0 END,
    'conversion_pct', CASE WHEN ft.total > 0 THEN ROUND((ft.won::numeric / ft.total * 100), 1) ELSE 0 END,
    'avg_cycle_days', COALESCE(ft.avg_cycle_days, 0),
    'stages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', s.stage_name, 'leads', s.lead_count, 'value', s.total_value, 'avg_days', s.avg_days
    ) ORDER BY s.order_index) FROM stages_agg s), '[]'::jsonb),
    'loss_reasons', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'reason', r.reason, 'count', r.cnt
    )) FROM loss_reasons r), '[]'::jsonb)
  ) INTO v_funnel
  FROM funnel_totals ft;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 2: PEOPLE & COMPANIES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH people_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ativo') AS active,
      COUNT(*) FILTER (WHERE status != 'ativo') AS inactive,
      COUNT(*) FILTER (WHERE score BETWEEN 0 AND 25) AS score_0_25,
      COUNT(*) FILTER (WHERE score BETWEEN 26 AND 50) AS score_26_50,
      COUNT(*) FILTER (WHERE score BETWEEN 51 AND 75) AS score_51_75,
      COUNT(*) FILTER (WHERE score BETWEEN 76 AND 100) AS score_76_100
    FROM clients_people
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  top_sources AS (
    SELECT source, COUNT(*) AS cnt
    FROM clients_people
    WHERE source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY source
    ORDER BY cnt DESC
    LIMIT 5
  ),
  company_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) AS active
    FROM clients_companies
  )
  SELECT jsonb_build_object(
    'people_total', ps.total,
    'people_active', ps.active,
    'people_inactive', ps.inactive,
    'score_distribution', jsonb_build_object(
      '0_25', ps.score_0_25, '26_50', ps.score_26_50,
      '51_75', ps.score_51_75, '76_100', ps.score_76_100
    ),
    'top_sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('source', ts.source, 'count', ts.cnt)) FROM top_sources ts), '[]'::jsonb),
    'companies_total', cs.total,
    'companies_active', cs.active
  ) INTO v_people
  FROM people_stats ps, company_stats cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 3: MESSAGES (volume by channel, IA vs human, trend, abandoned)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH msg_base AS (
    SELECT id, channel, from_contact, created_at, lead_id
    FROM messages
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  by_channel AS (
    SELECT channel, COUNT(*) AS cnt
    FROM msg_base GROUP BY channel ORDER BY cnt DESC
  ),
  by_sender AS (
    SELECT from_contact, COUNT(*) AS cnt
    FROM msg_base GROUP BY from_contact
  ),
  daily_trend AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM msg_base
    WHERE created_at >= (COALESCE(p_date_to, now()) - interval '7 days')
    GROUP BY day ORDER BY day
  ),
  abandoned AS (
    SELECT COUNT(DISTINCT lead_id) AS cnt
    FROM (
      SELECT lead_id,
             from_contact,
             created_at,
             LEAD(from_contact) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_sender,
             LEAD(created_at) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_at
      FROM msg_base
    ) sub
    WHERE from_contact = 'cliente'
      AND (next_sender IS NULL OR (next_sender != 'cliente' AND next_at - created_at > interval '24 hours'))
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM msg_base),
    'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'count', c.cnt)) FROM by_channel c), '[]'::jsonb),
    'by_sender', COALESCE((SELECT jsonb_agg(jsonb_build_object('sender', s.from_contact, 'count', s.cnt)) FROM by_sender s), '[]'::jsonb),
    'daily_trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'count', d.cnt)) FROM daily_trend d), '[]'::jsonb),
    'abandoned_conversations', ab.cnt
  ) INTO v_messages
  FROM abandoned ab;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 4: MEETINGS (status, show rate by closer, time metrics)
  -- FILTER: Only system-booked meetings (exclude Google Calendar imports)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH mtg_base AS (
    SELECT m.id, m.status, m.start_time, m.user_id, m.lead_id,
           l.created_at AS lead_created, l.won_at,
           l.utm_campaign, l.utm_source
    FROM meetings m
    LEFT JOIN leads l ON l.id = m.lead_id
    WHERE (p_date_from IS NULL OR m.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR m.created_at <= p_date_to)
      AND (m.source IS NULL OR m.source != 'google')
  ),
  by_status AS (
    SELECT status, COUNT(*) AS cnt FROM mtg_base GROUP BY status
  ),
  show_rate_by_user AS (
    SELECT
      COALESCE(su.name, 'Sem responsável') AS closer_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mb.status IN ('compareceu', 'realizado')) AS attended,
      CASE WHEN COUNT(*) > 0
        THEN ROUND((COUNT(*) FILTER (WHERE mb.status IN ('compareceu', 'realizado')))::numeric / COUNT(*) * 100, 1)
        ELSE 0 END AS show_rate
    FROM mtg_base mb
    LEFT JOIN settings_users su ON su.id = mb.user_id
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 5
  ),
  time_metrics AS (
    SELECT
      ROUND(AVG(EXTRACT(EPOCH FROM (start_time - lead_created)) / 86400)::numeric, 1) AS avg_lead_to_meeting,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - start_time)) / 86400) FILTER (WHERE won_at IS NOT NULL))::numeric, 1) AS avg_meeting_to_close
    FROM mtg_base
    WHERE lead_created IS NOT NULL
  ),
  meetings_by_campaign AS (
    -- Reverse lookup: start from leads with UTM → check if they have meetings
    SELECT
      COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha') AS campaign,
      COUNT(DISTINCT l.id) AS leads,
      COUNT(DISTINCT m2.id) AS meetings,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('compareceu', 'realizado')) AS attended,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('nao_compareceu', 'não compareceu', 'cancelado', 'cancelada')) AS no_show,
      COUNT(DISTINCT l.id) FILTER (WHERE l.status = 'won') AS won
    FROM leads l
    LEFT JOIN meetings m2 ON m2.lead_id = l.id AND (m2.source IS NULL OR m2.source != 'google')
    WHERE (l.utm_source IS NOT NULL OR l.utm_campaign IS NOT NULL)
      AND (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
    GROUP BY COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha')
    ORDER BY leads DESC
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM mtg_base),
    'by_status', COALESCE((SELECT jsonb_agg(jsonb_build_object('status', bs.status, 'count', bs.cnt)) FROM by_status bs), '[]'::jsonb),
    'show_rate_by_closer', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', sr.closer_name, 'total', sr.total, 'attended', sr.attended, 'show_rate', sr.show_rate
    )) FROM show_rate_by_user sr), '[]'::jsonb),
    'avg_lead_to_meeting_days', COALESCE(tm.avg_lead_to_meeting, 0),
    'avg_meeting_to_close_days', COALESCE(tm.avg_meeting_to_close, 0),
    'by_campaign', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'campaign', mc.campaign, 'leads', mc.leads, 'meetings', mc.meetings,
      'attended', mc.attended, 'no_show', mc.no_show, 'won', mc.won
    )) FROM meetings_by_campaign mc), '[]'::jsonb)
  ) INTO v_meetings
  FROM time_metrics tm;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 5: CALLS (inbound/outbound, answer rate, duration, operators)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH call_base AS (
    SELECT id, direction, status, duration, user_id, outcome, tags
    FROM call_pro_calls
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  call_summary AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE direction = 'inbound') AS inbound,
      COUNT(*) FILTER (WHERE direction = 'outbound') AS outbound,
      COUNT(*) FILTER (WHERE status IN ('answered', 'handled')) AS answered,
      ROUND((AVG(duration) FILTER (WHERE duration > 0))::numeric, 0) AS avg_duration_sec
    FROM call_base
  ),
  top_operators AS (
    SELECT
      COALESCE(su.name, 'Desconhecido') AS operator_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE cb.status IN ('answered', 'handled')) AS answered
    FROM call_base cb
    LEFT JOIN settings_users su ON su.id = cb.user_id
    WHERE cb.user_id IS NOT NULL
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 3
  ),
  top_outcomes AS (
    SELECT outcome, COUNT(*) AS cnt
    FROM call_base
    WHERE outcome IS NOT NULL AND outcome != ''
    GROUP BY outcome
    ORDER BY cnt DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total', cs.total,
    'inbound', cs.inbound,
    'outbound', cs.outbound,
    'answered', cs.answered,
    'answer_rate', CASE WHEN cs.total > 0 THEN ROUND((cs.answered::numeric / cs.total * 100), 1) ELSE 0 END,
    'avg_duration_sec', COALESCE(cs.avg_duration_sec, 0),
    'top_operators', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', op.operator_name, 'total', op.total, 'answered', op.answered
    )) FROM top_operators op), '[]'::jsonb),
    'top_outcomes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'outcome', o.outcome, 'count', o.cnt
    )) FROM top_outcomes o), '[]'::jsonb)
  ) INTO v_calls
  FROM call_summary cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 6: MARKETING (sends, LPs, UTM, Meta forms)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH sends_summary AS (
    SELECT
      COUNT(*) AS total_sends,
      SUM(total_contacts) AS total_contacts,
      SUM(sent_count) AS total_sent,
      SUM(delivered_count) AS total_delivered,
      SUM(read_count) AS total_read
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  sends_by_channel AS (
    SELECT channel, COUNT(*) AS cnt, SUM(sent_count) AS sent, SUM(delivered_count) AS delivered, SUM(read_count) AS read_cnt
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY channel
  ),
  lp_stats AS (
    SELECT
      f.name AS page_name,
      COUNT(s.id) AS submissions
    FROM form_pro_forms f
    LEFT JOIN form_pro_submissions s ON s.form_id = f.id
      AND (p_date_from IS NULL OR s.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR s.submitted_at <= p_date_to)
    GROUP BY f.name
    ORDER BY submissions DESC
    LIMIT 5
  ),
  utm_stats AS (
    SELECT
      COALESCE(utm_source, 'direto') AS source,
      COALESCE(utm_medium, 'none') AS medium,
      COUNT(*) AS leads,
      COUNT(*) FILTER (WHERE status = 'won') AS won
    FROM leads
    WHERE utm_source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR leads_pipelines_id = p_pipeline_id)
    GROUP BY utm_source, utm_medium
    ORDER BY leads DESC
    LIMIT 5
  ),
  meta_forms_stats AS (
    SELECT
      mf.name AS form_name,
      COUNT(DISTINCT l.id) AS leads_count
    FROM meta_lead_forms mf
    LEFT JOIN form_pro_submissions fps ON fps.meta_form_id = mf.id
      AND (p_date_from IS NULL OR fps.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR fps.submitted_at <= p_date_to)
    LEFT JOIN leads l ON l.id = fps.lead_id
    WHERE mf.status = 'active'
    GROUP BY mf.name
    ORDER BY leads_count DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'sends', jsonb_build_object(
      'total_campaigns', ss.total_sends,
      'total_sent', COALESCE(ss.total_sent, 0),
      'total_delivered', COALESCE(ss.total_delivered, 0),
      'total_read', COALESCE(ss.total_read, 0),
      'delivery_rate', CASE WHEN COALESCE(ss.total_sent, 0) > 0
        THEN ROUND((COALESCE(ss.total_delivered, 0)::numeric / ss.total_sent * 100), 1) ELSE 0 END,
      'read_rate', CASE WHEN COALESCE(ss.total_delivered, 0) > 0
        THEN ROUND((COALESCE(ss.total_read, 0)::numeric / ss.total_delivered * 100), 1) ELSE 0 END,
      'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'channel', sc.channel, 'campaigns', sc.cnt, 'sent', sc.sent, 'delivered', sc.delivered, 'read', sc.read_cnt
      )) FROM sends_by_channel sc), '[]'::jsonb)
    ),
    'landing_pages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', lps.page_name, 'submissions', lps.submissions
    )) FROM lp_stats lps WHERE lps.submissions > 0), '[]'::jsonb),
    'utm_attribution', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'source', u.source, 'medium', u.medium, 'leads', u.leads, 'won', u.won
    )) FROM utm_stats u), '[]'::jsonb),
    'meta_forms', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', mfs.form_name, 'leads', mfs.leads_count
    )) FROM meta_forms_stats mfs), '[]'::jsonb)
  ) INTO v_marketing
  FROM sends_summary ss;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 7: PROSPECT PRO (campaigns, contacts breakdown, AI score)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH prospect_campaigns_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'running') AS running,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed
    FROM prospect_campaigns
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  prospect_contacts_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE pc.status = 'raw') AS raw_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'filtered') AS filtered_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'enriched') AS enriched_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'approved') AS approved_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'rejected') AS rejected_cnt,
      ROUND((AVG(ai_score) FILTER (WHERE ai_score IS NOT NULL))::numeric, 0) AS avg_ai_score
    FROM prospect_contacts pc
    JOIN prospect_campaigns camp ON camp.id = pc.campaign_id
    WHERE (p_date_from IS NULL OR pc.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR pc.created_at <= p_date_to)
  )
  SELECT jsonb_build_object(
    'campaigns_total', pca.total,
    'campaigns_running', pca.running,
    'campaigns_completed', pca.completed,
    'contacts_total', pcta.total,
    'contacts_by_status', jsonb_build_object(
      'raw', pcta.raw_cnt, 'filtered', pcta.filtered_cnt,
      'enriched', pcta.enriched_cnt, 'approved', pcta.approved_cnt, 'rejected', pcta.rejected_cnt
    ),
    'avg_ai_score', COALESCE(pcta.avg_ai_score, 0),
    'approval_rate', CASE WHEN pcta.total > 0
      THEN ROUND((pcta.approved_cnt::numeric / pcta.total * 100), 1) ELSE 0 END
  ) INTO v_prospect
  FROM prospect_campaigns_agg pca, prospect_contacts_agg pcta;

  -- ═══════════════════════════════════════════════════════════════════════
  -- ASSEMBLE FINAL RESULT
  -- ═══════════════════════════════════════════════════════════════════════
  result := jsonb_build_object(
    'pipelines', COALESCE(v_pipelines, '[]'::jsonb),
    'funnel', COALESCE(v_funnel, '{}'::jsonb),
    'people', COALESCE(v_people, '{}'::jsonb),
    'messages', COALESCE(v_messages, '{}'::jsonb),
    'meetings', COALESCE(v_meetings, '{}'::jsonb),
    'calls', COALESCE(v_calls, '{}'::jsonb),
    'marketing', COALESCE(v_marketing, '{}'::jsonb),
    'prospect', COALESCE(v_prospect, '{}'::jsonb)
  );

  RETURN result;
END;
$$;

-- Grant access to authenticated users and service_role
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO service_role;


-- ---------------------------------------------------------------------------
-- Migration: 20260420200000_add_daily_breakdown_insights.sql
-- ---------------------------------------------------------------------------

-- Add leads_by_day and sales_by_day to get_insights_context BLOCK 1
-- Enables line/area chart generation in bi-insights-chat for temporal queries

CREATE OR REPLACE FUNCTION public.get_insights_context(
  p_date_from timestamptz DEFAULT NULL,
  p_date_to   timestamptz DEFAULT NULL,
  p_pipeline_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result jsonb := '{}'::jsonb;
  v_funnel jsonb;
  v_people jsonb;
  v_messages jsonb;
  v_meetings jsonb;
  v_calls jsonb;
  v_marketing jsonb;
  v_prospect jsonb;
  v_pipelines jsonb;
BEGIN

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 0: AVAILABLE PIPELINES (for LLM context)
  -- ═══════════════════════════════════════════════════════════════════════
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name)), '[]'::jsonb)
  INTO v_pipelines
  FROM leads_pipelines
  WHERE active = true;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 1: FUNNEL (leads by stage, conversion, loss reasons, velocity)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH lead_base AS (
    SELECT l.id, l.status, l.value, l.leads_stages_id, l.leads_pipelines_id,
           l.leads_loss_reasons_id, l.created_at, l.won_at
    FROM leads l
    WHERE (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
  ),
  stages_agg AS (
    SELECT
      ls.name AS stage_name,
      ls.order_index,
      COUNT(lb.id) AS lead_count,
      COALESCE(SUM(lb.value), 0) AS total_value,
      ROUND(AVG(EXTRACT(EPOCH FROM (now() - lb.created_at)) / 86400)::numeric, 1) AS avg_days
    FROM lead_base lb
    JOIN leads_stages ls ON ls.id = lb.leads_stages_id
    WHERE lb.status = 'in_progress'
    GROUP BY ls.name, ls.order_index
    ORDER BY ls.order_index
  ),
  loss_reasons AS (
    SELECT
      COALESCE(lr.name, 'Sem motivo') AS reason,
      COUNT(*) AS cnt
    FROM lead_base lb
    LEFT JOIN leads_loss_reasons lr ON lr.id = lb.leads_loss_reasons_id
    WHERE lb.status = 'lost'
    GROUP BY lr.name
    ORDER BY cnt DESC
    LIMIT 5
  ),
  funnel_totals AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'won') AS won,
      COUNT(*) FILTER (WHERE status = 'lost') AS lost,
      COUNT(*) FILTER (WHERE status = 'in_progress') AS active,
      COALESCE(SUM(value) FILTER (WHERE status = 'won'), 0) AS revenue,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - created_at)) / 86400) FILTER (WHERE status = 'won' AND won_at IS NOT NULL))::numeric, 1) AS avg_cycle_days
    FROM lead_base
  ),
  leads_by_day AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM lead_base
    GROUP BY day ORDER BY day
  ),
  sales_by_day AS (
    SELECT won_at::date AS day, COUNT(*) AS cnt, COALESCE(SUM(value), 0) AS revenue
    FROM lead_base
    WHERE status = 'won' AND won_at IS NOT NULL
    GROUP BY day ORDER BY day
  )
  SELECT jsonb_build_object(
    'total', ft.total,
    'won', ft.won,
    'lost', ft.lost,
    'active', ft.active,
    'revenue', ft.revenue,
    'avg_deal', CASE WHEN ft.won > 0 THEN ROUND((ft.revenue / ft.won)::numeric, 2) ELSE 0 END,
    'conversion_pct', CASE WHEN ft.total > 0 THEN ROUND((ft.won::numeric / ft.total * 100), 1) ELSE 0 END,
    'avg_cycle_days', COALESCE(ft.avg_cycle_days, 0),
    'stages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', s.stage_name, 'leads', s.lead_count, 'value', s.total_value, 'avg_days', s.avg_days
    ) ORDER BY s.order_index) FROM stages_agg s), '[]'::jsonb),
    'loss_reasons', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'reason', r.reason, 'count', r.cnt
    )) FROM loss_reasons r), '[]'::jsonb),
    'leads_by_day', COALESCE((SELECT jsonb_agg(jsonb_build_object('dia', d.day, 'leads', d.cnt)) FROM leads_by_day d), '[]'::jsonb),
    'sales_by_day', COALESCE((SELECT jsonb_agg(jsonb_build_object('dia', d.day, 'vendas', d.cnt, 'receita', d.revenue)) FROM sales_by_day d), '[]'::jsonb)
  ) INTO v_funnel
  FROM funnel_totals ft;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 2: PEOPLE & COMPANIES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH people_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ativo') AS active,
      COUNT(*) FILTER (WHERE status != 'ativo') AS inactive,
      COUNT(*) FILTER (WHERE score BETWEEN 0 AND 25) AS score_0_25,
      COUNT(*) FILTER (WHERE score BETWEEN 26 AND 50) AS score_26_50,
      COUNT(*) FILTER (WHERE score BETWEEN 51 AND 75) AS score_51_75,
      COUNT(*) FILTER (WHERE score BETWEEN 76 AND 100) AS score_76_100
    FROM clients_people
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  top_sources AS (
    SELECT source, COUNT(*) AS cnt
    FROM clients_people
    WHERE source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY source
    ORDER BY cnt DESC
    LIMIT 5
  ),
  company_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) AS active
    FROM clients_companies
  )
  SELECT jsonb_build_object(
    'people_total', ps.total,
    'people_active', ps.active,
    'people_inactive', ps.inactive,
    'score_distribution', jsonb_build_object(
      '0_25', ps.score_0_25, '26_50', ps.score_26_50,
      '51_75', ps.score_51_75, '76_100', ps.score_76_100
    ),
    'top_sources', COALESCE((SELECT jsonb_agg(jsonb_build_object('source', ts.source, 'count', ts.cnt)) FROM top_sources ts), '[]'::jsonb),
    'companies_total', cs.total,
    'companies_active', cs.active
  ) INTO v_people
  FROM people_stats ps, company_stats cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 3: MESSAGES (volume by channel, IA vs human, trend, abandoned)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH msg_base AS (
    SELECT id, channel, from_contact, created_at, lead_id
    FROM messages
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  by_channel AS (
    SELECT channel, COUNT(*) AS cnt
    FROM msg_base GROUP BY channel ORDER BY cnt DESC
  ),
  by_sender AS (
    SELECT from_contact, COUNT(*) AS cnt
    FROM msg_base GROUP BY from_contact
  ),
  daily_trend AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM msg_base
    WHERE created_at >= (COALESCE(p_date_to, now()) - interval '7 days')
    GROUP BY day ORDER BY day
  ),
  abandoned AS (
    SELECT COUNT(DISTINCT lead_id) AS cnt
    FROM (
      SELECT lead_id,
             from_contact,
             created_at,
             LEAD(from_contact) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_sender,
             LEAD(created_at) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_at
      FROM msg_base
    ) sub
    WHERE from_contact = 'cliente'
      AND (next_sender IS NULL OR (next_sender != 'cliente' AND next_at - created_at > interval '24 hours'))
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM msg_base),
    'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'count', c.cnt)) FROM by_channel c), '[]'::jsonb),
    'by_sender', COALESCE((SELECT jsonb_agg(jsonb_build_object('sender', s.from_contact, 'count', s.cnt)) FROM by_sender s), '[]'::jsonb),
    'daily_trend', COALESCE((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'count', d.cnt)) FROM daily_trend d), '[]'::jsonb),
    'abandoned_conversations', ab.cnt
  ) INTO v_messages
  FROM abandoned ab;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 4: MEETINGS (status, show rate by closer, time metrics)
  -- FILTER: Only system-booked meetings (exclude Google Calendar imports)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH mtg_base AS (
    SELECT m.id, m.status, m.start_time, m.user_id, m.lead_id,
           l.created_at AS lead_created, l.won_at,
           l.utm_campaign, l.utm_source
    FROM meetings m
    LEFT JOIN leads l ON l.id = m.lead_id
    WHERE (p_date_from IS NULL OR m.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR m.created_at <= p_date_to)
      AND (m.source IS NULL OR m.source != 'google')
  ),
  by_status AS (
    SELECT status, COUNT(*) AS cnt FROM mtg_base GROUP BY status
  ),
  show_rate_by_user AS (
    SELECT
      COALESCE(su.name, 'Sem responsável') AS closer_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mb.status IN ('compareceu', 'realizado')) AS attended,
      CASE WHEN COUNT(*) > 0
        THEN ROUND((COUNT(*) FILTER (WHERE mb.status IN ('compareceu', 'realizado')))::numeric / COUNT(*) * 100, 1)
        ELSE 0 END AS show_rate
    FROM mtg_base mb
    LEFT JOIN settings_users su ON su.id = mb.user_id
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 5
  ),
  time_metrics AS (
    SELECT
      ROUND(AVG(EXTRACT(EPOCH FROM (start_time - lead_created)) / 86400)::numeric, 1) AS avg_lead_to_meeting,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - start_time)) / 86400) FILTER (WHERE won_at IS NOT NULL))::numeric, 1) AS avg_meeting_to_close
    FROM mtg_base
    WHERE lead_created IS NOT NULL
  ),
  meetings_by_campaign AS (
    SELECT
      COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha') AS campaign,
      COUNT(DISTINCT l.id) AS leads,
      COUNT(DISTINCT m2.id) AS meetings,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('compareceu', 'realizado')) AS attended,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('nao_compareceu', 'não compareceu', 'cancelado', 'cancelada')) AS no_show,
      COUNT(DISTINCT l.id) FILTER (WHERE l.status = 'won') AS won
    FROM leads l
    LEFT JOIN meetings m2 ON m2.lead_id = l.id AND (m2.source IS NULL OR m2.source != 'google')
    WHERE (l.utm_source IS NOT NULL OR l.utm_campaign IS NOT NULL)
      AND (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
    GROUP BY COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha')
    ORDER BY leads DESC
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'total', (SELECT COUNT(*) FROM mtg_base),
    'by_status', COALESCE((SELECT jsonb_agg(jsonb_build_object('status', bs.status, 'count', bs.cnt)) FROM by_status bs), '[]'::jsonb),
    'show_rate_by_closer', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', sr.closer_name, 'total', sr.total, 'attended', sr.attended, 'show_rate', sr.show_rate
    )) FROM show_rate_by_user sr), '[]'::jsonb),
    'avg_lead_to_meeting_days', COALESCE(tm.avg_lead_to_meeting, 0),
    'avg_meeting_to_close_days', COALESCE(tm.avg_meeting_to_close, 0),
    'by_campaign', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'campaign', mc.campaign, 'leads', mc.leads, 'meetings', mc.meetings,
      'attended', mc.attended, 'no_show', mc.no_show, 'won', mc.won
    )) FROM meetings_by_campaign mc), '[]'::jsonb)
  ) INTO v_meetings
  FROM time_metrics tm;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 5: CALLS (inbound/outbound, answer rate, duration, operators)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH call_base AS (
    SELECT id, direction, status, duration, user_id, outcome, tags
    FROM call_pro_calls
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  call_summary AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE direction = 'inbound') AS inbound,
      COUNT(*) FILTER (WHERE direction = 'outbound') AS outbound,
      COUNT(*) FILTER (WHERE status IN ('answered', 'handled')) AS answered,
      ROUND((AVG(duration) FILTER (WHERE duration > 0))::numeric, 0) AS avg_duration_sec
    FROM call_base
  ),
  top_operators AS (
    SELECT
      COALESCE(su.name, 'Desconhecido') AS operator_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE cb.status IN ('answered', 'handled')) AS answered
    FROM call_base cb
    LEFT JOIN settings_users su ON su.id = cb.user_id
    WHERE cb.user_id IS NOT NULL
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 3
  ),
  top_outcomes AS (
    SELECT outcome, COUNT(*) AS cnt
    FROM call_base
    WHERE outcome IS NOT NULL AND outcome != ''
    GROUP BY outcome
    ORDER BY cnt DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total', cs.total,
    'inbound', cs.inbound,
    'outbound', cs.outbound,
    'answered', cs.answered,
    'answer_rate', CASE WHEN cs.total > 0 THEN ROUND((cs.answered::numeric / cs.total * 100), 1) ELSE 0 END,
    'avg_duration_sec', COALESCE(cs.avg_duration_sec, 0),
    'top_operators', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'name', op.operator_name, 'total', op.total, 'answered', op.answered
    )) FROM top_operators op), '[]'::jsonb),
    'top_outcomes', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'outcome', o.outcome, 'count', o.cnt
    )) FROM top_outcomes o), '[]'::jsonb)
  ) INTO v_calls
  FROM call_summary cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 6: MARKETING (sends, LPs, UTM, Meta forms)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH sends_summary AS (
    SELECT
      COUNT(*) AS total_sends,
      SUM(total_contacts) AS total_contacts,
      SUM(sent_count) AS total_sent,
      SUM(delivered_count) AS total_delivered,
      SUM(read_count) AS total_read
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  sends_by_channel AS (
    SELECT channel, COUNT(*) AS cnt, SUM(sent_count) AS sent, SUM(delivered_count) AS delivered, SUM(read_count) AS read_cnt
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY channel
  ),
  lp_stats AS (
    SELECT
      f.name AS page_name,
      COUNT(s.id) AS submissions
    FROM form_pro_forms f
    LEFT JOIN form_pro_submissions s ON s.form_id = f.id
      AND (p_date_from IS NULL OR s.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR s.submitted_at <= p_date_to)
    GROUP BY f.name
    ORDER BY submissions DESC
    LIMIT 5
  ),
  utm_stats AS (
    SELECT
      COALESCE(utm_source, 'direto') AS source,
      COALESCE(utm_medium, 'none') AS medium,
      COUNT(*) AS leads,
      COUNT(*) FILTER (WHERE status = 'won') AS won
    FROM leads
    WHERE utm_source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR leads_pipelines_id = p_pipeline_id)
    GROUP BY utm_source, utm_medium
    ORDER BY leads DESC
    LIMIT 5
  ),
  meta_forms_stats AS (
    SELECT
      mf.name AS form_name,
      COUNT(DISTINCT l.id) AS leads_count
    FROM meta_lead_forms mf
    LEFT JOIN form_pro_submissions fps ON fps.meta_form_id = mf.id
      AND (p_date_from IS NULL OR fps.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR fps.submitted_at <= p_date_to)
    LEFT JOIN leads l ON l.id = fps.lead_id
    WHERE mf.status = 'active'
    GROUP BY mf.name
    ORDER BY leads_count DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'sends', jsonb_build_object(
      'total_campaigns', ss.total_sends,
      'total_sent', COALESCE(ss.total_sent, 0),
      'total_delivered', COALESCE(ss.total_delivered, 0),
      'total_read', COALESCE(ss.total_read, 0),
      'delivery_rate', CASE WHEN COALESCE(ss.total_sent, 0) > 0
        THEN ROUND((COALESCE(ss.total_delivered, 0)::numeric / ss.total_sent * 100), 1) ELSE 0 END,
      'read_rate', CASE WHEN COALESCE(ss.total_delivered, 0) > 0
        THEN ROUND((COALESCE(ss.total_read, 0)::numeric / ss.total_delivered * 100), 1) ELSE 0 END,
      'by_channel', COALESCE((SELECT jsonb_agg(jsonb_build_object(
        'channel', sc.channel, 'campaigns', sc.cnt, 'sent', sc.sent, 'delivered', sc.delivered, 'read', sc.read_cnt
      )) FROM sends_by_channel sc), '[]'::jsonb)
    ),
    'landing_pages', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', lps.page_name, 'submissions', lps.submissions
    )) FROM lp_stats lps WHERE lps.submissions > 0), '[]'::jsonb),
    'utm_attribution', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'source', u.source, 'medium', u.medium, 'leads', u.leads, 'won', u.won
    )) FROM utm_stats u), '[]'::jsonb),
    'meta_forms', COALESCE((SELECT jsonb_agg(jsonb_build_object(
      'form', mfs.form_name, 'leads', mfs.leads_count
    )) FROM meta_forms_stats mfs), '[]'::jsonb)
  ) INTO v_marketing
  FROM sends_summary ss;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 7: PROSPECT PRO (campaigns, contacts breakdown, AI score)
  -- ═══════════════════════════════════════════════════════════════════════
  WITH prospect_campaigns_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'running') AS running,
      COUNT(*) FILTER (WHERE status = 'completed') AS completed
    FROM prospect_campaigns
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  prospect_contacts_agg AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE pc.status = 'raw') AS raw_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'filtered') AS filtered_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'enriched') AS enriched_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'approved') AS approved_cnt,
      COUNT(*) FILTER (WHERE pc.status = 'rejected') AS rejected_cnt,
      ROUND((AVG(ai_score) FILTER (WHERE ai_score IS NOT NULL))::numeric, 0) AS avg_ai_score
    FROM prospect_contacts pc
    JOIN prospect_campaigns camp ON camp.id = pc.campaign_id
    WHERE (p_date_from IS NULL OR pc.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR pc.created_at <= p_date_to)
  )
  SELECT jsonb_build_object(
    'campaigns_total', pca.total,
    'campaigns_running', pca.running,
    'campaigns_completed', pca.completed,
    'contacts_total', pcta.total,
    'contacts_by_status', jsonb_build_object(
      'raw', pcta.raw_cnt, 'filtered', pcta.filtered_cnt,
      'enriched', pcta.enriched_cnt, 'approved', pcta.approved_cnt, 'rejected', pcta.rejected_cnt
    ),
    'avg_ai_score', COALESCE(pcta.avg_ai_score, 0),
    'approval_rate', CASE WHEN pcta.total > 0
      THEN ROUND((pcta.approved_cnt::numeric / pcta.total * 100), 1) ELSE 0 END
  ) INTO v_prospect
  FROM prospect_campaigns_agg pca, prospect_contacts_agg pcta;

  -- ═══════════════════════════════════════════════════════════════════════
  -- ASSEMBLE FINAL RESULT
  -- ═══════════════════════════════════════════════════════════════════════
  result := jsonb_build_object(
    'pipelines', COALESCE(v_pipelines, '[]'::jsonb),
    'funnel', COALESCE(v_funnel, '{}'::jsonb),
    'people', COALESCE(v_people, '{}'::jsonb),
    'messages', COALESCE(v_messages, '{}'::jsonb),
    'meetings', COALESCE(v_meetings, '{}'::jsonb),
    'calls', COALESCE(v_calls, '{}'::jsonb),
    'marketing', COALESCE(v_marketing, '{}'::jsonb),
    'prospect', COALESCE(v_prospect, '{}'::jsonb)
  );

  RETURN result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO service_role;


