-- ---------------------------------------------------------------------------
-- Migration: 20260422000400_prospect_v1_cleanup_contacts.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Prospect PRO™ — v1 Cleanup (Part 1)
-- Drop prospect_contacts (dead table post-split) + view + pg_cron update
--
-- prospect_contacts was split into prospect_establishments + prospect_people
-- in migration 20260315195000. No edge function or frontend hook references it.
-- prospect_contacts_v (the compat view) is also dropped as it projecs from
-- prospect_establishments which remains active for the v1 pipeline.
--
-- prospect_establishments and prospect_people (v1) are NOT dropped here:
-- they are still used by prospect-filter, prospect-scorer and the v1 branch
-- of prospect-commit. Their cleanup is blocked on updating those edge functions.
-- ============================================================

BEGIN;

-- 1. Drop compatibility view
DROP VIEW IF EXISTS public.prospect_contacts_v;

-- 2. Drop prospect_contacts (cascades FK from audit_log.contact_id — which is
--    intentionally without FK constraint, so nothing to cascade there)
DROP TABLE IF EXISTS public.prospect_contacts CASCADE;

-- 3. Update pg_cron LGPD auto-delete: was targeting prospect_contacts, now
--    targets prospect_establishments (the active v1 staging table).
--    Uses cron.schedule which is idempotent — replaces the existing job by name.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    PERFORM cron.schedule(
      'prospect-lgpd-auto-delete',
      '0 3 * * *',
      $cron$
        -- Log before delete
        INSERT INTO prospect_audit_log (campaign_id, establishment_id, action, actor, details)
        SELECT campaign_id, id, 'deleted_lgpd', 'system',
               jsonb_build_object('reason', 'data_retention_expired', 'deleted_at', now())
        FROM prospect_establishments
        WHERE data_retention_deadline < now()
          AND company_id IS NULL
          AND status NOT IN ('approved', 'committed');

        DELETE FROM prospect_establishments
        WHERE data_retention_deadline < now()
          AND company_id IS NULL
          AND status NOT IN ('approved', 'committed');
      $cron$
    );
  END IF;
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422000450_tenant_functions_bootstrap.sql
-- ---------------------------------------------------------------------------

-- Bootstrap: ensure user_has_tenant_access and is_admin_or_gestor exist
-- These functions were originally created in pre-manifest migrations (-ok.sql)
-- and may be absent in tenants provisioned before the manifest system.
-- Using CREATE OR REPLACE — idempotent.
-- Note: user_has_tenant_access uses crm_tenants (exists in all tenants).
--       Falls back to false if tenant cannot be resolved (safe default).

CREATE OR REPLACE FUNCTION public.user_has_tenant_access(target_tenant_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.crm_tenants
    WHERE id = target_tenant_id
      AND (
        -- Check if current user is associated via settings_users
        EXISTS (
          SELECT 1 FROM public.settings_users
          WHERE auth_user_id = auth.uid()
            AND active = true
        )
        -- Super admin emails (fallback)
        OR auth.email() IN ('joao@growthsales.ai', 'rafaela@iatize.com', 'joao@iatize.com')
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.is_admin_or_manager()
  RETURNS boolean
  LANGUAGE sql
  STABLE SECURITY DEFINER
  SET search_path TO 'public'
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.settings_users
    WHERE auth_user_id = auth.uid()
      AND (super_admin = true OR user_type = 'gestor')
      AND active = true
  )
$$;

CREATE OR REPLACE FUNCTION public.is_admin_or_gestor()
  RETURNS boolean
  LANGUAGE sql
  STABLE SECURITY DEFINER
  SET search_path TO 'public'
AS $$
  SELECT public.is_admin_or_manager()
$$;

CREATE OR REPLACE FUNCTION public.get_current_user_tenant_id()
RETURNS uuid
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260422000500_prospect_rename_people_v2.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Prospect PRO™ — Rename prospect_people_v2 → prospect_people
--
-- Precondition: prospect_people (v1, linked to prospect_establishments) must
-- still exist at this point — it is renamed to prospect_people_legacy first,
-- freeing the name. Then prospect_people_v2 is renamed to prospect_people.
--
-- Edge functions that reference prospect_people (v1 path):
--   - prospect-scorer: reads prospect_people by establishment_id
--   - prospect-commit (v1 branch): reads/writes prospect_people
-- These functions must be updated AFTER this migration is applied.
-- Until updated, v1 campaigns (version=1) will fail to score and commit.
-- v2/v3 campaigns are unaffected.
--
-- Indexes are renamed to match the new table name for clarity.
-- The FK in prospect_enrichment_results is automatically updated by Postgres
-- when the referenced table is renamed (FK tracks by OID, not name).
-- ============================================================

BEGIN;

DO $$
BEGIN
  -- 1. Rename v1 prospect_people → prospect_people_legacy (only if v2 still exists and legacy doesn't)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='prospect_people_v2')
    AND NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='prospect_people_legacy')
  THEN
    ALTER TABLE public.prospect_people RENAME TO prospect_people_legacy;
  END IF;

  -- 2. Rename prospect_people_v2 → prospect_people (only if v2 still exists)
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='prospect_people_v2') THEN
    ALTER TABLE public.prospect_people_v2 RENAME TO prospect_people;

    -- 3. Rename RLS policies on the newly renamed table (ignore errors if already renamed)
    BEGIN
      ALTER POLICY "prospect_people_v2_select" ON public.prospect_people RENAME TO "prospect_people_select";
    EXCEPTION WHEN undefined_object THEN NULL;
    END;
    BEGIN
      ALTER POLICY "prospect_people_v2_insert" ON public.prospect_people RENAME TO "prospect_people_insert";
    EXCEPTION WHEN undefined_object THEN NULL;
    END;
    BEGIN
      ALTER POLICY "prospect_people_v2_update" ON public.prospect_people RENAME TO "prospect_people_update";
    EXCEPTION WHEN undefined_object THEN NULL;
    END;
    BEGIN
      ALTER POLICY "prospect_people_v2_delete" ON public.prospect_people RENAME TO "prospect_people_delete";
    EXCEPTION WHEN undefined_object THEN NULL;
    END;
  END IF;
END;
$$;

-- 4. Rename indexes to drop the _v2 suffix (IF EXISTS handles idempotency)
ALTER INDEX IF EXISTS idx_ppv2_company RENAME TO idx_pp_company;
ALTER INDEX IF EXISTS idx_ppv2_campaign_status RENAME TO idx_pp_campaign_status;
ALTER INDEX IF EXISTS idx_ppv2_role RENAME TO idx_pp_role;
ALTER INDEX IF EXISTS idx_ppv2_seniority RENAME TO idx_pp_seniority;
ALTER INDEX IF EXISTS idx_ppv2_selected RENAME TO idx_pp_selected;
ALTER INDEX IF EXISTS idx_ppv2_email RENAME TO idx_pp_email;
ALTER INDEX IF EXISTS idx_ppv2_person_id RENAME TO idx_pp_person_id;
ALTER INDEX IF EXISTS idx_ppv2_explorium_pid RENAME TO idx_pp_explorium_pid;

-- 5. The FK in prospect_enrichment_results references prospect_people_v2 by OID.
--    Postgres automatically tracks the renamed table — no ALTER needed.
--    The constraint name remains valid as-is.

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422000600_prospect_drop_v1_tables.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Prospect PRO™ — Drop v1 tables
--
-- Precondition: migration 20260422000500 already ran
--   (prospect_people renamed to prospect_people_legacy,
--    prospect_people_v2 renamed to prospect_people)
--
-- Tables dropped:
--   - prospect_people_legacy (ex-prospect_people v1, FK child of prospect_establishments)
--   - prospect_establishments (ex-v1 Google Maps staging)
--
-- FK dependency to handle before DROP:
--   prospect_audit_log.establishment_id → prospect_establishments(id) ON DELETE SET NULL
--   Added in migration 20260315195000. Must be dropped explicitly — DROP TABLE CASCADE
--   does not cascade ON DELETE SET NULL; Postgres will block if the FK constraint exists.
--   The column is retained (audit log is immutable), only the FK constraint is removed.
-- ============================================================

BEGIN;

-- 1. Unschedule pg_cron job that targets prospect_establishments (now being dropped).
--    Without this, the job becomes orphaned and will error on every run.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron')
    AND EXISTS (SELECT 1 FROM cron.job WHERE jobname = 'prospect-lgpd-auto-delete')
  THEN
    PERFORM cron.unschedule('prospect-lgpd-auto-delete');
  END IF;
END $$;

-- 2. Drop FK constraint on prospect_audit_log that references prospect_establishments
--    The column establishment_id is kept — only the referential constraint is removed.
ALTER TABLE public.prospect_audit_log
  DROP CONSTRAINT IF EXISTS prospect_audit_log_establishment_id_fkey;

-- 3. Drop legacy v1 people table (FK child of prospect_establishments via establishment_id)
DROP TABLE IF EXISTS public.prospect_people_legacy CASCADE;

-- 4. Drop legacy v1 establishments table
DROP TABLE IF EXISTS public.prospect_establishments CASCADE;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422000700_prospect_tenant_isolation.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Prospect PRO™ — Tenant Isolation
-- Adds tenant_id to all prospect tables + RLS policies scoped by tenant
--
-- Depends on:
--   - 20260422000500_prospect_rename_people_v2 (prospect_people exists)
--   - public.get_current_user_tenant_id() (defined in CRM migrations)
--   - public.user_has_tenant_access(uuid) (defined in CRM migrations)
-- ============================================================

BEGIN;

-- ============================================================
-- 1. Add tenant_id column to all prospect tables
-- ============================================================

ALTER TABLE public.prospect_campaigns
  ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.crm_tenants(id) ON DELETE CASCADE;

ALTER TABLE public.prospect_companies
  ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.crm_tenants(id) ON DELETE CASCADE;

ALTER TABLE public.prospect_people
  ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.crm_tenants(id) ON DELETE CASCADE;

ALTER TABLE public.prospect_enrichment_results
  ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.crm_tenants(id) ON DELETE CASCADE;

ALTER TABLE public.prospect_audit_log
  ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.crm_tenants(id) ON DELETE CASCADE;

ALTER TABLE public.prospect_opt_out_registry
  ADD COLUMN IF NOT EXISTS tenant_id uuid REFERENCES public.crm_tenants(id) ON DELETE CASCADE;

-- ============================================================
-- 2. Backfill tenant_id from existing data
-- ============================================================

-- prospect_campaigns: backfill tenant_id if crm_usuarios exists (older tenants)
-- New tenants will have empty prospect_campaigns so this is a no-op.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema='public' AND table_name='crm_usuarios') THEN
    UPDATE public.prospect_campaigns pc
    SET tenant_id = cu.tenant_id
    FROM public.crm_usuarios cu
    WHERE pc.created_by = cu.auth_user_id
      AND pc.tenant_id IS NULL;
  END IF;
END;
$$;

-- Report unresolved campaigns (no created_by match)
DO $$
DECLARE
  v_count int;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.prospect_campaigns
  WHERE tenant_id IS NULL;
  IF v_count > 0 THEN
    RAISE WARNING '[prospect_tenant_isolation] % campaign(s) could not be backfilled (no created_by match). Escalate to Chief: delete, move to default tenant, or keep NULL.', v_count;
  END IF;
END $$;

-- prospect_companies: derive from parent campaign
UPDATE public.prospect_companies pc
SET tenant_id = camp.tenant_id
FROM public.prospect_campaigns camp
WHERE pc.campaign_id = camp.id
  AND camp.tenant_id IS NOT NULL
  AND pc.tenant_id IS NULL;

-- prospect_people: derive from parent campaign
UPDATE public.prospect_people pp
SET tenant_id = camp.tenant_id
FROM public.prospect_campaigns camp
WHERE pp.campaign_id = camp.id
  AND camp.tenant_id IS NOT NULL
  AND pp.tenant_id IS NULL;

-- prospect_enrichment_results: derive via person → campaign
UPDATE public.prospect_enrichment_results per
SET tenant_id = camp.tenant_id
FROM public.prospect_people pp
JOIN public.prospect_campaigns camp ON pp.campaign_id = camp.id
WHERE per.person_id = pp.id
  AND camp.tenant_id IS NOT NULL
  AND per.tenant_id IS NULL;

-- prospect_audit_log: derive from campaign
UPDATE public.prospect_audit_log pal
SET tenant_id = camp.tenant_id
FROM public.prospect_campaigns camp
WHERE pal.campaign_id = camp.id
  AND camp.tenant_id IS NOT NULL
  AND pal.tenant_id IS NULL;

-- prospect_opt_out_registry: per-tenant (ADR-PP-02 decision: per-tenant, not global)
-- No automatic backfill possible — no campaign link. Leave NULL; NOT NULL enforced after human review.

-- ============================================================
-- 3. Set NOT NULL on tenant_id (fails deliberately if NULLs remain)
--    Exception: prospect_opt_out_registry stays nullable until human review
-- ============================================================

ALTER TABLE public.prospect_campaigns
  ALTER COLUMN tenant_id SET NOT NULL;

ALTER TABLE public.prospect_companies
  ALTER COLUMN tenant_id SET NOT NULL;

ALTER TABLE public.prospect_people
  ALTER COLUMN tenant_id SET NOT NULL;

ALTER TABLE public.prospect_enrichment_results
  ALTER COLUMN tenant_id SET NOT NULL;

ALTER TABLE public.prospect_audit_log
  ALTER COLUMN tenant_id SET NOT NULL;

-- prospect_opt_out_registry: nullable — human decision pending on orphaned records

-- ============================================================
-- 4. Indexes for tenant-scoped queries (avoid full-scan post-RLS)
-- ============================================================

CREATE INDEX IF NOT EXISTS idx_prospect_campaigns_tenant
  ON public.prospect_campaigns(tenant_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_prospect_campaigns_tenant_status
  ON public.prospect_campaigns(tenant_id, status);

CREATE INDEX IF NOT EXISTS idx_prospect_companies_tenant
  ON public.prospect_companies(tenant_id, campaign_id);

CREATE INDEX IF NOT EXISTS idx_prospect_companies_tenant_status
  ON public.prospect_companies(tenant_id, status);

CREATE INDEX IF NOT EXISTS idx_prospect_people_tenant
  ON public.prospect_people(tenant_id, campaign_id);

CREATE INDEX IF NOT EXISTS idx_prospect_people_tenant_status
  ON public.prospect_people(tenant_id, status);

CREATE INDEX IF NOT EXISTS idx_prospect_enrichment_results_tenant
  ON public.prospect_enrichment_results(tenant_id);

CREATE INDEX IF NOT EXISTS idx_prospect_audit_log_tenant
  ON public.prospect_audit_log(tenant_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_prospect_opt_out_tenant
  ON public.prospect_opt_out_registry(tenant_id) WHERE tenant_id IS NOT NULL;

-- ============================================================
-- 5. Drop old permissive RLS policies
-- ============================================================

-- prospect_campaigns
DROP POLICY IF EXISTS "prospect_campaigns_select" ON public.prospect_campaigns;
DROP POLICY IF EXISTS "prospect_campaigns_insert" ON public.prospect_campaigns;
DROP POLICY IF EXISTS "prospect_campaigns_update" ON public.prospect_campaigns;
DROP POLICY IF EXISTS "prospect_campaigns_delete" ON public.prospect_campaigns;

-- prospect_companies
DROP POLICY IF EXISTS "prospect_companies_select" ON public.prospect_companies;
DROP POLICY IF EXISTS "prospect_companies_insert" ON public.prospect_companies;
DROP POLICY IF EXISTS "prospect_companies_update" ON public.prospect_companies;
DROP POLICY IF EXISTS "prospect_companies_delete" ON public.prospect_companies;

-- prospect_people (renamed from prospect_people_v2 in migration 000500)
DROP POLICY IF EXISTS "prospect_people_select" ON public.prospect_people;
DROP POLICY IF EXISTS "prospect_people_insert" ON public.prospect_people;
DROP POLICY IF EXISTS "prospect_people_update" ON public.prospect_people;
DROP POLICY IF EXISTS "prospect_people_delete" ON public.prospect_people;

-- prospect_enrichment_results
DROP POLICY IF EXISTS "prospect_enrichment_results_select" ON public.prospect_enrichment_results;
DROP POLICY IF EXISTS "prospect_enrichment_results_insert" ON public.prospect_enrichment_results;
DROP POLICY IF EXISTS "prospect_enrichment_results_update" ON public.prospect_enrichment_results;

-- prospect_audit_log
DROP POLICY IF EXISTS "prospect_audit_select" ON public.prospect_audit_log;
DROP POLICY IF EXISTS "prospect_audit_insert" ON public.prospect_audit_log;

-- prospect_opt_out_registry
DROP POLICY IF EXISTS "prospect_opt_out_select" ON public.prospect_opt_out_registry;
DROP POLICY IF EXISTS "prospect_opt_out_insert" ON public.prospect_opt_out_registry;

-- ============================================================
-- 6. Create tenant-scoped RLS policies
-- ============================================================

-- prospect_campaigns
CREATE POLICY "prospect_campaigns_select"
  ON public.prospect_campaigns FOR SELECT TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

CREATE POLICY "prospect_campaigns_insert"
  ON public.prospect_campaigns FOR INSERT TO authenticated
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_campaigns_update"
  ON public.prospect_campaigns FOR UPDATE TO authenticated
  USING (public.user_has_tenant_access(tenant_id))
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_campaigns_delete"
  ON public.prospect_campaigns FOR DELETE TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

-- prospect_companies
CREATE POLICY "prospect_companies_select"
  ON public.prospect_companies FOR SELECT TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

CREATE POLICY "prospect_companies_insert"
  ON public.prospect_companies FOR INSERT TO authenticated
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_companies_update"
  ON public.prospect_companies FOR UPDATE TO authenticated
  USING (public.user_has_tenant_access(tenant_id))
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_companies_delete"
  ON public.prospect_companies FOR DELETE TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

-- prospect_people
CREATE POLICY "prospect_people_select"
  ON public.prospect_people FOR SELECT TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

CREATE POLICY "prospect_people_insert"
  ON public.prospect_people FOR INSERT TO authenticated
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_people_update"
  ON public.prospect_people FOR UPDATE TO authenticated
  USING (public.user_has_tenant_access(tenant_id))
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_people_delete"
  ON public.prospect_people FOR DELETE TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

-- prospect_enrichment_results: no tenant-scoped INSERT check needed (service_role writes)
-- SELECT filtered by tenant; UPDATE/INSERT via service_role bypass RLS
CREATE POLICY "prospect_enrichment_results_select"
  ON public.prospect_enrichment_results FOR SELECT TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

CREATE POLICY "prospect_enrichment_results_insert"
  ON public.prospect_enrichment_results FOR INSERT TO authenticated
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

CREATE POLICY "prospect_enrichment_results_update"
  ON public.prospect_enrichment_results FOR UPDATE TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

-- prospect_audit_log: LGPD immutable — INSERT-only for authenticated; SELECT scoped by tenant
CREATE POLICY "prospect_audit_select"
  ON public.prospect_audit_log FOR SELECT TO authenticated
  USING (public.user_has_tenant_access(tenant_id));

CREATE POLICY "prospect_audit_insert"
  ON public.prospect_audit_log FOR INSERT TO authenticated
  WITH CHECK (tenant_id = public.get_current_user_tenant_id());

-- prospect_opt_out_registry: per-tenant (ADR-PP-02)
-- tenant_id is nullable here — rows with tenant_id NULL are treated as global (visible to all)
CREATE POLICY "prospect_opt_out_select"
  ON public.prospect_opt_out_registry FOR SELECT TO authenticated
  USING (tenant_id IS NULL OR public.user_has_tenant_access(tenant_id));

CREATE POLICY "prospect_opt_out_insert"
  ON public.prospect_opt_out_registry FOR INSERT TO authenticated
  WITH CHECK (tenant_id = public.get_current_user_tenant_id() OR tenant_id IS NULL);

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422000800_prospect_people_scoring_columns.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Prospect PRO™ — AI Scoring columns em prospect_people
--
-- Depends on: 20260422000500 (prospect_people_v2 → prospect_people)
-- Adds: ai_score, ai_reasoning, ai_tags + composite index
-- ============================================================

BEGIN;

ALTER TABLE public.prospect_people
  ADD COLUMN IF NOT EXISTS ai_score     integer CHECK (ai_score IS NULL OR (ai_score >= 0 AND ai_score <= 100)),
  ADD COLUMN IF NOT EXISTS ai_reasoning text,
  ADD COLUMN IF NOT EXISTS ai_tags      text[];

CREATE INDEX IF NOT EXISTS idx_prospect_people_ai_score
  ON public.prospect_people(campaign_id, ai_score DESC) WHERE ai_score IS NOT NULL;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422000900_prospect_stuck_recovery_cron.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Prospect PRO™ — pg_cron: stuck campaign recovery
--
-- Marks campaigns stuck in 'running' for more than 3 minutes
-- as 'error'. Runs every 5 minutes.
-- ============================================================

SELECT cron.schedule(
  'prospect-stuck-recovery',
  '*/5 * * * *',
  $$
    UPDATE prospect_campaigns
    SET status = 'error', updated_at = now()
    WHERE status = 'running'
      AND updated_at < now() - interval '3 minutes';
  $$
);


-- ---------------------------------------------------------------------------
-- Migration: 20260422001000_zoom_integration.sql
-- ---------------------------------------------------------------------------

-- Zoom Integration — Schedule PRO™
-- Per-user Zoom OAuth tokens + meeting sync
-- App-level Zoom credentials in bi_settings
-- Follows same pattern as google_calendar (20260218143000) and ms_teams (20260219220000)

BEGIN;

-- ── 1. user_calendar_connections ─────────────────────────────────────────────

-- Make google_email nullable (was NOT NULL, but only applies to Google provider)
ALTER TABLE public.user_calendar_connections
  ALTER COLUMN google_email DROP NOT NULL;

-- Extend provider CHECK constraint to include 'zoom'
ALTER TABLE public.user_calendar_connections
  DROP CONSTRAINT IF EXISTS user_calendar_connections_provider_check;

ALTER TABLE public.user_calendar_connections
  ADD CONSTRAINT user_calendar_connections_provider_check
  CHECK (provider IN ('google', 'microsoft', 'zoom'));

-- Add Zoom OAuth token fields (per-user)
ALTER TABLE public.user_calendar_connections
  ADD COLUMN IF NOT EXISTS zoom_access_token     text,
  ADD COLUMN IF NOT EXISTS zoom_refresh_token    text,
  ADD COLUMN IF NOT EXISTS zoom_token_expires_at timestamptz,
  ADD COLUMN IF NOT EXISTS zoom_user_id          text,
  ADD COLUMN IF NOT EXISTS zoom_account_id       text,
  ADD COLUMN IF NOT EXISTS zoom_email            text;

-- ── 2. meetings ───────────────────────────────────────────────────────────────

ALTER TABLE public.meetings
  ADD COLUMN IF NOT EXISTS zoom_meeting_id  text,
  ADD COLUMN IF NOT EXISTS zoom_join_url    text,
  ADD COLUMN IF NOT EXISTS zoom_sync_error  text;

CREATE UNIQUE INDEX IF NOT EXISTS meetings_zoom_meeting_id_idx
  ON public.meetings (zoom_meeting_id)
  WHERE zoom_meeting_id IS NOT NULL;

-- ── 3. bi_settings — app-level Zoom OAuth credentials ────────────────────────

ALTER TABLE public.bi_settings
  ADD COLUMN IF NOT EXISTS zoom_client_id     text,
  ADD COLUMN IF NOT EXISTS zoom_client_secret text,  -- Server-only, never sent to client
  ADD COLUMN IF NOT EXISTS zoom_account_id    text;  -- Server-to-Server OAuth account ID

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422001100_capability_token_tables.sql
-- ---------------------------------------------------------------------------

-- Capability Token Tables — Schedule PRO™
-- ADR-SP-01: booking_token_jti_usage — denylist for revoked booking tokens
-- ADR-SP-02: action_token_consumed   — single-use enforcement for edge action tokens

BEGIN;

-- ── 1. booking_token_jti_usage (ADR-SP-01) ───────────────────────────────────

CREATE TABLE IF NOT EXISTS public.booking_token_jti_usage (
  jti        text        PRIMARY KEY,
  revoked_at timestamptz NOT NULL DEFAULT now(),
  reason     text
);

CREATE INDEX IF NOT EXISTS idx_booking_token_jti_revoked_at
  ON public.booking_token_jti_usage (revoked_at);

COMMENT ON TABLE public.booking_token_jti_usage IS
  'ADR-SP-01: Denylist of revoked booking JWT tokens (opt-in revocation). Checked on every public-booking request. GC cron purges entries older than token TTL.';

ALTER TABLE public.booking_token_jti_usage ENABLE ROW LEVEL SECURITY;

-- Only service_role can write; no authenticated read (checked in SECURITY DEFINER functions only)
DROP POLICY IF EXISTS "booking_jti_service_role_only" ON public.booking_token_jti_usage;
CREATE POLICY "booking_jti_service_role_only"
  ON public.booking_token_jti_usage
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

-- ── 2. action_token_consumed (ADR-SP-02) ─────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.action_token_consumed (
  jti         text        PRIMARY KEY,
  consumed_at timestamptz NOT NULL DEFAULT now(),
  action      text,
  meeting_id  text
);

CREATE INDEX IF NOT EXISTS idx_action_token_consumed_at
  ON public.action_token_consumed (consumed_at);

COMMENT ON TABLE public.action_token_consumed IS
  $$ADR-SP-02: Single-use enforcement for edge action tokens (confirm, cancel, reschedule). INSERT on first use, duplicate jti = token already consumed. GC cron purges expired entries.$$;

ALTER TABLE public.action_token_consumed ENABLE ROW LEVEL SECURITY;

-- Only service_role can write; no authenticated read (checked in SECURITY DEFINER functions only)
DROP POLICY IF EXISTS "action_token_service_role_only" ON public.action_token_consumed;
CREATE POLICY "action_token_service_role_only"
  ON public.action_token_consumed
  FOR ALL
  TO service_role
  USING (true)
  WITH CHECK (true);

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422001200_secret_access_log.sql
-- ---------------------------------------------------------------------------

-- Secret Access Log — ADR-SP-05
-- Append-only audit trail for Vault secret access.
-- Retention: 90 days — GC cron deletes WHERE accessed_at < now() - interval '90 days'.

BEGIN;

CREATE TABLE IF NOT EXISTS public.secret_access_log (
  id             uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  secret_name    text        NOT NULL,
  caller_context text,
  accessed_at    timestamptz NOT NULL DEFAULT now(),
  ip_address     inet
);

CREATE INDEX IF NOT EXISTS idx_secret_access_log_accessed_at
  ON public.secret_access_log (accessed_at);

COMMENT ON TABLE public.secret_access_log IS
  'ADR-SP-05: Append-only audit trail for Vault secret access. '
  'Each row records which secret was read and by which function/edge context. '
  'Retention 90 days — GC cron purges entries where accessed_at < now() - interval ''90 days''.';

ALTER TABLE public.secret_access_log ENABLE ROW LEVEL SECURITY;

-- INSERT only — service_role appends audit entries; no UPDATE or DELETE allowed via RLS
DROP POLICY IF EXISTS "secret_access_log_insert" ON public.secret_access_log;
CREATE POLICY "secret_access_log_insert"
  ON public.secret_access_log
  FOR INSERT
  TO service_role
  WITH CHECK (true);

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422001300_secure_http_post_wrapper.sql
-- ---------------------------------------------------------------------------

-- secure_http_post wrapper — ADR-SP-05
-- SECURITY DEFINER function that fetches secrets from Vault and logs access.
-- Replaces hardcoded JWTs in cron migrations with a single audited call site.
-- Depends on: public.secret_access_log (20260422001200), vault extension, pg_net extension.

BEGIN;

CREATE OR REPLACE FUNCTION public.secure_http_post(
  secret_name text,
  url text,
  body jsonb,
  caller_context text DEFAULT 'unknown'
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_secret   text;
  v_response jsonb;
BEGIN
  -- Fetch secret from Vault (Vault bootstrap is a manual step — see ADR-SP-05)
  SELECT decrypted_secret INTO v_secret
  FROM vault.decrypted_secrets
  WHERE name = secret_name;

  IF v_secret IS NULL THEN
    RAISE EXCEPTION 'Secret not found: %', secret_name;
  END IF;

  -- Audit log (append-only via secret_access_log)
  INSERT INTO public.secret_access_log (secret_name, caller_context)
  VALUES (secret_name, caller_context);

  -- HTTP POST via pg_net
  SELECT net.http_post(
    url     := url,
    body    := body::text,
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_secret
    )
  )::jsonb INTO v_response;

  RETURN v_response;
END;
$$;

-- Revoke public access; only service_role may call this function
REVOKE ALL ON FUNCTION public.secure_http_post(text, text, jsonb, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.secure_http_post(text, text, jsonb, text) TO service_role;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422001400_capability_token_gc_cron.sql
-- ---------------------------------------------------------------------------

-- Capability Token GC Cron — ADR-SP-01 / ADR-SP-02
-- Daily garbage collection for JTI denylist tables.
-- Runs at 03:00 UTC. pg_cron executes SQL directly as a privileged role —
-- no HTTP call or JWT required.
--
-- TTLs:
--   booking_token_jti_usage  — 30 days (aligns with ADR-SP-01 token TTL)
--   action_token_consumed    — 24 hours (action tokens are valid for 60s max)

-- Idempotent: cron.schedule replaces an existing job with the same name.
SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'capability-token-gc';

SELECT cron.schedule(
  'capability-token-gc',
  '0 3 * * *',
  $$
    -- GC booking_token_jti_usage (TTL: 30 days)
    DELETE FROM public.booking_token_jti_usage
    WHERE revoked_at < now() - interval '30 days';

    -- GC action_token_consumed (TTL: 24 hours)
    DELETE FROM public.action_token_consumed
    WHERE consumed_at < now() - interval '24 hours';
  $$
);


-- ---------------------------------------------------------------------------
-- Migration: 20260422001500_move_cron_jwt_to_vault.sql
-- ---------------------------------------------------------------------------

-- SCH-H-3: Move service-role JWT from cron migrations to Vault — ADR-SP-05
--
-- PREREQUISITE (manual — must be done BEFORE applying this migration):
--   1. In Supabase Dashboard → Settings → API → Reset service_role key
--   2. In Supabase Dashboard → Vault → Add secret:
--        name: service_role_cron
--        value: <new service_role JWT>
--
-- WHAT THIS MIGRATION DOES:
--   Re-registers both pg_cron jobs that contained hardcoded JWTs
--   (20260226301000:207 and 20260219140000:21) to use secure_http_post()
--   which reads the secret from Vault at runtime — never hardcoded.
--
-- If Vault secret 'service_role_cron' is absent, cron jobs fail-closed
-- (RAISE EXCEPTION from secure_http_post). This is the intended behaviour.
--
-- NOTE: Old migration files are NOT modified — they are git history.
-- The leaked JWT is invalidated by rotation (step 1 above), not by code.

BEGIN;

-- ── 1. Re-register process-meeting-followups (every 5 min) ──────────────────

SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'process-meeting-followups';

SELECT cron.schedule(
  'process-meeting-followups',
  '*/5 * * * *',
  $$
  SELECT public.secure_http_post(
    'service_role_cron',
    'https://ohzwetkaazgxafubzvop.supabase.co/functions/v1/process-meeting-followups',
    '{}'::jsonb,
    'process-meeting-followups-cron'
  );
  $$
);

-- ── 2. Re-register google-calendar-sync (every 15 min) ──────────────────────

SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'google-calendar-sync';

SELECT cron.schedule(
  'google-calendar-sync',
  '*/15 * * * *',
  $$
  SELECT public.secure_http_post(
    'service_role_cron',
    'https://ohzwetkaazgxafubzvop.supabase.co/functions/v1/google-cal-sync-to-db',
    '{}'::jsonb,
    'google-calendar-sync-cron'
  );
  $$
);

COMMIT;


