-- ---------------------------------------------------------------------------
-- Migration: 20260422001700_vault_bootstrap_service_role_cron.sql
-- ---------------------------------------------------------------------------

-- SCH-H-3 bootstrap — seed Vault secret 'service_role_cron' programmatically.
-- This migration inserts the service_role JWT into Vault so that
-- migration 20260422001500 cron jobs can call secure_http_post() at runtime.
--
-- SECURITY NOTE: The JWT value here is the same one that was already in git
-- history (migrations 20260226301000 and 20260219140000). Rotation is the fix;
-- this migration only moves it from cron-job plaintext into Vault.
-- Rotate the JWT in Supabase Dashboard → Settings → API after applying.
--
-- Idempotent: skips insert if 'service_role_cron' already exists in vault.secrets.

DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM vault.secrets WHERE name = 'service_role_cron'
  ) THEN
    PERFORM vault.create_secret(
      'REPLACE_WITH_SERVICE_ROLE_JWT_FROM_VAULT',
      'service_role_cron',
      'Service role JWT for pg_cron secure_http_post calls — rotate after bootstrap'
    );
  END IF;
END $$;


-- ---------------------------------------------------------------------------
-- Migration: 20260422001800_get_booking_session_remove_pii.sql
-- ---------------------------------------------------------------------------

-- SCH-H-1 AC8 / SCH-H-2: Remove PII from get_booking_session public RPC.
-- Before: { person: { id, name, email }, slots }
-- After:  { person: { name: "<first_name_only>" }, slots }
--
-- email and id MUST NOT leave this RPC — granted to 'anon' (unauthenticated).
-- Slot generation logic is identical to the original (20260226220000).

CREATE OR REPLACE FUNCTION public.get_booking_session(
  p_lead_id     uuid,
  p_rule_set_id uuid    DEFAULT NULL,
  p_duration    integer DEFAULT 30,
  p_days_ahead  integer DEFAULT 14
)
RETURNS json
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_first_name   text;
  v_user_ids     uuid[];
  v_slots        json;
BEGIN
  -- 1. Lead / person lookup — only first name leaves this function (AC8)
  SELECT split_part(COALESCE(cp.name, 'Cliente'), ' ', 1)
  INTO v_first_name
  FROM public.leads l
  LEFT JOIN public.clients_people cp ON cp.id = l.people_id
  WHERE l.id = p_lead_id;

  IF NOT FOUND THEN
    RETURN json_build_object('error', 'Lead not found');
  END IF;

  -- 2. Eligible consultants
  v_user_ids := public.get_booking_eligible_user_ids(p_rule_set_id);

  IF v_user_ids IS NULL OR array_length(v_user_ids, 1) IS NULL THEN
    RETURN json_build_object('error', 'Nenhum consultor disponível no momento');
  END IF;

  -- 3. Available slots (identical to original — 30-min intervals within schedule)
  SELECT json_agg(
    json_build_object(
      'date',       slot_date,
      'start_time', start_time,
      'end_time',   end_time
    )
    ORDER BY slot_date, start_time
  )
  INTO v_slots
  FROM (
    SELECT DISTINCT
      TO_CHAR(dr.d, 'YYYY-MM-DD') AS slot_date,
      TO_CHAR(ss.start_time::time + (n.n * INTERVAL '30 minutes'), 'HH24:MI') AS start_time,
      TO_CHAR(ss.start_time::time + (n.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute'), 'HH24:MI') AS end_time,
      su.id AS user_id,
      dr.d + (ss.start_time::time + (n.n * INTERVAL '30 minutes')) AS ts_start,
      dr.d + (ss.start_time::time + (n.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute')) AS ts_end
    FROM
      (SELECT (CURRENT_DATE + s.n)::date AS d
       FROM generate_series(0, p_days_ahead - 1) AS s(n)) AS dr
      CROSS JOIN (SELECT unnest(v_user_ids) AS id) AS cand
      INNER JOIN public.settings_users su ON su.id = cand.id AND su.active = true
      INNER JOIN public.settings_schedules ss
        ON ss.user_id = su.id
        AND ss.day_of_week = EXTRACT(DOW FROM dr.d)::int
        AND ss.is_available = true
      CROSS JOIN LATERAL (
        SELECT s2.n
        FROM generate_series(0,
          GREATEST(0, FLOOR(
            EXTRACT(EPOCH FROM (ss.end_time::time - ss.start_time::time)) / 1800
          )::int - 1)
        ) AS s2(n)
        WHERE ss.start_time::time + (s2.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute')
              <= ss.end_time::time
      ) AS n
  ) AS all_slots
  WHERE NOT EXISTS (
    SELECT 1 FROM public.meetings m
    WHERE m.users_id  = all_slots.user_id
      AND m.start_time < all_slots.ts_end::timestamptz
      AND m.end_time   > all_slots.ts_start::timestamptz
      AND m.status NOT IN ('cancelado', 'cancelada')
  );

  RETURN json_build_object(
    'person', json_build_object('name', v_first_name),
    'slots',  COALESCE(v_slots, '[]'::json)
  );
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260422002000_settings_bi_settings_decouple.sql
-- ---------------------------------------------------------------------------

-- FIX-SETTINGS-02: Formalize settings / bi_settings separation
--
-- Decision: keep tables separate. Their responsibilities are distinct:
--   settings     → tenant identity, branding, enrichment API keys (multi-row, ordered)
--   bi_settings  → BI/ads OAuth credentials, singleton row (WHERE singleton = true)
--
-- The only true overlap is google_client_id + google_client_secret.
-- Migration CFG-05 (20260310200000) already seeded settings.google_client_id/secret
-- from bi_settings. All server-side edge functions already read settings first
-- and fall back to bi_settings. This migration removes the duplicate columns
-- from bi_settings so there is a single source of truth.
--
-- Edge functions affected (already have the settings-first pattern):
--   google-cal-connect, google-cal-sync-events, google-cal-upsert-event,
--   google-cal-pull-event, google-cal-availability, google-cal-sync-to-db,
--   public-booking
-- The bi-google-oauth edge function reads google_client_id/secret exclusively
-- from bi_settings — it will be updated separately (FIX-SETTINGS-02 AC4).

BEGIN;

-- Safety: ensure settings.google_client_id is populated before dropping
-- the bi_settings columns. If for any tenant settings is empty, copy now.
UPDATE public.settings s
SET
  google_client_id     = COALESCE(s.google_client_id,     b.google_client_id),
  google_client_secret = COALESCE(s.google_client_secret, b.google_client_secret)
FROM public.bi_settings b
WHERE b.singleton = true
  AND (s.google_client_id IS NULL OR s.google_client_secret IS NULL)
  AND (b.google_client_id IS NOT NULL OR b.google_client_secret IS NOT NULL);

-- Drop redundant columns from bi_settings
ALTER TABLE public.bi_settings
  DROP COLUMN IF EXISTS google_client_id,
  DROP COLUMN IF EXISTS google_client_secret;

-- google_developer_token is BI-only (Google Ads API, not Calendar OAuth).
-- It stays in bi_settings — no change needed.

COMMENT ON TABLE public.bi_settings IS
  'BI PRO™: Singleton row — OAuth credentials for Meta Ads, Google Ads, Microsoft, and Zoom integrations. '
  'Google Calendar OAuth (google_client_id/secret) lives in the settings table.';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260422002500_tenant_functions_bootstrap.sql
-- ---------------------------------------------------------------------------

-- Bootstrap: ensure user_has_tenant_access and is_admin_or_gestor exist
-- These functions were originally created in pre-manifest migrations (-ok.sql)
-- and may be absent in tenants provisioned before the manifest system.
-- Using CREATE OR REPLACE — idempotent.
-- Note: user_has_tenant_access uses crm_tenants (exists in all tenants).
--       Falls back to false if tenant cannot be resolved (safe default).

CREATE OR REPLACE FUNCTION public.user_has_tenant_access(target_tenant_id uuid)
RETURNS boolean
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1 FROM public.crm_tenants
    WHERE id = target_tenant_id
      AND (
        -- Check if current user is associated via settings_users
        EXISTS (
          SELECT 1 FROM public.settings_users
          WHERE auth_user_id = auth.uid()
            AND active = true
        )
        -- Super admin emails (fallback)
        OR auth.email() IN ('joao@growthsales.ai', 'rafaela@iatize.com', 'joao@iatize.com')
      )
  );
$$;

CREATE OR REPLACE FUNCTION public.is_admin_or_manager()
  RETURNS boolean
  LANGUAGE sql
  STABLE SECURITY DEFINER
  SET search_path TO 'public'
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.settings_users
    WHERE auth_user_id = auth.uid()
      AND (super_admin = true OR user_type = 'gestor')
      AND active = true
  )
$$;

CREATE OR REPLACE FUNCTION public.is_admin_or_gestor()
  RETURNS boolean
  LANGUAGE sql
  STABLE SECURITY DEFINER
  SET search_path TO 'public'
AS $$
  SELECT public.is_admin_or_manager()
$$;

CREATE OR REPLACE FUNCTION public.get_current_user_tenant_id()
RETURNS uuid
LANGUAGE sql
STABLE SECURITY DEFINER
SET search_path = public
AS $$
  SELECT (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid
$$;


