ALTER TABLE public.settings_users
  ADD COLUMN IF NOT EXISTS role_id uuid REFERENCES public.tenant_roles(id) ON DELETE SET NULL;

CREATE INDEX IF NOT EXISTS settings_users_role_id_idx ON public.settings_users (role_id);

-- ── 5. Seed system roles + default permissions ───────────────────────────────
-- Seeds gestor (all features enabled, system) and atendente (restricted) for
-- the tenant identified by auth.jwt() — only seeds if not already present.
-- Tenants without any rows fall back to hardcoded behavior (backward compat).
CREATE OR REPLACE FUNCTION public.seed_default_tenant_roles(p_tenant_id uuid)
RETURNS void LANGUAGE plpgsql AS $$
DECLARE
  v_gestor_id    uuid;
  v_atendente_id uuid;
  fk             public.feature_key;
BEGIN
  -- Gestor role (system — all features enabled)
  INSERT INTO public.tenant_roles (tenant_id, name, description, is_system)
  VALUES (p_tenant_id, 'gestor', 'Acesso total', true)
  ON CONFLICT (tenant_id, name) DO NOTHING
  RETURNING id INTO v_gestor_id;

  IF v_gestor_id IS NOT NULL THEN
    FOR fk IN SELECT unnest(enum_range(NULL::public.feature_key)) LOOP
      INSERT INTO public.tenant_role_permissions (role_id, feature_key, enabled)
      VALUES (v_gestor_id, fk, true)
      ON CONFLICT (role_id, feature_key) DO NOTHING;
    END LOOP;
  END IF;

  -- Atendente role (system — restricted features)
  INSERT INTO public.tenant_roles (tenant_id, name, description, is_system)
  VALUES (p_tenant_id, 'atendente', 'Acesso padrão', true)
  ON CONFLICT (tenant_id, name) DO NOTHING
  RETURNING id INTO v_atendente_id;

  IF v_atendente_id IS NOT NULL THEN
    -- Atendente: can view score and BI, cannot export/delete/edit coach/create sends/view settings
    INSERT INTO public.tenant_role_permissions (role_id, feature_key, enabled) VALUES
      (v_atendente_id, 'crm_export',   false),
      (v_atendente_id, 'crm_delete',   false),
      (v_atendente_id, 'score_view',   true),
      (v_atendente_id, 'coach_view',   true),
      (v_atendente_id, 'coach_edit',   false),
      (v_atendente_id, 'sends_create', false),
      (v_atendente_id, 'bi_view',      true),
      (v_atendente_id, 'settings_view',false)
    ON CONFLICT (role_id, feature_key) DO NOTHING;
  END IF;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260423010000_sends_server_dispatch.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- FIX-SENDS-01: Server-side dispatch loop for SENDS PRO
-- Adds last_batch_at to sends + pg_cron job calling sends-dispatch-batch
-- =============================================================================

-- ── 1. Add last_batch_at column to sends ─────────────────────────────────────
-- Tracks when the last batch was dispatched; used by sends-dispatch-batch
-- to enforce send_interval_seconds cadence without browser involvement.
ALTER TABLE public.sends
  ADD COLUMN IF NOT EXISTS last_batch_at timestamptz;

COMMENT ON COLUMN public.sends.last_batch_at IS
  'Timestamp of last batch dispatch. Used by sends-dispatch-batch (pg_cron) '
  'to enforce send_interval_seconds cadence server-side.';

-- ── 2. Create dispatch scheduler function ────────────────────────────────────
-- Called by pg_cron every minute; invokes sends-dispatch-batch edge fn.
-- Edge fn handles per-send cadence logic (last_batch_at + interval check).
CREATE OR REPLACE FUNCTION public.trigger_sends_dispatch_batch()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  supabase_url  text;
  svc_key       text;
BEGIN
  SELECT value INTO supabase_url FROM _app_config WHERE key = 'supabase_url';
  SELECT value INTO svc_key      FROM _app_config WHERE key = 'service_role_key';

  IF supabase_url IS NULL OR supabase_url = '' OR svc_key IS NULL OR svc_key = '' THEN
    RAISE NOTICE 'trigger_sends_dispatch_batch: _app_config missing supabase_url or service_role_key. '
                 'Run: INSERT INTO _app_config VALUES (''supabase_url'', ''https://xxx.supabase.co''), '
                 '(''service_role_key'', ''...'') ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;';
    RETURN;
  END IF;

  -- Only fire if there are running sends to process (skip wasted HTTP call)
  IF NOT EXISTS (SELECT 1 FROM public.sends WHERE status = 'running' LIMIT 1) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := supabase_url || '/functions/v1/sends-dispatch-batch',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || svc_key
    ),
    body    := jsonb_build_object('source', 'pg_cron')
  );
END;
$$;

COMMENT ON FUNCTION public.trigger_sends_dispatch_batch() IS
  'Called by pg_cron every minute. Fires sends-dispatch-batch edge fn only when '
  'there are running sends. Requires _app_config to have supabase_url and service_role_key.';

-- ── 3. Register pg_cron job ───────────────────────────────────────────────────
-- cron.schedule() is idempotent — safe to re-run on migration retry.
SELECT cron.schedule(
  'sends-dispatch-batch',
  '* * * * *',
  'SELECT public.trigger_sends_dispatch_batch()'
);


-- ---------------------------------------------------------------------------
-- Migration: 20260423011000_meeting_evaluations_rls_tenant_scoped.sql
-- ---------------------------------------------------------------------------

-- FIX-SCH-02: RLS tenant-scoped em meeting_evaluations
-- Substitui política permissiva (USING true) por isolamento via user_calendar_connections.
-- meeting_evaluations → meetings → settings_users → auth_user_id = auth.uid()
-- Service role bypassa RLS (coach-pro AI usa service role).
-- Edge functions de avaliação (coach-pro-evaluate) usam service role key — sem impacto.

BEGIN;

DROP POLICY IF EXISTS "meeting_evaluations_all" ON public.meeting_evaluations;
DROP POLICY IF EXISTS "meeting_evaluations_authenticated_read" ON public.meeting_evaluations;
DROP POLICY IF EXISTS "meeting_evaluations_manager_write" ON public.meeting_evaluations;

-- Leitura: usuário autenticado vê avaliações de reuniões do seu próprio sistema.
-- JOIN seguro: meeting_evaluations.meeting_id → meetings.user_id → settings_users.auth_user_id
-- Para single-tenant: qualquer usuário autenticado da instância pode ler todas as avaliações.
-- Para multi-tenant futuro: policy pode ser narrowed com tenant_id em settings_users.
CREATE POLICY "meeting_evaluations_authenticated_read"
  ON public.meeting_evaluations
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1
      FROM public.meetings m
      JOIN public.settings_users su ON su.id = m.user_id
      WHERE m.id = meeting_evaluations.meeting_id
        AND su.auth_user_id IS NOT NULL
        AND EXISTS (
          SELECT 1 FROM public.settings_users su2
          WHERE su2.auth_user_id = auth.uid()
        )
    )
  );

-- Escrita: apenas admins/gestores podem criar/atualizar avaliações via client.
-- Avaliações criadas por AI usam service role (bypassa RLS).
CREATE POLICY "meeting_evaluations_manager_write"
  ON public.meeting_evaluations
  FOR ALL
  TO authenticated
  USING (is_admin_or_gestor())
  WITH CHECK (is_admin_or_gestor());

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260423012000_zoom_token_refresh_cron.sql
-- ---------------------------------------------------------------------------

-- FIX-SCH-02: Zoom token auto-refresh via pg_cron
-- Zoom access tokens expire in 1 hour. Proactive refresh every 30 minutes
-- prevents zoom-upsert-event failures for active users.
-- Pattern: same as instagram-token-refresh (SECURITY DEFINER + _app_config)

-- ── 1. PL/pgSQL trigger function ─────────────────────────────────────────────

CREATE OR REPLACE FUNCTION trigger_zoom_token_refresh()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  supabase_url text;
  svc_key      text;
BEGIN
  SELECT value INTO supabase_url FROM _app_config WHERE key = 'supabase_url';
  SELECT value INTO svc_key      FROM _app_config WHERE key = 'service_role_key';

  IF supabase_url IS NULL OR svc_key IS NULL THEN
    RAISE WARNING 'trigger_zoom_token_refresh: _app_config missing supabase_url or service_role_key';
    RETURN;
  END IF;

  -- Only trigger if there are active Zoom connections
  IF NOT EXISTS (
    SELECT 1 FROM user_calendar_connections
    WHERE provider = 'zoom' AND is_active = true
    LIMIT 1
  ) THEN
    RETURN;
  END IF;

  PERFORM net.http_post(
    url     := supabase_url || '/functions/v1/zoom-token-refresh',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || svc_key
    ),
    body    := '{"trigger":"cron"}'::jsonb
  );
END;
$$;

COMMENT ON FUNCTION trigger_zoom_token_refresh() IS
  'Disparada pelo pg_cron a cada 30 minutos. '
  'Renova tokens Zoom que expiram em menos de 45 minutos. '
  'Só chama a edge function se houver conexão Zoom ativa.';

-- ── 2. Remover job anterior se existir ───────────────────────────────────────

SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'zoom-token-refresh';

-- ── 3. Agendar a cada 30 minutos ─────────────────────────────────────────────

SELECT cron.schedule(
  'zoom-token-refresh',
  '*/30 * * * *',
  $$ SELECT trigger_zoom_token_refresh(); $$
);


