-- ---------------------------------------------------------------------------
-- Migration: 20260424003000_mfa_recovery_codes.sql
-- ---------------------------------------------------------------------------

-- AUTH-V2-03a AC1: mfa_recovery_codes table
-- Stores bcrypt-hashed recovery codes per user. Plaintext returned once
-- at generation time (mfa_recovery_generate) and never stored.

BEGIN;

CREATE TABLE IF NOT EXISTS public.mfa_recovery_codes (
  id               uuid        PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id          uuid        NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  code_hash        text        NOT NULL,
  recovery_set_id  uuid        NOT NULL,
  used_at          timestamptz,
  created_at       timestamptz NOT NULL DEFAULT now()
);

-- Fast lookup: unused codes for a given user
CREATE INDEX IF NOT EXISTS idx_mfa_recovery_codes_user_unused
  ON public.mfa_recovery_codes (user_id)
  WHERE used_at IS NULL;

COMMENT ON TABLE public.mfa_recovery_codes IS
  'AUTH-V2-03a: bcrypt-hashed MFA recovery codes. Plaintext returned once at generation, never stored. RPCs: mfa_recovery_generate() / mfa_recovery_consume().';

COMMENT ON COLUMN public.mfa_recovery_codes.code_hash IS
  'bcrypt hash via crypt(plaintext, gen_salt(''bf'', 10)). Constant-time verify: crypt(input, code_hash) = code_hash.';

COMMENT ON COLUMN public.mfa_recovery_codes.recovery_set_id IS
  'Groups codes from the same generation call. All codes in a set are invalidated together on regeneration.';

-- RLS: user sees/deletes only own rows; INSERT/UPDATE via SECURITY DEFINER RPCs
ALTER TABLE public.mfa_recovery_codes ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "mfa_recovery_codes_select_own" ON public.mfa_recovery_codes;
CREATE POLICY "mfa_recovery_codes_select_own"
  ON public.mfa_recovery_codes FOR SELECT
  USING (auth.uid() = user_id);

DROP POLICY IF EXISTS "mfa_recovery_codes_delete_own" ON public.mfa_recovery_codes;
CREATE POLICY "mfa_recovery_codes_delete_own"
  ON public.mfa_recovery_codes FOR DELETE
  USING (auth.uid() = user_id);

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260424003500_mfa_recovery_rpcs.sql
-- ---------------------------------------------------------------------------

-- AUTH-V2-03a AC2+AC3: RPCs mfa_recovery_generate + mfa_recovery_consume
-- pgcrypto confirmed available via 20260325210000_adm_secrets_encryption.sql.
--
-- QA manual:
--   SELECT mfa_recovery_generate();
--   SELECT mfa_recovery_consume('XXXX-XXXX-XXXX-XXXX');

BEGIN;

-- ── AC2: mfa_recovery_generate ────────────────────────────────────────────────
-- Returns 10 plaintext codes (XXXX-XXXX-XXXX-XXXX) for the calling user.
-- Requires authenticated caller with enrolled TOTP factor.
-- Deletes all unused codes from prior sets before inserting new ones.

CREATE OR REPLACE FUNCTION public.mfa_recovery_generate()
RETURNS text[]
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id   uuid := auth.uid();
  v_set_id    uuid := gen_random_uuid();
  v_codes     text[] := '{}';
  v_plaintext text;
  v_has_totp  boolean;
  i           int;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- Verify caller has an enrolled TOTP factor
  SELECT EXISTS (
    SELECT 1 FROM auth.mfa_factors
    WHERE user_id = v_user_id
      AND factor_type = 'totp'
      AND status = 'verified'
  ) INTO v_has_totp;

  IF NOT v_has_totp THEN
    RAISE EXCEPTION 'MFA TOTP not enrolled for this user';
  END IF;

  -- Invalidate previous unused codes
  DELETE FROM public.mfa_recovery_codes
   WHERE user_id = v_user_id
     AND used_at IS NULL;

  -- Generate 10 codes: XXXX-XXXX-XXXX-XXXX (4 groups of 4 hex chars, uppercase)
  FOR i IN 1..10 LOOP
    v_plaintext :=
      upper(substring(encode(gen_random_bytes(2), 'hex'), 1, 4)) || '-' ||
      upper(substring(encode(gen_random_bytes(2), 'hex'), 1, 4)) || '-' ||
      upper(substring(encode(gen_random_bytes(2), 'hex'), 1, 4)) || '-' ||
      upper(substring(encode(gen_random_bytes(2), 'hex'), 1, 4));

    INSERT INTO public.mfa_recovery_codes (user_id, code_hash, recovery_set_id)
    VALUES (
      v_user_id,
      extensions.crypt(v_plaintext, extensions.gen_salt('bf', 10)),
      v_set_id
    );

    v_codes := array_append(v_codes, v_plaintext);
  END LOOP;

  RETURN v_codes;
END;
$$;

REVOKE ALL ON FUNCTION public.mfa_recovery_generate() FROM PUBLIC;
REVOKE ALL ON FUNCTION public.mfa_recovery_generate() FROM anon;
GRANT EXECUTE ON FUNCTION public.mfa_recovery_generate() TO authenticated;
GRANT EXECUTE ON FUNCTION public.mfa_recovery_generate() TO service_role;

COMMENT ON FUNCTION public.mfa_recovery_generate() IS
  'AUTH-V2-03a AC2: Generates 10 bcrypt-hashed recovery codes for the calling user. Requires enrolled TOTP. Invalidates prior unused codes. Plaintext returned ONCE.';

-- ── AC3: mfa_recovery_consume ─────────────────────────────────────────────────
-- Validates a recovery code via constant-time bcrypt comparison.
-- Returns true on match (marks used_at + audit log), false otherwise.
-- Does NOT issue a session — caller manages auth flow (AUTH-V2-03c).

CREATE OR REPLACE FUNCTION public.mfa_recovery_consume(p_code text)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions
AS $$
DECLARE
  v_user_id uuid := auth.uid();
  v_row     public.mfa_recovery_codes%ROWTYPE;
  v_matched boolean := false;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  FOR v_row IN
    SELECT * FROM public.mfa_recovery_codes
     WHERE user_id = v_user_id
       AND used_at IS NULL
     ORDER BY created_at
  LOOP
    IF extensions.crypt(p_code, v_row.code_hash) = v_row.code_hash THEN
      UPDATE public.mfa_recovery_codes
         SET used_at = now()
       WHERE id = v_row.id;

      INSERT INTO public.adm_audit_log (actor_id, action, details)
      VALUES (
        v_user_id,
        'mfa.recovery_consumed',
        jsonb_build_object(
          'code_id',          v_row.id,
          'recovery_set_id',  v_row.recovery_set_id
        )
      );

      v_matched := true;
      EXIT;
    END IF;
  END LOOP;

  RETURN v_matched;
END;
$$;

REVOKE ALL ON FUNCTION public.mfa_recovery_consume(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.mfa_recovery_consume(text) FROM anon;
GRANT EXECUTE ON FUNCTION public.mfa_recovery_consume(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mfa_recovery_consume(text) TO service_role;

COMMENT ON FUNCTION public.mfa_recovery_consume(text) IS
  'AUTH-V2-03a AC3: Validates a recovery code (constant-time bcrypt). Marks used_at on match. Returns false for invalid/used codes. Does NOT issue a session.';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260424004000_settings_mfa_policy.sql
-- ---------------------------------------------------------------------------

-- AUTH-V2-03a AC5: settings.mfa_policy enum column + data migration
-- Migrates require_mfa_for_gestores (boolean) → mfa_policy (3-level text enum).
-- Old column kept (deprecated) until UI stops reading it.

BEGIN;

ALTER TABLE public.settings
  ADD COLUMN IF NOT EXISTS mfa_policy text
    CHECK (mfa_policy IN ('opt_in', 'required_gestores', 'required_all'))
    DEFAULT 'opt_in';

-- Idempotent data migration from old boolean flag
UPDATE public.settings
   SET mfa_policy = CASE
     WHEN require_mfa_for_gestores = true THEN 'required_gestores'
     ELSE 'opt_in'
   END
 WHERE mfa_policy IS NULL
    OR mfa_policy = 'opt_in';

COMMENT ON COLUMN public.settings.mfa_policy IS
  'MFA enforcement level: opt_in | required_gestores | required_all. Supersedes require_mfa_for_gestores.';

COMMENT ON COLUMN public.settings.require_mfa_for_gestores IS
  'Deprecated 2026-04-24 — use mfa_policy instead. Kept for backwards compatibility until UI is updated.';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260424004500_settings_users_mfa_grace.sql
-- ---------------------------------------------------------------------------

-- AUTH-V2-03a AC6: settings_users.mfa_grace_until + trigger
-- New users get 7-day grace period when tenant mfa_policy requires their role.
-- Read by AUTH-V2-03b banner — does not block routes.

BEGIN;

ALTER TABLE public.settings_users
  ADD COLUMN IF NOT EXISTS mfa_grace_until timestamptz;

COMMENT ON COLUMN public.settings_users.mfa_grace_until IS
  'AUTH-V2-03a AC6: MFA enrollment deadline. Set to now()+7d on INSERT when tenant mfa_policy requires this role. NULL = no active grace period.';

-- Trigger function: sets grace period based on tenant mfa_policy
CREATE OR REPLACE FUNCTION public.settings_users_set_mfa_grace()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_policy  text;
  v_applies boolean := false;
BEGIN
  SELECT mfa_policy INTO v_policy
    FROM public.settings
   LIMIT 1;

  IF v_policy = 'required_all' THEN
    v_applies := true;
  ELSIF v_policy = 'required_gestores' AND NEW.user_type = 'gestor' THEN
    v_applies := true;
  END IF;

  IF v_applies THEN
    NEW.mfa_grace_until := now() + interval '7 days';
  END IF;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS trg_settings_users_mfa_grace ON public.settings_users;

CREATE TRIGGER trg_settings_users_mfa_grace
  BEFORE INSERT ON public.settings_users
  FOR EACH ROW
  EXECUTE FUNCTION public.settings_users_set_mfa_grace();

COMMIT;


