);

-- Índice principal: telemetria por tenant cronológica
CREATE INDEX IF NOT EXISTS bi_voice_tool_invocations_tenant_called_idx
  ON public.bi_voice_tool_invocations (tenant_id, called_at DESC);

-- Índice secundário: análise por tool ao longo do tempo
CREATE INDEX IF NOT EXISTS bi_voice_tool_invocations_tool_called_idx
  ON public.bi_voice_tool_invocations (tool_name, called_at DESC);

-- RLS
ALTER TABLE public.bi_voice_tool_invocations ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "bi_voice_tool_invocations_tenant_select" ON public.bi_voice_tool_invocations;
CREATE POLICY "bi_voice_tool_invocations_tenant_select"
  ON public.bi_voice_tool_invocations
  FOR SELECT
  TO authenticated
  USING (
    tenant_id IN (SELECT id FROM public.settings LIMIT 1)
  );

DROP POLICY IF EXISTS "bi_voice_tool_invocations_tenant_insert" ON public.bi_voice_tool_invocations;
CREATE POLICY "bi_voice_tool_invocations_tenant_insert"
  ON public.bi_voice_tool_invocations
  FOR INSERT
  TO authenticated
  WITH CHECK (
    tenant_id IN (SELECT id FROM public.settings LIMIT 1)
  );

-- pg_cron: purge de registros com mais de 30 dias (diário às 03h UTC)
SELECT cron.schedule(
  'bi_voice_tool_invocations_cleanup',
  '0 3 * * *',
  $$DELETE FROM public.bi_voice_tool_invocations WHERE called_at < now() - interval '30 days'$$
);


-- ---------------------------------------------------------------------------
-- Migration: 20260426002000_mfa_recovery_consume_atomic.sql
-- ---------------------------------------------------------------------------

-- AUTH-V2-03c-fixup AC1: make mfa_recovery_consume atomic
-- Adds DELETE FROM auth.mfa_factors inside the same transaction that marks used_at.
-- SECURITY DEFINER with service_role bypasses Supabase MFA AAL2 enforcement,
-- which would otherwise block unenroll when the caller's JWT is AAL1 (recovery flow).
-- AC4: if no totp factor found, rolls back and returns { success, error } jsonb.

BEGIN;

-- Drop first: return type changes boolean→jsonb, CREATE OR REPLACE cannot change return type
DROP FUNCTION IF EXISTS public.mfa_recovery_consume(text);

CREATE OR REPLACE FUNCTION public.mfa_recovery_consume(p_code text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, extensions, auth
AS $$
DECLARE
  v_user_id    uuid := auth.uid();
  v_row        public.mfa_recovery_codes%ROWTYPE;
  v_matched    boolean := false;
  v_factor_id  uuid;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  -- 1. Find and consume a matching unused recovery code (constant-time bcrypt)
  FOR v_row IN
    SELECT * FROM public.mfa_recovery_codes
     WHERE user_id = v_user_id
       AND used_at IS NULL
     ORDER BY created_at
  LOOP
    IF extensions.crypt(p_code, v_row.code_hash) = v_row.code_hash THEN
      UPDATE public.mfa_recovery_codes
         SET used_at = now()
       WHERE id = v_row.id;

      v_matched := true;
      EXIT;
    END IF;
  END LOOP;

  IF NOT v_matched THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_code');
  END IF;

  -- 2. Resolve the user's totp factor id
  SELECT id INTO v_factor_id
    FROM auth.mfa_factors
   WHERE user_id    = v_user_id
     AND factor_type = 'totp'
   LIMIT 1;

  IF v_factor_id IS NULL THEN
    -- Code was valid but factor already absent — roll back used_at to keep code reusable
    RAISE EXCEPTION 'factor_not_found';
  END IF;

  -- 3. Delete the totp factor atomically (service_role bypasses AAL2 enforcement)
  DELETE FROM auth.mfa_factors
   WHERE id      = v_factor_id
     AND user_id = v_user_id;

  -- 4. Audit log
  INSERT INTO public.adm_audit_log (actor_id, action, details)
  VALUES (
    v_user_id,
    'mfa.recovery_consumed',
    jsonb_build_object(
      'code_id',         v_row.id,
      'recovery_set_id', v_row.recovery_set_id,
      'factor_id',       v_factor_id
    )
  );

  RETURN jsonb_build_object('success', true);

EXCEPTION
  WHEN OTHERS THEN
    -- Rolls back used_at update + factor delete automatically (same transaction)
    IF SQLERRM = 'factor_not_found' THEN
      RETURN jsonb_build_object('success', false, 'error', 'factor_not_found');
    END IF;
    RAISE;
END;
$$;

REVOKE ALL ON FUNCTION public.mfa_recovery_consume(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.mfa_recovery_consume(text) FROM anon;
GRANT EXECUTE ON FUNCTION public.mfa_recovery_consume(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.mfa_recovery_consume(text) TO service_role;

COMMENT ON FUNCTION public.mfa_recovery_consume(text) IS
  'AUTH-V2-03c-fixup AC1: Validates recovery code + deletes totp factor atomically (SECURITY DEFINER). Returns jsonb {success, error?}. Replaces boolean return of AUTH-V2-03a.';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260426003000_settings_bi_voice_beta_role_guard.sql
-- ---------------------------------------------------------------------------

-- BI-VOICE-04 AC6: Restrict UPDATE of bi_voice_chat_beta_enabled to gestor/super_adm.
--
-- Context: public.settings has a blanket "authenticated_write" FOR ALL USING (true) policy.
-- Postgres RLS is row-level — column-level restriction requires a SECURITY DEFINER helper
-- that validates caller role before allowing the guarded field to be toggled.
--
-- Strategy: drop the blanket write policy and replace it with:
--   1) INSERT (unrestricted for authenticated)
--   2) UPDATE with WITH CHECK that guards bi_voice_chat_beta_enabled changes
--   3) DELETE (unrestricted for authenticated)
-- All other settings UPDATE paths are unaffected.

BEGIN;

CREATE OR REPLACE FUNCTION public.check_bi_voice_beta_update()
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_is_gestor boolean;
BEGIN
  SELECT (user_type IN ('gestor') OR super_admin = true)
    INTO v_is_gestor
    FROM public.settings_users
   WHERE auth_user_id = auth.uid()
     AND active = true
   LIMIT 1;

  RETURN COALESCE(v_is_gestor, false);
END;
$$;

-- Drop the blanket write policy that allows any authenticated user to UPDATE anything
DROP POLICY IF EXISTS "authenticated_write" ON public.settings;

-- INSERT: unrestricted for authenticated (same as before)
DROP POLICY IF EXISTS "settings_insert" ON public.settings;
CREATE POLICY "settings_insert" ON public.settings
  FOR INSERT
  TO authenticated
  WITH CHECK (true);

-- UPDATE: allow freely, EXCEPT when bi_voice_chat_beta_enabled is changed — require gestor
DROP POLICY IF EXISTS "settings_update_with_bi_voice_guard" ON public.settings;
CREATE POLICY "settings_update_with_bi_voice_guard" ON public.settings
  FOR UPDATE
  TO authenticated
  USING (true)
  WITH CHECK (
    (bi_voice_chat_beta_enabled IS NOT DISTINCT FROM
      (SELECT s.bi_voice_chat_beta_enabled FROM public.settings s WHERE s.id = settings.id LIMIT 1))
    OR
    public.check_bi_voice_beta_update()
  );

-- DELETE: unrestricted for authenticated (same as before)
DROP POLICY IF EXISTS "settings_delete" ON public.settings;
CREATE POLICY "settings_delete" ON public.settings
  FOR DELETE
  TO authenticated
  USING (true);

COMMIT;


