-- ---------------------------------------------------------------------------
-- Migration: 20260427020000_fwup01_rotate_service_role_jwt.sql
-- ---------------------------------------------------------------------------

-- FWUP-01: Rotate service_role JWT + sync _app_config from Vault
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- CONTEXT:
--   Migrations 20260226301000, 20260219140000, 20260307100000, and 20260422001700
--   contain a service_role JWT in plaintext. That JWT is compromised.
--
-- PREREQUISITES (manual steps BEFORE applying this migration):
--
--   1. Supabase Dashboard → Settings → API → Regenerate service_role key
--      (copy the new JWT — you will need it in step 2)
--
--   2. Supabase Vault → Update secret 'service_role_cron':
--        vault.secrets WHERE name = 'service_role_cron'
--      Update the value to the new JWT from step 1.
--      If the secret does not exist yet, create it:
--        SELECT vault.create_secret('<new-jwt>', 'service_role_cron', 'Service role JWT for pg_cron — rotated FWUP-01');
--
--   3. Apply THIS migration (supabase db push or migration apply).
--
--   4. Validate: SELECT trigger_fwup01_smoke_test();
--
-- WHAT THIS MIGRATION DOES:
--   a) Defines sync_service_role_from_vault() — reads from vault.decrypted_secrets
--      and updates _app_config.service_role_key with the current Vault value.
--      This decouples _app_config from hardcoded values permanently.
--   b) Calls sync_service_role_from_vault() immediately on apply.
--      After rotation (step 1+2 above), this migration replaces the old
--      plaintext JWT in _app_config with the new rotated value from Vault.
--   c) Logs the rotation in secret_access_log with context 'fwup01-rotation'.
--   d) Provides trigger_fwup01_smoke_test() for post-rotation validation.
--
-- NOTE ON GIT HISTORY:
--   Files 20260226301000 and 20260219140000 in git history cannot be removed
--   without rewriting history. The security fix is key rotation (step 1), not
--   file deletion. The old JWT is invalidated by rotation — historical presence
--   in git is not exploitable after rotation.
--
-- ═══════════════════════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Function: sync _app_config.service_role_key from Vault ─────────────────

CREATE OR REPLACE FUNCTION public.sync_service_role_from_vault()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_new_key text;
BEGIN
  SELECT decrypted_secret INTO v_new_key
  FROM vault.decrypted_secrets
  WHERE name = 'service_role_cron'
  LIMIT 1;

  IF v_new_key IS NULL THEN
    RAISE EXCEPTION 'FWUP-01: Vault secret service_role_cron not found. '
      'Create it in Supabase Dashboard → Vault before applying this migration.';
  END IF;

  -- Update _app_config with the Vault value (idempotent)
  INSERT INTO public._app_config (key, value)
  VALUES ('service_role_key', v_new_key)
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;

  -- Audit log
  INSERT INTO public.secret_access_log (secret_name, caller_context)
  VALUES ('service_role_cron', 'fwup01-rotation');

  RAISE NOTICE 'FWUP-01: _app_config.service_role_key synced from Vault (service_role_cron).';
END;
$$;

COMMENT ON FUNCTION public.sync_service_role_from_vault() IS
  'FWUP-01: Reads service_role JWT from vault.decrypted_secrets (name=service_role_cron) '
  'and updates _app_config.service_role_key. Call after each JWT rotation.';

-- Only service_role may call this
REVOKE ALL ON FUNCTION public.sync_service_role_from_vault() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.sync_service_role_from_vault() TO service_role;


-- ── 2. Apply sync immediately (rotation takes effect on migration apply) ───────

DO $fwup01_apply$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.tables
    WHERE table_schema = 'public' AND table_name = '_app_config'
  ) THEN
    PERFORM public.sync_service_role_from_vault();
  ELSE
    RAISE NOTICE 'FWUP-01: _app_config não existe ainda — sync ignorado. Será executado após adm-sync-client semear _app_config.';
  END IF;
END $fwup01_apply$;


-- ── 3. Smoke-test function (call after apply to validate end-to-end) ──────────

CREATE OR REPLACE FUNCTION public.trigger_fwup01_smoke_test()
RETURNS TABLE(check_name text, status text, detail text)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_vault_key   text;
  v_config_key  text;
BEGIN
  -- Check 1: Vault secret exists
  SELECT decrypted_secret INTO v_vault_key
  FROM vault.decrypted_secrets WHERE name = 'service_role_cron' LIMIT 1;

  check_name := 'vault_secret_exists';
  status     := CASE WHEN v_vault_key IS NOT NULL THEN 'PASS' ELSE 'FAIL' END;
  detail     := CASE WHEN v_vault_key IS NOT NULL
                  THEN 'service_role_cron found in vault (' || length(v_vault_key) || ' chars)'
                  ELSE 'service_role_cron NOT FOUND in vault.decrypted_secrets' END;
  RETURN NEXT;

  -- Check 2: _app_config matches Vault
  SELECT value INTO v_config_key FROM public._app_config WHERE key = 'service_role_key' LIMIT 1;

  check_name := 'app_config_synced';
  status     := CASE WHEN v_config_key = v_vault_key THEN 'PASS' ELSE 'FAIL' END;
  detail     := CASE
    WHEN v_config_key IS NULL THEN '_app_config missing service_role_key row'
    WHEN v_config_key = v_vault_key THEN '_app_config.service_role_key matches Vault'
    ELSE '_app_config.service_role_key DIFFERS from Vault — sync failed'
  END;
  RETURN NEXT;

  -- Check 3: cron job 'process-meeting-followups' uses secure_http_post
  check_name := 'cron_uses_secure_http_post';
  status     := CASE
    WHEN EXISTS (
      SELECT 1 FROM cron.job
      WHERE jobname = 'process-meeting-followups'
        AND command LIKE '%secure_http_post%'
    ) THEN 'PASS' ELSE 'FAIL'
  END;
  detail     := CASE
    WHEN EXISTS (
      SELECT 1 FROM cron.job
      WHERE jobname = 'process-meeting-followups'
        AND command LIKE '%secure_http_post%'
    ) THEN 'process-meeting-followups uses secure_http_post (no JWT literal)'
    ELSE 'process-meeting-followups cron NOT found or still using JWT literal'
  END;
  RETURN NEXT;

  -- Check 4: No JWT literal in active cron commands
  check_name := 'no_jwt_in_cron_commands';
  DECLARE
    v_count int;
  BEGIN
    SELECT COUNT(*) INTO v_count
    FROM cron.job
    WHERE command ~ 'eyJ[A-Za-z0-9_\-]{30,}';

    status := CASE WHEN v_count = 0 THEN 'PASS' ELSE 'FAIL' END;
    detail := CASE WHEN v_count = 0
      THEN 'No JWT literals found in active cron.job commands'
      ELSE v_count || ' cron job(s) still contain JWT literals — check cron.job table'
    END;
  END;
  RETURN NEXT;

  -- Check 5: Rotation logged in secret_access_log
  check_name := 'rotation_audit_logged';
  status     := CASE
    WHEN EXISTS (
      SELECT 1 FROM public.secret_access_log
      WHERE secret_name = 'service_role_cron'
        AND caller_context = 'fwup01-rotation'
    ) THEN 'PASS' ELSE 'WARN'
  END;
  detail     := CASE
    WHEN EXISTS (
      SELECT 1 FROM public.secret_access_log
      WHERE secret_name = 'service_role_cron'
        AND caller_context = 'fwup01-rotation'
    ) THEN 'Rotation logged in secret_access_log'
    ELSE 'No rotation log entry found — secret_access_log may be missing'
  END;
  RETURN NEXT;

END;
$$;

COMMENT ON FUNCTION public.trigger_fwup01_smoke_test() IS
  'FWUP-01 post-rotation validator. Returns one row per check with PASS/FAIL/WARN. '
  'All checks should be PASS after rotation + migration apply.';

REVOKE ALL ON FUNCTION public.trigger_fwup01_smoke_test() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.trigger_fwup01_smoke_test() TO service_role;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260427030000_fwup02_meetings_followups_source.sql
-- ---------------------------------------------------------------------------

-- FWUP-02: Add source discriminator to meetings_followups
-- ═══════════════════════════════════════════════════════════════════════════════
--
-- PROBLEM:
--   useCallProFollowups (webhook/N8N model) and useAgendamentosFollowups
--   (direct channel model) both write to meetings_followups with semantically
--   incompatible fields. A rule created for CallPro appears in Agendamento UI
--   and vice-versa, risking corruption.
--
-- SOLUTION:
--   Add column `source TEXT NOT NULL DEFAULT 'channel'
--     CHECK (source IN ('webhook', 'channel'))`.
--   Backfill existing rows. Add RLS guard preventing cross-source writes.
--
-- BACKFILL LOGIC:
--   webhook: webhook_url IS NOT NULL AND webhook_url != ''
--   channel: whatsapp_template_id IS NOT NULL
--            OR template_id IS NOT NULL
--            OR as_queue_id IS NOT NULL
--   ambiguous (both/neither): → 'channel' (modern path default) + logged
--
-- DEPENDS ON: FWUP-01 (no dependency on JWT rotation, but merged after).
-- ═══════════════════════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Add source column ───────────────────────────────────────────────────────

ALTER TABLE public.meetings_followups
  ADD COLUMN IF NOT EXISTS source text
    NOT NULL DEFAULT 'channel'
    CHECK (source IN ('webhook', 'channel'));

COMMENT ON COLUMN public.meetings_followups.source IS
  'webhook = dispatch via webhook_url (N8N/external) | channel = dispatch via direct channel (WA template, AS, email, SMS)';

-- ── 2. Backfill existing rows ──────────────────────────────────────────────────

DO $$
DECLARE
  v_webhook_count  int := 0;
  v_channel_count  int := 0;
  v_ambiguous      int := 0;
  rec              record;
BEGIN
  -- Pass 1: pure webhook (has webhook_url, no channel identifiers)
  UPDATE public.meetings_followups
     SET source = 'webhook'
   WHERE (webhook_url IS NOT NULL AND webhook_url != '')
     AND whatsapp_template_id IS NULL
     AND template_id IS NULL
     AND as_queue_id IS NULL;
  GET DIAGNOSTICS v_webhook_count = ROW_COUNT;

  -- Pass 2: pure channel (no webhook_url, has at least one channel identifier)
  UPDATE public.meetings_followups
     SET source = 'channel'
   WHERE (webhook_url IS NULL OR webhook_url = '')
     AND (whatsapp_template_id IS NOT NULL
          OR template_id IS NOT NULL
          OR as_queue_id IS NOT NULL);
  GET DIAGNOSTICS v_channel_count = ROW_COUNT;

  -- Pass 3: ambiguous rows (have both webhook_url AND a channel identifier)
  --         Default is already 'channel' (set on column ADD) — log each for audit.
  FOR rec IN
    SELECT id, webhook_url, whatsapp_template_id, template_id, as_queue_id, meeting_status
      FROM public.meetings_followups
     WHERE (webhook_url IS NOT NULL AND webhook_url != '')
       AND (whatsapp_template_id IS NOT NULL
            OR template_id IS NOT NULL
            OR as_queue_id IS NOT NULL)
  LOOP
    v_ambiguous := v_ambiguous + 1;
    RAISE NOTICE '[FWUP-02] Ambiguous row id=% meeting_status=% — has both webhook_url and channel identifier. Defaulted to source=channel. Review manually.',
      rec.id, rec.meeting_status;
  END LOOP;

  RAISE NOTICE '[FWUP-02] Backfill complete: % webhook, % channel, % ambiguous (defaulted to channel)',
    v_webhook_count, v_channel_count, v_ambiguous;
END $$;

-- ── 3. Index for query performance on filtered hooks ──────────────────────────

CREATE INDEX IF NOT EXISTS idx_meetings_followups_source
  ON public.meetings_followups (source)
  WHERE active = true;

-- ── 4. RLS: replace write policy with source-aware guard ──────────────────────
--
-- The new policy adds a cross-source guard: a write can only touch rows
-- where the source matches what the writer declares. This is enforced via
-- WITH CHECK on source equality — prevents a callpro writer from accidentally
-- updating an agendamento rule and vice-versa.
--
-- SELECT policy is unchanged (any active authenticated user).

-- Remove old write policy
DROP POLICY IF EXISTS "meet_fup_write" ON public.meetings_followups;

-- New write policy: gestor/super_admin + source-stable guard
CREATE POLICY "meet_fup_write"
  ON public.meetings_followups FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM public.settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  )
  WITH CHECK (
    -- Must be gestor/super_admin
    EXISTS (
      SELECT 1 FROM public.settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
    AND
    -- source must match the existing row (prevents cross-source corruption on UPDATE)
    -- On INSERT this is a no-op (no existing row to compare) — source is validated by CHECK constraint.
    (
      -- For INSERT: passes (no existing row)
      NOT EXISTS (SELECT 1 FROM public.meetings_followups mf WHERE mf.id = meetings_followups.id)
      OR
      -- For UPDATE: new source must equal existing source
      meetings_followups.source = (
        SELECT source FROM public.meetings_followups WHERE id = meetings_followups.id
      )
    )
  );

COMMENT ON POLICY "meet_fup_write" ON public.meetings_followups IS
  'FWUP-02: Gestor/super_admin may write. Cross-source UPDATE is blocked (source must remain stable after INSERT).';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260427040000_fwup03_canonicalize_leads_stages_followups.sql
-- ---------------------------------------------------------------------------

-- FWUP-03: Canonicalizar schema de leads_stages_followups
--
-- Três migrations conflitantes (20251005, 20251110, 20251202) criaram
-- leads_stages_followups com schemas distintos via CREATE TABLE IF NOT EXISTS,
-- causando drift potencial entre tenants dependendo da ordem de aplicação.
--
-- Esta migration normaliza o schema para o estado canônico:
-- FK canônica: leads_stages_id (NOT NULL)
-- Delay: days / hours / minutes  (não delay_minutes)
-- Sem: stage_id (FK duplicada), name, delay_minutes
--
-- IMPORTANTE: executar dry-run antes de aplicar em produção:
-- psql $DATABASE_URL -c "BEGIN; \i supabase/migrations/20260427040000_fwup03_canonicalize_leads_stages_followups.sql; ROLLBACK;"

BEGIN;

-- ─── Fase 1: garantir colunas canônicas (idempotente) ────────────────────────

ALTER TABLE public.leads_stages_followups
  ADD COLUMN IF NOT EXISTS leads_stages_id uuid REFERENCES public.leads_stages(id) ON DELETE CASCADE;

ALTER TABLE public.leads_stages_followups
  ADD COLUMN IF NOT EXISTS score_matrix_id uuid REFERENCES public.score_matrix(id) ON DELETE SET NULL;

ALTER TABLE public.leads_stages_followups
  ADD COLUMN IF NOT EXISTS target_stage_id uuid REFERENCES public.leads_stages(id) ON DELETE SET NULL;

ALTER TABLE public.leads_stages_followups
  ADD COLUMN IF NOT EXISTS control integer;

-- ─── Fase 2: backfill leads_stages_id a partir de stage_id (se existir) ──────

DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'leads_stages_followups'
      AND column_name = 'stage_id'
  ) THEN
    UPDATE public.leads_stages_followups
    SET leads_stages_id = stage_id
    WHERE leads_stages_id IS NULL
      AND stage_id IS NOT NULL;

    RAISE NOTICE 'FWUP-03: backfill de stage_id → leads_stages_id concluído. Rows afetadas: %',
      (SELECT COUNT(*) FROM public.leads_stages_followups WHERE leads_stages_id IS NOT NULL);
  END IF;
END $$;

-- ─── Fase 3: drop de colunas órfãs ───────────────────────────────────────────

-- stage_id: FK duplicada com nome errado (schema B e C vs schema A que usa leads_stages_id)
ALTER TABLE public.leads_stages_followups
  DROP COLUMN IF EXISTS stage_id;

-- name: campo obrigatório em schema B/C, inexistente no schema A canônico
-- Frontend nunca lê nem escreve este campo
ALTER TABLE public.leads_stages_followups
  DROP COLUMN IF EXISTS name;

-- delay_minutes: representação alternativa de delay usada em schema B/C
-- Schema canônico usa days + hours + minutes separados
ALTER TABLE public.leads_stages_followups
  DROP COLUMN IF EXISTS delay_minutes;

-- ─── Fase 4: índices canônicos ────────────────────────────────────────────────

-- Índice primário de lookup (por etapa, ativos)
CREATE INDEX IF NOT EXISTS idx_leads_stages_fup_stage_active
  ON public.leads_stages_followups (leads_stages_id, active)
  WHERE active = true;

-- Índice para score matrix (filtro alternativo)
CREATE INDEX IF NOT EXISTS idx_leads_stages_fup_score
  ON public.leads_stages_followups (score_matrix_id)
  WHERE score_matrix_id IS NOT NULL;

-- Índice para target_stage_id (FK lookup)
CREATE INDEX IF NOT EXISTS idx_leads_stages_fup_target
  ON public.leads_stages_followups (target_stage_id)
  WHERE target_stage_id IS NOT NULL;

-- ─── Fase 5: smoke test ───────────────────────────────────────────────────────

DO $$
DECLARE
  v_orphan_stage_id    boolean;
  v_orphan_name        boolean;
  v_orphan_delay_min   boolean;
  v_has_canonical_fk   boolean;
  v_row_count          bigint;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='leads_stages_followups' AND column_name='stage_id'
  ) INTO v_orphan_stage_id;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='leads_stages_followups' AND column_name='name'
  ) INTO v_orphan_name;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='leads_stages_followups' AND column_name='delay_minutes'
  ) INTO v_orphan_delay_min;

  SELECT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema='public' AND table_name='leads_stages_followups' AND column_name='leads_stages_id'
  ) INTO v_has_canonical_fk;

  SELECT COUNT(*) INTO v_row_count FROM public.leads_stages_followups;

  IF v_orphan_stage_id THEN
    RAISE EXCEPTION 'FWUP-03 SMOKE FAIL: coluna stage_id ainda existe';
  END IF;
  IF v_orphan_name THEN
    RAISE EXCEPTION 'FWUP-03 SMOKE FAIL: coluna name ainda existe';
  END IF;
  IF v_orphan_delay_min THEN
    RAISE EXCEPTION 'FWUP-03 SMOKE FAIL: coluna delay_minutes ainda existe';
  END IF;
  IF NOT v_has_canonical_fk THEN
    RAISE EXCEPTION 'FWUP-03 SMOKE FAIL: coluna canonical leads_stages_id não existe';
  END IF;

  RAISE NOTICE 'FWUP-03 SMOKE PASS — schema canônico verificado. Rows: %', v_row_count;
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260427041000_fwup06_followup_retry_worker_cron.sql
-- ---------------------------------------------------------------------------

-- FWUP-06: Followup Queue Retry Worker — pg_cron + meeting_followup_queue retry support
-- Story: FWUP-06
-- Adds:
--   1. retry_count column to meeting_followup_queue (if missing)
--   2. PL/pgSQL trigger function using secure_http_post (ADR-SP-05)
--   3. pg_cron job: followup-retry-worker every 10 minutes
--   4. Rollback companion: 20260427040000_fwup06_followup_retry_worker_cron.rollback.sql

BEGIN;

-- ── 1. Add retry_count to meeting_followup_queue ──────────────────────────────

ALTER TABLE public.meeting_followup_queue
  ADD COLUMN IF NOT EXISTS retry_count integer NOT NULL DEFAULT 0;

COMMENT ON COLUMN public.meeting_followup_queue.retry_count IS
  'Number of retry attempts after N8N/webhook callback timeout (max 3). FWUP-06.';

-- Index for the retry worker query pattern
CREATE INDEX IF NOT EXISTS idx_mfq_retry
  ON public.meeting_followup_queue (status, scheduled_for, retry_count)
  WHERE status = 'queued';

-- ── 2. Index on followup_queue for retry worker ───────────────────────────────

CREATE INDEX IF NOT EXISTS idx_fup_queue_retry
  ON public.followup_queue (status, updated_at, retry_count)
  WHERE status = 'queued';

-- ── 3. PL/pgSQL trigger function ──────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.trigger_followup_retry_worker()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_stale_threshold timestamptz := now() - interval '15 minutes';
BEGIN
  -- Only invoke edge function when there are stale queued entries
  IF NOT EXISTS (
    SELECT 1
    FROM public.followup_queue
    WHERE status = 'queued'
      AND updated_at < v_stale_threshold
      AND retry_count < 3
    LIMIT 1
  ) THEN
    RETURN;
  END IF;

  PERFORM public.secure_http_post(
    'service_role_key',
    current_setting('app.supabase_url', true) || '/functions/v1/followup-retry-worker',
    jsonb_build_object('source', 'pg_cron'),
    'trigger_followup_retry_worker'
  );
END;
$$;

COMMENT ON FUNCTION public.trigger_followup_retry_worker() IS
  'Called by pg_cron every 10 minutes. Invokes followup-retry-worker edge fn only when '
  'there are stale queued entries in followup_queue (status=queued, updated_at older than 15 min). '
  'Uses secure_http_post (ADR-SP-05). FWUP-06.';

-- ── 4. Register pg_cron job ───────────────────────────────────────────────────

SELECT cron.unschedule(jobid)
FROM cron.job
WHERE jobname = 'followup-retry-worker';

SELECT cron.schedule(
  'followup-retry-worker',
  '*/10 * * * *',
  $$ SELECT public.trigger_followup_retry_worker(); $$
);

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260427050000_fwup05_leads_stages_followups_waid_index.sql
-- ---------------------------------------------------------------------------

-- FWUP-05: Garantir whatsapp_template_id uuid + índice em leads_stages_followups
--
-- Tenants com schema 20251202 têm whatsapp_template_id TEXT sem FK.
-- Tenants com schema 20251005/20251110 podem não ter a coluna.
-- Esta migration normaliza para UUID com FK opcional + índice.

DO $$
DECLARE
  v_col_type text;
BEGIN
  SELECT data_type INTO v_col_type
  FROM information_schema.columns
  WHERE table_schema = 'public'
    AND table_name   = 'leads_stages_followups'
    AND column_name  = 'whatsapp_template_id';

  IF v_col_type IS NULL THEN
    -- Coluna não existe: adicionar como uuid com FK
    ALTER TABLE public.leads_stages_followups
      ADD COLUMN whatsapp_template_id uuid REFERENCES public.whatsapp_templates(id) ON DELETE SET NULL;
    RAISE NOTICE 'FWUP-05: whatsapp_template_id (uuid) adicionada';

  ELSIF v_col_type = 'text' THEN
    -- Coluna existe como text: converter para uuid (valores legados são nulos em prod)
    ALTER TABLE public.leads_stages_followups
      ALTER COLUMN whatsapp_template_id TYPE uuid USING whatsapp_template_id::uuid;
    ALTER TABLE public.leads_stages_followups
      ADD CONSTRAINT fk_lsf_wa_template
        FOREIGN KEY (whatsapp_template_id) REFERENCES public.whatsapp_templates(id) ON DELETE SET NULL;
    RAISE NOTICE 'FWUP-05: whatsapp_template_id convertida de text para uuid com FK';

  ELSE
    RAISE NOTICE 'FWUP-05: whatsapp_template_id já é % — noop', v_col_type;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS idx_leads_stages_fup_wa_template
  ON public.leads_stages_followups (whatsapp_template_id)
  WHERE whatsapp_template_id IS NOT NULL;


-- ---------------------------------------------------------------------------
-- Migration: 20260427051000_fwup07_nao_compareceu_cleanup.sql
-- ---------------------------------------------------------------------------

-- FWUP-07-DB: Padronizar meeting_status 'não compareceu' → 'nao_compareceu'
--
-- Contexto:
--   - CHECK constraint em meetings_followups aceita apenas 'nao_compareceu' (sem acento)
--   - CHECK constraint em meetings.status aceita AMBOS (com e sem acento) — FWUP-07 não altera meetings
--   - Trigger handle_meeting_followup_queue não mapeava 'não compareceu' → 'nao_compareceu',
--     causando falha silenciosa ao enfileirar followups quando meeting.status era 'não compareceu'
--
-- O que esta migration faz:
--   1. Backfill: converte rows em meetings_followups com meeting_status 'não compareceu'
--   2. Atualiza handle_meeting_followup_queue para normalizar 'não compareceu' → 'nao_compareceu'
--   3. Smoke test inline
--
-- Nota: meeting_followup_queue não possui coluna meeting_status — não requer limpeza aqui.
-- Nota: meetings.status NÃO é alterado — escopo deste story é apenas followup rules + trigger.

BEGIN;

-- ─── 1. Contar e logar rows afetadas em meetings_followups ────────────────────

DO $$
DECLARE
  v_count bigint;
BEGIN
  SELECT COUNT(*) INTO v_count
  FROM public.meetings_followups
  WHERE meeting_status = 'não compareceu';

  IF v_count > 0 THEN
    RAISE NOTICE 'FWUP-07: encontrados % rows em meetings_followups com meeting_status = ''não compareceu'' — convertendo', v_count;
  ELSE
    RAISE NOTICE 'FWUP-07: nenhum row com ''não compareceu'' em meetings_followups — cleanup desnecessário mas migration segura';
  END IF;
END $$;

-- ─── 2. Backfill meetings_followups ───────────────────────────────────────────

UPDATE public.meetings_followups
SET meeting_status = 'nao_compareceu',
    updated_at     = now()
WHERE meeting_status = 'não compareceu';

-- ─── 3. Patch trigger: adicionar normalização de 'não compareceu' ─────────────
--
-- O trigger anterior mapeava meetings.status → meetings_followups.meeting_status
-- mas não incluía o caso 'não compareceu' (com acento) na CASE expression.
-- Adicionado como último WHEN antes do ELSE para cobrir registros legados.

CREATE OR REPLACE FUNCTION public.handle_meeting_followup_queue()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_status    text;
  rule_rec    record;
  delay_secs  bigint;
BEGIN
  -- Skip if status didn't change on UPDATE
  IF (TG_OP = 'UPDATE' AND OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;

  -- Normalize meetings.status → meetings_followups.meeting_status
  -- 'não compareceu' (com acento, legado) → 'nao_compareceu' (canônico)
  v_status := CASE NEW.status
    WHEN 'agendada'         THEN 'agendado'
    WHEN 'agendado'         THEN 'agendado'
    WHEN 'compareceu'       THEN 'compareceu'
    WHEN 'nao_compareceu'   THEN 'nao_compareceu'
    WHEN 'não compareceu'   THEN 'nao_compareceu'
    WHEN 'cancelado'        THEN 'cancelado'
    WHEN 'cancelada'        THEN 'cancelado'
    WHEN 'realizado'        THEN 'realizado'
    ELSE NULL
  END;

  -- Status desconhecido — não enfileirar
  IF v_status IS NULL THEN
    RETURN NEW;
  END IF;

  -- Cancelar entradas pendentes anteriores para este meeting (status mudou)
  IF TG_OP = 'UPDATE' THEN
    UPDATE public.meeting_followup_queue
       SET status = 'cancelled'
     WHERE meeting_id = NEW.id
       AND status = 'pending';
  END IF;

  -- Criar entrada na fila para cada regra ativa com o status correspondente
  FOR rule_rec IN
    SELECT id, channel, webhook_url, message, days, hours, minutes
      FROM public.meetings_followups
     WHERE active = true
       AND meeting_status = v_status
  LOOP
    delay_secs := (
      COALESCE(rule_rec.days, 0)    * 86400 +
      COALESCE(rule_rec.hours, 0)   * 3600  +
      COALESCE(rule_rec.minutes, 0) * 60
    )::bigint;

    INSERT INTO public.meeting_followup_queue (
      rule_id, meeting_id, people_id, leads_id,
      scheduled_for, channel, webhook_url, message_snapshot
    ) VALUES (
      rule_rec.id,
      NEW.id,
      NEW.people_id,
      NEW.leads_id,
      now() + (delay_secs * interval '1 second'),
      rule_rec.channel,
      COALESCE(rule_rec.webhook_url, ''),
      rule_rec.message
    )
    ON CONFLICT DO NOTHING;
  END LOOP;

  RETURN NEW;
END;
$$;

COMMENT ON FUNCTION public.handle_meeting_followup_queue() IS
  'Trigger: enfileira followup rules quando meeting.status muda. '
  'Normaliza status canonical incluindo ''não compareceu'' (legado) → ''nao_compareceu''. '
  'FWUP-07.';

-- ─── 4. Smoke test ────────────────────────────────────────────────────────────

DO $$
DECLARE
  v_remaining bigint;
BEGIN
  SELECT COUNT(*) INTO v_remaining
  FROM public.meetings_followups
  WHERE meeting_status = 'não compareceu';

  IF v_remaining > 0 THEN
    RAISE EXCEPTION 'FWUP-07 SMOKE FAIL: % rows ainda com meeting_status = ''não compareceu''', v_remaining;
  END IF;

  RAISE NOTICE 'FWUP-07 SMOKE PASS — meetings_followups sem ''não compareceu'' residual. Trigger atualizado.';
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
