-- ---------------------------------------------------------------------------
-- Migration: 20260430080000_fwup20_leads_pipelines_order_index.sql
-- ---------------------------------------------------------------------------

-- FWUP-20: add order_index to leads_pipelines (absent from baseline)
-- usePipelinesReal.ts queries .order('order_index') — missing column causes DB error → empty result → invisible pipelines

ALTER TABLE public.leads_pipelines
  ADD COLUMN IF NOT EXISTS order_index integer NOT NULL DEFAULT 0;

-- Backfill existing rows with stable ordering based on creation time
UPDATE public.leads_pipelines p
SET    order_index = sub.rn
FROM (
  SELECT id, (ROW_NUMBER() OVER (ORDER BY created_at ASC) - 1) AS rn
  FROM public.leads_pipelines
) sub
WHERE p.id = sub.id
  AND p.order_index = 0;


-- ---------------------------------------------------------------------------
-- Migration: 20260430090000_fwup21_gcal_credentials_fix.sql
-- ---------------------------------------------------------------------------

-- FWUP-21: Fix Google Calendar credentials save in new tenants
--
-- Two root causes:
-- 1. settings table has no seed row in baseline → useUpdateSettings falls into
--    insert path requiring company_name, but Step4Credentials only sends
--    google_client_id/google_client_secret → throws "company_name é obrigatório"
-- 2. user_calendar_connections has RLS enabled but zero policies in any
--    client migration → frontend reads blocked → connections never appear

-- ── 1. Seed settings row if missing ──────────────────────────────────────────
-- settings has no UNIQUE constraint besides id (PK with gen_random_uuid) so
-- ON CONFLICT DO NOTHING never fires — use WHERE NOT EXISTS to guard instead.
INSERT INTO public.settings (company_name, timezone, language, currency)
SELECT 'Minha Empresa', 'America/Sao_Paulo', 'pt-br', 'BRL'
WHERE NOT EXISTS (SELECT 1 FROM public.settings);

-- ── 2. RLS policies for user_calendar_connections ─────────────────────────────
ALTER TABLE public.user_calendar_connections ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "calendar_connection_self" ON public.user_calendar_connections;
CREATE POLICY "calendar_connection_self"
  ON public.user_calendar_connections
  FOR ALL
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.settings_users su
      WHERE su.auth_user_id = auth.uid()
        AND (
          su.id = user_calendar_connections.user_id
          OR su.super_admin = true
          OR su.user_type = 'gestor'
        )
        AND su.active = true
    )
  );


-- ---------------------------------------------------------------------------
-- Migration: 20260430100000_fwup22_settings_update_fix.sql
-- ---------------------------------------------------------------------------

-- FWUP-22: Fix settings UPDATE failure — Google Calendar + logo em ORA
--
-- Root cause: settings_audit_trigger_fn (migration 136) insere em
-- settings_audit_log com tenant_id NOT NULL. Mas create-tenant-user nunca
-- define app_metadata.tenant_id no JWT dos usuários do tenant → _tenant_id
-- é NULL → INSERT viola NOT NULL → trigger aborta → UPDATE da settings faz
-- rollback com PostgrestError.
--
-- Sintomas em ORA:
--   • Logo:             "Erro ao salvar configurações" + "Erro ao fazer upload"
--   • Google Calendar:  "Erro ao salvar. Tente novamente."
--
-- Fix 1: guard IS NULL no trigger (fail-open — não bloqueia UPDATE quando
--         tenant_id ausente do JWT)
-- Fix 2: ADD COLUMN IF NOT EXISTS para google_client_id / google_client_secret
--         (belt-and-suspenders caso migração 036 não tenha chegado a este tenant)

-- ── 1. Belt-and-suspenders: garantir colunas de OAuth Google ─────────────────
ALTER TABLE public.settings
  ADD COLUMN IF NOT EXISTS google_client_id     text,
  ADD COLUMN IF NOT EXISTS google_client_secret text;

-- ── 2. Harden settings_audit_trigger_fn — bail-out on NULL tenant_id ─────────
-- CREATE OR REPLACE é idempotente; o trigger existente continua apontando
-- para a mesma função — a lógica é apenas substituída.
CREATE OR REPLACE FUNCTION public.settings_audit_trigger_fn()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $$
DECLARE
  _tenant_id uuid;
  _user_id   uuid;
  _col       text;
  _old_val   text;
  _new_val   text;
  _section   text := TG_ARGV[0];
BEGIN
  _tenant_id := (auth.jwt() -> 'app_metadata' ->> 'tenant_id')::uuid;
  _user_id   := auth.uid();

  -- Tenants onde o JWT não carrega app_metadata.tenant_id: não bloquear UPDATE
  IF _tenant_id IS NULL THEN
    RETURN NEW;
  END IF;

  FOREACH _col IN ARRAY (
    SELECT array_agg(column_name::text)
    FROM information_schema.columns
    WHERE table_schema = TG_TABLE_SCHEMA
      AND table_name   = TG_TABLE_NAME
      AND column_name NOT IN ('id', 'created_at', 'updated_at', 'tenant_id')
  ) LOOP
    EXECUTE format('SELECT ($1).%I::text', _col) INTO _old_val USING OLD;
    EXECUTE format('SELECT ($1).%I::text', _col) INTO _new_val USING NEW;
    IF _old_val IS DISTINCT FROM _new_val THEN
      INSERT INTO public.settings_audit_log
        (tenant_id, user_id, section, field, old_value, new_value, is_sensitive)
      VALUES (
        _tenant_id,
        _user_id,
        _section,
        _col,
        public.audit_value(_col, _old_val),
        public.audit_value(_col, _new_val),
        public.is_sensitive_column(_col)
      );
    END IF;
  END LOOP;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Fallback final: nunca deixar falha de auditoria bloquear UPDATE
  RETURN NEW;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260430110000_fwup23_sends_import_presets.sql
-- ---------------------------------------------------------------------------

-- FWUP-23: sends_import_presets — Presets de importação de listas para Sends
-- Allows operators to pick a pre-configured field mapping when importing CSV contacts.
-- The preset stores field_mapping (FieldMappingConfig) + lead_control value.

CREATE TABLE IF NOT EXISTS public.sends_import_presets (
  id           uuid    PRIMARY KEY DEFAULT gen_random_uuid(),
  name         text    NOT NULL,
  description  text,
  field_mapping jsonb  NOT NULL DEFAULT '{}',
  lead_control text,   -- value written to leads.control on import (e.g. 'recomendacao')
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now()
);

ALTER TABLE public.sends_import_presets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "sends_import_presets_auth" ON public.sends_import_presets
  FOR ALL USING (true) WITH CHECK (true);

CREATE TRIGGER update_sends_import_presets_updated_at
  BEFORE UPDATE ON public.sends_import_presets
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

COMMENT ON TABLE  public.sends_import_presets IS 'Pre-configured CSV field mappings for lead import in Sends campaigns';
COMMENT ON COLUMN public.sends_import_presets.field_mapping IS 'FieldMappingConfig JSON: {name, whatsapp, crm_extra, lead_extra}';
COMMENT ON COLUMN public.sends_import_presets.lead_control  IS 'Value set on leads.control for all leads imported with this preset';


-- ---------------------------------------------------------------------------
-- Migration: 20260430120000_fwup24_followup_control_text.sql
-- ---------------------------------------------------------------------------

-- FWUP-24: Migrar leads_stages_followups.control de INTEGER para TEXT
-- Valores: 1→'recomendacao', 2→'pessoal', 3→'evento', 4→'network', NULL→NULL
-- Motivo: inteiros são opacos para operadores; texto é autoexplicativo na UI e no DB.

ALTER TABLE leads_stages_followups
  ALTER COLUMN control TYPE text USING CASE control::text
    WHEN '1' THEN 'recomendacao'
    WHEN '2' THEN 'pessoal'
    WHEN '3' THEN 'evento'
    WHEN '4' THEN 'network'
    ELSE NULL
  END;

COMMENT ON COLUMN leads_stages_followups.control IS
  'Filtra follow-ups por origem do lead: recomendacao | pessoal | evento | network | NULL (universal)';


