  ADD COLUMN IF NOT EXISTS telefone text;
CREATE INDEX IF NOT EXISTS idx_clients_people_telefone_not_null
  ON public.clients_people (telefone) WHERE telefone IS NOT NULL;

-- ai_last_message_at + ai_processing_lock — controle do buffer de IA
ALTER TABLE public.clients_people
  ADD COLUMN IF NOT EXISTS ai_last_message_at timestamptz,
  ADD COLUMN IF NOT EXISTS ai_processing_lock boolean NOT NULL DEFAULT false;

-- tiktok_open_id — canal TikTok
ALTER TABLE public.clients_people
  ADD COLUMN IF NOT EXISTS tiktok_open_id text;
CREATE INDEX IF NOT EXISTS idx_clients_people_tiktok_open_id
  ON public.clients_people (tiktok_open_id) WHERE tiktok_open_id IS NOT NULL;


-- ---------------------------------------------------------------------------
-- Migration: 20260430160000_fwup28_get_omni_contacts_rpc.sql
-- ---------------------------------------------------------------------------

-- fwup28: RPC get_omni_contacts — query definitiva para o Omni inbox
--
-- Substitui o JOIN frágil do PostgREST. Em PostgREST, qualquer filtro em
-- recurso embutido (mesmo sem !inner) vira WHERE clause — contatos sem lead
-- sempre desaparecem. Solução: EXISTS subqueries controlam exatamente quando
-- um contato sem lead deve aparecer.
--
-- Lógica do filtro responsavel:
--   Mostrar contato se:
--   (a) não tem nenhum lead ativo (inbound sem CRM) → aparece para qualquer user
--   (b) tem lead com user_id = responsavel → aparece para esse user
--   (c) tem lead com user_id IS NULL (não atribuído) → aparece para qualquer user
--
-- Retorna: (contact jsonb, total_count bigint)
--   total_count via COUNT(*) OVER() reflete o total antes do LIMIT/OFFSET.

CREATE OR REPLACE FUNCTION public.get_omni_contacts(
  p_search_term  text DEFAULT NULL,
  p_status_atend text DEFAULT NULL,
  p_atend_ia     text DEFAULT NULL,
  p_filtro_data  text DEFAULT NULL,   -- formato: 'YYYY-MM-DD_YYYY-MM-DD'
  p_responsavel  text DEFAULT NULL,   -- UUID do usuário
  p_pipeline     text DEFAULT NULL,   -- UUID do pipeline
  p_etapa        text DEFAULT NULL,   -- UUID da etapa
  p_time         text DEFAULT NULL,   -- UUID do time
  p_limit        int  DEFAULT 20,
  p_offset       int  DEFAULT 0
)
RETURNS TABLE (contact jsonb, total_count bigint)
LANGUAGE sql
STABLE
SECURITY INVOKER
AS $$
  SELECT
    to_jsonb(p.*)    AS contact,
    COUNT(*) OVER()  AS total_count
  FROM public.clients_people p
  WHERE
    -- canal: whatsapp ou instagram obrigatório
    (p.whatsapp IS NOT NULL OR p.instagram_id IS NOT NULL)
    AND p.status <> 'merged'
    -- busca
    AND (
      p_search_term IS NULL OR p_search_term = '' OR
      p.name             ILIKE '%' || p_search_term || '%' OR
      p.whatsapp         ILIKE '%' || p_search_term || '%' OR
      p.instagram_user_id ILIKE '%' || p_search_term || '%'
    )
    -- status de atendimento
    AND (p_status_atend IS NULL OR p.service_status = p_status_atend)
    -- atendimento IA
    AND (
      p_atend_ia IS NULL OR
      (p_atend_ia = 'ia_ativa' AND p.ai_enabled = true) OR
      (p_atend_ia = 'humano'   AND p.ai_enabled = false)
    )
    -- intervalo de data
    AND (
      p_filtro_data IS NULL OR
      p.updated_at BETWEEN
        (split_part(p_filtro_data, '_', 1) || 'T00:00:00')::timestamptz
        AND (split_part(p_filtro_data, '_', 2) || 'T23:59:59')::timestamptz
    )
    -- responsavel: sem lead ativo → aparece; com lead → filtra por user_id
    AND (
      p_responsavel IS NULL
      OR NOT EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND l.status NOT IN ('lost', 'archived')
         )
      OR EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND (l.user_id = p_responsavel::uuid OR l.user_id IS NULL)
         )
    )
    -- pipeline
    AND (
      p_pipeline IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_pipelines_id = p_pipeline::uuid
      )
    )
    -- etapa
    AND (
      p_etapa IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_stages_id = p_etapa::uuid
      )
    )
    -- time
    AND (
      p_time IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.teams_id = p_time::uuid
      )
    )
  ORDER BY p.updated_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$$;

GRANT EXECUTE ON FUNCTION public.get_omni_contacts(text,text,text,text,text,text,text,text,int,int) TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260430180000_fwup30_get_omni_contacts_rpc_v2.sql
-- ---------------------------------------------------------------------------

-- fwup30: get_omni_contacts v2 — fixes for ORA empty inbox and TikTok contacts
--
-- Changes vs fwup28:
--   1. Canal filter now includes tiktok_open_id (contacts without WA or IG but with TikTok)
--   2. service_status filter for 'open' now also matches NULL (contacts that predate
--      the p10 normalization migration and were never explicitly set to 'open')

CREATE OR REPLACE FUNCTION public.get_omni_contacts(
  p_search_term  text DEFAULT NULL,
  p_status_atend text DEFAULT NULL,
  p_atend_ia     text DEFAULT NULL,
  p_filtro_data  text DEFAULT NULL,   -- formato: 'YYYY-MM-DD_YYYY-MM-DD'
  p_responsavel  text DEFAULT NULL,   -- UUID do usuário
  p_pipeline     text DEFAULT NULL,   -- UUID do pipeline
  p_etapa        text DEFAULT NULL,   -- UUID da etapa
  p_time         text DEFAULT NULL,   -- UUID do time
  p_limit        int  DEFAULT 20,
  p_offset       int  DEFAULT 0
)
RETURNS TABLE (contact jsonb, total_count bigint)
LANGUAGE sql
STABLE
SECURITY INVOKER
AS $$
  SELECT
    to_jsonb(p.*)    AS contact,
    COUNT(*) OVER()  AS total_count
  FROM public.clients_people p
  WHERE
    -- canal: whatsapp, instagram, or tiktok obrigatório
    (p.whatsapp IS NOT NULL OR p.instagram_id IS NOT NULL OR p.tiktok_open_id IS NOT NULL)
    AND p.status <> 'merged'
    -- busca
    AND (
      p_search_term IS NULL OR p_search_term = '' OR
      p.name              ILIKE '%' || p_search_term || '%' OR
      p.whatsapp          ILIKE '%' || p_search_term || '%' OR
      p.instagram_user_id ILIKE '%' || p_search_term || '%'
    )
    -- status de atendimento
    -- NULL service_status is treated as 'open' (contacts predating p10 migration)
    AND (
      p_status_atend IS NULL
      OR (p_status_atend = 'open'   AND (p.service_status = 'open'   OR p.service_status IS NULL))
      OR (p_status_atend <> 'open'  AND p.service_status = p_status_atend)
    )
    -- atendimento IA
    AND (
      p_atend_ia IS NULL OR
      (p_atend_ia = 'ia_ativa' AND p.ai_enabled = true) OR
      (p_atend_ia = 'humano'   AND p.ai_enabled = false)
    )
    -- intervalo de data
    AND (
      p_filtro_data IS NULL OR
      p.updated_at BETWEEN
        (split_part(p_filtro_data, '_', 1) || 'T00:00:00')::timestamptz
        AND (split_part(p_filtro_data, '_', 2) || 'T23:59:59')::timestamptz
    )
    -- responsavel: sem lead ativo → aparece; com lead → filtra por user_id
    AND (
      p_responsavel IS NULL
      OR NOT EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND l.status NOT IN ('lost', 'archived')
         )
      OR EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND (l.user_id = p_responsavel::uuid OR l.user_id IS NULL)
         )
    )
    -- pipeline
    AND (
      p_pipeline IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_pipelines_id = p_pipeline::uuid
      )
    )
    -- etapa
    AND (
      p_etapa IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_stages_id = p_etapa::uuid
      )
    )
    -- time
    AND (
      p_time IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.teams_id = p_time::uuid
      )
    )
  ORDER BY p.updated_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$$;

GRANT EXECUTE ON FUNCTION public.get_omni_contacts(text,text,text,text,text,text,text,text,int,int) TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260430190000_add_private_reply_message_type.sql
-- ---------------------------------------------------------------------------

-- Adiciona 'private_reply' ao check constraint de message_type.
-- Contexto: Instagram "private reply" é uma resposta privada (DM) a um comentário,
-- roteada via /{comment_id}/private_replies na Graph API. Tipo distinto de 'reply_comentario'
-- (que é resposta pública) e de 'texto' (DM direto por IGSID).
ALTER TABLE public.messages DROP CONSTRAINT IF EXISTS messages_message_type_check;
ALTER TABLE public.messages
  ADD CONSTRAINT messages_message_type_check
  CHECK (message_type = ANY (ARRAY[
    'texto'::text,
    'audio'::text,
    'imagem'::text,
    'video'::text,
    'documento'::text,
    'chamada'::text,
    'comentario'::text,
    'story_reply'::text,
    'story_mention'::text,
    'reply_comentario'::text,
    'arquivo'::text,
    'private_reply'::text
  ]));


-- ---------------------------------------------------------------------------
-- Migration: 20260430200000_add_email_chamada_message_types.sql
-- ---------------------------------------------------------------------------

-- Adiciona 'email' e 'chamada' ao check constraint de message_type.
-- Contexto: NegocioConversa.tsx e Conversas.tsx inserem mensagens com
-- message_type='email' (canal email) e message_type='chamada' (registro de ligação),
-- mas esses valores estavam ausentes da constraint, causando violação em runtime.
ALTER TABLE public.messages DROP CONSTRAINT IF EXISTS messages_message_type_check;
ALTER TABLE public.messages
  ADD CONSTRAINT messages_message_type_check
  CHECK (message_type = ANY (ARRAY[
    'texto'::text,
    'audio'::text,
    'imagem'::text,
    'video'::text,
    'documento'::text,
    'chamada'::text,
    'comentario'::text,
    'story_reply'::text,
    'story_mention'::text,
    'reply_comentario'::text,
    'arquivo'::text,
    'private_reply'::text,
    'email'::text
  ]));


-- ---------------------------------------------------------------------------
-- Migration: 20260430220000_fwup31_sends_missing_columns.sql
-- ---------------------------------------------------------------------------

-- FWUP-31: Adds missing sends columns for tenants created from the baseline.
-- phase_consolidation (20260223) and sends_wa_channel (20260302200000) were never
-- added to client-migrations.json, so new tenants (e.g. ORA) are missing:
-- channel, type, failed_count, send_interval_seconds, webhook_id, filter_config,
-- wa_channel_id, message_content.

ALTER TABLE public.sends
  ADD COLUMN IF NOT EXISTS channel               text NOT NULL DEFAULT 'whatsapp',
  ADD COLUMN IF NOT EXISTS type                  text NOT NULL DEFAULT 'filtered',
  ADD COLUMN IF NOT EXISTS failed_count          integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS send_interval_seconds integer NOT NULL DEFAULT 60,
  ADD COLUMN IF NOT EXISTS webhook_id            uuid,
  ADD COLUMN IF NOT EXISTS filter_config         jsonb,
  ADD COLUMN IF NOT EXISTS wa_channel_id         uuid,
  ADD COLUMN IF NOT EXISTS message_content       text,
  ADD COLUMN IF NOT EXISTS last_batch_at         timestamptz;

-- Check constraints (idempotent)
ALTER TABLE public.sends
  DROP CONSTRAINT IF EXISTS sends_channel_check;
ALTER TABLE public.sends
  ADD CONSTRAINT sends_channel_check
  CHECK (channel IN ('whatsapp', 'email', 'sms', 'phone'));

ALTER TABLE public.sends
  DROP CONSTRAINT IF EXISTS sends_type_check;
ALTER TABLE public.sends
  ADD CONSTRAINT sends_type_check
  CHECK (type IN ('imported', 'filtered'));

ALTER TABLE public.sends
  DROP CONSTRAINT IF EXISTS sends_interval_check;
ALTER TABLE public.sends
  ADD CONSTRAINT sends_interval_check
  CHECK (send_interval_seconds IN (5, 10, 30, 60, 300, 600, 1800, 3600));

-- FK: sends.wa_channel_id → settings_whatsapp_channels
ALTER TABLE public.sends
  DROP CONSTRAINT IF EXISTS sends_wa_channel_id_fkey;
ALTER TABLE public.sends
  ADD CONSTRAINT sends_wa_channel_id_fkey
  FOREIGN KEY (wa_channel_id)
  REFERENCES public.settings_whatsapp_channels(id)
  ON DELETE SET NULL;

-- FK: sends.webhook_id → webhooks
ALTER TABLE public.sends
  DROP CONSTRAINT IF EXISTS fk_sends_webhook;
ALTER TABLE public.sends
  ADD CONSTRAINT fk_sends_webhook
  FOREIGN KEY (webhook_id)
  REFERENCES public.webhooks(id)
  ON DELETE SET NULL;


-- ---------------------------------------------------------------------------
-- Migration: 20260430230000_fwup32_omni_channel_configs_rls.sql
-- ---------------------------------------------------------------------------

-- FWUP-32: RLS policies for omni_channel_configs on new tenants.
-- 20260308010001_omni_channel_configs-ok.sql was never added to client-migrations.json
-- so tenants onboarded from the baseline have RLS enabled but no policies —
-- all reads and writes (including tl;dv API key save) were rejected.

DROP POLICY IF EXISTS "omni_channel_configs_read"  ON public.omni_channel_configs;
DROP POLICY IF EXISTS "omni_channel_configs_write" ON public.omni_channel_configs;

CREATE POLICY "omni_channel_configs_read"
  ON public.omni_channel_configs FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.settings_users
      WHERE auth_user_id = auth.uid()
        AND active = true
        AND deleted_at IS NULL
    )
  );

CREATE POLICY "omni_channel_configs_write"
  ON public.omni_channel_configs FOR ALL
  USING (
    EXISTS (
      SELECT 1 FROM public.settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = 'gestor')
        AND active = true
        AND deleted_at IS NULL
    )
  );


-- ---------------------------------------------------------------------------
-- Migration: 20260430240000_fix_save_agent_complete_humanizacao_cast.sql
-- ---------------------------------------------------------------------------

-- Fix save_agent_complete: humanizacao cast text → not boolean
--
-- Bug: line `humanizacao = COALESCE((p_agent_data->>'humanizacao')::boolean, humanizacao)`
-- was casting a text enum ('alta', 'media', 'nenhuma') to boolean, causing the entire
-- save_agent_complete RPC to fail with a cast error whenever humanizacao was set.

CREATE OR REPLACE FUNCTION public.save_agent_complete(
  p_agent_id   uuid,
  p_agent_data jsonb,
  p_steps_data jsonb DEFAULT NULL,
  p_changelog  jsonb DEFAULT NULL,
  p_created_by uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_current_version int;
  v_new_version     int;
  v_snapshot        jsonb;
  v_step            jsonb;
  v_step_id         uuid;
BEGIN
  -- 1. Lock the agent row and read current state
  SELECT current_version,
         to_jsonb(a) AS snapshot
  INTO   v_current_version, v_snapshot
  FROM   public.ai_agents a
  WHERE  id = p_agent_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent not found: %', p_agent_id;
  END IF;

  -- Attach current steps to the snapshot (same shape as the frontend historyData)
  v_snapshot := jsonb_set(
    v_snapshot,
    '{steps}',
    COALESCE(
      (SELECT jsonb_agg(to_jsonb(s) ORDER BY s.order_index)
       FROM public.ai_agents_steps s
       WHERE s.ai_agent_id = p_agent_id),
      '[]'::jsonb
    )
  );

  -- 2. Write history entry (state BEFORE the update)
  INSERT INTO public.ai_agents_history
    (ai_agent_id, version, data, changelog, created_by)
  VALUES
    (p_agent_id, v_current_version, v_snapshot, p_changelog, p_created_by);

  -- 3. Update ai_agents
  v_new_version := v_current_version + 1;

  UPDATE public.ai_agents
  SET
    name                = COALESCE((p_agent_data->>'name'),                name),
    description         = COALESCE((p_agent_data->>'description'),         description),
    identity            = COALESCE((p_agent_data->>'identity'),            identity),
    general_rules       = COALESCE((p_agent_data->>'general_rules'),       general_rules),
    input_data          = COALESCE((p_agent_data->>'input_data'),          input_data),
    use_stages          = COALESCE((p_agent_data->>'use_stages')::boolean, use_stages),
    active              = COALESCE((p_agent_data->>'active')::boolean,     active),
    pipeline_id         = CASE WHEN p_agent_data ? 'pipeline_id'
                               THEN (p_agent_data->>'pipeline_id')::uuid
                               ELSE pipeline_id END,
    pipeline_ids        = CASE WHEN p_agent_data ? 'pipeline_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'pipeline_ids'))::uuid[]
                               ELSE pipeline_ids END,
    leads_stages_id     = CASE WHEN p_agent_data ? 'leads_stages_id'
                               THEN (p_agent_data->>'leads_stages_id')::uuid
                               ELSE leads_stages_id END,
    score_matrix_ids    = CASE WHEN p_agent_data ? 'score_matrix_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'score_matrix_ids'))::uuid[]
                               ELSE score_matrix_ids END,
    score_allow_empty   = COALESCE((p_agent_data->>'score_allow_empty')::boolean, score_allow_empty),
    score_value         = COALESCE((p_agent_data->>'score_value')::integer,       score_value),
    channel_types       = CASE WHEN p_agent_data ? 'channel_types'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'channel_types'))
                               ELSE channel_types END,
    stage_ids           = CASE WHEN p_agent_data ? 'stage_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'stage_ids'))::uuid[]
                               ELSE stage_ids END,
    llm_provider        = COALESCE((p_agent_data->>'llm_provider'),        llm_provider),
    llm_model           = COALESCE((p_agent_data->>'llm_model'),           llm_model),
    llm_temperature     = COALESCE((p_agent_data->>'llm_temperature')::numeric,  llm_temperature),
    llm_max_tokens      = COALESCE((p_agent_data->>'llm_max_tokens')::integer,   llm_max_tokens),
    llm_provider_id     = CASE WHEN p_agent_data ? 'llm_provider_id'
                               THEN (p_agent_data->>'llm_provider_id')::uuid
                               ELSE llm_provider_id END,
    memory_window       = COALESCE((p_agent_data->>'memory_window')::integer,    memory_window),
    wa_phone_number_id  = COALESCE((p_agent_data->>'wa_phone_number_id'),  wa_phone_number_id),
    wa_channel_id       = CASE WHEN p_agent_data ? 'wa_channel_id'
                               THEN (p_agent_data->>'wa_channel_id')::uuid
                               ELSE wa_channel_id END,
    buffer_ms           = COALESCE((p_agent_data->>'buffer_ms')::integer,  buffer_ms),
    humanizacao         = COALESCE((p_agent_data->>'humanizacao'),         humanizacao),
    agent_type          = COALESCE((p_agent_data->>'agent_type'),          agent_type),
    voice_enabled       = COALESCE((p_agent_data->>'voice_enabled')::boolean,    voice_enabled),
    voice_response_mode = COALESCE((p_agent_data->>'voice_response_mode'), voice_response_mode),
    voice_id            = COALESCE((p_agent_data->>'voice_id'),            voice_id),
    voice_first_message = COALESCE((p_agent_data->>'voice_first_message'), voice_first_message),
    voice_language      = COALESCE((p_agent_data->>'voice_language'),      voice_language),
    voice_model_id      = COALESCE((p_agent_data->>'voice_model_id'),      voice_model_id),
    voice_stability     = COALESCE((p_agent_data->>'voice_stability')::numeric,  voice_stability),
    voice_similarity    = COALESCE((p_agent_data->>'voice_similarity')::numeric, voice_similarity),
    voice_speed         = COALESCE((p_agent_data->>'voice_speed')::numeric,      voice_speed),
    el_sync_status      = COALESCE((p_agent_data->>'el_sync_status'),      el_sync_status),
    current_version     = v_new_version,
    updated_at          = now()
  WHERE id = p_agent_id;

  -- 4. Replace steps (only when caller provides the array)
  IF p_steps_data IS NOT NULL THEN
    DELETE FROM public.ai_agents_steps
    WHERE ai_agent_id = p_agent_id;

    FOR v_step IN SELECT * FROM jsonb_array_elements(p_steps_data)
    LOOP
      -- Honour the id supplied by the frontend so React Query cache stays valid;
      -- fall back to a fresh uuid when not provided.
      v_step_id := CASE
        WHEN v_step ? 'id'
          AND (v_step->>'id') IS NOT NULL
          AND (v_step->>'id') <> ''
        THEN (v_step->>'id')::uuid
        ELSE gen_random_uuid()
      END;

      INSERT INTO public.ai_agents_steps
        (id, ai_agent_id, name, prompt, control, order_index,
         pipeline_id, stage_id, active, created_at, updated_at)
      VALUES (
        v_step_id,
        p_agent_id,
        v_step->>'name',
        COALESCE(v_step->>'prompt', ''),
        NULLIF(v_step->>'control', ''),
        (v_step->>'order_index')::integer,
        CASE WHEN (v_step->>'pipeline_id') IS NOT NULL AND (v_step->>'pipeline_id') <> ''
             THEN (v_step->>'pipeline_id')::uuid ELSE NULL END,
        CASE WHEN (v_step->>'stage_id') IS NOT NULL AND (v_step->>'stage_id') <> ''
             THEN (v_step->>'stage_id')::uuid ELSE NULL END,
        COALESCE((v_step->>'active')::boolean, true),
        now(),
        now()
      );
    END LOOP;
  END IF;

  -- 5. Return new version
  RETURN jsonb_build_object('version', v_new_version, 'ok', true);
END;
$$;

-- Grants unchanged from original migration
GRANT EXECUTE ON FUNCTION public.save_agent_complete(uuid, jsonb, jsonb, jsonb, uuid)
  TO authenticated;

REVOKE EXECUTE ON FUNCTION public.save_agent_complete(uuid, jsonb, jsonb, jsonb, uuid)
  FROM anon;


-- ---------------------------------------------------------------------------
-- Migration: 20260430250000_ai_agent_stage_trigger.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- AI Agent Stage Trigger
--
-- When a lead enters a pipeline stage, the DB trigger notify_lead_stage_changed
-- previously only fired dispara-webhook (tipo='lead_etapa').
--
-- This migration extends the trigger to also call ai-agent-execute proactively
-- when any ai_agents row has stage_ids containing the new stage AND the lead's
-- person has ai_enabled = true.
--
-- The edge function receives { people_id, stage_trigger: true }, which bypasses
-- the message_buffer requirement and uses loadAgentForStageEntry routing (stage
-- match regardless of channel_types constraint).
-- =============================================================================

CREATE OR REPLACE FUNCTION public.notify_lead_stage_changed()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'extensions'
AS $$
DECLARE
  v_supabase_url TEXT;
  v_service_key  TEXT;
  v_people_id    UUID;
  v_ai_enabled   BOOLEAN;
  v_agent_exists BOOLEAN;
BEGIN
  -- Only fire when stage actually changes (skip if unchanged on UPDATE)
  IF TG_OP = 'UPDATE' AND OLD.leads_stages_id IS NOT DISTINCT FROM NEW.leads_stages_id THEN
    RETURN NEW;
  END IF;

  -- Skip if no stage assigned
  IF NEW.leads_stages_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_key  := current_setting('app.service_role_key', true);

  -- Silently skip if settings not configured
  IF v_supabase_url IS NULL OR v_supabase_url = ''
     OR v_service_key IS NULL OR v_service_key = '' THEN
    RETURN NEW;
  END IF;

  -- 1. Always fire dispara-webhook for lead_etapa events
  PERFORM extensions.http_post(
    url     := v_supabase_url || '/functions/v1/dispara-webhook',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := jsonb_build_object(
      'tipo',    'lead_etapa',
      'lead_id', NEW.id::text
    )
  );

  -- 2. Check if any active ai_agents target this stage
  SELECT EXISTS(
    SELECT 1 FROM public.ai_agents
    WHERE active = true
      AND is_template = false
      AND (
        stage_ids @> ARRAY[NEW.leads_stages_id]
        OR (
          -- also check scalar leads_stages_id (legacy single-stage field)
          leads_stages_id = NEW.leads_stages_id
        )
      )
  ) INTO v_agent_exists;

  IF NOT v_agent_exists THEN
    RETURN NEW;
  END IF;

  -- 3. Get the lead's person and check ai_enabled
  v_people_id := NEW.people_id;

  IF v_people_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT ai_enabled INTO v_ai_enabled
    FROM public.clients_people
    WHERE id = v_people_id;

  IF v_ai_enabled IS NOT TRUE THEN
    RETURN NEW;
  END IF;

  -- 4. Proactively call ai-agent-execute with stage_trigger=true
  PERFORM extensions.http_post(
    url     := v_supabase_url || '/functions/v1/ai-agent-execute',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := jsonb_build_object(
      'people_id',     v_people_id::text,
      'stage_trigger', true
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never block lead updates due to webhook/agent failures
  RETURN NEW;
END;
$$;

-- Trigger is already registered as on_lead_stage_changed — just replace the function.
-- No need to recreate the trigger itself.


-- ---------------------------------------------------------------------------
-- Migration: 20260430260000_fix_save_agent_complete_uuid_guards.sql
-- ---------------------------------------------------------------------------

-- Fix save_agent_complete: guard NULLIF on all UUID fields to prevent
-- "invalid input syntax for type uuid: ''" exceptions when empty strings
-- are passed for optional UUID columns (pipeline_id, leads_stages_id,
-- llm_provider_id, wa_channel_id).

CREATE OR REPLACE FUNCTION public.save_agent_complete(
  p_agent_id   uuid,
  p_agent_data jsonb,
  p_steps_data jsonb DEFAULT NULL,
  p_changelog  jsonb DEFAULT NULL,
  p_created_by uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_current_version int;
  v_new_version     int;
  v_snapshot        jsonb;
  v_step            jsonb;
  v_step_id         uuid;
BEGIN
  -- 1. Lock the agent row and read current state
  SELECT current_version,
         to_jsonb(a) AS snapshot
  INTO   v_current_version, v_snapshot
  FROM   public.ai_agents a
  WHERE  id = p_agent_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'agent not found: %', p_agent_id;
  END IF;

  -- Attach current steps to the snapshot
  v_snapshot := jsonb_set(
    v_snapshot,
    '{steps}',
    COALESCE(
      (SELECT jsonb_agg(to_jsonb(s) ORDER BY s.order_index)
       FROM public.ai_agents_steps s
       WHERE s.ai_agent_id = p_agent_id),
      '[]'::jsonb
    )
  );

  -- 2. Write history entry (state BEFORE the update)
  INSERT INTO public.ai_agents_history
    (ai_agent_id, version, data, changelog, created_by)
  VALUES
    (p_agent_id, v_current_version, v_snapshot, p_changelog, p_created_by);

  -- 3. Update ai_agents
  v_new_version := v_current_version + 1;

  UPDATE public.ai_agents
  SET
    name                = COALESCE((p_agent_data->>'name'),                name),
    description         = COALESCE((p_agent_data->>'description'),         description),
    identity            = COALESCE((p_agent_data->>'identity'),            identity),
    general_rules       = COALESCE((p_agent_data->>'general_rules'),       general_rules),
    input_data          = COALESCE((p_agent_data->>'input_data'),          input_data),
    use_stages          = COALESCE((p_agent_data->>'use_stages')::boolean, use_stages),
    active              = COALESCE((p_agent_data->>'active')::boolean,     active),
    pipeline_id         = CASE WHEN p_agent_data ? 'pipeline_id'
                               THEN NULLIF(p_agent_data->>'pipeline_id', '')::uuid
                               ELSE pipeline_id END,
    pipeline_ids        = CASE WHEN p_agent_data ? 'pipeline_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'pipeline_ids'))::uuid[]
                               ELSE pipeline_ids END,
    leads_stages_id     = CASE WHEN p_agent_data ? 'leads_stages_id'
                               THEN NULLIF(p_agent_data->>'leads_stages_id', '')::uuid
                               ELSE leads_stages_id END,
    score_matrix_ids    = CASE WHEN p_agent_data ? 'score_matrix_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'score_matrix_ids'))::uuid[]
                               ELSE score_matrix_ids END,
    score_allow_empty   = COALESCE((p_agent_data->>'score_allow_empty')::boolean, score_allow_empty),
    score_value         = COALESCE((p_agent_data->>'score_value')::integer,       score_value),
    channel_types       = CASE WHEN p_agent_data ? 'channel_types'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'channel_types'))
                               ELSE channel_types END,
    stage_ids           = CASE WHEN p_agent_data ? 'stage_ids'
                               THEN ARRAY(SELECT jsonb_array_elements_text(p_agent_data->'stage_ids'))::uuid[]
                               ELSE stage_ids END,
    llm_provider        = COALESCE((p_agent_data->>'llm_provider'),        llm_provider),
    llm_model           = COALESCE((p_agent_data->>'llm_model'),           llm_model),
    llm_temperature     = COALESCE((p_agent_data->>'llm_temperature')::numeric,  llm_temperature),
    llm_max_tokens      = COALESCE((p_agent_data->>'llm_max_tokens')::integer,   llm_max_tokens),
    llm_provider_id     = CASE WHEN p_agent_data ? 'llm_provider_id'
                               THEN NULLIF(p_agent_data->>'llm_provider_id', '')::uuid
                               ELSE llm_provider_id END,
    memory_window       = COALESCE((p_agent_data->>'memory_window')::integer,    memory_window),
    wa_phone_number_id  = COALESCE((p_agent_data->>'wa_phone_number_id'),  wa_phone_number_id),
    wa_channel_id       = CASE WHEN p_agent_data ? 'wa_channel_id'
                               THEN NULLIF(p_agent_data->>'wa_channel_id', '')::uuid
                               ELSE wa_channel_id END,
    buffer_ms           = COALESCE((p_agent_data->>'buffer_ms')::integer,  buffer_ms),
    humanizacao         = COALESCE((p_agent_data->>'humanizacao'),         humanizacao),
    agent_type          = COALESCE((p_agent_data->>'agent_type'),          agent_type),
    voice_enabled       = COALESCE((p_agent_data->>'voice_enabled')::boolean,    voice_enabled),
    voice_response_mode = COALESCE((p_agent_data->>'voice_response_mode'), voice_response_mode),
    voice_id            = COALESCE((p_agent_data->>'voice_id'),            voice_id),
    voice_first_message = COALESCE((p_agent_data->>'voice_first_message'), voice_first_message),
    voice_language      = COALESCE((p_agent_data->>'voice_language'),      voice_language),
    voice_model_id      = COALESCE((p_agent_data->>'voice_model_id'),      voice_model_id),
    voice_stability     = COALESCE((p_agent_data->>'voice_stability')::numeric,  voice_stability),
    voice_similarity    = COALESCE((p_agent_data->>'voice_similarity')::numeric, voice_similarity),
    voice_speed         = COALESCE((p_agent_data->>'voice_speed')::numeric,      voice_speed),
    el_sync_status      = COALESCE((p_agent_data->>'el_sync_status'),      el_sync_status),
    current_version     = v_new_version,
    updated_at          = now()
  WHERE id = p_agent_id;

  -- 4. Replace steps (only when caller provides the array)
  IF p_steps_data IS NOT NULL THEN
    DELETE FROM public.ai_agents_steps
    WHERE ai_agent_id = p_agent_id;

    FOR v_step IN SELECT * FROM jsonb_array_elements(p_steps_data)
    LOOP
      v_step_id := CASE
        WHEN v_step ? 'id'
          AND (v_step->>'id') IS NOT NULL
          AND (v_step->>'id') <> ''
        THEN (v_step->>'id')::uuid
        ELSE gen_random_uuid()
      END;

      INSERT INTO public.ai_agents_steps
        (id, ai_agent_id, name, prompt, control, order_index,
         pipeline_id, stage_id, active, created_at, updated_at)
      VALUES (
        v_step_id,
        p_agent_id,
        v_step->>'name',
        COALESCE(v_step->>'prompt', ''),
        NULLIF(v_step->>'control', ''),
        (v_step->>'order_index')::integer,
        CASE WHEN (v_step->>'pipeline_id') IS NOT NULL AND (v_step->>'pipeline_id') <> ''
             THEN (v_step->>'pipeline_id')::uuid ELSE NULL END,
        CASE WHEN (v_step->>'stage_id') IS NOT NULL AND (v_step->>'stage_id') <> ''
             THEN (v_step->>'stage_id')::uuid ELSE NULL END,
        COALESCE((v_step->>'active')::boolean, true),
        now(),
        now()
      );
    END LOOP;
  END IF;

  -- 5. Return new version
  RETURN jsonb_build_object('version', v_new_version, 'ok', true);
END;
$$;

GRANT EXECUTE ON FUNCTION public.save_agent_complete(uuid, jsonb, jsonb, jsonb, uuid)
  TO authenticated;

REVOKE EXECUTE ON FUNCTION public.save_agent_complete(uuid, jsonb, jsonb, jsonb, uuid)
  FROM anon;


-- ---------------------------------------------------------------------------
-- Migration: 20260501100000_fix_leads_status_ativo.sql
-- ---------------------------------------------------------------------------

-- Fix leads.status: normalize 'ativo' → 'in_progress' and ensure default is correct.
-- Complement to p8_leads_status_normalize (20260228) which didn't cover 'ativo'.
-- Safe to run multiple times (idempotent).

BEGIN;

-- Drop constraint first so we can add/normalize values freely
ALTER TABLE public.leads DROP CONSTRAINT IF EXISTS leads_status_check;

-- Normalize remaining non-canonical values
UPDATE public.leads SET status = 'in_progress'
  WHERE status IN ('em-andamento', 'em_andamento', 'aberto', 'ativo');

UPDATE public.leads SET status = 'won'   WHERE status = 'ganho';
UPDATE public.leads SET status = 'lost'  WHERE status = 'perdido';
UPDATE public.leads SET status = 'archived' WHERE status = 'arquivado';

-- Ensure default is canonical
ALTER TABLE public.leads ALTER COLUMN status SET DEFAULT 'in_progress';

-- Re-add CHECK constraint with canonical values
ALTER TABLE public.leads ADD CONSTRAINT leads_status_check
  CHECK (status = ANY (ARRAY[
    'in_progress'::text,
    'won'::text,
    'lost'::text,
    'archived'::text
  ]));

COMMIT;


