-- ---------------------------------------------------------------------------
-- Migration: 20260505080000_remove_prospect_pro.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Remove Prospect PRO™ — drop de todas as tabelas, cron jobs e
-- limpeza de FKs externas / seed de módulo.
--
-- Contexto:
--   Após remoção do módulo do frontend e edge functions, esta migration
--   elimina a infraestrutura de banco do Prospect Pro de forma irreversível.
--
-- Pré-condições já atendidas por migrations anteriores:
--   - prospect_contacts dropada em 20260422000400
--   - prospect_establishments + prospect_people_legacy dropadas em 20260422000600
--   - cron job prospect-lgpd-auto-delete unscheduled em 20260422000600
--   - prospect_people_v2 renomeada para prospect_people em 20260422000500
--
-- Tabelas alvo deste drop:
--   prospect_audit_log
--   prospect_enrichment_results       (FK → prospect_people, prospect_enrichment_plugins)
--   prospect_people                   (FK → prospect_companies, prospect_campaigns)
--   prospect_companies                (FK → prospect_campaigns)
--   prospect_enrichment_plugins
--   prospect_opt_out_registry
--   prospect_campaigns                (root)
--
-- FK externa crítica:
--   clients_people.prospect_campaign_id → prospect_campaigns(id) ON DELETE SET NULL
--   Adicionada em 20260312180000 linha 253. Não cascateia em DROP TABLE,
--   precisa ser removida explicitamente. A coluna é dropada também porque
--   perde semântica sem o módulo Prospect.
--
-- Cron jobs vivos:
--   prospect-stuck-recovery (criado em 20260422000900) — unscheduled aqui.
--   Loop adicional ILIKE '%prospect%' como cinto-e-suspensórios para casos
--   de jobs ad-hoc criados manualmente no Dashboard.
-- ============================================================

BEGIN;

-- 1. Unschedule TODOS os cron jobs com 'prospect' no nome (defensivo)
DO $$
DECLARE
  job_record RECORD;
BEGIN
  IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'pg_cron') THEN
    FOR job_record IN
      SELECT jobname FROM cron.job WHERE jobname ILIKE '%prospect%'
    LOOP
      PERFORM cron.unschedule(job_record.jobname);
      RAISE NOTICE 'Unscheduled cron job: %', job_record.jobname;
    END LOOP;
  END IF;
END $$;

-- 2. Remover FK externa em clients_people antes do DROP de prospect_campaigns
ALTER TABLE public.clients_people
  DROP CONSTRAINT IF EXISTS clients_people_prospect_campaign_id_fkey;

-- 3. Dropar índice associado à coluna prospect_campaign_id em clients_people
DROP INDEX IF EXISTS public.clients_people_prospect_campaign_id_idx;

-- 4. Dropar a coluna clients_people.prospect_campaign_id
--    (perde semântica sem o módulo; mantê-la criaria órfãos)
ALTER TABLE public.clients_people
  DROP COLUMN IF EXISTS prospect_campaign_id;

-- 5. Dropar tabelas Prospect em ordem topológica (folhas primeiro)
--    CASCADE cobre views/triggers eventuais; FKs entre prospect_* já
--    são respeitadas pela ordem.
DROP TABLE IF EXISTS public.prospect_audit_log           CASCADE;
DROP TABLE IF EXISTS public.prospect_enrichment_results  CASCADE;
DROP TABLE IF EXISTS public.prospect_people              CASCADE;
DROP TABLE IF EXISTS public.prospect_companies           CASCADE;
DROP TABLE IF EXISTS public.prospect_enrichment_plugins  CASCADE;
DROP TABLE IF EXISTS public.prospect_opt_out_registry    CASCADE;
DROP TABLE IF EXISTS public.prospect_campaigns           CASCADE;

-- Tabelas já dropadas em migrations anteriores (idempotente):
DROP TABLE IF EXISTS public.prospect_contacts            CASCADE;
DROP TABLE IF EXISTS public.prospect_establishments      CASCADE;
DROP TABLE IF EXISTS public.prospect_people_legacy       CASCADE;
DROP TABLE IF EXISTS public.prospect_people_v2           CASCADE;

-- 6. Remover seed do módulo prospect
DELETE FROM public.settings_system_modules
  WHERE module_key = 'prospect';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260507160901_fix_usr_01_settings_users_rls_writes.sql
-- ---------------------------------------------------------------------------

-- ═══════════════════════════════════════════════════════════════════
-- 20260507160901_fix_usr_01_settings_users_rls_writes.sql
-- FIX-USR-01: Restaura RLS restritivo em writes de settings_users.
--
-- Problema:
--   FWUP-17 (20260428060000) reabriu intencionalmente settings_users com
--   authenticated_write USING (true) para evitar quebra em tenants novos.
--   Isso permite auto-promoção: qualquer usuário autenticado pode rodar
--   UPDATE settings_users SET user_type='admin' via anon-key.
--
-- Solução:
--   - SELECT permanece aberto (UI precisa listar usuários)
--   - INSERT: somente admin (super_admin OR user_type='admin')
--   - UPDATE: dono da linha (auth.uid() = auth_user_id) OU admin
--   - DELETE: somente admin
--   - Função is_admin_or_manager() já existe; criamos is_admin() para distinguir
--
-- Idempotente via DROP IF EXISTS antes de cada CREATE.
-- ═══════════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Função auxiliar is_admin() ───────────────────────────────────
-- Mais restritiva que is_admin_or_manager(): exige admin (não aceita manager).
CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.settings_users
    WHERE auth_user_id = auth.uid()
      AND (super_admin = true OR user_type = 'admin')
      AND active = true
      AND deleted_at IS NULL
  )
$function$;

-- ── 2. Drop policies abertas legadas ────────────────────────────────
DROP POLICY IF EXISTS "authenticated_read"  ON public.settings_users;
DROP POLICY IF EXISTS "authenticated_write" ON public.settings_users;
DROP POLICY IF EXISTS "users_select_policy" ON public.settings_users;
DROP POLICY IF EXISTS "users_insert_policy" ON public.settings_users;
DROP POLICY IF EXISTS "users_update_policy" ON public.settings_users;
DROP POLICY IF EXISTS "users_delete_policy" ON public.settings_users;
DROP POLICY IF EXISTS "Users can read own profile" ON public.settings_users;
DROP POLICY IF EXISTS "Users can update own profile" ON public.settings_users;
DROP POLICY IF EXISTS "Admins can create users" ON public.settings_users;
DROP POLICY IF EXISTS "Admins can delete users" ON public.settings_users;

-- ── 3. SELECT aberto (mantém UX de listas de usuários) ──────────────
CREATE POLICY "settings_users_select_authenticated"
  ON public.settings_users
  FOR SELECT
  TO authenticated
  USING (true);

-- ── 4. INSERT: somente admin ────────────────────────────────────────
CREATE POLICY "settings_users_insert_admin_only"
  ON public.settings_users
  FOR INSERT
  TO authenticated
  WITH CHECK (public.is_admin());

-- ── 5. UPDATE: dono da linha (sem alterar role/status) OU admin ─────
-- Notas:
--   - Postgres avalia USING para a linha existente (pré-update)
--     e WITH CHECK para o estado pós-update.
--   - Bloqueio de auto-promoção: dono pode atualizar a linha, mas
--     se tentar mudar user_type/super_admin/active/deleted_at,
--     o WITH CHECK exige is_admin(). Como is_admin() consulta a tabela
--     (SECURITY DEFINER), funciona sem recursão.
CREATE POLICY "settings_users_update_owner_or_admin"
  ON public.settings_users
  FOR UPDATE
  TO authenticated
  USING (
    public.is_admin()
    OR auth_user_id = auth.uid()
  )
  WITH CHECK (
    public.is_admin()
    OR (
      auth_user_id = auth.uid()
      -- Owner não pode alterar campos sensíveis em si próprio.
      -- A comparação contra OLD não é possível em WITH CHECK; em vez disso,
      -- delegamos a proteção a um trigger BEFORE UPDATE (FIX-USR-03 cuida).
      -- Aqui apenas garantimos que owner não pode setar super_admin=true
      -- nem user_type='admin' (escala de privilégio direta).
      AND super_admin IS NOT TRUE
      AND user_type IS DISTINCT FROM 'admin'
    )
  );

-- ── 6. DELETE: somente admin ────────────────────────────────────────
CREATE POLICY "settings_users_delete_admin_only"
  ON public.settings_users
  FOR DELETE
  TO authenticated
  USING (public.is_admin());

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260507161250_fix_usr_03_settings_users_super_admin_invariant.sql
-- ---------------------------------------------------------------------------

-- ═══════════════════════════════════════════════════════════════════
-- 20260507161250_fix_usr_03_settings_users_super_admin_invariant.sql
-- FIX-USR-03: Trigger garantindo invariante super_admin ↔ user_type='admin'.
--
-- Problema:
--   Sem trigger, é possível existir row com super_admin=true E user_type≠'admin',
--   ou super_admin=false E user_type='admin'. Ambos causam drift entre frontend
--   (que deriva super_adm de user_type) e edge functions (que checam super_admin).
--
-- Solução (sync-on-write):
--   - Se super_admin=true e user_type≠'admin' → força user_type='admin'
--   - Se user_type='admin' e super_admin IS NOT TRUE → força super_admin=true
--   - Demais combinações passam intactas
--   Trigger BEFORE INSERT OR UPDATE; idempotente via DROP IF EXISTS.
-- ═══════════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Função do trigger ────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.settings_users_sync_admin_flag()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.super_admin = true AND (NEW.user_type IS DISTINCT FROM 'admin') THEN
    NEW.user_type := 'admin';
  ELSIF NEW.user_type = 'admin' AND (NEW.super_admin IS NOT TRUE) THEN
    NEW.super_admin := true;
  END IF;
  RETURN NEW;
END;
$function$;

-- ── 2. Backfill: corrigir rows que violam o invariante ─────────────
-- Caso A: super_admin=true e user_type≠'admin' → user_type='admin'
UPDATE public.settings_users
   SET user_type = 'admin'
 WHERE super_admin = true
   AND user_type IS DISTINCT FROM 'admin';

-- Caso B: user_type='admin' e super_admin IS NOT TRUE → super_admin=true
UPDATE public.settings_users
   SET super_admin = true
 WHERE user_type = 'admin'
   AND super_admin IS NOT TRUE;

-- ── 3. Trigger BEFORE INSERT OR UPDATE ─────────────────────────────
DROP TRIGGER IF EXISTS trg_settings_users_sync_admin_flag ON public.settings_users;
CREATE TRIGGER trg_settings_users_sync_admin_flag
  BEFORE INSERT OR UPDATE OF super_admin, user_type
  ON public.settings_users
  FOR EACH ROW
  EXECUTE FUNCTION public.settings_users_sync_admin_flag();

COMMIT;


