    ARRAY['nome','whatsapp','nome_evento'],
    ARRAY['Pedro Lima','5548977777777','Workshop Imóveis 2025'],
    2
  ),
  (
    'Network',
    'Conexões profissionais',
    ARRAY['nome','whatsapp'],
    ARRAY['Maria Souza','5548966666666'],
    3
  )
ON CONFLICT (name) DO NOTHING;

COMMIT;


