  -- ── 1. Lock agent row + read current version and snapshot ───────────────────
  SELECT current_version, to_jsonb(a)
  INTO   v_current_version, v_snapshot
  FROM   public.ai_agents a
  WHERE  id = p_agent_id
  FOR UPDATE;

