-- ---------------------------------------------------------------------------
-- Migration: 20260510210000_webhook_inbound_increment.sql
-- ---------------------------------------------------------------------------

-- wh-02: Increment in inbound_webhooks for create_mode + trigger_config support.
-- Adds two additive columns; no data migration required.
-- create_mode controls dedup/upsert behavior on payload arrival.
-- trigger_config holds optional auto-dispatch config (template, channel, delay).

BEGIN;

-- 1. create_mode: TEXT + CHECK (lighter than enum for single-tenant evolvability)
ALTER TABLE public.inbound_webhooks
  ADD COLUMN IF NOT EXISTS create_mode TEXT NOT NULL DEFAULT 'criar';

ALTER TABLE public.inbound_webhooks
  DROP CONSTRAINT IF EXISTS inbound_webhooks_create_mode_check;

ALTER TABLE public.inbound_webhooks
  ADD CONSTRAINT inbound_webhooks_create_mode_check
  CHECK (create_mode IN ('criar', 'criar_se_nao_existir', 'atualizar_etapa', 'somente_etapa'));

-- 2. trigger_config: JSONB nullable (no default — NULL = no auto-dispatch)
ALTER TABLE public.inbound_webhooks
  ADD COLUMN IF NOT EXISTS trigger_config JSONB;

COMMENT ON COLUMN public.inbound_webhooks.create_mode IS
  'Controla comportamento ao receber payload: criar | criar_se_nao_existir | atualizar_etapa | somente_etapa';

COMMENT ON COLUMN public.inbound_webhooks.trigger_config IS
  'Disparo automatico opcional. JSONB shape: {enabled, template_id, template_name, channel, delay_minutes}. NULL = desabilitado.';

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260511100000_fix_get_active_ai_provider_key_fallback.sql
-- ---------------------------------------------------------------------------

-- Fix get_active_ai_provider_key: fallback to any active provider when no default is set.
-- Behavior: prefer is_default=true, otherwise return the oldest active key.
-- This prevents "gemini_not_configured" errors when the user saved a key without
-- toggling "Padrão para este provedor".

CREATE OR REPLACE FUNCTION public.get_active_ai_provider_key(
  p_provider text
)
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_key text;
BEGIN
  -- Prefer the explicit default; fall back to any active provider for this type.
  SELECT api_key
    INTO v_key
    FROM public.settings_ai_providers
   WHERE provider = p_provider
     AND active   = true
   ORDER BY is_default DESC, created_at ASC
   LIMIT 1;

  RETURN v_key; -- NULL when not configured at all
END;
$$;

REVOKE ALL ON FUNCTION public.get_active_ai_provider_key(text) FROM PUBLIC;
REVOKE ALL ON FUNCTION public.get_active_ai_provider_key(text) FROM anon;
REVOKE ALL ON FUNCTION public.get_active_ai_provider_key(text) FROM authenticated;
GRANT  EXECUTE ON FUNCTION public.get_active_ai_provider_key(text) TO service_role;

COMMENT ON FUNCTION public.get_active_ai_provider_key(text) IS
  'Returns api_key for the provider: prefers is_default=true, falls back to any active row. service_role only.';


-- ---------------------------------------------------------------------------
-- Migration: 20260511110000_fix_insights_context_prospect_guard.sql
-- ---------------------------------------------------------------------------

-- Fix get_insights_context: guard prospect_campaigns table (may not exist in all tenants).
-- Root cause: prospect_campaigns_agg CTE queried the table directly, crashing the whole
-- function with "relation does not exist" on tenants without Prospect PRO installed.
-- Fix: wrap the block in a conditional using pg_class existence check.

CREATE OR REPLACE FUNCTION public.get_insights_context(
  p_date_from timestamptz DEFAULT NULL,
  p_date_to   timestamptz DEFAULT NULL,
  p_pipeline_id uuid DEFAULT NULL
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
AS $$
DECLARE
  result      jsonb := '{}'::jsonb;
  v_funnel    jsonb;
  v_people    jsonb;
  v_messages  jsonb;
  v_meetings  jsonb;
  v_calls     jsonb;
  v_marketing jsonb;
  v_prospect  jsonb;
  v_pipelines jsonb;
  v_has_prospect boolean;
BEGIN

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 0: AVAILABLE PIPELINES (for LLM context)
  -- ═══════════════════════════════════════════════════════════════════════
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id', id, 'name', name)), '[]'::jsonb)
  INTO v_pipelines
  FROM leads_pipelines
  WHERE active = true;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 1: FUNNEL
  -- ═══════════════════════════════════════════════════════════════════════
  WITH lead_base AS (
    SELECT l.id, l.status, l.value, l.leads_stages_id, l.leads_pipelines_id,
           l.leads_loss_reasons_id, l.created_at, l.won_at
    FROM leads l
    WHERE (p_date_from  IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to    IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
  ),
  stages_agg AS (
    SELECT
      ls.name AS stage_name,
      ls.order_index,
      COUNT(lb.id) AS lead_count,
      COALESCE(SUM(lb.value), 0) AS total_value,
      ROUND(AVG(EXTRACT(EPOCH FROM (now() - lb.created_at)) / 86400)::numeric, 1) AS avg_days
    FROM lead_base lb
    JOIN leads_stages ls ON ls.id = lb.leads_stages_id
    WHERE lb.status = 'in_progress'
    GROUP BY ls.name, ls.order_index
    ORDER BY ls.order_index
  ),
  loss_reasons AS (
    SELECT
      COALESCE(lr.name, 'Sem motivo') AS reason,
      COUNT(*) AS cnt
    FROM lead_base lb
    LEFT JOIN leads_loss_reasons lr ON lr.id = lb.leads_loss_reasons_id
    WHERE lb.status = 'lost'
    GROUP BY lr.name
    ORDER BY cnt DESC
    LIMIT 5
  ),
  funnel_totals AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'won')         AS won,
      COUNT(*) FILTER (WHERE status = 'lost')        AS lost,
      COUNT(*) FILTER (WHERE status = 'in_progress') AS active,
      COALESCE(SUM(value) FILTER (WHERE status = 'won'), 0) AS revenue,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - created_at)) / 86400)
             FILTER (WHERE status = 'won' AND won_at IS NOT NULL))::numeric, 1) AS avg_cycle_days
    FROM lead_base
  )
  SELECT jsonb_build_object(
    'total',           ft.total,
    'won',             ft.won,
    'lost',            ft.lost,
    'active',          ft.active,
    'revenue',         ft.revenue,
    'avg_deal',        CASE WHEN ft.won > 0 THEN ROUND((ft.revenue / ft.won)::numeric, 2) ELSE 0 END,
    'conversion_pct',  CASE WHEN ft.total > 0 THEN ROUND((ft.won::numeric / ft.total * 100), 1) ELSE 0 END,
    'avg_cycle_days',  COALESCE(ft.avg_cycle_days, 0),
    'stages',          COALESCE((SELECT jsonb_agg(jsonb_build_object(
                         'name', s.stage_name, 'leads', s.lead_count,
                         'value', s.total_value, 'avg_days', s.avg_days
                       ) ORDER BY s.order_index) FROM stages_agg s), '[]'::jsonb),
    'loss_reasons',    COALESCE((SELECT jsonb_agg(jsonb_build_object(
                         'reason', r.reason, 'count', r.cnt
                       )) FROM loss_reasons r), '[]'::jsonb)
  ) INTO v_funnel
  FROM funnel_totals ft;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 2: PEOPLE & COMPANIES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH people_stats AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE status = 'ativo')  AS active,
      COUNT(*) FILTER (WHERE status != 'ativo') AS inactive,
      COUNT(*) FILTER (WHERE score BETWEEN 0  AND 25)  AS score_0_25,
      COUNT(*) FILTER (WHERE score BETWEEN 26 AND 50)  AS score_26_50,
      COUNT(*) FILTER (WHERE score BETWEEN 51 AND 75)  AS score_51_75,
      COUNT(*) FILTER (WHERE score BETWEEN 76 AND 100) AS score_76_100
    FROM clients_people
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  top_sources AS (
    SELECT source, COUNT(*) AS cnt
    FROM clients_people
    WHERE source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY source
    ORDER BY cnt DESC
    LIMIT 5
  ),
  company_stats AS (
    SELECT COUNT(*) AS total, COUNT(*) AS active FROM clients_companies
  )
  SELECT jsonb_build_object(
    'people_total',    ps.total,
    'people_active',   ps.active,
    'people_inactive', ps.inactive,
    'score_distribution', jsonb_build_object(
      '0_25', ps.score_0_25, '26_50', ps.score_26_50,
      '51_75', ps.score_51_75, '76_100', ps.score_76_100
    ),
    'top_sources',      COALESCE((SELECT jsonb_agg(jsonb_build_object('source', ts.source, 'count', ts.cnt)) FROM top_sources ts), '[]'::jsonb),
    'companies_total',  cs.total,
    'companies_active', cs.active
  ) INTO v_people
  FROM people_stats ps, company_stats cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 3: MESSAGES
  -- ═══════════════════════════════════════════════════════════════════════
  WITH msg_base AS (
    SELECT id, channel, from_contact, created_at, lead_id
    FROM messages
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  by_channel AS (
    SELECT channel, COUNT(*) AS cnt FROM msg_base GROUP BY channel ORDER BY cnt DESC
  ),
  by_sender AS (
    SELECT from_contact, COUNT(*) AS cnt FROM msg_base GROUP BY from_contact
  ),
  daily_trend AS (
    SELECT created_at::date AS day, COUNT(*) AS cnt
    FROM msg_base
    WHERE created_at >= (COALESCE(p_date_to, now()) - interval '7 days')
    GROUP BY day ORDER BY day
  ),
  abandoned AS (
    SELECT COUNT(DISTINCT lead_id) AS cnt
    FROM (
      SELECT lead_id, from_contact, created_at,
             LEAD(from_contact) OVER (PARTITION BY lead_id ORDER BY created_at) AS next_sender,
             LEAD(created_at)   OVER (PARTITION BY lead_id ORDER BY created_at) AS next_at
      FROM msg_base
    ) sub
    WHERE from_contact = 'cliente'
      AND (next_sender IS NULL OR (next_sender != 'cliente' AND next_at - created_at > interval '24 hours'))
  )
  SELECT jsonb_build_object(
    'total',                   (SELECT COUNT(*) FROM msg_base),
    'by_channel',              COALESCE((SELECT jsonb_agg(jsonb_build_object('channel', c.channel, 'count', c.cnt)) FROM by_channel c), '[]'::jsonb),
    'by_sender',               COALESCE((SELECT jsonb_agg(jsonb_build_object('sender', s.from_contact, 'count', s.cnt)) FROM by_sender s), '[]'::jsonb),
    'daily_trend',             COALESCE((SELECT jsonb_agg(jsonb_build_object('day', d.day, 'count', d.cnt)) FROM daily_trend d), '[]'::jsonb),
    'abandoned_conversations', ab.cnt
  ) INTO v_messages
  FROM abandoned ab;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 4: MEETINGS
  -- ═══════════════════════════════════════════════════════════════════════
  WITH mtg_base AS (
    SELECT m.id, m.status, m.start_time, m.user_id, m.lead_id,
           l.created_at AS lead_created, l.won_at,
           l.utm_campaign, l.utm_source
    FROM meetings m
    LEFT JOIN leads l ON l.id = m.lead_id
    WHERE (p_date_from IS NULL OR m.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR m.created_at <= p_date_to)
      AND (m.source IS NULL OR m.source != 'google')
  ),
  by_status AS (
    SELECT status, COUNT(*) AS cnt FROM mtg_base GROUP BY status
  ),
  show_rate_by_user AS (
    SELECT
      COALESCE(su.name, 'Sem responsável') AS closer_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE mb.status IN ('compareceu', 'realizado')) AS attended,
      CASE WHEN COUNT(*) > 0
        THEN ROUND((COUNT(*) FILTER (WHERE mb.status IN ('compareceu', 'realizado')))::numeric / COUNT(*) * 100, 1)
        ELSE 0 END AS show_rate
    FROM mtg_base mb
    LEFT JOIN settings_users su ON su.id = mb.user_id
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 5
  ),
  time_metrics AS (
    SELECT
      ROUND(AVG(EXTRACT(EPOCH FROM (start_time - lead_created)) / 86400)::numeric, 1) AS avg_lead_to_meeting,
      ROUND((AVG(EXTRACT(EPOCH FROM (won_at - start_time)) / 86400) FILTER (WHERE won_at IS NOT NULL))::numeric, 1) AS avg_meeting_to_close
    FROM mtg_base
    WHERE lead_created IS NOT NULL
  ),
  meetings_by_campaign AS (
    SELECT
      COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha') AS campaign,
      COUNT(DISTINCT l.id) AS leads,
      COUNT(DISTINCT m2.id) AS meetings,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('compareceu', 'realizado')) AS attended,
      COUNT(DISTINCT m2.id) FILTER (WHERE m2.status IN ('nao_compareceu', 'não compareceu', 'cancelado', 'cancelada')) AS no_show,
      COUNT(DISTINCT l.id) FILTER (WHERE l.status = 'won') AS won
    FROM leads l
    LEFT JOIN meetings m2 ON m2.lead_id = l.id AND (m2.source IS NULL OR m2.source != 'google')
    WHERE (l.utm_source IS NOT NULL OR l.utm_campaign IS NOT NULL)
      AND (p_date_from IS NULL OR l.created_at >= p_date_from)
      AND (p_date_to   IS NULL OR l.created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR l.leads_pipelines_id = p_pipeline_id)
    GROUP BY COALESCE(l.utm_campaign, l.utm_source, 'Sem campanha')
    ORDER BY leads DESC
    LIMIT 10
  )
  SELECT jsonb_build_object(
    'total',                    (SELECT COUNT(*) FROM mtg_base),
    'by_status',                COALESCE((SELECT jsonb_agg(jsonb_build_object('status', bs.status, 'count', bs.cnt)) FROM by_status bs), '[]'::jsonb),
    'show_rate_by_closer',      COALESCE((SELECT jsonb_agg(jsonb_build_object(
                                  'name', sr.closer_name, 'total', sr.total,
                                  'attended', sr.attended, 'show_rate', sr.show_rate
                                )) FROM show_rate_by_user sr), '[]'::jsonb),
    'avg_lead_to_meeting_days', COALESCE(tm.avg_lead_to_meeting, 0),
    'avg_meeting_to_close_days',COALESCE(tm.avg_meeting_to_close, 0),
    'by_campaign',              COALESCE((SELECT jsonb_agg(jsonb_build_object(
                                  'campaign', mc.campaign, 'leads', mc.leads, 'meetings', mc.meetings,
                                  'attended', mc.attended, 'no_show', mc.no_show, 'won', mc.won
                                )) FROM meetings_by_campaign mc), '[]'::jsonb)
  ) INTO v_meetings
  FROM time_metrics tm;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 5: CALLS
  -- ═══════════════════════════════════════════════════════════════════════
  WITH call_base AS (
    SELECT id, direction, status, duration, user_id, outcome, tags
    FROM call_pro_calls
    WHERE (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  call_summary AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE direction = 'inbound')  AS inbound,
      COUNT(*) FILTER (WHERE direction = 'outbound') AS outbound,
      COUNT(*) FILTER (WHERE status IN ('answered', 'handled')) AS answered,
      ROUND((AVG(duration) FILTER (WHERE duration > 0))::numeric, 0) AS avg_duration_sec
    FROM call_base
  ),
  top_operators AS (
    SELECT
      COALESCE(su.name, 'Desconhecido') AS operator_name,
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE cb.status IN ('answered', 'handled')) AS answered
    FROM call_base cb
    LEFT JOIN settings_users su ON su.id = cb.user_id
    WHERE cb.user_id IS NOT NULL
    GROUP BY su.name
    ORDER BY total DESC
    LIMIT 3
  ),
  top_outcomes AS (
    SELECT outcome, COUNT(*) AS cnt
    FROM call_base
    WHERE outcome IS NOT NULL AND outcome != ''
    GROUP BY outcome
    ORDER BY cnt DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'total',           cs.total,
    'inbound',         cs.inbound,
    'outbound',        cs.outbound,
    'answered',        cs.answered,
    'answer_rate',     CASE WHEN cs.total > 0 THEN ROUND((cs.answered::numeric / cs.total * 100), 1) ELSE 0 END,
    'avg_duration_sec',COALESCE(cs.avg_duration_sec, 0),
    'top_operators',   COALESCE((SELECT jsonb_agg(jsonb_build_object(
                         'name', op.operator_name, 'total', op.total, 'answered', op.answered
                       )) FROM top_operators op), '[]'::jsonb),
    'top_outcomes',    COALESCE((SELECT jsonb_agg(jsonb_build_object(
                         'outcome', o.outcome, 'count', o.cnt
                       )) FROM top_outcomes o), '[]'::jsonb)
  ) INTO v_calls
  FROM call_summary cs;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 6: MARKETING
  -- ═══════════════════════════════════════════════════════════════════════
  WITH sends_summary AS (
    SELECT
      COUNT(*) AS total_sends,
      SUM(total_contacts)  AS total_contacts,
      SUM(sent_count)      AS total_sent,
      SUM(delivered_count) AS total_delivered,
      SUM(read_count)      AS total_read
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
  ),
  sends_by_channel AS (
    SELECT channel, COUNT(*) AS cnt,
           SUM(sent_count) AS sent, SUM(delivered_count) AS delivered, SUM(read_count) AS read_cnt
    FROM sends
    WHERE status IN ('completed', 'running')
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
    GROUP BY channel
  ),
  lp_stats AS (
    SELECT f.name AS page_name, COUNT(s.id) AS submissions
    FROM form_pro_forms f
    LEFT JOIN form_pro_submissions s ON s.form_id = f.id
      AND (p_date_from IS NULL OR s.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR s.submitted_at <= p_date_to)
    GROUP BY f.name
    ORDER BY submissions DESC
    LIMIT 5
  ),
  utm_stats AS (
    SELECT
      COALESCE(utm_source, 'direto') AS source,
      COALESCE(utm_medium, 'none')   AS medium,
      COUNT(*) AS leads,
      COUNT(*) FILTER (WHERE status = 'won') AS won
    FROM leads
    WHERE utm_source IS NOT NULL
      AND (p_date_from IS NULL OR created_at >= p_date_from)
      AND (p_date_to   IS NULL OR created_at <= p_date_to)
      AND (p_pipeline_id IS NULL OR leads_pipelines_id = p_pipeline_id)
    GROUP BY utm_source, utm_medium
    ORDER BY leads DESC
    LIMIT 5
  ),
  meta_forms_stats AS (
    SELECT mf.name AS form_name, COUNT(DISTINCT l.id) AS leads_count
    FROM meta_lead_forms mf
    LEFT JOIN form_pro_submissions fps ON fps.meta_form_id = mf.id
      AND (p_date_from IS NULL OR fps.submitted_at >= p_date_from)
      AND (p_date_to   IS NULL OR fps.submitted_at <= p_date_to)
    LEFT JOIN leads l ON l.id = fps.lead_id
    WHERE mf.status = 'active'
    GROUP BY mf.name
    ORDER BY leads_count DESC
    LIMIT 5
  )
  SELECT jsonb_build_object(
    'sends', jsonb_build_object(
      'total_campaigns', ss.total_sends,
      'total_sent',      COALESCE(ss.total_sent, 0),
      'total_delivered', COALESCE(ss.total_delivered, 0),
      'total_read',      COALESCE(ss.total_read, 0),
      'delivery_rate',   CASE WHEN COALESCE(ss.total_sent, 0) > 0
                           THEN ROUND((COALESCE(ss.total_delivered, 0)::numeric / ss.total_sent * 100), 1) ELSE 0 END,
      'read_rate',       CASE WHEN COALESCE(ss.total_delivered, 0) > 0
                           THEN ROUND((COALESCE(ss.total_read, 0)::numeric / ss.total_delivered * 100), 1) ELSE 0 END,
      'by_channel',      COALESCE((SELECT jsonb_agg(jsonb_build_object(
                           'channel', sc.channel, 'campaigns', sc.cnt,
                           'sent', sc.sent, 'delivered', sc.delivered, 'read', sc.read_cnt
                         )) FROM sends_by_channel sc), '[]'::jsonb)
    ),
    'landing_pages',    COALESCE((SELECT jsonb_agg(jsonb_build_object(
                          'form', lps.page_name, 'submissions', lps.submissions
                        )) FROM lp_stats lps WHERE lps.submissions > 0), '[]'::jsonb),
    'utm_attribution',  COALESCE((SELECT jsonb_agg(jsonb_build_object(
                          'source', u.source, 'medium', u.medium, 'leads', u.leads, 'won', u.won
                        )) FROM utm_stats u), '[]'::jsonb),
    'meta_forms',       COALESCE((SELECT jsonb_agg(jsonb_build_object(
                          'form', mfs.form_name, 'leads', mfs.leads_count
                        )) FROM meta_forms_stats mfs), '[]'::jsonb)
  ) INTO v_marketing
  FROM sends_summary ss;

  -- ═══════════════════════════════════════════════════════════════════════
  -- BLOCK 7: PROSPECT PRO (guarded — table may not exist)
  -- ═══════════════════════════════════════════════════════════════════════
  SELECT EXISTS (
    SELECT 1 FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE c.relname = 'prospect_campaigns' AND n.nspname = 'public'
  ) INTO v_has_prospect;

  IF v_has_prospect THEN
    EXECUTE $prospect$
      WITH prospect_campaigns_agg AS (
        SELECT
          COUNT(*) AS total,
          COUNT(*) FILTER (WHERE status = 'running')   AS running,
          COUNT(*) FILTER (WHERE status = 'completed') AS completed
        FROM prospect_campaigns
        WHERE ($1 IS NULL OR created_at >= $1)
          AND ($2 IS NULL OR created_at <= $2)
      ),
      prospect_contacts_agg AS (
        SELECT 0 AS total, 0 AS raw_cnt, 0 AS filtered_cnt,
               0 AS enriched_cnt, 0 AS approved_cnt, 0 AS rejected_cnt,
               0 AS avg_ai_score
      )
      SELECT jsonb_build_object(
        'campaigns_total',     pca.total,
        'campaigns_running',   pca.running,
        'campaigns_completed', pca.completed,
        'contacts_total',      pcta.total,
        'contacts_by_status',  jsonb_build_object(
          'raw', pcta.raw_cnt, 'filtered', pcta.filtered_cnt,
          'enriched', pcta.enriched_cnt, 'approved', pcta.approved_cnt, 'rejected', pcta.rejected_cnt
        ),
        'avg_ai_score',  COALESCE(pcta.avg_ai_score, 0),
        'approval_rate', 0
      ) FROM prospect_campaigns_agg pca, prospect_contacts_agg pcta
    $prospect$ INTO v_prospect USING p_date_from, p_date_to;
  ELSE
    v_prospect := jsonb_build_object(
      'campaigns_total', 0, 'campaigns_running', 0, 'campaigns_completed', 0,
      'contacts_total', 0, 'avg_ai_score', 0, 'approval_rate', 0,
      'installed', false
    );
  END IF;

  -- ═══════════════════════════════════════════════════════════════════════
  -- ASSEMBLE
  -- ═══════════════════════════════════════════════════════════════════════
  result := jsonb_build_object(
    'pipelines', COALESCE(v_pipelines, '[]'::jsonb),
    'funnel',    COALESCE(v_funnel,    '{}'::jsonb),
    'people',    COALESCE(v_people,    '{}'::jsonb),
    'messages',  COALESCE(v_messages,  '{}'::jsonb),
    'meetings',  COALESCE(v_meetings,  '{}'::jsonb),
    'calls',     COALESCE(v_calls,     '{}'::jsonb),
    'marketing', COALESCE(v_marketing, '{}'::jsonb),
    'prospect',  COALESCE(v_prospect,  '{}'::jsonb)
  );

  RETURN result;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO authenticated;
GRANT EXECUTE ON FUNCTION public.get_insights_context(timestamptz, timestamptz, uuid) TO service_role;


-- ---------------------------------------------------------------------------
-- Migration: 20260527130000_pipe_2_1_lead_field_curso.sql
-- ---------------------------------------------------------------------------

-- ═══════════════════════════════════════════════════════════════════
-- 20260527130000_pipe_2_1_lead_field_curso.sql
-- Brief: Cria definição global do custom field "Curso" em lead_field_definitions
--        (entity_type=pessoa) para uso por webhooks por curso (Story PIPE-2.1).
--
-- Por que entity_type='pessoa':
--   A RPC upsert_crm_field_value (chamada por crm-mapper.persistCustomFields no
--   edge function webhook-inbound) é hardcoded para entity_type='pessoa'.
--   Custom fields enviados via webhook (namespace custom.*) sempre persistem como
--   atributo da pessoa, não do negócio. Mantemos consistência com q1..q26.
--
-- Idempotente: ON CONFLICT DO NOTHING preserva estado humano se a row já existir.
-- ═══════════════════════════════════════════════════════════════════

BEGIN;

-- O unique constraint canônico em lead_field_definitions é:
--   idx_lead_field_definitions_key_entity_pipeline (key, entity_type, pipeline_id)
-- com NULLS NOT DISTINCT — então NULL=NULL para fins de unicidade.
-- Criado em 20260224001000_unify_field_tables-ok.sql linha 47-48.
INSERT INTO public.lead_field_definitions (
  key,
  name,
  type,
  category,
  entity_type,
  pipeline_id,
  options,
  required,
  active,
  agent_managed,
  order_index
)
VALUES (
  'curso',
  'Curso',
  'text',                -- decisão do lead (2026-05-27): text, não single_select
  'qualificacao',
  'pessoa',
  NULL,                  -- global (cross-pipeline)
  '[]'::jsonb,           -- não usado por type=text — fica como array vazio por consistência de schema
  false,
  true,
  false,
  100                    -- ordem alta para aparecer no final da seção qualificação
)
ON CONFLICT (key, entity_type, pipeline_id) DO NOTHING;

-- Verificação informacional (não falha a migration se a row pré-existia com config diferente)
DO $$
DECLARE
  v_count int;
BEGIN
  SELECT count(*) INTO v_count
  FROM public.lead_field_definitions
  WHERE key = 'curso'
    AND entity_type = 'pessoa'
    AND pipeline_id IS NULL;

  IF v_count = 0 THEN
    RAISE EXCEPTION 'PIPE-2.1: row curso/pessoa não foi criada — verificar constraint ou conflito';
  ELSE
    RAISE NOTICE 'PIPE-2.1: lead_field_definitions(curso/pessoa) presente — total rows: %', v_count;
  END IF;
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260527140000_pipe_3_1_dedup_constraints.sql
-- ---------------------------------------------------------------------------

-- ═══════════════════════════════════════════════════════════════════
-- 20260527140000_pipe_3_1_dedup_constraints.sql
-- Brief: Story PIPE-3.1 — adiciona UNIQUE partial indexes para fechar gaps de dedup
--        em leads/clients_people/form_pro_submissions + muda default de
--        inbound_webhooks.create_mode para 'criar_se_nao_existir'.
--
-- Pre-flight check: aborta a migration se duplicatas existirem hoje, com
-- mensagem orientativa para o operador (executar merge_persons antes).
--
-- Diagnóstico: docs/smart-memory/agents/research/dedup-analysis.md
-- ═══════════════════════════════════════════════════════════════════
-- @lint-skip MIG002 reason: adiciona constraints + change default; rollback documentado.

BEGIN;

-- ═══════════════════════════════════════════════════════════════════
-- 0) PRE-FLIGHT CHECK — aborta se duplicatas existirem
-- ═══════════════════════════════════════════════════════════════════
DO $$
DECLARE
  v_dup_email      int;
  v_dup_whatsapp   int;
  v_dup_leads      int;
  v_dup_meta       int;
  v_msg            text;
BEGIN
  -- clients_people.email duplicado entre rows ativas/inativas/archived (não-merged)
  SELECT count(*) INTO v_dup_email FROM (
    SELECT email
    FROM public.clients_people
    WHERE email IS NOT NULL
      AND status <> 'merged'
    GROUP BY email
    HAVING count(*) > 1
  ) s;

  -- clients_people.whatsapp duplicado
  SELECT count(*) INTO v_dup_whatsapp FROM (
    SELECT whatsapp
    FROM public.clients_people
    WHERE whatsapp IS NOT NULL
      AND status <> 'merged'
    GROUP BY whatsapp
    HAVING count(*) > 1
  ) s;

  -- leads (people_id, leads_pipelines_id) duplicado entre status NÃO finais
  SELECT count(*) INTO v_dup_leads FROM (
    SELECT people_id, leads_pipelines_id
    FROM public.leads
    WHERE people_id IS NOT NULL
      AND leads_pipelines_id IS NOT NULL
      AND status NOT IN ('won','lost','archived')
    GROUP BY people_id, leads_pipelines_id
    HAVING count(*) > 1
  ) s;

  -- form_pro_submissions.meta_leadgen_id duplicado
  SELECT count(*) INTO v_dup_meta FROM (
    SELECT meta_leadgen_id
    FROM public.form_pro_submissions
    WHERE meta_leadgen_id IS NOT NULL
    GROUP BY meta_leadgen_id
    HAVING count(*) > 1
  ) s;

  IF v_dup_email > 0 OR v_dup_whatsapp > 0 OR v_dup_leads > 0 OR v_dup_meta > 0 THEN
    v_msg := format(
      E'PIPE-3.1 migration ABORTED — duplicates pre-existing:\n'
      '  - clients_people.email duplicates:         % distinct keys\n'
      '  - clients_people.whatsapp duplicates:      % distinct keys\n'
      '  - leads(people_id, pipeline_id) actives:   % distinct keys\n'
      '  - form_pro_submissions.meta_leadgen_id:    % distinct keys\n'
      'Action: review the queries in docs/smart-memory/agents/research/dedup-analysis.md\n'
      '        run public.merge_persons(canonical_id, duplicate_id) for each pair, then retry.',
      v_dup_email, v_dup_whatsapp, v_dup_leads, v_dup_meta
    );
    RAISE EXCEPTION '%', v_msg;
  ELSE
    RAISE NOTICE 'PIPE-3.1: pre-flight OK — 0 duplicates';
  END IF;
END $$;

-- ═══════════════════════════════════════════════════════════════════
-- 1) UNIQUE partial em clients_people.email
-- ═══════════════════════════════════════════════════════════════════
-- Já existe idx_people_email (LOWER, non-unique) para performance.
-- Esse índice abaixo é case-sensitive para casar com crm-mapper.upsertPerson
-- (que faz .eq('email', value) sem LOWER).
CREATE UNIQUE INDEX IF NOT EXISTS idx_clients_people_email_unique
  ON public.clients_people (email)
  WHERE email IS NOT NULL AND status <> 'merged';

COMMENT ON INDEX public.idx_clients_people_email_unique IS
  'PIPE-3.1: dedup duro de email (case-sensitive — casa com crm-mapper.upsertPerson). Exclui merged.';

-- ═══════════════════════════════════════════════════════════════════
-- 2) UNIQUE partial em clients_people.whatsapp
-- ═══════════════════════════════════════════════════════════════════
-- crm-mapper.normalizePhone já normaliza para "55..." sem caracteres não-digit.
CREATE UNIQUE INDEX IF NOT EXISTS idx_clients_people_whatsapp_unique
  ON public.clients_people (whatsapp)
  WHERE whatsapp IS NOT NULL AND status <> 'merged';

COMMENT ON INDEX public.idx_clients_people_whatsapp_unique IS
  'PIPE-3.1: dedup duro de whatsapp normalizado. Exclui merged.';

-- ═══════════════════════════════════════════════════════════════════
-- 3) UNIQUE partial em leads (people_id, leads_pipelines_id) — apenas leads ativos
-- ═══════════════════════════════════════════════════════════════════
-- Status canônicos: 'in_progress'|'won'|'lost'|'archived' (p8/fix_leads_status_ativo).
-- Permite múltiplos leads finalizados (won/lost/archived) por (pessoa, pipeline) —
-- semântica: pessoa pode voltar ao pipeline depois de fechar/perder negócio anterior.
CREATE UNIQUE INDEX IF NOT EXISTS idx_leads_people_pipeline_active_unique
  ON public.leads (people_id, leads_pipelines_id)
  WHERE people_id IS NOT NULL
    AND leads_pipelines_id IS NOT NULL
    AND status NOT IN ('won', 'lost', 'archived');

COMMENT ON INDEX public.idx_leads_people_pipeline_active_unique IS
  'PIPE-3.1: dedup de leads "abertos" (status NOT IN won/lost/archived). Permite reentrada após fechamento.';

-- ═══════════════════════════════════════════════════════════════════
-- 4) UNIQUE partial em form_pro_submissions.meta_leadgen_id
-- ═══════════════════════════════════════════════════════════════════
-- Garante que cada Meta leadgen_id seja importado uma única vez,
-- mesmo em race entre chamadas paralelas de meta-leadgen-sync.
CREATE UNIQUE INDEX IF NOT EXISTS idx_form_pro_submissions_meta_leadgen_unique
  ON public.form_pro_submissions (meta_leadgen_id)
  WHERE meta_leadgen_id IS NOT NULL;

COMMENT ON INDEX public.idx_form_pro_submissions_meta_leadgen_unique IS
  'PIPE-3.1: dedup duro de Meta leadgen_id (race-safe import).';

-- ═══════════════════════════════════════════════════════════════════
-- 5) Default de inbound_webhooks.create_mode → 'criar_se_nao_existir'
-- ═══════════════════════════════════════════════════════════════════
-- Razão: a queixa "leads duplicados" é majoritariamente consequência de webhooks
-- criados pela UI sem revisar o create_mode (que era 'criar' por default e força
-- INSERT de novo lead a cada hit, ignorando dedup de pipeline).
--
-- NÃO faz backfill — rows existentes preservam o estado configurado (mesmo que
-- via default antigo). Operador re-edita pela UI se desejar. Motivo: distinguir
-- "default automático" de "escolha consciente do operador" é impossível e o backfill
-- poderia trocar comportamento de webhooks intencionais.
ALTER TABLE public.inbound_webhooks
  ALTER COLUMN create_mode SET DEFAULT 'criar_se_nao_existir';

COMMENT ON COLUMN public.inbound_webhooks.create_mode IS
  'Controla comportamento ao receber payload: criar | criar_se_nao_existir | atualizar_etapa | somente_etapa. Default (PIPE-3.1): criar_se_nao_existir.';

-- ═══════════════════════════════════════════════════════════════════
-- 6) Verificação final (informacional)
-- ═══════════════════════════════════════════════════════════════════
DO $$
DECLARE
  v_indexes_created int;
  v_default text;
BEGIN
  SELECT count(*) INTO v_indexes_created
  FROM pg_indexes
  WHERE indexname IN (
    'idx_clients_people_email_unique',
    'idx_clients_people_whatsapp_unique',
    'idx_leads_people_pipeline_active_unique',
    'idx_form_pro_submissions_meta_leadgen_unique'
  );

  SELECT column_default INTO v_default
  FROM information_schema.columns
  WHERE table_schema='public'
    AND table_name='inbound_webhooks'
    AND column_name='create_mode';

  IF v_indexes_created < 4 THEN
    RAISE EXCEPTION 'PIPE-3.1 verification failed: only %/4 unique indexes created', v_indexes_created;
  END IF;

  IF v_default NOT LIKE '%criar_se_nao_existir%' THEN
    RAISE EXCEPTION 'PIPE-3.1 verification failed: create_mode default is %, expected criar_se_nao_existir', v_default;
  END IF;

  RAISE NOTICE 'PIPE-3.1 verified OK — 4 unique indexes + create_mode default updated';
END $$;

COMMIT;


