-- ---------------------------------------------------------------------------
-- Migration: 20260610000003_whatsapp_template_sync_cron.sql
-- ---------------------------------------------------------------------------

-- WAT-SYNC-02: Auto-sync WhatsApp templates via pg_cron every 5 minutes.
--
-- Adds last_synced_at tracking and schedules a cron job that invokes the
-- whatsapp-templates-sync edge function through the project's existing
-- secure_http_post() helper (reads the service-role JWT from Vault — never
-- hardcoded). The edge function accepts that service-role JWT on the
-- Authorization header as a cron bypass for its normal user-JWT auth.
--
-- PREREQUISITE (manual, one-time): a Vault secret named 'service_role_cron'
-- holding the project's service_role JWT must exist. If it is absent, the
-- cron job is skipped and a NOTICE is emitted — the migration still succeeds.

BEGIN;

-- ── 1. last_synced_at column ────────────────────────────────────────────────
ALTER TABLE public.whatsapp_templates
  ADD COLUMN IF NOT EXISTS last_synced_at timestamptz;

-- ── 2. Required extensions ──────────────────────────────────────────────────
CREATE EXTENSION IF NOT EXISTS pg_net;
CREATE EXTENSION IF NOT EXISTS pg_cron;

-- ── 3. Schedule the auto-sync cron job ──────────────────────────────────────
DO $$
DECLARE
  v_has_secret boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM vault.secrets WHERE name = 'service_role_cron'
  ) INTO v_has_secret;

  IF NOT v_has_secret THEN
    RAISE NOTICE 'Vault secret service_role_cron not found — skipping whatsapp_templates_auto_sync cron. Add the secret and re-run this migration.';
    RETURN;
  END IF;

  -- Remove any prior registration so re-running is idempotent.
  PERFORM cron.unschedule(jobid)
  FROM cron.job
  WHERE jobname = 'whatsapp_templates_auto_sync';

  PERFORM cron.schedule(
    'whatsapp_templates_auto_sync',
    '*/5 * * * *',
    $cron$
    SELECT public.secure_http_post(
      'service_role_cron',
      'https://wotuyxscsfralqpoiyfv.supabase.co/functions/v1/whatsapp-templates-sync',
      '{"channel_id": "eced709d-a50c-44aa-a844-b787119f9e1b"}'::jsonb,
      'whatsapp-templates-auto-sync-cron'
    );
    $cron$
  );
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260610100000_fwup34_repair_message_type_check_private_reply_email.sql
-- ---------------------------------------------------------------------------

-- =============================================================================
-- FWUP-34: Repair messages_message_type_check — restore 'private_reply' + 'email'
-- =============================================================================
-- Root cause:
--   Migrations 20260430190000 (private_reply) and 20260430200000 (private_reply +
--   email) are recorded in supabase_migrations.schema_migrations as applied, but
--   the LIVE constraint contains neither value (drift from the "db push broken"
--   workflow — version stamped without the ALTER TABLE actually executing).
--
-- Symptoms (both Instagram + email manual send):
--   • Private reply to a commenter (Conversas.tsx -> tipo_mensagem='private_reply')
--     fails with: new row for relation "messages" violates check constraint
--     "messages_message_type_check". omni-delivery-engine routes 'private_reply'
--     to instagram-comment-reply (/private_replies — comment_id bypass, no IGSID
--     and no 7-day window needed), so the row MUST be insertable.
--   • Email send (tipo_mensagem='email') fails the same way.
--
-- Fix:
--   Re-assert the canonical constraint from 20260430200000 (strict superset of the
--   live 11 values). Idempotent: DROP IF EXISTS + ADD. Only widens the allowed set,
--   so no existing row can violate it.
-- =============================================================================

ALTER TABLE public.messages DROP CONSTRAINT IF EXISTS messages_message_type_check;
ALTER TABLE public.messages
  ADD CONSTRAINT messages_message_type_check
  CHECK (message_type = ANY (ARRAY[
    'texto'::text,
    'audio'::text,
    'imagem'::text,
    'video'::text,
    'documento'::text,
    'chamada'::text,
    'comentario'::text,
    'story_reply'::text,
    'story_mention'::text,
    'reply_comentario'::text,
    'arquivo'::text,
    'private_reply'::text,
    'email'::text
  ]));

DO $$
BEGIN
  RAISE NOTICE 'FWUP-34: messages_message_type_check repaired — private_reply + email restored';
END $$;


-- ---------------------------------------------------------------------------
-- Migration: 20260611220000_process_buffer_pass_lock_preacquired-ok.sql
-- ---------------------------------------------------------------------------

-- FIX-AGENT-DUP-03: process_message_buffer() pré-adquire ai_processing_lock antes de
-- chamar ai-agent-execute. Agora sinaliza isso no body com lock_preacquired=true para
-- que a function pule o CAS lock inline (senão veria o lock já em true e abortaria com
-- lock_not_acquired → toda execução via cron ficaria muda).
-- Corpo idêntico ao de 20260308015000_process_buffer_timeout-ok.sql; muda só o body do http_post.
-- Sem DDL, sem novas colunas, timeout continua 30000.

CREATE OR REPLACE FUNCTION process_message_buffer()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  rec           record;
  supabase_url  text;
  svc_key       text;
BEGIN
  SELECT value INTO supabase_url FROM _app_config WHERE key = 'supabase_url';
  SELECT value INTO svc_key      FROM _app_config WHERE key = 'service_role_key';

  IF supabase_url IS NULL OR supabase_url = '' OR svc_key IS NULL OR svc_key = '' THEN
    RAISE NOTICE 'process_message_buffer: _app_config incompleta.';
    RETURN;
  END IF;

  FOR rec IN
    SELECT DISTINCT ON (mb.people_id) mb.people_id
    FROM   message_buffer mb
    JOIN   clients_people cp ON cp.id = mb.people_id
    WHERE  mb.processed          = false
      AND  mb.expires_at         < now()
      AND  cp.ai_processing_lock = false
      AND  cp.ai_enabled         = true
    ORDER BY mb.people_id, mb.created_at DESC
  LOOP
    UPDATE clients_people
      SET ai_processing_lock = true
      WHERE id = rec.people_id
        AND ai_processing_lock = false;

    IF FOUND THEN
      PERFORM net.http_post(
        url                  := supabase_url || '/functions/v1/ai-agent-execute',
        headers              := jsonb_build_object(
          'Content-Type',  'application/json',
          'Authorization', 'Bearer ' || svc_key
        ),
        body                 := jsonb_build_object('people_id', rec.people_id, 'lock_preacquired', true),
        timeout_milliseconds := 30000
      );
    END IF;
  END LOOP;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260611230000_fix_custom_field_defs_entity_type-ok.sql
-- ---------------------------------------------------------------------------

-- FIX-CAMPOS-EXTRAS-01: pipeline-scoped qualification fields were created with
-- entity_type='pessoa', but CamposExtrasSection + useLeadFieldDefinitions filter
-- exclusively on entity_type='negocio'. These fields (objetivo, interesse_area,
-- perfil_tipo, nivel_tecnico, momento) qualify the lead/deal — not a generic person
-- record — so 'negocio' is the semantically correct entity type.
-- Existing lead_field_values were already saved as entity_type='negocio' (old code
-- hardcoded it), so no values migration is needed.

UPDATE lead_field_definitions
SET    entity_type = 'negocio',
       updated_at  = now()
WHERE  entity_type = 'pessoa'
  AND  key IN (
    'objetivo',
    'interesse_area',
    'perfil_tipo',
    'nivel_tecnico',
    'momento',
    'conversation_summary',
    'curso'
  );


-- ---------------------------------------------------------------------------
-- Migration: 20260612000000_revert_field_defs_restore_pessoa_migrate_values-ok.sql
-- ---------------------------------------------------------------------------

-- FIX-CAMPOS-EXTRAS-02: revert entity_type change from 20260611230000.
-- Fields objetivo, interesse_area, perfil_tipo, nivel_tecnico, momento,
-- conversation_summary, curso belong to entity_type='pessoa' by design —
-- ExtraFieldsCard renders entity_type='pessoa' fields, CamposExtrasSection
-- renders entity_type='negocio' fields. The prior migration incorrectly
-- flattened both into 'negocio'.
--
-- Step 1: restore entity_type='pessoa' on the field definitions.
-- Step 2: move any values that were incorrectly persisted as entity_type='negocio'
--         for these fields into the correct (entity_type='pessoa', entity_id=pessoa_id) row.
-- Step 3: delete the orphaned entity_type='negocio' rows for those fields.

-- ── Step 1: restore definitions ───────────────────────────────────────────────

UPDATE lead_field_definitions
SET    entity_type = 'pessoa',
       updated_at  = now()
WHERE  key IN (
  'objetivo', 'interesse_area', 'perfil_tipo',
  'nivel_tecnico', 'momento',
  'conversation_summary', 'curso'
);

-- ── Step 2: copy misplaced negocio values → pessoa ───────────────────────────
-- entity_id for negocio rows = leads.id; we resolve leads.people_id to get the
-- correct pessoa entity_id.

INSERT INTO lead_field_values (
  entity_type, entity_id, field_definition_id,
  value_text, value_number, value_boolean, value_date,
  updated_at
)
SELECT
  'pessoa',
  l.people_id,
  lfv.field_definition_id,
  lfv.value_text,
  lfv.value_number,
  lfv.value_boolean,
  lfv.value_date,
  now()
FROM lead_field_values lfv
JOIN leads               l  ON l.id  = lfv.entity_id
JOIN lead_field_definitions lfd ON lfd.id = lfv.field_definition_id
WHERE lfv.entity_type = 'negocio'
  AND lfd.key IN (
    'objetivo', 'interesse_area', 'perfil_tipo',
    'nivel_tecnico', 'momento',
    'conversation_summary', 'curso'
  )
  AND l.people_id IS NOT NULL
ON CONFLICT (entity_type, entity_id, field_definition_id)
DO UPDATE SET
  value_text    = EXCLUDED.value_text,
  value_number  = EXCLUDED.value_number,
  value_boolean = EXCLUDED.value_boolean,
  value_date    = EXCLUDED.value_date,
  updated_at    = now();

-- ── Step 3: delete orphaned negocio rows ─────────────────────────────────────

DELETE FROM lead_field_values
WHERE  entity_type = 'negocio'
  AND  field_definition_id IN (
    SELECT id FROM lead_field_definitions
    WHERE  key IN (
      'objetivo', 'interesse_area', 'perfil_tipo',
      'nivel_tecnico', 'momento',
      'conversation_summary', 'curso'
    )
  );


-- ---------------------------------------------------------------------------
-- Migration: 20260612003000_whatsapp_template_sync_cron_20min.sql
-- ---------------------------------------------------------------------------

-- FIX-WA-TEMPLATE-SYNC-CRON-401 — corrige o cron de auto-sync de templates WhatsApp.
--
-- ROOT CAUSE REAL (a hipótese original de "Vault service_role_cron defasado" estava
-- ERRADA): o Vault secret `service_role_cron` É a service_role key legacy correta
-- (passa o gateway). O 401 vinha da PRÓPRIA função: ela autorizava o cron via
-- `bearer === SUPABASE_SERVICE_ROLE_KEY` (string match), mas após a migração do
-- projeto para o novo sistema de API keys (rotação em 2026-06-12 00:11 UTC) o
-- `SUPABASE_SERVICE_ROLE_KEY` injetado no runtime da função deixou de bater
-- byte-a-byte com o JWT legacy guardado no Vault. Resultado: cron 401 em 100%.
--
-- FIX (no código da edge function, fora desta migration — ver
-- supabase/functions/whatsapp-templates-sync/index.ts): a função passa a tratar
-- como cron QUALQUER Bearer que o gateway já validou como JWT `role=service_role`
-- (decodifica o payload), em vez de exigir igualdade literal com a key volátil.
-- À prova de rotação. Deploy: `supabase functions deploy whatsapp-templates-sync
-- --no-verify-jwt`.
--
-- Esta migration cobre apenas a parte SQL: reduzir a frequência do cron de */5
-- para */20 (decisão do usuário, 2026-06-12). Idempotente — cron.schedule faz
-- upsert por jobname.

BEGIN;

DO $$
DECLARE
  v_has_secret boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM vault.secrets WHERE name = 'service_role_cron'
  ) INTO v_has_secret;

  IF NOT v_has_secret THEN
    RAISE NOTICE 'Vault secret service_role_cron not found — skipping whatsapp_templates_auto_sync cron reschedule.';
    RETURN;
  END IF;

  PERFORM cron.schedule(
    'whatsapp_templates_auto_sync',
    '*/20 * * * *',
    $cron$
    SELECT public.secure_http_post(
      'service_role_cron',
      'https://wotuyxscsfralqpoiyfv.supabase.co/functions/v1/whatsapp-templates-sync',
      '{"channel_id": "eced709d-a50c-44aa-a844-b787119f9e1b"}'::jsonb,
      'whatsapp-templates-auto-sync-cron'
    );
    $cron$
  );
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260612010000_agendar_gcal_freebusy.sql
-- ---------------------------------------------------------------------------

-- FEAT-AGENDAR-GCAL-FREEBUSY-01 — /agendar respeita o Google Calendar externo dos consultores.
-- Parte SQL: (1) get_booking_session expõe o pool real de candidatos por slot;
--            (2) book_meeting aceita p_exclude_user_ids (não atribui a quem está ocupado no GCal).
-- A lógica de freebusy vive na edge function booking-availability (availability + confirm).
-- Aplicado LIVE via db query (db push quebrado) + snapshots em backups/2026-06-12_*.
-- @no-rollback reason: backfill de estado já LIVE e estável (CREATE OR REPLACE idempotente em get_booking_session/book_meeting); reverter exigiria restaurar defs anteriores a partir dos snapshots em backups/2026-06-12_*, fora de escopo.
BEGIN;

-- FEAT-AGENDAR-GCAL-FREEBUSY-01 — get_booking_session: user_ids = pool real de candidatos
-- Mudança vs FIX-AGENDAR-PAGE-01 v2:
--   * A janela de horários continua vindo de settings_schedules dos elegíveis (igual).
--   * Mas o slot agora aparece se ≥1 consultor ELEGÍVEL+ATIVO estiver livre na agenda
--     interna naquele horário (não só o dono do horário) — alinhado ao book_meeting,
--     que distribui a reunião entre TODOS os elegíveis por load-balance.
--   * Cada slot expõe user_ids = exatamente esse pool de candidatos, para a edge
--     function `booking-availability` subtrair o Google Calendar externo por consultor.
CREATE OR REPLACE FUNCTION public.get_booking_session(p_lead_id uuid, p_rule_set_id uuid DEFAULT NULL::uuid, p_duration integer DEFAULT 30, p_days_ahead integer DEFAULT 14)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_first_name text;
  v_user_ids uuid[];
  v_slots json;
  v_existing public.meetings%ROWTYPE;
  v_existing_consultor_name text;
BEGIN
  SELECT split_part(COALESCE(cp.name, 'Cliente'), ' ', 1)
    INTO v_first_name
    FROM public.leads l
    LEFT JOIN public.clients_people cp ON cp.id = l.people_id
    WHERE l.id = p_lead_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'Lead not found'); END IF;

  -- #3 — reunião ativa futura já marcada para este lead → retorna sem gerar slots
  SELECT m.* INTO v_existing
    FROM public.meetings m
    WHERE m.lead_id = p_lead_id
      AND m.status NOT IN ('cancelado', 'cancelada')
      AND m.end_time > NOW()
    ORDER BY m.start_time ASC
    LIMIT 1;
  IF FOUND THEN
    SELECT su.name INTO v_existing_consultor_name
      FROM public.settings_users su WHERE su.id = v_existing.user_id;
    RETURN json_build_object(
      'person', json_build_object('name', v_first_name),
      'slots', '[]'::json,
      'existing_meeting', json_build_object(
        'meeting_id', v_existing.id::text,
        'start_time', to_char(v_existing.start_time AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD"T"HH24:MI:SS'),
        'end_time',   to_char(v_existing.end_time   AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD"T"HH24:MI:SS'),
        'consultor', json_build_object(
          'id', v_existing.user_id::text,
          'name', v_existing_consultor_name
        )
      )
    );
  END IF;

  v_user_ids := public.get_booking_eligible_user_ids(p_rule_set_id);
  IF v_user_ids IS NULL OR array_length(v_user_ids, 1) IS NULL THEN
    RETURN json_build_object('error', 'Nenhum consultor disponível no momento');
  END IF;

  SELECT json_agg(json_build_object('date', slot_date, 'start_time', start_time, 'end_time', end_time, 'user_ids', user_ids) ORDER BY slot_date, start_time)
    INTO v_slots
    FROM (
      SELECT g.slot_date, g.start_time, g.end_time,
        ( SELECT json_agg(DISTINCT su.id)
            FROM public.settings_users su
            WHERE su.id = ANY(v_user_ids)
              AND su.active = true
              AND NOT EXISTS (
                SELECT 1 FROM public.meetings m
                WHERE m.user_id = su.id
                  AND m.start_time < g.ts_end::timestamptz
                  AND m.end_time   > g.ts_start::timestamptz
                  AND m.status NOT IN ('cancelado', 'cancelada')
              )
        ) AS user_ids
      FROM (
        -- janela de horários: distinct times dos horários de trabalho dos elegíveis, só futuros
        SELECT DISTINCT slot_date, start_time, end_time, ts_start, ts_end
        FROM (
          SELECT
            TO_CHAR(dr.d, 'YYYY-MM-DD') AS slot_date,
            TO_CHAR(ss.start_time::time + (n.n * INTERVAL '30 minutes'), 'HH24:MI') AS start_time,
            TO_CHAR(ss.start_time::time + (n.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute'), 'HH24:MI') AS end_time,
            dr.d + (ss.start_time::time + (n.n * INTERVAL '30 minutes')) AS ts_start,
            dr.d + (ss.start_time::time + (n.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute')) AS ts_end
          FROM (SELECT (CURRENT_DATE + s.n)::date AS d FROM generate_series(0, p_days_ahead - 1) AS s(n)) AS dr
          CROSS JOIN (SELECT unnest(v_user_ids) AS id) AS cand
          INNER JOIN public.settings_users su ON su.id = cand.id AND su.active = true
          INNER JOIN public.settings_schedules ss ON ss.user_id = su.id AND ss.day_of_week = EXTRACT(DOW FROM dr.d)::int AND ss.is_available = true
          CROSS JOIN LATERAL (
            SELECT s2.n FROM generate_series(0, GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (ss.end_time::time - ss.start_time::time)) / 1800)::int - 1)) AS s2(n)
            WHERE ss.start_time::time + (s2.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute') <= ss.end_time::time
          ) AS n
        ) AS raw_slots
        WHERE raw_slots.ts_start > (NOW() AT TIME ZONE 'America/Sao_Paulo')
      ) AS g
    ) AS grouped
    WHERE user_ids IS NOT NULL;  -- só aparece se ≥1 consultor elegível livre na agenda interna

  RETURN json_build_object(
    'person', json_build_object('name', v_first_name),
    'slots', COALESCE(v_slots, '[]'::json)
  );
END;
$function$;

-- FEAT-AGENDAR-GCAL-FREEBUSY-01 — book_meeting: aceita p_exclude_user_ids
-- Base: book_meeting LIVE (FIX-AGENDAR-PAGE-01, com guard + move "Reunião Marcada").
-- Mudança única: novo param p_exclude_user_ids uuid[] DEFAULT '{}'. Consultores nessa
--   lista são REMOVIDOS da atribuição (specific_user E load-balance). A edge function
--   `booking-availability` (action=confirm) passa aí os consultores ocupados no Google
--   Calendar externo no horário escolhido → o book_meeting não atribui a reunião a quem
--   está ocupado no GCal. Backward-compatible: chamada sem o param ('{}') = comportamento
--   anterior (não exclui ninguém).
-- Drop da assinatura antiga (6 args) p/ evitar overload + ambiguidade no PostgREST.
DROP FUNCTION IF EXISTS public.book_meeting(uuid, timestamp with time zone, timestamp with time zone, uuid, integer, text);
CREATE OR REPLACE FUNCTION public.book_meeting(p_lead_id uuid, p_start_time timestamp with time zone, p_end_time timestamp with time zone, p_rule_set_id uuid DEFAULT NULL::uuid, p_duration integer DEFAULT 30, p_notes text DEFAULT NULL::text, p_exclude_user_ids uuid[] DEFAULT '{}'::uuid[])
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id       uuid;
  v_user_name     text;
  v_meeting_id    uuid;
  v_title         text;
  v_people_id     uuid;
  v_eligible_ids  uuid[];
BEGIN
  -- #3 backstop — bloqueia duplo agendamento caso o frontend seja burlado.
  IF EXISTS (
    SELECT 1 FROM public.meetings m
    WHERE m.lead_id = p_lead_id
      AND m.status NOT IN ('cancelado', 'cancelada')
      AND m.end_time > NOW()
  ) THEN
    RETURN json_build_object('error', 'already_booked');
  END IF;

  v_eligible_ids := public.get_booking_eligible_user_ids(p_rule_set_id);

  IF v_eligible_ids IS NULL OR array_length(v_eligible_ids, 1) IS NULL THEN
    RETURN json_build_object('error', 'Nenhum consultor disponível');
  END IF;

  -- Resolve people_id from lead
  SELECT people_id INTO v_people_id FROM public.leads WHERE id = p_lead_id;

  IF p_rule_set_id IS NOT NULL THEN
    SELECT su.id, su.name
    INTO v_user_id, v_user_name
    FROM public.booking_rules br
    INNER JOIN public.settings_users su
      ON su.id = (br.config->>'user_id')::uuid
      AND su.active = true
      AND su.id = ANY(v_eligible_ids)
      AND su.id <> ALL(p_exclude_user_ids)            -- GCal: pula quem está ocupado externamente
    WHERE br.rule_set_id = p_rule_set_id
      AND br.rule_type   = 'specific_user'
      AND br.is_active   = true
      AND NOT EXISTS (
        SELECT 1 FROM public.meetings m
        WHERE m.user_id    = su.id
          AND m.start_time < p_end_time
          AND m.end_time   > p_start_time
          AND m.status NOT IN ('cancelado', 'cancelada')
      )
    ORDER BY br.order_index ASC
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    SELECT su.id, su.name
    INTO v_user_id, v_user_name
    FROM public.settings_users su
    WHERE su.id = ANY(v_eligible_ids)
      AND su.active = true
      AND su.id <> ALL(p_exclude_user_ids)            -- GCal: pula quem está ocupado externamente
      AND NOT EXISTS (
        SELECT 1 FROM public.meetings m
        WHERE m.user_id    = su.id
          AND m.start_time < p_end_time
          AND m.end_time   > p_start_time
          AND m.status NOT IN ('cancelado', 'cancelada')
      )
    ORDER BY
      (SELECT COUNT(*) FROM public.meetings m2
       WHERE m2.user_id    = su.id
         AND m2.start_time >= NOW()
         AND m2.status NOT IN ('cancelado', 'cancelada')
      ) ASC,
      COALESCE((
        SELECT MAX(m3.created_at) FROM public.meetings m3
        WHERE m3.user_id = su.id
      ), '1970-01-01'::timestamptz) ASC
    LIMIT 1;
  END IF;

  IF v_user_id IS NULL THEN
    RETURN json_build_object('error', 'Horário não disponível — escolha outro horário');
  END IF;

  v_title := 'Reunião agendada — ' ||
    TO_CHAR(p_start_time AT TIME ZONE 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI');

  INSERT INTO public.meetings (
    lead_id, people_id, user_id, title, start_time, end_time, status, notes, source
  )
  VALUES (
    p_lead_id, v_people_id, v_user_id, v_title,
    p_start_time, p_end_time,
    'agendado', p_notes, 'public_booking'
  )
  RETURNING id INTO v_meeting_id;

  -- Avança o lead para "Reunião Marcada" do pipeline ATUAL dele (curso ou mentoria).
  UPDATE public.leads l
  SET leads_stages_id = rm.id
  FROM public.leads_stages rm
  WHERE l.id = p_lead_id
    AND rm.leads_pipelines_id = l.leads_pipelines_id
    AND rm.name = 'Reunião Marcada'
    AND rm.active = true;

  RETURN json_build_object(
    'meeting_id', v_meeting_id::text,
    'consultor', json_build_object(
      'id',   v_user_id::text,
      'name', v_user_name
    )
  );
END;
$function$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260612160000_agenda_gcal_03_email_capture.sql
-- ---------------------------------------------------------------------------

-- AGENDA-GCAL-03 — captura segura do email do lead no /agendar (público/anônimo).
-- DOIS writes, sem migration de schema (clients_people.email já existe):
--   1) RPC set_booking_lead_email(p_lead_id, p_email) SECURITY DEFINER — escopada ao lead
--      do link (NUNCA people_id arbitrário = anti-IDOR), valida formato, não sobrescreve
--      email pré-existente. anon-callable (mesmo modelo de book_meeting/get_booking_session).
--   2) get_booking_session expõe person.has_email:boolean (sem expor o email — privacidade),
--      para o /agendar saber quando exibir o input de email. Backward-compatible.
-- Aplicado LIVE via db query (db push quebrado) + registro manual em schema_migrations.
-- Snapshot da def anterior de get_booking_session: backups/get_booking_session-PRE-AGENDA-GCAL-03-*.json
BEGIN;

-- ── (1) RPC set_booking_lead_email ────────────────────────────────────────────
CREATE OR REPLACE FUNCTION public.set_booking_lead_email(p_lead_id uuid, p_email text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_people_id uuid;
  v_existing  text;
  v_clean     text;
BEGIN
  v_clean := lower(btrim(p_email));
  -- validação de formato server-side (a coluna não tem CHECK; rejeita lixo)
  IF v_clean IS NULL OR v_clean !~ '^[^@\s]+@[^@\s]+\.[^@\s]+$' THEN
    RETURN json_build_object('error', 'invalid_email');
  END IF;

  -- escopo anti-IDOR: a pessoa é a do LEAD do link, nunca um people_id arbitrário
  SELECT people_id INTO v_people_id FROM public.leads WHERE id = p_lead_id;
  IF v_people_id IS NULL THEN
    RETURN json_build_object('error', 'lead_not_found');
  END IF;

  SELECT email INTO v_existing FROM public.clients_people WHERE id = v_people_id;
  -- não sobrescreve email válido pré-existente (anti-vazamento). '' conta como vazio.
  IF v_existing IS NOT NULL AND btrim(v_existing) <> '' THEN
    RETURN json_build_object('ok', true, 'skipped', 'already_has_email');
  END IF;

  UPDATE public.clients_people SET email = v_clean, updated_at = NOW() WHERE id = v_people_id;
  RETURN json_build_object('ok', true, 'people_id', v_people_id::text);
END;
$function$;

GRANT EXECUTE ON FUNCTION public.set_booking_lead_email(uuid, text) TO anon, authenticated, service_role;

-- ── (2) get_booking_session — adiciona person.has_email (booleano) ────────────
-- Base = def LIVE da migration 20260612010000. Única mudança: captura v_has_email no
-- SELECT inicial e o adiciona ao objeto `person` nos DOIS RETURN (existing_meeting + slots).
CREATE OR REPLACE FUNCTION public.get_booking_session(p_lead_id uuid, p_rule_set_id uuid DEFAULT NULL::uuid, p_duration integer DEFAULT 30, p_days_ahead integer DEFAULT 14)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_first_name text;
  v_has_email  boolean;
  v_user_ids uuid[];
  v_slots json;
  v_existing public.meetings%ROWTYPE;
  v_existing_consultor_name text;
BEGIN
  SELECT split_part(COALESCE(cp.name, 'Cliente'), ' ', 1),
         (cp.email IS NOT NULL AND btrim(cp.email) <> '')
    INTO v_first_name, v_has_email
    FROM public.leads l
    LEFT JOIN public.clients_people cp ON cp.id = l.people_id
    WHERE l.id = p_lead_id;
  IF NOT FOUND THEN RETURN json_build_object('error', 'Lead not found'); END IF;
  v_has_email := COALESCE(v_has_email, false);

  -- #3 — reunião ativa futura já marcada para este lead → retorna sem gerar slots
  SELECT m.* INTO v_existing
    FROM public.meetings m
    WHERE m.lead_id = p_lead_id
      AND m.status NOT IN ('cancelado', 'cancelada')
      AND m.end_time > NOW()
    ORDER BY m.start_time ASC
    LIMIT 1;
  IF FOUND THEN
    SELECT su.name INTO v_existing_consultor_name
      FROM public.settings_users su WHERE su.id = v_existing.user_id;
    RETURN json_build_object(
      'person', json_build_object('name', v_first_name, 'has_email', v_has_email),
      'slots', '[]'::json,
      'existing_meeting', json_build_object(
        'meeting_id', v_existing.id::text,
        'start_time', to_char(v_existing.start_time AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD"T"HH24:MI:SS'),
        'end_time',   to_char(v_existing.end_time   AT TIME ZONE 'America/Sao_Paulo', 'YYYY-MM-DD"T"HH24:MI:SS'),
        'consultor', json_build_object(
          'id', v_existing.user_id::text,
          'name', v_existing_consultor_name
        )
      )
    );
  END IF;

  v_user_ids := public.get_booking_eligible_user_ids(p_rule_set_id);
  IF v_user_ids IS NULL OR array_length(v_user_ids, 1) IS NULL THEN
    RETURN json_build_object('error', 'Nenhum consultor disponível no momento');
  END IF;

  SELECT json_agg(json_build_object('date', slot_date, 'start_time', start_time, 'end_time', end_time, 'user_ids', user_ids) ORDER BY slot_date, start_time)
    INTO v_slots
    FROM (
      SELECT g.slot_date, g.start_time, g.end_time,
        ( SELECT json_agg(DISTINCT su.id)
            FROM public.settings_users su
            WHERE su.id = ANY(v_user_ids)
              AND su.active = true
              AND NOT EXISTS (
                SELECT 1 FROM public.meetings m
                WHERE m.user_id = su.id
                  AND m.start_time < g.ts_end::timestamptz
                  AND m.end_time   > g.ts_start::timestamptz
                  AND m.status NOT IN ('cancelado', 'cancelada')
              )
        ) AS user_ids
      FROM (
        SELECT DISTINCT slot_date, start_time, end_time, ts_start, ts_end
        FROM (
          SELECT
            TO_CHAR(dr.d, 'YYYY-MM-DD') AS slot_date,
            TO_CHAR(ss.start_time::time + (n.n * INTERVAL '30 minutes'), 'HH24:MI') AS start_time,
            TO_CHAR(ss.start_time::time + (n.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute'), 'HH24:MI') AS end_time,
            dr.d + (ss.start_time::time + (n.n * INTERVAL '30 minutes')) AS ts_start,
            dr.d + (ss.start_time::time + (n.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute')) AS ts_end
          FROM (SELECT (CURRENT_DATE + s.n)::date AS d FROM generate_series(0, p_days_ahead - 1) AS s(n)) AS dr
          CROSS JOIN (SELECT unnest(v_user_ids) AS id) AS cand
          INNER JOIN public.settings_users su ON su.id = cand.id AND su.active = true
          INNER JOIN public.settings_schedules ss ON ss.user_id = su.id AND ss.day_of_week = EXTRACT(DOW FROM dr.d)::int AND ss.is_available = true
          CROSS JOIN LATERAL (
            SELECT s2.n FROM generate_series(0, GREATEST(0, FLOOR(EXTRACT(EPOCH FROM (ss.end_time::time - ss.start_time::time)) / 1800)::int - 1)) AS s2(n)
            WHERE ss.start_time::time + (s2.n * INTERVAL '30 minutes') + (p_duration * INTERVAL '1 minute') <= ss.end_time::time
          ) AS n
        ) AS raw_slots
        WHERE raw_slots.ts_start > (NOW() AT TIME ZONE 'America/Sao_Paulo')
      ) AS g
    ) AS grouped
    WHERE user_ids IS NOT NULL;

  RETURN json_build_object(
    'person', json_build_object('name', v_first_name, 'has_email', v_has_email),
    'slots', COALESCE(v_slots, '[]'::json)
  );
END;
$function$;

COMMIT;


