-- ---------------------------------------------------------------------------
-- Migration: 20260616000001_fix_meetings_followups_rls.sql
-- ---------------------------------------------------------------------------

-- Fix: meet_fup_write WITH CHECK had a self-referential subquery bug
-- Original WITH CHECK queried meetings_followups from within its own policy → infinite recursion (42P17)
-- and/or returned all rows → "more than one row returned by a subquery" on every UPDATE.
-- Fix: remove the source subquery entirely. The source column is enforced by:
--   1. CHECK constraint (source IN ('webhook','channel'))
--   2. Frontend never sends source in the UPDATE payload

DROP POLICY IF EXISTS meet_fup_write ON public.meetings_followups;

CREATE POLICY meet_fup_write ON public.meetings_followups
  FOR ALL TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = ANY (ARRAY['admin'::text, 'manager'::text]))
        AND active = true
        AND deleted_at IS NULL
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM settings_users
      WHERE auth_user_id = auth.uid()
        AND (super_admin = true OR user_type = ANY (ARRAY['admin'::text, 'manager'::text]))
        AND active = true
        AND deleted_at IS NULL
    )
  );


-- ---------------------------------------------------------------------------
-- Migration: 20260618000000_stage_followup_wa_bridge.sql
-- ---------------------------------------------------------------------------

-- Stage → Followup → WA bridge
--
-- 1. Update notify_lead_stage_changed to auto-cancel stale stage followups
--    and call followup-enqueue when a lead enters a new stage.
-- 2. Add "Entrar no WhatsApp" stage to all active pipelines so operators
--    can configure a whatsapp_template followup on it via UI.

-- ── 1. Update trigger function ────────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.notify_lead_stage_changed()
  RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_supabase_url TEXT;
  v_service_key  TEXT;
BEGIN
  -- Only fire when stage actually changes
  IF TG_OP = 'UPDATE' AND OLD.leads_stages_id IS NOT DISTINCT FROM NEW.leads_stages_id THEN
    RETURN NEW;
  END IF;

  IF NEW.leads_stages_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Always cancel pending stage followups from prior stage (no settings needed)
  UPDATE public.followup_queue
  SET status        = 'cancelled',
      fired_at      = now(),
      error_message = 'Cancelado: lead mudou de etapa'
  WHERE lead_id     = NEW.id
    AND status      = 'pending'
    AND source_type = 'stage';

  v_supabase_url := current_setting('app.supabase_url', true);
  v_service_key  := current_setting('app.service_role_key', true);

  IF v_supabase_url IS NULL OR v_supabase_url = ''
     OR v_service_key IS NULL OR v_service_key = '' THEN
    RETURN NEW;
  END IF;

  -- Fire dispara-webhook (lead_etapa event for N8N / webhooks)
  PERFORM extensions.http_post(
    url     := v_supabase_url || '/functions/v1/dispara-webhook',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := jsonb_build_object(
      'tipo',    'lead_etapa',
      'lead_id', NEW.id::text
    )
  );

  -- Enqueue stage followups for the new stage
  PERFORM extensions.http_post(
    url     := v_supabase_url || '/functions/v1/followup-enqueue',
    headers := jsonb_build_object(
      'Content-Type',  'application/json',
      'Authorization', 'Bearer ' || v_service_key
    ),
    body    := jsonb_build_object(
      'lead_id',     NEW.id::text,
      'stage_id',    NEW.leads_stages_id::text,
      'source_type', 'stage'
    )
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never block lead updates due to webhook/enqueue failures
  RETURN NEW;
END;
$function$;

-- ── 2. Add "Entrar no WhatsApp" stage to each active pipeline ─────────────────
--    Idempotent: skips if a stage with this name already exists in the pipeline.

DO $$
DECLARE
  r RECORD;
  v_max_order INT;
BEGIN
  FOR r IN
    SELECT id, name FROM public.leads_pipelines WHERE active = true ORDER BY name
  LOOP
    -- Skip if stage already exists
    IF EXISTS (
      SELECT 1 FROM public.leads_stages
      WHERE leads_pipelines_id = r.id AND name = 'Entrar no WhatsApp' AND active = true
    ) THEN
      RAISE NOTICE 'Pipeline "%": stage "Entrar no WhatsApp" já existe, pulando.', r.name;
      CONTINUE;
    END IF;

    -- Find next order_index
    SELECT COALESCE(MAX(order_index), 0) + 1
      INTO v_max_order
      FROM public.leads_stages
     WHERE leads_pipelines_id = r.id;

    INSERT INTO public.leads_stages (
      leads_pipelines_id,
      name,
      color,
      order_index,
      active
    ) VALUES (
      r.id,
      'Entrar no WhatsApp',
      '#25D366',
      v_max_order,
      true
    );

    RAISE NOTICE 'Pipeline "%": stage "Entrar no WhatsApp" criado (order_index=%).', r.name, v_max_order;
  END LOOP;
END;
$$;


-- ---------------------------------------------------------------------------
-- Migration: 20260619000000_instagram_automation_comment_dedup.sql
-- ---------------------------------------------------------------------------

-- ============================================================
-- Instagram comment automation — one reply per comment
-- ============================================================
-- A single Instagram comment can match MULTIPLE active automations. Each one
-- independently posted a public comment reply AND tried to DM the commenter.
-- Meta allows many public replies but only ONE DM per comment, so the result was:
-- two+ different public replies ("Mandei", "Mandei lá") plus a string of
-- "comment already has a reply — DM skipped (Meta 2534023)" log entries.
-- Webhook retries (Meta re-delivers on slow ACK) compounded it, but the core
-- cause is several automations acting on the same comment.
--
-- Fix: exactly one automation may act per comment (highest priority wins).
-- This unique partial index — keyed on ig_message_id alone for post_comment rows —
-- lets the runner claim a comment atomically with INSERT ... ON CONFLICT DO NOTHING
-- before any automation executes. Subsequent automations and webhook retries
-- conflict on the index and skip without sending anything.

-- Collapse pre-existing duplicate post_comment rows (created by the bug) so the
-- unique index can be built. Keep the earliest-executed row per comment.
DELETE FROM public.instagram_automation_log a
USING public.instagram_automation_log b
WHERE a.trigger_type = 'post_comment'
  AND b.trigger_type = 'post_comment'
  AND a.ig_message_id IS NOT DISTINCT FROM b.ig_message_id
  AND a.ig_message_id IS NOT NULL
  AND (a.executed_at, a.id) > (b.executed_at, b.id);

CREATE UNIQUE INDEX IF NOT EXISTS instagram_automation_log_comment_claim_idx
  ON public.instagram_automation_log (ig_message_id)
  WHERE trigger_type = 'post_comment';


