-- ---------------------------------------------------------------------------
-- Migration: 20260702130000_kiwify_rls_manager_fix.sql
-- ---------------------------------------------------------------------------

-- KFY-1.1 FIX: correct RLS WRITE policy predicate on the 5 Kiwify tables.
--
-- Bug: 20260702120000 used `user_type = 'gestor'` in the `kiwify_write_managers`
-- policies, but the live domain is CHECK (user_type IN ('admin','manager','user')).
-- 'gestor' never matches → only super_admin could write outside service-role.
-- Fix (additive, not a rollback): recreate the 5 write policies with 'manager'.
--
-- Live-verified (2026-07-02, wotuyxscsfralqpoiyfv): settings_users.user_type is text,
-- CHECK IN ('admin','manager','user'); actual values present: admin, manager.
--
-- Apply: supabase db query --linked --file <this> ; register in schema_migrations.

BEGIN;

DO $rls$
DECLARE
  t text;
BEGIN
  FOREACH t IN ARRAY ARRAY[
    'kiwify_connections','kiwify_webhook_events','kiwify_event_mappings',
    'kiwify_message_automations','kiwify_message_jobs'
  ]
  LOOP
    EXECUTE format('DROP POLICY IF EXISTS "kiwify_write_managers" ON public.%I;', t);

    EXECUTE format($p$
      CREATE POLICY "kiwify_write_managers" ON public.%I
        FOR ALL USING (
          EXISTS (SELECT 1 FROM public.settings_users su
                  WHERE su.auth_user_id = auth.uid() AND su.active = true
                    AND (su.super_admin = true OR su.user_type = 'manager'))
        ) WITH CHECK (
          EXISTS (SELECT 1 FROM public.settings_users su
                  WHERE su.auth_user_id = auth.uid() AND su.active = true
                    AND (su.super_admin = true OR su.user_type = 'manager'))
        );$p$, t);
  END LOOP;
END
$rls$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260702140000_messages_source_type_kiwify.sql
-- ---------------------------------------------------------------------------

-- KFY (God Node fix): allow source_type='kiwify' on messages.
--
-- kiwify-dispatch-worker inserts messages with source_type='kiwify' (index.ts:171).
-- Live constraint `messages_source_type_check` did NOT include 'kiwify' → every
-- Kiwify automation send would violate the CHECK. This migration widens the CHECK
-- to the existing 7 values + 'kiwify' (additive superset; no data change).
--
-- Live-verified (2026-07-02, wotuyxscsfralqpoiyfv): existing source_type values in use
-- are inbound/manual/ai_agent/campaign/form/appointment_reminder — all within the new
-- superset, so ADD CONSTRAINT validates without error. source_type is nullable and a
-- CHECK ... IN(...) passes on NULL (behavior preserved).
--
-- ⚠️ GOD NODE: `messages` is shared by the whole system. DROP+ADD is atomic inside the
-- transaction; the superset guarantees no existing row is rejected.
--
-- Apply: supabase db query --linked --file <this> ; register in schema_migrations.

BEGIN;

ALTER TABLE public.messages
  DROP CONSTRAINT IF EXISTS messages_source_type_check;

ALTER TABLE public.messages
  ADD CONSTRAINT messages_source_type_check
  CHECK (source_type = ANY (ARRAY[
    'inbound'::text,
    'manual'::text,
    'ai_agent'::text,
    'campaign'::text,
    'form'::text,
    'followup'::text,
    'appointment_reminder'::text,
    'kiwify'::text
  ]));

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260702150000_kiwify_reconcile_cron.sql
-- ---------------------------------------------------------------------------

-- KFY-1.6: kiwify-reconcile — pg_cron schedule (every 6h).
--
-- Invokes the kiwify-reconcile edge function through the project's audited
-- secure_http_post() helper (reads the service-role JWT from Vault — never hardcoded,
-- rotation-proof; ADR-SP-05). The edge function accepts that JWT on the Authorization
-- header and authorizes the call by its `role=service_role` claim.
--
-- ⚠️ DELIVERED TO DEVOPS — apply manually via `supabase db query --linked --file`, then
--    register in supabase_migrations.schema_migrations. Do NOT apply from the dev agent.
--
-- PREREQUISITE (manual, one-time): a Vault secret named 'service_role_cron' holding the
-- project's service_role JWT must exist (same as whatsapp_templates_auto_sync). If absent,
-- the cron job is skipped with a NOTICE and the migration still succeeds.
--
-- DEPLOY NOTE: kiwify-reconcile must be deployed WITHOUT --no-verify-jwt so the gateway
-- validates the JWT signature; the function only reads the role claim.

BEGIN;

CREATE EXTENSION IF NOT EXISTS pg_net;
CREATE EXTENSION IF NOT EXISTS pg_cron;

DO $$
DECLARE
  v_has_secret boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM vault.secrets WHERE name = 'service_role_cron'
  ) INTO v_has_secret;

  IF NOT v_has_secret THEN
    RAISE NOTICE 'Vault secret service_role_cron not found — skipping kiwify_reconcile cron. Add the secret and re-run this migration.';
    RETURN;
  END IF;

  -- Idempotent: remove any prior registration before (re)scheduling.
  PERFORM cron.unschedule(jobid)
  FROM cron.job
  WHERE jobname = 'kiwify_reconcile';

  -- Every 6 hours (00:00, 06:00, 12:00, 18:00 UTC).
  PERFORM cron.schedule(
    'kiwify_reconcile',
    '0 */6 * * *',
    $cron$
    SELECT public.secure_http_post(
      'service_role_cron',
      'https://wotuyxscsfralqpoiyfv.supabase.co/functions/v1/kiwify-reconcile',
      '{"source":"pg_cron"}'::jsonb,
      'kiwify-reconcile-cron'
    );
    $cron$
  );
END $$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260702160000_kiwify_lead_products.sql
-- ---------------------------------------------------------------------------

-- KFY-2.2 (AC1+AC2): kiwify_lead_products — M-N junction contact↔Kiwify product.
--
-- Populated by kiwify-process-event on ownership events (compra_aprovada,
-- subscription_renewed) — AC3, handled separately. Enables the per-lead course badge.
-- Reference: kiwify-integration-architecture §8.2.
--
-- RLS mirrors the other kiwify_* tables (SELECT for active settings_users; WRITE for
-- super_admin OR user_type='manager'; service_role bypass). 'manager' is the real enum
-- value (admin/manager/user) — 'gestor' does not exist (fixed in 20260702130000).
--
-- Apply: supabase db query --linked --file <this> ; register in schema_migrations.

BEGIN;

CREATE TABLE IF NOT EXISTS public.kiwify_lead_products (
  id             uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  people_id      uuid NOT NULL REFERENCES public.clients_people(id) ON DELETE CASCADE,
  product_id     text NOT NULL,
  product_name   text NOT NULL,
  connection_id  uuid REFERENCES public.kiwify_connections(id) ON DELETE SET NULL,
  first_seen_at  timestamptz NOT NULL DEFAULT now(),
  last_seen_at   timestamptz NOT NULL DEFAULT now(),
  created_at     timestamptz NOT NULL DEFAULT now(),
  updated_at     timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT kiwify_lead_products_people_product_uq UNIQUE (people_id, product_id)
);

COMMENT ON TABLE  public.kiwify_lead_products IS 'M-N junction: which Kiwify products a contact owns. Populated by kiwify-process-event on ownership events (compra_aprovada/subscription_renewed).';
COMMENT ON COLUMN public.kiwify_lead_products.product_id IS 'Kiwify product id (text).';
COMMENT ON COLUMN public.kiwify_lead_products.product_name IS 'Snapshot of product name at last ownership event.';
COMMENT ON COLUMN public.kiwify_lead_products.first_seen_at IS 'First ownership event — never updated on upsert.';
COMMENT ON COLUMN public.kiwify_lead_products.last_seen_at IS 'Most recent ownership event — refreshed on upsert.';

CREATE INDEX IF NOT EXISTS kiwify_lead_products_people_idx
  ON public.kiwify_lead_products (people_id);

DROP TRIGGER IF EXISTS kiwify_lead_products_set_updated_at ON public.kiwify_lead_products;
CREATE TRIGGER kiwify_lead_products_set_updated_at
  BEFORE UPDATE ON public.kiwify_lead_products
  FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();

-- RLS (mirrors other kiwify_* tables)
ALTER TABLE public.kiwify_lead_products ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "kiwify_select_active_users" ON public.kiwify_lead_products;
CREATE POLICY "kiwify_select_active_users" ON public.kiwify_lead_products
  FOR SELECT USING (
    EXISTS (SELECT 1 FROM public.settings_users su
            WHERE su.auth_user_id = auth.uid() AND su.active = true)
  );

DROP POLICY IF EXISTS "kiwify_write_managers" ON public.kiwify_lead_products;
CREATE POLICY "kiwify_write_managers" ON public.kiwify_lead_products
  FOR ALL USING (
    EXISTS (SELECT 1 FROM public.settings_users su
            WHERE su.auth_user_id = auth.uid() AND su.active = true
              AND (su.super_admin = true OR su.user_type = 'manager'))
  ) WITH CHECK (
    EXISTS (SELECT 1 FROM public.settings_users su
            WHERE su.auth_user_id = auth.uid() AND su.active = true
              AND (su.super_admin = true OR su.user_type = 'manager'))
  );

DROP POLICY IF EXISTS "kiwify_service_role" ON public.kiwify_lead_products;
CREATE POLICY "kiwify_service_role" ON public.kiwify_lead_products
  FOR ALL USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');

COMMIT;


