-- ---------------------------------------------------------------------------
-- Migration: 20260727120000_lead_multi_pipeline_ai_priority.sql
-- ---------------------------------------------------------------------------

-- Permite um lead (people_id) estar ativo em dois pipelines simultaneamente
-- (isso já acontecia implicitamente via kiwify-process-event/moveLead, que
-- cria uma leads row nova por pipeline quando não existe uma ativa lá — sem
-- unique constraint bloqueando) e adiciona uma forma explícita de:
--   1) o usuário colocar deliberadamente um lead existente em outro pipeline
--      (RPC add_lead_to_pipeline);
--   2) sinalizar qual etapa deve ser a "prioridade da IA" quando o mesmo
--      people_id tiver leads ativos em pipelines diferentes ao mesmo tempo
--      (leads_stages.ai_priority — consumido por ai-agent-execute/loadContext).

-- ── 1. Flag de prioridade da IA por etapa ───────────────────────────────────

ALTER TABLE public.leads_stages
  ADD COLUMN IF NOT EXISTS ai_priority boolean NOT NULL DEFAULT false;

-- ── 2. RPC: adiciona o people_id de um lead existente a outro pipeline ─────
-- Mesma permissividade da inserção normal de leads (users_insert_leads:
-- with_check true) — não é uma config de admin como as RPCs de vínculo
-- produto↔pipeline, é uma ação de uso diário de quem já pode criar leads.

CREATE OR REPLACE FUNCTION public.add_lead_to_pipeline(
  p_lead_id uuid,
  p_target_pipeline_id uuid
) RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_people_id uuid;
  v_company_id uuid;
  v_teams_id uuid;
  v_user_id uuid;
  v_title text;
  v_target_pipeline_name text;
  v_first_stage_id uuid;
  v_existing_lead_id uuid;
  v_new_lead_id uuid;
BEGIN
  SELECT people_id, company_id, teams_id, user_id, title
  INTO v_people_id, v_company_id, v_teams_id, v_user_id, v_title
  FROM leads
  WHERE id = p_lead_id;

  IF v_people_id IS NULL THEN
    RAISE EXCEPTION 'Lead de origem não encontrado';
  END IF;

  SELECT name INTO v_target_pipeline_name
  FROM leads_pipelines
  WHERE id = p_target_pipeline_id AND active = true;

  IF v_target_pipeline_name IS NULL THEN
    RAISE EXCEPTION 'Pipeline de destino não encontrado ou inativo';
  END IF;

  SELECT id INTO v_existing_lead_id
  FROM leads
  WHERE people_id = v_people_id
    AND leads_pipelines_id = p_target_pipeline_id
    AND status = 'in_progress';

  IF v_existing_lead_id IS NOT NULL THEN
    RAISE EXCEPTION 'Este lead já está ativo no pipeline "%"', v_target_pipeline_name;
  END IF;

  SELECT id INTO v_first_stage_id
  FROM leads_stages
  WHERE leads_pipelines_id = p_target_pipeline_id AND active = true
  ORDER BY order_index ASC
  LIMIT 1;

  IF v_first_stage_id IS NULL THEN
    RAISE EXCEPTION 'Pipeline "%" não tem nenhuma etapa ativa', v_target_pipeline_name;
  END IF;

  INSERT INTO leads (people_id, company_id, teams_id, user_id, title, leads_pipelines_id, leads_stages_id, status)
  VALUES (v_people_id, v_company_id, v_teams_id, v_user_id, v_title, p_target_pipeline_id, v_first_stage_id, 'in_progress')
  RETURNING id INTO v_new_lead_id;

  RETURN jsonb_build_object('lead_id', v_new_lead_id, 'leads_stages_id', v_first_stage_id, 'pipeline_name', v_target_pipeline_name);
END;
$$;

GRANT EXECUTE ON FUNCTION public.add_lead_to_pipeline(uuid, uuid) TO authenticated;


-- ---------------------------------------------------------------------------
-- Migration: 20260727130000_lead_stage_duplication_rules.sql
-- ---------------------------------------------------------------------------

-- Automação: quando um lead entra numa etapa específica de um pipeline
-- (movido pra lá OU já criado direto ali — ex. via webhook do Kiwify), pode
-- ser configurada uma regra que duplica automaticamente esse lead pra outro
-- pipeline (opcionalmente numa etapa específica; sem etapa definida, cai na
-- primeira etapa ativa do pipeline destino). É um trigger — funciona
-- independente de como a etapa mudou (drag&drop no Kanban, tool da IA,
-- webhook, edição manual), sem precisar instrumentar cada write path.
--
-- Reusa a mesma noção de "lead duplicado" da RPC add_lead_to_pipeline (MULTI-
-- PIPELINE-01): pula silenciosamente se o people_id já tem lead ativo no
-- pipeline destino — aqui não há usuário pra mostrar erro, então é idempotente
-- em vez de lançar exceção.

-- ── 1. Tabela de regras ──────────────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.leads_stage_duplication_rules (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  source_stage_id uuid NOT NULL REFERENCES public.leads_stages(id) ON DELETE CASCADE,
  target_pipeline_id uuid NOT NULL REFERENCES public.leads_pipelines(id) ON DELETE CASCADE,
  target_stage_id uuid REFERENCES public.leads_stages(id) ON DELETE SET NULL,
  active boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_stage_id, target_pipeline_id)
);

ALTER TABLE public.leads_stage_duplication_rules ENABLE ROW LEVEL SECURITY;

CREATE POLICY authenticated_read_duplication_rules ON public.leads_stage_duplication_rules
  FOR SELECT
  USING (true);

CREATE POLICY managers_write_duplication_rules ON public.leads_stage_duplication_rules
  FOR ALL
  USING (is_admin_or_manager())
  WITH CHECK (is_admin_or_manager());

-- ── 2. Trigger de duplicação ─────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.duplicate_lead_on_stage_enter() RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rule record;
  v_target_stage_id uuid;
  v_already_active uuid;
BEGIN
  -- Guarda contra encadeamento indefinido: se uma regra mal configurada criar
  -- um ciclo (etapa A duplica pra pipeline B, cuja primeira etapa duplica de
  -- volta pra A...), essa profundidade limita o dano em vez de estourar a
  -- stack do Postgres.
  IF pg_trigger_depth() > 3 THEN
    RETURN NEW;
  END IF;

  IF NEW.status <> 'in_progress' OR NEW.leads_stages_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'UPDATE' AND NEW.leads_stages_id IS NOT DISTINCT FROM OLD.leads_stages_id THEN
    RETURN NEW;
  END IF;

  FOR v_rule IN
    SELECT * FROM leads_stage_duplication_rules
    WHERE source_stage_id = NEW.leads_stages_id AND active = true
  LOOP
    SELECT id INTO v_already_active
    FROM leads
    WHERE people_id = NEW.people_id
      AND leads_pipelines_id = v_rule.target_pipeline_id
      AND status = 'in_progress';

    IF v_already_active IS NOT NULL THEN
      CONTINUE;
    END IF;

    v_target_stage_id := v_rule.target_stage_id;
    IF v_target_stage_id IS NULL THEN
      SELECT id INTO v_target_stage_id
      FROM leads_stages
      WHERE leads_pipelines_id = v_rule.target_pipeline_id AND active = true
      ORDER BY order_index ASC
      LIMIT 1;
    END IF;

    IF v_target_stage_id IS NULL THEN
      CONTINUE;
    END IF;

    INSERT INTO leads (people_id, company_id, teams_id, user_id, title, leads_pipelines_id, leads_stages_id, status)
    VALUES (NEW.people_id, NEW.company_id, NEW.teams_id, NEW.user_id, NEW.title, v_rule.target_pipeline_id, v_target_stage_id, 'in_progress');
  END LOOP;

  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS leads_stage_duplication_trigger ON public.leads;
CREATE TRIGGER leads_stage_duplication_trigger
  AFTER INSERT OR UPDATE OF leads_stages_id ON public.leads
  FOR EACH ROW
  EXECUTE FUNCTION public.duplicate_lead_on_stage_enter();


-- ---------------------------------------------------------------------------
-- Migration: 20260728120000_clients_people_created_by_rls_fix.sql
-- ---------------------------------------------------------------------------

-- Bug real, achado via simulação de RLS como usuária 'comercial' (Aurea):
-- criar um novo cliente (NovoNegocioModal → useCriarPessoa) sempre falhava com
-- "new row violates row-level security policy for table clients_people" pra
-- qualquer usuário não-admin/manager.
--
-- Causa: useCriarPessoa faz `INSERT ... .select().single()` — o RETURNING
-- exige que a linha recém-criada passe também pela policy de SELECT
-- (users_read_own_clients), que hoje só concede visibilidade via um lead JÁ
-- existente vinculado à pessoa. No momento do INSERT da pessoa, esse lead
-- ainda não existe (é criado logo depois, em outro INSERT) — clássico
-- problema do ovo e da galinha em RLS. is_admin_or_manager() mascarava isso
-- pra admin/manager, por isso só reproduzia pra 'comercial'.
--
-- Fix: rastrear quem criou o contato (created_by) e usar isso como mais um
-- caminho de visibilidade — resolve tanto o problema imediato do RETURNING
-- quanto o caso mais amplo de criar um contato sem vincular a nenhum
-- pipeline/lead (ex: só cadastro, sem negócio ainda), que hoje ficaria
-- invisível pra sempre pro usuário 'comercial' que criou.

ALTER TABLE public.clients_people
  ADD COLUMN IF NOT EXISTS created_by uuid REFERENCES public.settings_users(id) ON DELETE SET NULL
    DEFAULT public.get_current_settings_user_id();

DROP POLICY IF EXISTS users_read_own_clients ON public.clients_people;
CREATE POLICY users_read_own_clients ON public.clients_people
  FOR SELECT
  USING (
    is_admin_or_manager()
    OR created_by = get_current_settings_user_id()
    OR EXISTS (
      SELECT 1 FROM leads l
      WHERE l.people_id = clients_people.id AND l.user_id = get_current_settings_user_id()
    )
    OR EXISTS (
      SELECT 1 FROM leads l
      JOIN settings_users_teams sut ON sut.team_id = l.teams_id
      WHERE l.people_id = clients_people.id AND sut.user_id = get_current_settings_user_id()
    )
    OR EXISTS (
      SELECT 1 FROM leads l
      WHERE l.people_id = clients_people.id AND lead_pipeline_accessible_to_current_user(l.leads_pipelines_id)
    )
  );

DROP POLICY IF EXISTS users_update_own_clients ON public.clients_people;
CREATE POLICY users_update_own_clients ON public.clients_people
  FOR UPDATE
  USING (
    is_admin_or_manager()
    OR created_by = get_current_settings_user_id()
    OR EXISTS (
      SELECT 1 FROM leads l
      WHERE l.people_id = clients_people.id AND l.user_id = get_current_settings_user_id()
    )
    OR EXISTS (
      SELECT 1 FROM leads l
      JOIN settings_users_teams sut ON sut.team_id = l.teams_id
      WHERE l.people_id = clients_people.id AND sut.user_id = get_current_settings_user_id()
    )
    OR EXISTS (
      SELECT 1 FROM leads l
      WHERE l.people_id = clients_people.id AND lead_pipeline_accessible_to_current_user(l.leads_pipelines_id)
    )
  )
  WITH CHECK (
    is_admin_or_manager()
    OR created_by = get_current_settings_user_id()
    OR EXISTS (
      SELECT 1 FROM leads l
      WHERE l.people_id = clients_people.id AND l.user_id = get_current_settings_user_id()
    )
    OR EXISTS (
      SELECT 1 FROM leads l
      JOIN settings_users_teams sut ON sut.team_id = l.teams_id
      WHERE l.people_id = clients_people.id AND sut.user_id = get_current_settings_user_id()
    )
    OR EXISTS (
      SELECT 1 FROM leads l
      WHERE l.people_id = clients_people.id AND lead_pipeline_accessible_to_current_user(l.leads_pipelines_id)
    )
  );


-- ---------------------------------------------------------------------------
-- Migration: 20260729220000_fix_stage_followup_webhook_config_source.sql
-- ---------------------------------------------------------------------------

BEGIN;

CREATE OR REPLACE FUNCTION public.notify_lead_stage_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_supabase_url TEXT;
  v_service_key  TEXT;
BEGIN
  IF TG_OP = 'UPDATE' AND OLD.leads_stages_id IS NOT DISTINCT FROM NEW.leads_stages_id THEN
    RETURN NEW;
  END IF;
  IF NEW.leads_stages_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- Always cancel pending stage followups from prior stage (no settings needed)
  UPDATE public.followup_queue
  SET status = 'cancelled', fired_at = now(), error_message = 'Cancelado: lead mudou de etapa'
  WHERE lead_id = NEW.id AND status = 'pending' AND source_type = 'stage';

  SELECT value INTO v_supabase_url FROM public._app_config WHERE key = 'supabase_url';
  SELECT value INTO v_service_key  FROM public._app_config WHERE key = 'service_role_key';
  IF v_supabase_url IS NULL OR v_supabase_url = '' OR v_service_key IS NULL OR v_service_key = '' THEN
    RETURN NEW;
  END IF;

  PERFORM extensions.http_post(
    url := v_supabase_url || '/functions/v1/dispara-webhook',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_service_key),
    body := jsonb_build_object('tipo', 'lead_etapa', 'lead_id', NEW.id::text)
  );
  PERFORM extensions.http_post(
    url := v_supabase_url || '/functions/v1/followup-enqueue',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_service_key),
    body := jsonb_build_object('lead_id', NEW.id::text, 'stage_id', NEW.leads_stages_id::text, 'source_type', 'stage')
  );
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.trigger_followup_retry_worker()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stale_threshold timestamptz := now() - interval '15 minutes';
  v_supabase_url text;
BEGIN
  IF NOT EXISTS (
    SELECT 1
    FROM public.followup_queue
    WHERE status = 'queued'
      AND updated_at < v_stale_threshold
      AND retry_count < 3
    LIMIT 1
  ) THEN
    RETURN;
  END IF;

  SELECT value INTO v_supabase_url FROM public._app_config WHERE key = 'supabase_url';
  IF v_supabase_url IS NULL OR v_supabase_url = '' THEN
    RETURN;
  END IF;

  PERFORM public.secure_http_post(
    'service_role_key',
    v_supabase_url || '/functions/v1/followup-retry-worker',
    jsonb_build_object('source', 'pg_cron'),
    'trigger_followup_retry_worker'
  );
END;
$function$;

-- smoke test: confirm both functions now resolve real values instead of NULL
SELECT
  (SELECT value FROM public._app_config WHERE key='supabase_url')     AS app_config_url,
  (SELECT value FROM public._app_config WHERE key='service_role_key' ) IS NOT NULL AS has_service_key;

COMMIT;


