-- ---------------------------------------------------------------------------
-- Migration: 20260729233000_lead_tags_system.sql
-- ---------------------------------------------------------------------------

-- Sistema de tags globais pra leads, com permissão de visibilidade por equipe.
-- Mesmo padrão de settings_teams_pipelines / lead_pipeline_accessible_to_current_user
-- (já testado em produção nesta sessão pra restringir a Aurea ao pipeline Recomendação).

BEGIN;

-- ── 1. Tabelas ────────────────────────────────────────────────────────────────

CREATE TABLE lead_tags (
  id         uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name       text NOT NULL UNIQUE,
  color      text NOT NULL DEFAULT '#3B82F6',
  active     boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE settings_teams_tags (
  team_id    uuid NOT NULL REFERENCES settings_teams(id) ON DELETE CASCADE,
  tag_id     uuid NOT NULL REFERENCES lead_tags(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (team_id, tag_id)
);

CREATE TABLE leads_tags (
  lead_id    uuid NOT NULL REFERENCES leads(id) ON DELETE CASCADE,
  tag_id     uuid NOT NULL REFERENCES lead_tags(id) ON DELETE CASCADE,
  created_at timestamptz NOT NULL DEFAULT now(),
  created_by uuid REFERENCES settings_users(id),
  PRIMARY KEY (lead_id, tag_id)
);

CREATE INDEX idx_leads_tags_tag_id ON leads_tags(tag_id);
CREATE INDEX idx_settings_teams_tags_tag_id ON settings_teams_tags(tag_id);

CREATE TRIGGER update_lead_tags_updated_at
  BEFORE UPDATE ON lead_tags
  FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

-- ── 2. Função de acesso (cópia estrutural de lead_pipeline_accessible_to_current_user) ──

CREATE OR REPLACE FUNCTION public.tag_accessible_to_current_user(p_tag_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
  v_team_ids uuid[];
  v_restricted_team_ids uuid[];
  v_has_universal_team boolean;
BEGIN
  v_user_id := public.get_current_settings_user_id();
  IF v_user_id IS NULL OR p_tag_id IS NULL THEN
    RETURN false;
  END IF;

  SELECT ARRAY(SELECT team_id FROM public.settings_users_teams WHERE user_id = v_user_id)
    INTO v_team_ids;

  IF v_team_ids IS NULL OR array_length(v_team_ids, 1) IS NULL THEN
    RETURN true; -- sem equipe = sem restrição (mesma regra do pipeline)
  END IF;

  SELECT ARRAY(SELECT DISTINCT team_id FROM public.settings_teams_tags WHERE team_id = ANY(v_team_ids))
    INTO v_restricted_team_ids;

  -- Qualquer equipe do usuário sem NENHUM vínculo em settings_teams_tags
  -- é "universal" (enxerga todas as tags) — basta uma pra liberar tudo.
  v_has_universal_team := EXISTS (
    SELECT 1 FROM unnest(v_team_ids) AS t(id)
    WHERE NOT (id = ANY(COALESCE(v_restricted_team_ids, ARRAY[]::uuid[])))
  );
  IF v_has_universal_team THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.settings_teams_tags stt
    WHERE stt.team_id = ANY(v_team_ids)
      AND stt.tag_id = p_tag_id
  );
END;
$function$;

COMMENT ON FUNCTION public.tag_accessible_to_current_user IS
  'Espelha lead_pipeline_accessible_to_current_user(): time sem vínculo em settings_teams_tags enxerga todas as tags; time com algum vínculo só enxerga as tags explicitamente vinculadas.';

-- ── 3. RLS ────────────────────────────────────────────────────────────────────

ALTER TABLE lead_tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE settings_teams_tags ENABLE ROW LEVEL SECURITY;
ALTER TABLE leads_tags ENABLE ROW LEVEL SECURITY;

CREATE POLICY tags_read ON lead_tags FOR SELECT
USING (is_admin_or_manager() OR tag_accessible_to_current_user(id));

CREATE POLICY tags_write ON lead_tags FOR ALL
USING (is_admin_or_manager())
WITH CHECK (is_admin_or_manager());

CREATE POLICY team_tags_read ON settings_teams_tags FOR SELECT
USING (true);

CREATE POLICY team_tags_write ON settings_teams_tags FOR ALL
USING (is_admin_or_manager())
WITH CHECK (is_admin_or_manager());

CREATE POLICY leads_tags_read ON leads_tags FOR SELECT
USING (
  tag_accessible_to_current_user(tag_id)
  AND EXISTS (SELECT 1 FROM leads l WHERE l.id = leads_tags.lead_id)
);

CREATE POLICY leads_tags_write ON leads_tags FOR INSERT
WITH CHECK (
  tag_accessible_to_current_user(tag_id)
  AND EXISTS (
    SELECT 1 FROM leads l
    WHERE l.id = leads_tags.lead_id
      AND (
        is_admin_or_manager()
        OR l.user_id = get_current_settings_user_id()
        OR l.teams_id IN (SELECT team_id FROM settings_users_teams WHERE user_id = get_current_settings_user_id())
        OR lead_pipeline_accessible_to_current_user(l.leads_pipelines_id)
      )
  )
);

CREATE POLICY leads_tags_delete ON leads_tags FOR DELETE
USING (
  tag_accessible_to_current_user(tag_id)
  AND EXISTS (
    SELECT 1 FROM leads l
    WHERE l.id = leads_tags.lead_id
      AND (
        is_admin_or_manager()
        OR l.user_id = get_current_settings_user_id()
        OR l.teams_id IN (SELECT team_id FROM settings_users_teams WHERE user_id = get_current_settings_user_id())
        OR lead_pipeline_accessible_to_current_user(l.leads_pipelines_id)
      )
  )
);

-- ── 4. get_omni_contacts ganha filtro por tag ──────────────────────────────────

DROP FUNCTION IF EXISTS public.get_omni_contacts(text, text, text, text, text, text, text, text, integer, integer);

CREATE OR REPLACE FUNCTION public.get_omni_contacts(
  p_search_term text DEFAULT NULL::text,
  p_status_atend text DEFAULT NULL::text,
  p_atend_ia text DEFAULT NULL::text,
  p_filtro_data text DEFAULT NULL::text,
  p_responsavel text DEFAULT NULL::text,
  p_pipeline text DEFAULT NULL::text,
  p_etapa text DEFAULT NULL::text,
  p_time text DEFAULT NULL::text,
  p_limit integer DEFAULT 20,
  p_offset integer DEFAULT 0,
  p_tag text DEFAULT NULL::text
)
RETURNS TABLE(contact jsonb, total_count bigint)
LANGUAGE sql
STABLE
AS $function$
  SELECT
    to_jsonb(p.*)    AS contact,
    COUNT(*) OVER()  AS total_count
  FROM public.clients_people p
  WHERE
    (
      p.whatsapp               IS NOT NULL
      OR p.instagram_id          IS NOT NULL
      OR p.tiktok_open_id        IS NOT NULL
      OR p.manychat_subscriber_id IS NOT NULL
      OR p.email                 IS NOT NULL
    )
    AND p.status <> 'merged'
    AND (
      p_search_term IS NULL OR p_search_term = '' OR
      p.name              ILIKE '%' || p_search_term || '%' OR
      p.whatsapp          ILIKE '%' || p_search_term || '%' OR
      p.email             ILIKE '%' || p_search_term || '%' OR
      p.instagram_user_id ILIKE '%' || p_search_term || '%'
    )
    AND (
      p_status_atend IS NULL
      OR (p_status_atend = 'open'   AND (p.service_status = 'open'   OR p.service_status IS NULL))
      OR (p_status_atend <> 'open'  AND p.service_status = p_status_atend)
    )
    AND (
      p_atend_ia IS NULL OR
      (p_atend_ia = 'ia_ativa' AND p.ai_enabled = true) OR
      (p_atend_ia = 'humano'   AND p.ai_enabled = false)
    )
    AND (
      p_filtro_data IS NULL OR
      p.updated_at BETWEEN
        (split_part(p_filtro_data, '_', 1) || 'T00:00:00')::timestamptz
        AND (split_part(p_filtro_data, '_', 2) || 'T23:59:59')::timestamptz
    )
    AND (
      p_responsavel IS NULL
      OR NOT EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND l.status NOT IN ('lost', 'archived')
         )
      OR EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND (l.user_id = p_responsavel::uuid OR l.user_id IS NULL)
         )
    )
    AND (
      p_pipeline IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_pipelines_id = p_pipeline::uuid
      )
    )
    AND (
      p_etapa IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_stages_id = p_etapa::uuid
      )
    )
    AND (
      p_time IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.teams_id = p_time::uuid
      )
    )
    AND (
      p_tag IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        JOIN public.leads_tags lt ON lt.lead_id = l.id
        WHERE l.people_id = p.id
          AND lt.tag_id = p_tag::uuid
      )
    )
  ORDER BY p.updated_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$function$;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730182000_bump_clients_people_on_message.sql
-- ---------------------------------------------------------------------------

BEGIN;

CREATE OR REPLACE FUNCTION public.bump_clients_people_on_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.people_id IS NOT NULL THEN
    UPDATE public.clients_people SET updated_at = now() WHERE id = NEW.people_id;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;
END;
$function$;

COMMENT ON FUNCTION public.bump_clients_people_on_message IS
  'Atualiza clients_people.updated_at a cada nova mensagem (inbound ou outbound) — é o campo que get_omni_contacts usa pra ordenar/surfacear conversas no Omni. Sem isso, uma conversa nova ou reativada não sobe na lista.';

CREATE TRIGGER bump_clients_people_on_message_insert
AFTER INSERT ON public.messages
FOR EACH ROW EXECUTE FUNCTION public.bump_clients_people_on_message();

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730190000_notif01_unread_conversations.sql
-- ---------------------------------------------------------------------------

-- NOTIF-01: rastreio de mensagens inbound não lidas (Omni + Kanban).
--
-- messages.read_at NÃO é reutilizada: é o recibo de leitura do WhatsApp
-- (o CLIENTE leu a NOSSA mensagem outbound), escrito por whatsapp-inbound e
-- send-status-callback e lido pelo BI. Semântica oposta. Coluna nova: seen_at.

BEGIN;

-- ── 1. messages.seen_at ───────────────────────────────────────────────────────

ALTER TABLE public.messages ADD COLUMN seen_at timestamptz;

COMMENT ON COLUMN public.messages.seen_at IS
  'Quando um atendente HUMANO abriu a thread e viu esta mensagem inbound. NÃO confundir com read_at, que é o recibo de leitura do WhatsApp (cliente leu nossa mensagem outbound). Só é preenchida para from_contact = ''cliente''.';

CREATE INDEX idx_messages_unread_by_person
  ON public.messages (people_id)
  WHERE from_contact = 'cliente' AND seen_at IS NULL;

-- Sem isso o sistema nasce com todo o histórico marcado como não lido.
UPDATE public.messages
   SET seen_at = created_at
 WHERE from_contact = 'cliente' AND seen_at IS NULL;

-- ── 2. clients_people: cache denormalizado que a UI lê ────────────────────────

ALTER TABLE public.clients_people
  ADD COLUMN unread_count    integer     NOT NULL DEFAULT 0,
  ADD COLUMN first_unread_at timestamptz,
  ADD COLUMN last_read_at    timestamptz,
  ADD COLUMN last_read_by    uuid REFERENCES public.settings_users(id) ON DELETE SET NULL;

COMMENT ON COLUMN public.clients_people.unread_count IS
  'Cache de COUNT(*) de messages inbound com seen_at IS NULL. Mantido pelo trigger bump_clients_people_on_message (insert) e zerado por mark_conversation_read(). Reparável via recalc_unread_count().';
COMMENT ON COLUMN public.clients_people.first_unread_at IS
  'created_at da mensagem que abriu a rajada não lida atual — usado pra "esperando há Xh" no Omni/Kanban.';
COMMENT ON COLUMN public.clients_people.last_read_by IS
  'Último atendente que abriu a thread. Inbox é compartilhado, então isso é o único sinal de "quem pegou essa conversa".';

CREATE INDEX idx_clients_people_unread
  ON public.clients_people (unread_count)
  WHERE unread_count > 0;

-- ── 3. Predicado de acesso à conversa (extração 1:1 da policy de messages) ────

CREATE OR REPLACE FUNCTION public.person_conversation_accessible_to_current_user(p_people_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  IF p_people_id IS NULL THEN
    RETURN true;  -- evento não atrelado a conversa não é restrito por pessoa
  END IF;

  IF public.is_admin_or_manager() THEN
    RETURN true;
  END IF;

  v_user_id := public.get_current_settings_user_id();
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN
    EXISTS (SELECT 1 FROM public.clients_people cp
             WHERE cp.id = p_people_id AND cp.created_by = v_user_id)
    OR EXISTS (SELECT 1 FROM public.leads l
                WHERE l.people_id = p_people_id AND l.user_id = v_user_id)
    OR EXISTS (SELECT 1 FROM public.leads l
                 JOIN public.settings_users_teams sut ON sut.team_id = l.teams_id
                WHERE l.people_id = p_people_id AND sut.user_id = v_user_id)
    OR EXISTS (SELECT 1 FROM public.leads l
                WHERE l.people_id = p_people_id
                  AND public.lead_pipeline_accessible_to_current_user(l.leads_pipelines_id));
END;
$function$;

COMMENT ON FUNCTION public.person_conversation_accessible_to_current_user IS
  'Extração 1:1 do predicado da policy authenticated_read de messages (20260729231500). Fonte única de "esse usuário pode ver a conversa dessa pessoa?". Usada por notifications e por mark_conversation_read.';

GRANT EXECUTE ON FUNCTION public.person_conversation_accessible_to_current_user(uuid) TO authenticated;

-- ── 4. Trigger existente ganha o contador (segue sendo UM trigger só) ─────────

CREATE OR REPLACE FUNCTION public.bump_clients_people_on_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.people_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.from_contact = 'cliente' THEN
    UPDATE public.clients_people
       SET updated_at      = now(),
           unread_count    = unread_count + 1,
           first_unread_at = COALESCE(first_unread_at, NEW.created_at, now())
     WHERE id = NEW.people_id;
  ELSE
    UPDATE public.clients_people SET updated_at = now() WHERE id = NEW.people_id;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;  -- PRESERVAR: bug de contador nunca pode derrubar a ingestão de mensagem
END;
$function$;

-- ── 5. mark_conversation_read: caminho único de escrita da leitura ────────────

CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_people_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
BEGIN
  IF p_people_id IS NULL OR v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  -- SECURITY DEFINER fura RLS: revalidar acesso na unha.
  IF NOT public.person_conversation_accessible_to_current_user(p_people_id) THEN
    RAISE EXCEPTION 'sem acesso a esta conversa';
  END IF;

  UPDATE public.messages
     SET seen_at = now()
   WHERE people_id = p_people_id
     AND from_contact = 'cliente'
     AND seen_at IS NULL;
  GET DIAGNOSTICS v_marked = ROW_COUNT;

  -- updated_at NÃO é bumpado: ler uma conversa não pode ressuscitá-la
  -- no topo do Omni, que ordena por updated_at DESC.
  UPDATE public.clients_people
     SET unread_count    = 0,
         first_unread_at = NULL,
         last_read_at    = now(),
         last_read_by    = v_user_id
   WHERE id = p_people_id;

  RETURN v_marked;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.mark_conversation_read(uuid) TO authenticated;

-- ── 6. Reparo do contador denormalizado ──────────────────────────────────────

CREATE OR REPLACE FUNCTION public.recalc_unread_count(p_people_id uuid DEFAULT NULL)
RETURNS void
LANGUAGE sql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
  UPDATE public.clients_people cp
     SET unread_count    = COALESCE(agg.n, 0),
         first_unread_at = agg.first_at
    FROM (
      SELECT p.id,
             COUNT(m.id)       AS n,
             MIN(m.created_at) AS first_at
        FROM public.clients_people p
        LEFT JOIN public.messages m
               ON m.people_id = p.id
              AND m.from_contact = 'cliente'
              AND m.seen_at IS NULL
       WHERE p_people_id IS NULL OR p.id = p_people_id
       GROUP BY p.id
    ) agg
   WHERE cp.id = agg.id;
$function$;

COMMENT ON FUNCTION public.recalc_unread_count IS
  'Reparo idempotente do cache clients_people.unread_count/first_unread_at a partir de messages. Ferramenta de operação — roda como service_role, sem GRANT para authenticated.';

REVOKE EXECUTE ON FUNCTION public.recalc_unread_count(uuid) FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.recalc_unread_count(uuid) FROM anon, authenticated;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730190500_notif02_notification_event_type_inbound_message.sql
-- ---------------------------------------------------------------------------

-- NOTIF-02 (parte 1/2): novo valor do enum notification_event_type.
--
-- SEM BEGIN/COMMIT de propósito: um valor adicionado por ALTER TYPE não pode ser
-- REFERENCIADO na mesma transação em que foi criado. A tabela notifications e o
-- trigger que usam 'inbound_message' vêm no arquivo seguinte.

ALTER TYPE public.notification_event_type ADD VALUE IF NOT EXISTS 'inbound_message';


-- ---------------------------------------------------------------------------
-- Migration: 20260730191000_notif02_notifications_table.sql
-- ---------------------------------------------------------------------------

-- NOTIF-02 (parte 2/2): tabela do sino, RLS, realtime e extensão do trigger.
-- Depende de 20260730190000 (person_conversation_accessible_to_current_user,
-- clients_people.unread_count) e de 20260730190500 (valor 'inbound_message').

BEGIN;

-- ── 1. Tabela ─────────────────────────────────────────────────────────────────

CREATE TABLE public.notifications (
  id              uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_type      public.notification_event_type NOT NULL,
  people_id       uuid   REFERENCES public.clients_people(id) ON DELETE CASCADE,
  lead_id         uuid   REFERENCES public.leads(id)          ON DELETE SET NULL,
  message_id      bigint REFERENCES public.messages(id)       ON DELETE SET NULL,
  title           text NOT NULL,
  body            text,
  channel         text,
  unread_messages integer NOT NULL DEFAULT 1,
  read_at         timestamptz,
  read_by         uuid REFERENCES public.settings_users(id) ON DELETE SET NULL,
  created_at      timestamptz NOT NULL DEFAULT now()
);

COMMENT ON TABLE public.notifications IS
  'Feed do sino (DashLayout). Linha GLOBAL: read_at/read_by são únicos, não por usuário — inbox compartilhado, quem atende limpa pra todo mundo. Visibilidade (não leitura) é por usuário via RLS.';
COMMENT ON COLUMN public.notifications.title IS
  'Nome do contato no momento do evento. Denormalizado de propósito: embed via RLS pode voltar null (bug conhecido, 20260717130000).';
COMMENT ON COLUMN public.notifications.unread_messages IS
  'Quantas mensagens inbound essa notificação representa após o colapso da rajada.';
COMMENT ON COLUMN public.notifications.message_id IS
  'bigint — messages.id é serial, não uuid.';

CREATE INDEX idx_notifications_feed   ON public.notifications (created_at DESC);
CREATE INDEX idx_notifications_open   ON public.notifications (people_id) WHERE read_at IS NULL;
CREATE INDEX idx_notifications_unread ON public.notifications (created_at DESC) WHERE read_at IS NULL;

-- ── 2. RLS ────────────────────────────────────────────────────────────────────

ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;

CREATE POLICY notifications_read ON public.notifications FOR SELECT
USING (public.person_conversation_accessible_to_current_user(people_id));

-- Sem policy de INSERT: escrita é exclusiva do trigger SECURITY DEFINER.
CREATE POLICY notifications_mark_read ON public.notifications FOR UPDATE
USING     (public.person_conversation_accessible_to_current_user(people_id))
WITH CHECK (public.person_conversation_accessible_to_current_user(people_id));

CREATE POLICY notifications_delete ON public.notifications FOR DELETE
USING (public.is_admin_or_manager());

-- ── 3. Realtime ───────────────────────────────────────────────────────────────

ALTER PUBLICATION supabase_realtime ADD TABLE public.notifications;
ALTER TABLE public.notifications REPLICA IDENTITY FULL;

-- ── 4. Trigger final: contador + sino, ainda em UM único AFTER INSERT ─────────

CREATE OR REPLACE FUNCTION public.bump_clients_people_on_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_name text;
BEGIN
  IF NEW.people_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.from_contact = 'cliente' THEN
    SELECT name INTO v_name FROM public.clients_people WHERE id = NEW.people_id;

    -- Colapso de rajada: enquanto ninguém atendeu, a notificação aberta é
    -- atualizada em vez de gerar uma linha nova por mensagem.
    UPDATE public.notifications
       SET message_id      = NEW.id,
           body            = left(COALESCE(NEW.content, ''), 280),
           channel         = NEW.channel,
           unread_messages = unread_messages + 1,
           created_at      = now(),
           lead_id         = COALESCE(NEW.lead_id, lead_id)
     WHERE people_id = NEW.people_id
       AND event_type = 'inbound_message'
       AND read_at IS NULL;

    IF NOT FOUND THEN
      INSERT INTO public.notifications
        (event_type, people_id, lead_id, message_id, title, body, channel, unread_messages)
      VALUES
        ('inbound_message', NEW.people_id, NEW.lead_id, NEW.id,
         left(COALESCE(v_name, 'Contato sem nome'), 120),
         left(COALESCE(NEW.content, ''), 280),
         NEW.channel, 1);
    END IF;

    UPDATE public.clients_people
       SET updated_at      = now(),
           unread_count    = unread_count + 1,
           first_unread_at = COALESCE(first_unread_at, NEW.created_at, now())
     WHERE id = NEW.people_id;
  ELSE
    UPDATE public.clients_people SET updated_at = now() WHERE id = NEW.people_id;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;  -- PRESERVAR: falha de contador/notificação nunca derruba a ingestão
END;
$function$;

COMMENT ON FUNCTION public.bump_clients_people_on_message IS
  'AFTER INSERT em messages: bumpa clients_people.updated_at (ordenação do Omni) e, para inbound de cliente, incrementa unread_count e mantém a notificação aberta do sino. Roda no caminho mais quente do sistema — o EXCEPTION WHEN OTHERS THEN RETURN NEW é o que impede um bug aqui de derrubar o webhook de mensagem; não remover.';

-- ── 5. mark_conversation_read passa a fechar o sino na mesma transação ────────

CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_people_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
BEGIN
  IF p_people_id IS NULL OR v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  IF NOT public.person_conversation_accessible_to_current_user(p_people_id) THEN
    RAISE EXCEPTION 'sem acesso a esta conversa';
  END IF;

  UPDATE public.messages
     SET seen_at = now()
   WHERE people_id = p_people_id
     AND from_contact = 'cliente'
     AND seen_at IS NULL;
  GET DIAGNOSTICS v_marked = ROW_COUNT;

  -- updated_at NÃO é bumpado: ler uma conversa não pode ressuscitá-la
  -- no topo do Omni, que ordena por updated_at DESC.
  UPDATE public.clients_people
     SET unread_count    = 0,
         first_unread_at = NULL,
         last_read_at    = now(),
         last_read_by    = v_user_id
   WHERE id = p_people_id;

  UPDATE public.notifications
     SET read_at = now(),
         read_by = v_user_id
   WHERE people_id = p_people_id
     AND read_at IS NULL;

  RETURN v_marked;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.mark_conversation_read(uuid) TO authenticated;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730200000_notif_rls_and_race_hardening.sql
-- ---------------------------------------------------------------------------

-- Hardening de 20260730190000 (NOTIF-01) e 20260730191000 (NOTIF-02), que já estão
-- aplicadas no LIVE e por isso são imutáveis. Três correções do pré-review do dev-qa.

BEGIN;

-- ── A. Furo de RLS: people_id NULL escapava do gate ───────────────────────────
--
-- notifications.people_id é nullable e person_conversation_accessible_to_current_user()
-- retorna true para NULL. Como a função é o gate único das policies, o primeiro
-- event_type sem pessoa associada (meeting_scheduled, followup_due...) ficaria
-- visível para QUALQUER usuário autenticado — e silenciosamente, porque hoje toda
-- linha tem people_id. Fail-closed nos dois níveis: no predicado e na policy.

CREATE OR REPLACE FUNCTION public.person_conversation_accessible_to_current_user(p_people_id uuid)
RETURNS boolean
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid;
BEGIN
  IF p_people_id IS NULL THEN
    RETURN false;  -- fail-closed: idêntico ao que a policy de messages faz com people_id NULL
  END IF;

  IF public.is_admin_or_manager() THEN
    RETURN true;
  END IF;

  v_user_id := public.get_current_settings_user_id();
  IF v_user_id IS NULL THEN
    RETURN false;
  END IF;

  RETURN
    EXISTS (SELECT 1 FROM public.clients_people cp
             WHERE cp.id = p_people_id AND cp.created_by = v_user_id)
    OR EXISTS (SELECT 1 FROM public.leads l
                WHERE l.people_id = p_people_id AND l.user_id = v_user_id)
    OR EXISTS (SELECT 1 FROM public.leads l
                 JOIN public.settings_users_teams sut ON sut.team_id = l.teams_id
                WHERE l.people_id = p_people_id AND sut.user_id = v_user_id)
    OR EXISTS (SELECT 1 FROM public.leads l
                WHERE l.people_id = p_people_id
                  AND public.lead_pipeline_accessible_to_current_user(l.leads_pipelines_id));
END;
$function$;

COMMENT ON FUNCTION public.person_conversation_accessible_to_current_user IS
  'Extração 1:1 do predicado da policy authenticated_read de messages (20260729231500). Fonte única de "esse usuário pode ver a conversa dessa pessoa?". p_people_id NULL => false (fail-closed), igual ao que a policy de messages faz. Quem adicionar notificação sem pessoa associada precisa de um gate próprio.';

DROP POLICY notifications_read      ON public.notifications;
DROP POLICY notifications_mark_read ON public.notifications;

CREATE POLICY notifications_read ON public.notifications FOR SELECT
USING (people_id IS NOT NULL AND public.person_conversation_accessible_to_current_user(people_id));

CREATE POLICY notifications_mark_read ON public.notifications FOR UPDATE
USING      (people_id IS NOT NULL AND public.person_conversation_accessible_to_current_user(people_id))
WITH CHECK (people_id IS NOT NULL AND public.person_conversation_accessible_to_current_user(people_id));

-- ── E. Colapso de rajada precisa ser atômico ─────────────────────────────────
--
-- O padrão "UPDATE; IF NOT FOUND THEN INSERT" não segura concorrência: duas inbounds
-- simultâneas do mesmo people_id não acham notificação aberta e ambas inserem, gerando
-- 2 linhas abertas e badge dobrado. Índice UNIQUE + ON CONFLICT DO UPDATE andam JUNTOS:
-- só o índice faria a violação cair no EXCEPTION WHEN OTHERS do trigger, trocando um
-- bug barulhento por um mudo (notificação sumida sem rastro).

DROP INDEX public.idx_notifications_open;

CREATE UNIQUE INDEX idx_notifications_open
  ON public.notifications (people_id, event_type)
  WHERE read_at IS NULL;

COMMENT ON INDEX public.idx_notifications_open IS
  'UNIQUE de propósito: garante no banco a invariante "no máximo 1 notificação aberta por (pessoa, tipo)". É o alvo do ON CONFLICT do trigger bump_clients_people_on_message.';

-- ── Trigger: INSERT ... ON CONFLICT DO UPDATE ────────────────────────────────

CREATE OR REPLACE FUNCTION public.bump_clients_people_on_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_name text;
BEGIN
  IF NEW.people_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.from_contact = 'cliente' THEN
    SELECT name INTO v_name FROM public.clients_people WHERE id = NEW.people_id;

    INSERT INTO public.notifications
      (event_type, people_id, lead_id, message_id, title, body, channel, unread_messages)
    VALUES
      ('inbound_message', NEW.people_id, NEW.lead_id, NEW.id,
       left(COALESCE(v_name, 'Contato sem nome'), 120),
       left(COALESCE(NEW.content, ''), 280),
       NEW.channel, 1)
    ON CONFLICT (people_id, event_type) WHERE read_at IS NULL
    DO UPDATE SET
      message_id      = EXCLUDED.message_id,
      body            = EXCLUDED.body,
      channel         = EXCLUDED.channel,
      unread_messages = notifications.unread_messages + 1,
      created_at      = now(),
      lead_id         = COALESCE(EXCLUDED.lead_id, notifications.lead_id);
      -- title não é atualizado: preserva o nome de quando a rajada começou.

    UPDATE public.clients_people
       SET updated_at      = now(),
           unread_count    = unread_count + 1,
           first_unread_at = COALESCE(first_unread_at, NEW.created_at, now())
     WHERE id = NEW.people_id;
  ELSE
    UPDATE public.clients_people SET updated_at = now() WHERE id = NEW.people_id;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;  -- PRESERVAR: falha de contador/notificação nunca derruba a ingestão
END;
$function$;

-- ── B. Race entre marcar lido e inbound concorrente ──────────────────────────
--
-- Os dois UPDATEs não são atômicos entre si. Se uma inbound chega no meio, o trigger
-- dela incrementa unread_count e o "SET unread_count = 0" seguinte apaga o incremento:
-- fica mensagem com seen_at IS NULL e contador 0 — badge some, ninguém responde o cliente.
-- Não é borda: acontece sempre que o atendente abre a thread na hora que o cliente escreve.
--
-- Correções:
--   1. Descontar exatamente o que foi marcado, em vez de zerar.
--   2. Recomputar first_unread_at (zerar perderia o "esperando há Xh" da mensagem nova).
--   3. Fechar a notificação escopada pelas mensagens efetivamente marcadas. O escopo é por
--      message_id, não por timestamp: messages.id é bigserial e a ordem de commit não
--      acompanha a do relógio, então um cutoff temporal ainda deixaria janela de corrida.

CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_people_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
  v_max_id  bigint;
BEGIN
  IF p_people_id IS NULL OR v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  -- SECURITY DEFINER fura RLS: revalidar acesso na unha.
  IF NOT public.person_conversation_accessible_to_current_user(p_people_id) THEN
    RAISE EXCEPTION 'sem acesso a esta conversa';
  END IF;

  WITH marked AS (
    UPDATE public.messages
       SET seen_at = now()
     WHERE people_id = p_people_id
       AND from_contact = 'cliente'
       AND seen_at IS NULL
    RETURNING id
  )
  SELECT count(*), max(id) INTO v_marked, v_max_id FROM marked;

  -- updated_at NÃO é bumpado: ler uma conversa não pode ressuscitá-la
  -- no topo do Omni, que ordena por updated_at DESC.
  UPDATE public.clients_people cp
     SET unread_count    = GREATEST(cp.unread_count - v_marked, 0),
         first_unread_at = (
           SELECT min(m.created_at) FROM public.messages m
            WHERE m.people_id = p_people_id
              AND m.from_contact = 'cliente'
              AND m.seen_at IS NULL
         ),
         last_read_at    = now(),
         last_read_by    = v_user_id
   WHERE cp.id = p_people_id;

  IF v_max_id IS NOT NULL THEN
    UPDATE public.notifications
       SET read_at = now(),
           read_by = v_user_id
     WHERE people_id = p_people_id
       AND read_at IS NULL
       AND (message_id IS NULL OR message_id <= v_max_id);

    -- Se uma inbound chegou no meio, a notificação dela sobrevive ao fechamento acima —
    -- mas com unread_messages contando também as mensagens que acabaram de ser lidas
    -- ("6 mensagens" no sino quando só 1 está por ler). Recomputa da verdade: o índice
    -- UNIQUE garante no máximo 1 notificação aberta por (pessoa, tipo), então todas as
    -- inbounds ainda não vistas pertencem a ela.
    UPDATE public.notifications
       SET unread_messages = GREATEST((
             SELECT count(*) FROM public.messages m
              WHERE m.people_id = p_people_id
                AND m.from_contact = 'cliente'
                AND m.seen_at IS NULL
           ), 1)
     WHERE people_id = p_people_id
       AND read_at IS NULL;
  END IF;

  RETURN v_marked;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.mark_conversation_read(uuid) TO authenticated;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730201000_mark_read_recompute_unread_count.sql
-- ---------------------------------------------------------------------------

-- Correção de 20260730200000 (já aplicada, portanto imutável).
--
-- O hardening trocou o "SET unread_count = 0" por um decremento
-- (GREATEST(unread_count - v_marked, 0)) enquanto first_unread_at passou a ser
-- recomputado por subquery. Duas estratégias diferentes na MESMA instrução:
--
--   1. O decremento nunca converge. Se unread_count já estiver divergido — que é
--      exatamente o cenário para o qual recalc_unread_count() existe — cada leitura
--      subtrai em cima do valor errado e o badge fica preso. E recalc_unread_count()
--      não tem GRANT para authenticated, então o usuário não tem como se recuperar.
--   2. Os dois campos podem discordar entre si: unread_count > 0 com first_unread_at
--      NULL (badge sem o "esperando há Xh") ou o inverso.
--
-- Recomputar os dois com o mesmo predicado e no mesmo snapshot elimina as duas coisas
-- e é auto-curativo: qualquer divergência se conserta na próxima abertura da conversa.
-- Custo idêntico — mesma tabela, mesmo predicado, mesmo índice parcial
-- (idx_messages_unread_by_person), e a subquery de first_unread_at já estava lá.

BEGIN;

CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_people_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
  v_max_id  bigint;
BEGIN
  IF p_people_id IS NULL OR v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  -- SECURITY DEFINER fura RLS: revalidar acesso na unha.
  IF NOT public.person_conversation_accessible_to_current_user(p_people_id) THEN
    RAISE EXCEPTION 'sem acesso a esta conversa';
  END IF;

  WITH marked AS (
    UPDATE public.messages
       SET seen_at = now()
     WHERE people_id = p_people_id
       AND from_contact = 'cliente'
       AND seen_at IS NULL
    RETURNING id
  )
  SELECT count(*), max(id) INTO v_marked, v_max_id FROM marked;

  -- updated_at NÃO é bumpado: ler uma conversa não pode ressuscitá-la
  -- no topo do Omni, que ordena por updated_at DESC.
  UPDATE public.clients_people cp
     SET unread_count    = (
           SELECT count(*) FROM public.messages m
            WHERE m.people_id = p_people_id
              AND m.from_contact = 'cliente'
              AND m.seen_at IS NULL
         ),
         first_unread_at = (
           SELECT min(m.created_at) FROM public.messages m
            WHERE m.people_id = p_people_id
              AND m.from_contact = 'cliente'
              AND m.seen_at IS NULL
         ),
         last_read_at    = now(),
         last_read_by    = v_user_id
   WHERE cp.id = p_people_id;

  IF v_max_id IS NOT NULL THEN
    -- Escopo por message_id e não por timestamp: messages.id é bigserial e a ordem de
    -- commit não acompanha a do relógio, então um cutoff temporal deixaria janela.
    UPDATE public.notifications
       SET read_at = now(),
           read_by = v_user_id
     WHERE people_id = p_people_id
       AND read_at IS NULL
       AND (message_id IS NULL OR message_id <= v_max_id);

    -- A notificação de uma inbound que chegou no meio sobrevive ao fechamento acima,
    -- mas contando também as mensagens recém-lidas. O índice UNIQUE garante no máximo
    -- 1 notificação aberta por (pessoa, tipo), então todas as não vistas são dela.
    UPDATE public.notifications
       SET unread_messages = GREATEST((
             SELECT count(*) FROM public.messages m
              WHERE m.people_id = p_people_id
                AND m.from_contact = 'cliente'
                AND m.seen_at IS NULL
           ), 1)
     WHERE people_id = p_people_id
       AND read_at IS NULL;
  END IF;

  RETURN v_marked;
END;
$function$;

COMMENT ON FUNCTION public.mark_conversation_read IS
  'Único caminho de escrita da leitura de uma conversa. Todo estado derivado (unread_count, first_unread_at, notifications.unread_messages) é RECOMPUTADO de messages, nunca zerado nem decrementado: zerar perde a inbound que chega no meio da transação, decrementar nunca converge se o cache já estiver divergido. Fechamento da notificação escopado por message_id.';

GRANT EXECUTE ON FUNCTION public.mark_conversation_read(uuid) TO authenticated;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730210000_mark_all_notifications_read.sql
-- ---------------------------------------------------------------------------

-- "Marcar todas" no sino vira ação LEVE: limpa só o feed de notificações.
--
-- Antes, o FE fazia um loop de mark_conversation_read() por people_id, o que cascateava
-- em messages.seen_at e clients_people.unread_count. Um clique em massa não significa que
-- o atendente leu cada conversa — e como o inbox é COMPARTILHADO, isso apagava o sinal de
-- "ninguém respondeu ainda" do time inteiro, sem undo. Clique numa notificação individual
-- continua chamando mark_conversation_read (aí sim o usuário abriu aquela conversa).

BEGIN;

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  -- SECURITY DEFINER fura RLS: repetir o predicado de visibilidade na unha, senão
  -- o usuário limparia notificação de conversa que nem pode enxergar.
  UPDATE public.notifications
     SET read_at = now(),
         read_by = v_user_id
   WHERE read_at IS NULL
     AND people_id IS NOT NULL
     AND public.person_conversation_accessible_to_current_user(people_id);

  GET DIAGNOSTICS v_marked = ROW_COUNT;
  RETURN v_marked;
END;
$function$;

COMMENT ON FUNCTION public.mark_all_notifications_read IS
  'Fecha o feed do sino em uma transação, respeitando a mesma visibilidade da policy de SELECT. Deliberadamente NÃO toca em messages.seen_at nem clients_people.unread_count: marcar o sino em massa não é o mesmo que ter atendido as conversas, e o inbox é compartilhado. Para o caso "abri esta conversa", use mark_conversation_read().';

GRANT EXECUTE ON FUNCTION public.mark_all_notifications_read() TO authenticated;

-- Toda escrita real passa por RPC SECURITY DEFINER (mark_conversation_read no clique
-- individual, mark_all_notifications_read no "marcar todas"). A policy de UPDATE direto
-- virou superfície sem uso — e permitia ao client reescrever title/body/unread_messages
-- de qualquer notificação que ele enxergue. Sem consumidor no FE, é só risco.
DROP POLICY notifications_mark_read ON public.notifications;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260730220000_closer_meeting_notification.sql
-- ---------------------------------------------------------------------------

-- Notifica o closer (meetings.user_id) quando uma reunião é agendada com ele:
-- sino (notifications, canal já existente) + WhatsApp (template
-- aviso_reuniao_agendada_closer_v1, registrado no Meta e pendente de aprovação).
--
-- Duas peças novas:
--   1. notifications ganha target_user_id — alerta PESSOAL (closer), distinto do
--      alerta por conversa (people_id) que já existe. RLS, mark_all e um novo RPC
--      mark_notification_read() passam a reconhecer as duas formas de visibilidade.
--   2. Trigger AFTER INSERT em meetings dispara o sino (transacional) e, fire-and-
--      forget, chama a edge function notify-closer-meeting (que resolve telefone/
--      template e envia via whatsapp-outbound — mesma arquitetura já usada por
--      notify_lead_stage_changed/followup-enqueue).

BEGIN;

-- ── 1. Coluna nova ──────────────────────────────────────────────────────────

ALTER TABLE public.notifications
  ADD COLUMN target_user_id uuid REFERENCES public.settings_users(id) ON DELETE SET NULL;

COMMENT ON COLUMN public.notifications.target_user_id IS
  'Alerta PESSOAL pra um settings_users específico (ex: closer avisado de reunião marcada), distinto da visibilidade por conversa via people_id. Uma linha pode ter os dois: people_id dá acesso a quem vê a conversa do lead, target_user_id garante que o destinatário específico sempre vê, mesmo sem acesso à conversa.';

CREATE INDEX idx_notifications_target_user
  ON public.notifications (target_user_id)
  WHERE target_user_id IS NOT NULL;

-- ── 2. RLS: reconhecer a segunda forma de visibilidade ───────────────────────

DROP POLICY notifications_read ON public.notifications;

CREATE POLICY notifications_read ON public.notifications FOR SELECT
USING (
  (people_id IS NOT NULL AND public.person_conversation_accessible_to_current_user(people_id))
  OR (target_user_id IS NOT NULL AND target_user_id = public.get_current_settings_user_id())
);

-- ── 3. mark_conversation_read: NÃO fecha alerta pessoal de outro tipo ────────
--
-- O UPDATE final fechava QUALQUER notificação daquele people_id, sem filtrar por
-- tipo. Isso deixaria um manager que abre a conversa do lead apagar, de tabela,
-- o aviso pessoal "você tem reunião" do closer antes dele ver — dois usuários
-- diferentes, uma ação nem percebe que afetou a outra. Alerta pessoal só fecha
-- via mark_notification_read (clique nele) ou mark_all_notifications_read
-- (do próprio destinatário).

CREATE OR REPLACE FUNCTION public.mark_conversation_read(p_people_id uuid)
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
  v_max_id  bigint;
BEGIN
  IF p_people_id IS NULL OR v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  IF NOT public.person_conversation_accessible_to_current_user(p_people_id) THEN
    RAISE EXCEPTION 'sem acesso a esta conversa';
  END IF;

  WITH marked AS (
    UPDATE public.messages
       SET seen_at = now()
     WHERE people_id = p_people_id
       AND from_contact = 'cliente'
       AND seen_at IS NULL
    RETURNING id
  )
  SELECT count(*), max(id) INTO v_marked, v_max_id FROM marked;

  UPDATE public.clients_people cp
     SET unread_count    = GREATEST(cp.unread_count - v_marked, 0),
         first_unread_at = (
           SELECT min(m.created_at) FROM public.messages m
            WHERE m.people_id = p_people_id
              AND m.from_contact = 'cliente'
              AND m.seen_at IS NULL
         ),
         last_read_at    = now(),
         last_read_by    = v_user_id
   WHERE cp.id = p_people_id;

  IF v_max_id IS NOT NULL THEN
    UPDATE public.notifications
       SET read_at = now(),
           read_by = v_user_id
     WHERE people_id = p_people_id
       AND read_at IS NULL
       AND target_user_id IS NULL
       AND (message_id IS NULL OR message_id <= v_max_id);

    UPDATE public.notifications
       SET unread_messages = GREATEST((
             SELECT count(*) FROM public.messages m
              WHERE m.people_id = p_people_id
                AND m.from_contact = 'cliente'
                AND m.seen_at IS NULL
           ), 1)
     WHERE people_id = p_people_id
       AND read_at IS NULL
       AND target_user_id IS NULL;
  END IF;

  RETURN v_marked;
END;
$function$;

-- ── 4. mark_all_notifications_read: fecha os dois tipos de alerta do próprio usuário ─

CREATE OR REPLACE FUNCTION public.mark_all_notifications_read()
RETURNS integer
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
  v_marked  integer;
BEGIN
  IF v_user_id IS NULL THEN
    RETURN 0;
  END IF;

  UPDATE public.notifications
     SET read_at = now(),
         read_by = v_user_id
   WHERE read_at IS NULL
     AND (
       (people_id IS NOT NULL AND public.person_conversation_accessible_to_current_user(people_id))
       OR (target_user_id IS NOT NULL AND target_user_id = v_user_id)
     );

  GET DIAGNOSTICS v_marked = ROW_COUNT;
  RETURN v_marked;
END;
$function$;

-- ── 5. mark_notification_read: fecha UMA notificação específica pelo id ─────
--
-- Complementa mark_conversation_read (que fecha por people_id + cascateia pra
-- messages/clients_people — certo pra 'inbound_message', errado pra um alerta
-- pessoal que não é sobre "li a conversa"). Usado pelo clique em notificações
-- que não são inbound_message (hoje: meeting_scheduled).

CREATE OR REPLACE FUNCTION public.mark_notification_read(p_notification_id uuid)
RETURNS boolean
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_user_id uuid := public.get_current_settings_user_id();
BEGIN
  IF p_notification_id IS NULL OR v_user_id IS NULL THEN
    RETURN false;
  END IF;

  UPDATE public.notifications
     SET read_at = now(),
         read_by = v_user_id
   WHERE id = p_notification_id
     AND read_at IS NULL
     AND (
       (people_id IS NOT NULL AND public.person_conversation_accessible_to_current_user(people_id))
       OR (target_user_id IS NOT NULL AND target_user_id = v_user_id)
     );

  RETURN FOUND;
END;
$function$;

GRANT EXECUTE ON FUNCTION public.mark_notification_read(uuid) TO authenticated;

-- ── 6. Trigger: reunião agendada → sino (transacional) + WhatsApp (fire-and-forget) ──
--
-- meeting_scheduled já existe no enum notification_event_type (20260423005000),
-- nunca tinha consumidor. Só dispara em INSERT (o momento de "marcou reunião");
-- reagendar/mudar status não deve re-notificar o closer.

CREATE OR REPLACE FUNCTION public.notify_closer_on_meeting_scheduled()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_lead_name    text;
  v_closer_phone text;
  v_time_label   text;
  v_supabase_url text;
  v_service_key  text;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW.status NOT IN ('agendada', 'agendado') THEN
    RETURN NEW;
  END IF;

  SELECT name INTO v_lead_name FROM public.clients_people WHERE id = NEW.people_id;
  SELECT phone INTO v_closer_phone FROM public.settings_users WHERE id = NEW.user_id;

  v_time_label := to_char(NEW.start_time AT TIME ZONE 'America/Sao_Paulo', 'DD/MM "às" HH24:MI');

  INSERT INTO public.notifications
    (event_type, people_id, lead_id, target_user_id, title, body, channel, unread_messages)
  VALUES
    ('meeting_scheduled', NEW.people_id, NEW.lead_id, NEW.user_id,
     'Reunião agendada: ' || COALESCE(v_lead_name, 'Lead'),
     'Marcada para ' || v_time_label,
     'meeting', 1);

  -- Envio de WhatsApp isolado num sub-bloco de propósito: EXCEPTION de bloco
  -- PL/pgSQL reverte pro savepoint do INÍCIO do bloco que a contém. Sem isolar
  -- aqui, uma falha no http_post (edge function fora do ar, DNS, timeout)
  -- desfaria também o INSERT em notifications de cima — o sino sumiria junto
  -- com o WhatsApp que falhou. Confirmado via dry-run: sem este sub-bloco, o
  -- teste "insere reunião com notify-closer-meeting ainda não deployado"
  -- resultava em ZERO notificações (não só zero envios de WA).
  BEGIN
    IF v_closer_phone IS NOT NULL AND v_closer_phone <> '' THEN
      SELECT value INTO v_supabase_url FROM public._app_config WHERE key = 'supabase_url';
      SELECT value INTO v_service_key  FROM public._app_config WHERE key = 'service_role_key';
      IF v_supabase_url IS NOT NULL AND v_supabase_url <> '' AND v_service_key IS NOT NULL AND v_service_key <> '' THEN
        PERFORM extensions.http_post(
          url := v_supabase_url || '/functions/v1/notify-closer-meeting',
          headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || v_service_key),
          body := jsonb_build_object('meeting_id', NEW.id::text)
        );
      END IF;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- WhatsApp é best-effort; o sino já inserido acima sobrevive
  END;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;  -- alerta de reunião nunca pode derrubar o agendamento em si
END;
$function$;

COMMENT ON FUNCTION public.notify_closer_on_meeting_scheduled IS
  'AFTER INSERT em meetings: cria o alerta pessoal (sino) do closer (NEW.user_id) na mesma transação e dispara notify-closer-meeting (fire-and-forget) pro envio de WhatsApp. EXCEPTION WHEN OTHERS THEN RETURN NEW — nunca pode bloquear o INSERT da reunião.';

DROP TRIGGER IF EXISTS trg_notify_closer_on_meeting_scheduled ON public.meetings;
CREATE TRIGGER trg_notify_closer_on_meeting_scheduled
  AFTER INSERT ON public.meetings
  FOR EACH ROW EXECUTE FUNCTION public.notify_closer_on_meeting_scheduled();

-- smoke test: confirma que as duas funções e a policy compilaram e a trigger existe
SELECT
  (SELECT count(*) FROM pg_trigger WHERE tgname = 'trg_notify_closer_on_meeting_scheduled') AS trigger_criada,
  (SELECT count(*) FROM pg_policies WHERE tablename = 'notifications' AND policyname = 'notifications_read') AS policy_ok,
  (SELECT count(*) FROM information_schema.columns WHERE table_name = 'notifications' AND column_name = 'target_user_id') AS coluna_ok;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260808100000_evolution_whatsapp_provider.sql
-- ---------------------------------------------------------------------------

-- Suporte a WhatsApp não-oficial via Evolution API (self-hosted, engine Baileys).
-- Referência: implementação do Ora (/Volumes/nvme/ora/ora), adaptada de per-user
-- pra tenant-wide — sem owner_user_id, sem "Meu WhatsApp Pessoal": conecta uma vez
-- em Integrações e o CRM inteiro passa a ter acesso, igual já funciona pra Meta.
--
-- settings_whatsapp_channels ganha uma 2ª forma de canal (provider='evolution')
-- coexistindo com os canais Meta já existentes — SEM switch exclusivo. Cada
-- canal já é resolvido individualmente por channel_id/canal-da-última-inbound/
-- default hoje; evolution entra nesse mesmo pool.

BEGIN;

-- ── 1. settings_whatsapp_channels: provider + campos evolution_* ────────────

ALTER TABLE public.settings_whatsapp_channels
  ALTER COLUMN phone_number_id DROP NOT NULL,
  ALTER COLUMN access_token DROP NOT NULL;

ALTER TABLE public.settings_whatsapp_channels
  ADD COLUMN provider text NOT NULL DEFAULT 'meta',
  ADD COLUMN evolution_base_url text,
  ADD COLUMN evolution_api_key text,
  ADD COLUMN evolution_webhook_token text,
  ADD COLUMN evolution_instance_name text,
  ADD COLUMN evolution_status text,
  ADD COLUMN evolution_last_seen_at timestamptz;

ALTER TABLE public.settings_whatsapp_channels
  ADD CONSTRAINT settings_whatsapp_channels_provider_check
    CHECK (provider IN ('meta', 'evolution'));

ALTER TABLE public.settings_whatsapp_channels
  ADD CONSTRAINT settings_whatsapp_channels_evolution_status_check
    CHECK (evolution_status IS NULL OR evolution_status IN ('STOPPED', 'STARTING', 'SCAN_QR_CODE', 'WORKING', 'FAILED', 'BANNED'));

-- Cada provider exige seus próprios campos obrigatórios — vocabulário canônico
-- de status (STOPPED/STARTING/SCAN_QR_CODE/WORKING/FAILED/BANNED) é o mesmo do
-- Ora, pra reaproveitar a tradução open/connecting/close → canônico do client.
ALTER TABLE public.settings_whatsapp_channels
  ADD CONSTRAINT settings_whatsapp_channels_provider_fields_check
    CHECK (
      (provider = 'meta' AND phone_number_id IS NOT NULL AND access_token IS NOT NULL)
      OR (provider = 'evolution' AND evolution_base_url IS NOT NULL AND evolution_api_key IS NOT NULL
          AND evolution_webhook_token IS NOT NULL AND evolution_instance_name IS NOT NULL)
    );

COMMENT ON COLUMN public.settings_whatsapp_channels.provider IS
  'meta = Cloud API oficial (existente). evolution = Evolution API self-hosted (Baileys), tenant-wide, sem template/janela 24h. No máx 1 canal evolution (idx_wa_channels_one_evolution).';
COMMENT ON COLUMN public.settings_whatsapp_channels.evolution_api_key IS
  'Cleartext — mesmo débito já aceito pra access_token do Meta nesta tabela. Rotacionar via UI se exposto.';

-- No máximo 1 canal Evolution (integração tenant-wide, não multi-instância).
CREATE UNIQUE INDEX idx_wa_channels_one_evolution
  ON public.settings_whatsapp_channels (provider)
  WHERE provider = 'evolution';

-- ── 2. whatsapp_templates: provider (evolution = texto livre, sem aprovação) ──

ALTER TABLE public.whatsapp_templates
  ADD COLUMN provider text NOT NULL DEFAULT 'meta';

ALTER TABLE public.whatsapp_templates
  ADD CONSTRAINT whatsapp_templates_provider_check CHECK (provider IN ('meta', 'evolution'));

-- ── 3. clients_people: auto-pause de IA quando humano responde manualmente ───
-- Canal-agnóstico de propósito (Meta, Evolution, Instagram, o que for) — não é
-- específico da integração Evolution, é um comportamento geral que faltava.

ALTER TABLE public.clients_people
  ADD COLUMN ai_paused_reason text,
  ADD COLUMN ai_paused_at timestamptz;

COMMENT ON COLUMN public.clients_people.ai_paused_reason IS
  'Motivo do último auto-pause da IA (ex: human_reply). NULL = nunca pausado automaticamente ou já reativado. Distinto de ai_enabled=false manual: aqui o sistema decidiu, não o admin.';

CREATE OR REPLACE FUNCTION public.auto_pause_ai_on_human_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.people_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- from_contact != 'cliente' e source_type='manual' é a assinatura exata de
  -- "um atendente digitou e enviou isso agora, no Omni" — automações (campaign,
  -- followup, appointment_reminder, kiwify) e a própria IA (ai_agent) não pausam.
  IF NEW.from_contact <> 'cliente' AND NEW.source_type = 'manual' THEN
    UPDATE public.clients_people
       SET ai_enabled = false,
           ai_paused_reason = 'human_reply',
           ai_paused_at = now()
     WHERE id = NEW.people_id
       AND ai_enabled = true;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;  -- nunca pode derrubar o envio da mensagem em si
END;
$function$;

COMMENT ON FUNCTION public.auto_pause_ai_on_human_message IS
  'AFTER INSERT em messages: quando um atendente responde manualmente (source_type=manual, from_contact != cliente), desliga ai_enabled pra esse contato — evita a IA responder por cima de quem já está atendendo. Reativação é manual (UI seta ai_enabled=true de volta, o que também deveria limpar ai_paused_reason).';

CREATE TRIGGER trg_auto_pause_ai_on_human_message
  AFTER INSERT ON public.messages
  FOR EACH ROW EXECUTE FUNCTION public.auto_pause_ai_on_human_message();

-- smoke test: confirma que compilou
SELECT
  (SELECT count(*) FROM information_schema.columns WHERE table_name='settings_whatsapp_channels' AND column_name='provider') AS provider_col_ok,
  (SELECT count(*) FROM pg_trigger WHERE tgname='trg_auto_pause_ai_on_human_message') AS trigger_ok,
  (SELECT count(*) FROM pg_indexes WHERE indexname='idx_wa_channels_one_evolution') AS index_ok;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260810180000_active_channel_id.sql
-- ---------------------------------------------------------------------------

-- Canal "atual" de cada lead — resolve o bug de roteamento que afeta IA/FUP/
-- Sends PRO: hoje, uma vez que existe canal padrão configurado, TODA resposta
-- vai por ele, nunca pelo canal que o cliente está de fato usando (Meta ou
-- Evolution, quando os dois estão conectados). `active_channel_id` passa a
-- ser a fonte de verdade única, atualizada automaticamente a cada mensagem de
-- conversa real e sobrescrevível manualmente na UI (Kanban/Omni).
--
-- `wa_phone_number_id` (em messages) guarda ou o phone_number_id real (Meta)
-- ou o id (uuid, como texto) do canal (Evolution) — convenção já estabelecida
-- na migration da Evolution. O lookup abaixo cobre os dois formatos.

BEGIN;

ALTER TABLE public.clients_people
  ADD COLUMN active_channel_id uuid REFERENCES public.settings_whatsapp_channels(id) ON DELETE SET NULL;

COMMENT ON COLUMN public.clients_people.active_channel_id IS
  'Canal WhatsApp (settings_whatsapp_channels) que esse lead está usando agora — Meta ou Evolution, quando os dois coexistem. Atualizado automaticamente por trg_sync_active_channel a cada mensagem de conversa real (exceto campaign, que não deve reatribuir); sobrescrevível manualmente na UI.';

-- ── Backfill: última mensagem de cada pessoa que tenha wa_phone_number_id ────

WITH last_channel AS (
  SELECT DISTINCT ON (m.people_id)
    m.people_id,
    c.id AS channel_id
  FROM public.messages m
  JOIN public.settings_whatsapp_channels c
    ON c.phone_number_id = m.wa_phone_number_id OR c.id::text = m.wa_phone_number_id
  WHERE m.channel = 'whatsapp'
    AND m.wa_phone_number_id IS NOT NULL
    AND m.people_id IS NOT NULL
  ORDER BY m.people_id, m.created_at DESC
)
UPDATE public.clients_people p
   SET active_channel_id = lc.channel_id
  FROM last_channel lc
 WHERE p.id = lc.people_id;

-- ── Trigger: mantém active_channel_id em sincronia com a conversa real ──────

CREATE OR REPLACE FUNCTION public.sync_active_channel_from_message()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  resolved_channel_id uuid;
BEGIN
  IF NEW.channel <> 'whatsapp' OR NEW.wa_phone_number_id IS NULL OR NEW.people_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- campaign é broadcast pontual pra um canal escolhido pelo admin — não
  -- reflete "o cliente passou a usar esse canal", então não reatribui.
  IF NEW.source_type = 'campaign' THEN
    RETURN NEW;
  END IF;

  SELECT id INTO resolved_channel_id
    FROM public.settings_whatsapp_channels
   WHERE phone_number_id = NEW.wa_phone_number_id OR id::text = NEW.wa_phone_number_id
   LIMIT 1;

  IF resolved_channel_id IS NOT NULL THEN
    UPDATE public.clients_people
       SET active_channel_id = resolved_channel_id
     WHERE id = NEW.people_id
       AND (active_channel_id IS DISTINCT FROM resolved_channel_id);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RETURN NEW;  -- nunca pode derrubar o envio/recebimento da mensagem em si
END;
$function$;

COMMENT ON FUNCTION public.sync_active_channel_from_message IS
  'AFTER INSERT em messages: resolve o canal (Meta ou Evolution) a partir de wa_phone_number_id e atualiza clients_people.active_channel_id. Ignora campaign (broadcast não deve redefinir o canal "de conversa" do lead).';

CREATE TRIGGER trg_sync_active_channel
  AFTER INSERT ON public.messages
  FOR EACH ROW EXECUTE FUNCTION public.sync_active_channel_from_message();

-- smoke test: confirma que compilou
SELECT
  (SELECT count(*) FROM information_schema.columns WHERE table_name='clients_people' AND column_name='active_channel_id') AS column_ok,
  (SELECT count(*) FROM pg_trigger WHERE tgname='trg_sync_active_channel') AS trigger_ok;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260810190000_omni_contacts_channel_filter.sql
-- ---------------------------------------------------------------------------

-- get_omni_contacts ganha p_channel — filtro por canal WhatsApp (Meta ou
-- Evolution) atual do contato, mesmo padrão já usado pro p_tag (EXISTS vs
-- coluna direta aqui, já que active_channel_id é coluna direta em
-- clients_people, não precisa de join).

BEGIN;

-- CREATE OR REPLACE não troca a assinatura antiga por conta própria quando o
-- número de parâmetros muda (mesmo só adicionando um opcional no fim) — cria
-- um OVERLOAD novo e deixa os dois coexistindo, o que tornaria toda chamada
-- futura ambígua. Precisa dropar a assinatura de 11 parâmetros explicitamente
-- antes de criar a de 12.
DROP FUNCTION IF EXISTS public.get_omni_contacts(text, text, text, text, text, text, text, text, integer, integer, text);

CREATE OR REPLACE FUNCTION public.get_omni_contacts(
  p_search_term text DEFAULT NULL::text,
  p_status_atend text DEFAULT NULL::text,
  p_atend_ia text DEFAULT NULL::text,
  p_filtro_data text DEFAULT NULL::text,
  p_responsavel text DEFAULT NULL::text,
  p_pipeline text DEFAULT NULL::text,
  p_etapa text DEFAULT NULL::text,
  p_time text DEFAULT NULL::text,
  p_limit integer DEFAULT 20,
  p_offset integer DEFAULT 0,
  p_tag text DEFAULT NULL::text,
  p_channel text DEFAULT NULL::text
)
RETURNS TABLE(contact jsonb, total_count bigint)
LANGUAGE sql
STABLE
AS $function$
  SELECT
    to_jsonb(p.*)    AS contact,
    COUNT(*) OVER()  AS total_count
  FROM public.clients_people p
  WHERE
    (
      p.whatsapp               IS NOT NULL
      OR p.instagram_id          IS NOT NULL
      OR p.tiktok_open_id        IS NOT NULL
      OR p.manychat_subscriber_id IS NOT NULL
      OR p.email                 IS NOT NULL
    )
    AND p.status <> 'merged'
    AND (
      p_search_term IS NULL OR p_search_term = '' OR
      p.name              ILIKE '%' || p_search_term || '%' OR
      p.whatsapp          ILIKE '%' || p_search_term || '%' OR
      p.email             ILIKE '%' || p_search_term || '%' OR
      p.instagram_user_id ILIKE '%' || p_search_term || '%'
    )
    AND (
      p_status_atend IS NULL
      OR (p_status_atend = 'open'   AND (p.service_status = 'open'   OR p.service_status IS NULL))
      OR (p_status_atend <> 'open'  AND p.service_status = p_status_atend)
    )
    AND (
      p_atend_ia IS NULL OR
      (p_atend_ia = 'ia_ativa' AND p.ai_enabled = true) OR
      (p_atend_ia = 'humano'   AND p.ai_enabled = false)
    )
    AND (
      p_filtro_data IS NULL OR
      p.updated_at BETWEEN
        (split_part(p_filtro_data, '_', 1) || 'T00:00:00')::timestamptz
        AND (split_part(p_filtro_data, '_', 2) || 'T23:59:59')::timestamptz
    )
    AND (
      p_responsavel IS NULL
      OR NOT EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND l.status NOT IN ('lost', 'archived')
         )
      OR EXISTS (
           SELECT 1 FROM public.leads l
           WHERE l.people_id = p.id
             AND (l.user_id = p_responsavel::uuid OR l.user_id IS NULL)
         )
    )
    AND (
      p_pipeline IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_pipelines_id = p_pipeline::uuid
      )
    )
    AND (
      p_etapa IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.leads_stages_id = p_etapa::uuid
      )
    )
    AND (
      p_time IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        WHERE l.people_id = p.id
          AND l.teams_id = p_time::uuid
      )
    )
    AND (
      p_tag IS NULL OR
      EXISTS (
        SELECT 1 FROM public.leads l
        JOIN public.leads_tags lt ON lt.lead_id = l.id
        WHERE l.people_id = p.id
          AND lt.tag_id = p_tag::uuid
      )
    )
    AND (
      p_channel IS NULL OR p.active_channel_id = p_channel::uuid
    )
  ORDER BY p.updated_at DESC
  LIMIT  p_limit
  OFFSET p_offset;
$function$;

-- smoke test: confirma que compilou e aceita o novo param
SELECT count(*) AS ok FROM public.get_omni_contacts(p_limit := 1, p_channel := NULL);

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260811130000_omni_media_bucket.sql
-- ---------------------------------------------------------------------------

-- Bucket `omni-media` (uploadToOmniMedia em whatsapp-inbound, uploadEvolutionMedia
-- em evolution-webhook) referenciado pelo código há tempo mas NUNCA existiu de fato
-- (storage.buckets tinha 0 linhas) — mídia recebida (Meta e Evolution) vinha
-- silenciosamente falhando o upload (try/catch non-fatal, só loga erro) e caindo
-- pro placeholder de texto. Criado aqui, público (getPublicUrl é usado — precisa
-- ser público pra `<img src>` funcionar sem assinatura).

BEGIN;

INSERT INTO storage.buckets (id, name, public)
VALUES ('omni-media', 'omni-media', true)
ON CONFLICT (id) DO NOTHING;

CREATE POLICY "omni_media_public_read"
  ON storage.objects FOR SELECT
  USING (bucket_id = 'omni-media');

-- smoke test
SELECT
  (SELECT count(*) FROM storage.buckets WHERE id = 'omni-media' AND public = true) AS bucket_ok,
  (SELECT count(*) FROM pg_policies WHERE schemaname='storage' AND tablename='objects' AND policyname='omni_media_public_read') AS policy_ok;

COMMIT;


-- ---------------------------------------------------------------------------
-- Migration: 20260811140000_evolution_multi_channel.sql
-- ---------------------------------------------------------------------------

-- Permite mais de 1 canal Evolution (WhatsApp não-oficial) simultâneo — antes
-- limitado a exatamente 1 por idx_wa_channels_one_evolution. As funções que
-- resolvem canal por id/channel_id (whatsapp-outbound, send-dispatch-worker)
-- já eram genéricas e não precisam de mudança; só o auth do webhook e o
-- gerenciamento de sessão assumiam singularidade — corrigidos junto (código).

BEGIN;

DROP INDEX IF EXISTS idx_wa_channels_one_evolution;

-- evolution_webhook_token vira chave de lookup do auth do webhook (cada canal
-- tem o seu, gerado no setup) — precisa ser único pra resolução não ficar ambígua.
CREATE UNIQUE INDEX idx_wa_channels_evolution_token_unique
  ON public.settings_whatsapp_channels (evolution_webhook_token)
  WHERE provider = 'evolution';

-- Evita registrar o mesmo servidor+instância duas vezes por engano — substitui
-- a regra antiga (max 1 no total) por uma mais correta (max 1 por servidor+instância).
CREATE UNIQUE INDEX idx_wa_channels_evolution_server_instance_unique
  ON public.settings_whatsapp_channels (evolution_base_url, evolution_instance_name)
  WHERE provider = 'evolution';

COMMENT ON COLUMN public.settings_whatsapp_channels.provider IS
  'meta = Cloud API oficial (existente). evolution = Evolution API self-hosted (Baileys), tenant-wide, sem template/janela 24h. Múltiplos canais evolution podem coexistir (cada um = um número/servidor distinto).';

-- smoke test
SELECT
  (SELECT count(*) FROM pg_indexes WHERE indexname = 'idx_wa_channels_one_evolution') AS old_index_gone,
  (SELECT count(*) FROM pg_indexes WHERE indexname = 'idx_wa_channels_evolution_token_unique') AS token_index_ok,
  (SELECT count(*) FROM pg_indexes WHERE indexname = 'idx_wa_channels_evolution_server_instance_unique') AS server_instance_index_ok;

COMMIT;


